const BASEDCOOKING_RECIPES = [{"id":"bc-aussie-snags","title":"Aussie Snags (sausage sizzle)","cuisine":"American","category":"Snack","ingredients":["Sausages (thin)","Onions (4g per sausage)","Tomato sauce","Mustard (optional)","White sliced bread","Butter","Oil","Wood chips (optional, fuel for smokey flavour)"],"steps":["Chop up the onions into rings","Bring the sausages to the grill, turning once every 5 mins","Add oil of your choice to the hotplate then add the onions","Use your tongs to toss the onions until they are golden brown","When the onions are golden brown turn off the hotplate","When the sausages are cooked, butter the bread, then the onions, and add a sausage (optionally split)","Finally tomato sauce on top"],"time":20,"servings":null,"image":"","source":"https://based.cooking/aussie-snags","page":"aussie-snags","tags":["basic","snack","australian","pork"]},{"id":"bc-baby-back-ribs","title":"Baby Back Ribs","cuisine":"American","category":"Recipe","ingredients":["Applewood (or other sweet cooking wood such as cherry or maple)","2 baby back rib racks","1 container of barbecue rub (Traeger Pork and Poultry Rub is recommended)","Tin foil","Bag of brown sugar","Bottle of honey","Barbecue Sauce","(Optional) A stick of butter"],"steps":["Preheat your smoker to 180 degrees Fahrenheit using applewood","Take the membrane off of the back of the ribs if your butcher hasn't already done so (tutorial)","Cover both sides of the ribs heavily in your barbecue rub, and let sit at room temp for 30 minutes","Place the ribs bone down (meat up) on your smoker, and let smoke at 180 degrees Fahrenheit for 3 hours","Take the meat out and place on top of two sheets of tin foil. Then, apply a generous amount of brown sugar and honey to both sides of the ribs, followed by a small amount of the barbecue rub. If you have butter, cut it into slices and add it on the meat side (butter is optional)","Wrap your ribs in the tin foil and place them back on the smoker at 225 degrees Fahrenheit for 2 hours","Take your ribs out of the foil and place them bone down (meat up) on your smoker","Apply a generous helping of your barbecue sauce to the ribs once every 30 minutes for an hour (twice)","Take out of smoker and cover in tin foil, allow to sit for 10-30 minutes before serving"],"time":null,"servings":null,"image":"","source":"https://based.cooking/baby-back-ribs","page":"baby-back-ribs","tags":["pork","american","supper"]},{"id":"bc-stroganoff","title":"Beef Stroganoff","cuisine":"American","category":"Recipe","ingredients":["beef","chicken stock","onions","flour","butter","Worchestershire sauce or something similar","dijon or honey dijon mustard","egg noodles"],"steps":["Dice an onion","Cut beef into bite-size strips. Ground beef can also be used (although not traditional), if beef is compacted into strips of similar size","Season the beef with kosher salt, freshly-ground pepper, or any other desired seasoning","Heat a skillet on high with butter or olive oil. Cook the onions until about translucent","Begin adding the beef strips and let them cook, stirring to prevent sticking or unequal cooking","Meanwhile, heat up a pot of highly salted water until it boils. Then add the egg noodles. Do not cook for too long as egg noodles might begin disintegrating when overcooked","Once beef is cooked, pour off the liquid produced from the meat","Add the chicken stock to the pan and continue cooking","Make roux (by mixing a small amount of flour with either water or melted butter). Mix this into the beef and stock as it cooks to thicken it to the desired consistency","Add Worchestershire sauce and the dijon mustard to taste","Serve on a plate with a scoop of egg noodles covered with the beef sauce"],"time":null,"servings":null,"image":"","source":"https://based.cooking/stroganoff","page":"stroganoff","tags":["american","beef"]},{"id":"bc-beef-tips","title":"Beef Tips in Gravy on Sour Cream Mashed Potatoes","cuisine":"American","category":"Recipe","ingredients":["Any lean, tough cut of meat (ex. round steak)","Unprocessed animal fat of some kind (ex. beef suet, mutton fat)","Potatoes","Sour cream","Butter","Milk","Shredded cheese of your choice","Small amount of flour","Beef bouillon (optional)","Red wine (optional)"],"steps":["Throw your pressure cooker with an open lid onto high heat or turn it onto saute mode if it's electric","Chop up the fat into very small, uniform cubes or strips and begin to saute it in the pressure cooker","Chop up your meat into medium, uniform cubes or strips and add it to the fat","Optional : If you are not using red wine as a deglaze in step 7 or are not cooking a large amount (~2+ pounds/~1+ kg) of meat, you may want to add a teaspoon or so of beef bouillon into the pressure cooker to intensify the beef flavor of the gravy","Add a generous amount of salt and pepper to taste along with a tiny pinch of garlic powder and stir (be very conservative with the garlic powder)","Once the meat is sufficiently browned off and there is a nice glaze forming on the bottom of the cooker, deglaze the cooker using hot water or red wine (optional) for more flavor","Put the top on your pressure cooker and allow the meat to cook for around 30 minutes on low heat while you prepare your mashed potatoes","After half an hour, vent your pressure cooker, remove the lid, and put the cooker back on low heat","Add a small amount of hot water until the liquid in the cooker is a bit more than the amount of gravy you want, then allow it to come to a boil","In a small bowl, mix up some flour with warm water to the consistency of a very runny batter","Very slowly begin adding flour water into the pot while constantly stirring until the gravy thickens and reaches the consistency you desire (it's very easy to overthicken the gravy here, don't overdo it!)","Turn off the heat and plate on top of your sour cream mashed potatoes, shown below","Peel and dice up your potatoes","Boil them on medium heat in a pot of slightly salty water until they begin to fall apart when poked with a fork","Turn off the heat and pour off the water","Mash up the potatoes to the chunkiness you desire","While the potatoes are still warm, add a generous amount of butter and shredded cheese and stir","Add a very small amount of milk and stir (be conservative here, the sour cream will provide most of the softness of the mash)","Begin adding sour cream and thoroughly mixing until the mash reaches your desired consistency","Plate under your beef tips in gravy"],"time":null,"servings":null,"image":"","source":"https://based.cooking/beef-tips","page":"beef-tips","tags":["american","beef","potato"]},{"id":"bc-cheesy-potatoe-bake","title":"Cheesy Potato Bake","cuisine":"American","category":"Recipe","ingredients":["30g+ Butter","250g Cheddar Cheese","275ml Milk","16g Flour","600g Potatoes","As much bacon as you want to garnish"],"steps":["Preparation","Preheat to 180C","Butter deep baking dish","Peal and thinly slice potatoes","Grate Cheese","Sauce","Melt Butter in Pot","Slowly add flour and stir constantly","After 2 min or bubbly remove from heat","Add milk slowly, stirring constantly","Add 3/4 of the cheese","Salt and Pepper to taste","Assembly","Add a thin layer of potatoes to the dish","Add a layer of cheese sauce","Add bacon","Repeat steps 1-3 of assembly until there are no more potatoes/sauce","Add the remaining 1/4 cheese to the top","Put in oven for 45 min. If it starts to brown too much cover with tinfoil"],"time":45,"servings":4,"image":"","source":"https://based.cooking/cheesy-potatoe-bake","page":"cheesy-potatoe-bake","tags":["american","cheese","potato"]},{"id":"bc-chicken-wings","title":"Chicken Wings","cuisine":"American","category":"Recipe","ingredients":["Chicken wings and drums","Enough Frank's RedHot Sauce to marinate and top dress","Reynold's Oven Bag"],"steps":["Soak your wings in Franks RedHot overnight","Preheat your oven to 350°F (175°C)","Transfer wings to the Reynold's bag, seal it, and put it in the oven for an hour","Crank up your grill† to high heat","Throw the wings on the grill to char the skin and dress with a light top coat of Franks"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicken-wings","page":"chicken-wings","tags":["chicken","american"]},{"id":"bc-clam-chowder","title":"Clam Chowder","cuisine":"American","category":"Recipe","ingredients":["Bacon, at least enough to create at least 2 tablespoons of drippings for the base","Butter, 2 tablespoons","1 Onion, diced","3 Cloves of Garlic, minced","1/3 cup of flour","3 cups half and half","1 cup of chicken broth, other stocks likely are no issue","1 cup of clam juice or dashi stock","Chopped clams","Salt","Potatoes, diced"],"steps":["Cook bacon in stew or soup pot, remove bacon to chop up and add back in later","Add butter and cook onions and garlic: Season as desired","Add and cook flour","Stir in broth, then stir in half and half","Add dashi or clam juice, bring to gentle boil and simmer for 20 minutes","Add potatoes and simmer till cooked, usually around 25 minutes","Add clams, cook for about 5 minutes","Garnish and ready to serve"],"time":60,"servings":4,"image":"","source":"https://based.cooking/clam-chowder","page":"clam-chowder","tags":["seafood","stew","american"]},{"id":"bc-coleslaw","title":"Coleslaw","cuisine":"American","category":"Side","ingredients":["3/4 cup mayonnaise","1/2 cup buttermilk","3 tbsp lemon juice","3 tbsp apple cider vinegar","4 tbsp distilled vinegar","1/3 cup olive oil","1/4 cup granulated sugar","1 1/2 tsp kosher salt","1 tsp ground black pepper","1 tsp celery seeds","1/2 tsp onion powder","1/4 tsp granulated garlic","1/4 tsp mustard powder","One large head of green cabbage","One large carrot"],"steps":["Finely shred, rinse, and drain the carrot","Finely shred the cabbage (use a food processor if possible)","Whisk together the mayonnaise, buttermilk, lemon juice, cider vinegar, distilled vinegar, olive oil, and sugar","Add the salt, pepper, celery seeds, onion powder, and granulated garlic, and combine well","Combine the shredded cabbage and carrot in a separate bowl","Slowly add the dressing until it lightly coats the vegetables, and toss well. Add more dressing until it tastes good","Refrigerate for at least an hour before serving"],"time":null,"servings":8,"image":"","source":"https://based.cooking/coleslaw","page":"coleslaw","tags":["side","cabbage","american","salad"]},{"id":"bc-country-skillet","title":"Country Breakfast Skillet","cuisine":"American","category":"Breakfast","ingredients":["2 eggs","2 small/medium-sized potatoes","Salt","Black pepper","4-6 bacon strips","½ an onion","Cheese (I usually use Gouda)","Paprika","A couple of Champignon 'shrooms","Some slices of bell pepper"],"steps":["Cut the bacon into pieces and fry it on a pan","Cut the potatoes into small cubes","After frying the bacon, set aside and use the bacon grease to fry the","Add some salt and paprika to the potatoes, mix well and cook for another ten","Cut the onions and add them to the frying pan. Cook for about five minutes","If you decide to add some vegetables, like mushrooms or peppers, add them","Now, there are two ways you can cook the eggs","Beat the eggs in a bowl and the pour them onto the pan","Or just crack the eggs directly on the mix in the pan and mix everything","Cut the cheese into small slices and add it","Cook for a couple of minutes more, until eggs are cooked enough. Don't let","For the final touch, chop the parsley (or whatever other spices/herbs you","Serve hot and add some freshly ground pepper"],"time":null,"servings":null,"image":"https://based.cooking/pix/country-skillet.webp","source":"https://based.cooking/country-skillet","page":"country-skillet","tags":["american","breakfast","pork"]},{"id":"bc-eggs-benedict","title":"Eggs Benedict","cuisine":"American","category":"Breakfast","ingredients":["3 egg yolks","1 tablespoon lemon juice","1/2 cup unsalted butter, melted","Cayenne pepper or hot sauce, to taste (optional)","4 eggs","1 tablespoon white vinegar","2 english muffins or toast, split","4 slices of Canadian bacon or ham","Butter, for spreading on muffins (optional)","Chives, finely chopped (optional)"],"steps":["Blend Yolks and Lemon Juice : In a blender, blend the yolks and lemon juice to create the base for the hollandaise sauce. This can optionally be done in a double boiler on a gentle simmer with whisking instead of blending to reduce curdling","Drizzle Butter : Slowly pour in the melted butter while blending. The sauce should thicken and become creamy. If it becomes too viscous, add a little warm water or lemon juice to thin it out","Season Sauce : Season to taste with cayenne pepper or hot sauce","Heat Water to Simmer : Prepare a large saucepan with at least four inches of water and bring it to a gentle simmer. Add the vinegar to help the egg whites set","Poach Eggs 3-4 Minutes : Gently slide the eggs into the simmering water. It helps to crack the eggs into a small bowl or ladle, bring the vessel to the surface of the water, and then drop the egg in that way. While cooking, take a spoon and stir the water into a little whirlpool; this can help displace the excess egg whites, giving the poached eggs a cleaner, firmer appearance. Cook for 3-4 minutes","Remove Eggs : Remove the eggs with a slotted spoon and place them on a paper towel-lined plate to drain","Toast Muffins : Halve the muffins and toast them. Optionally butter both halves. You could substitute the muffins with any kind of spongey bread","Cook Bacon : In a skillet on medium heat, cook the Canadian bacon or ham until slightly browned","Assemble : Place a slice of Canadian bacon on each toasted muffin half, top with a poached egg and a generous amount of hollandaise sauce. Garnish with cut chives and more cayenne pepper if desired"],"time":20,"servings":2,"image":"https://based.cooking/pix/eggs-benedict.webp","source":"https://based.cooking/eggs-benedict","page":"eggs-benedict","tags":["breakfast","brunch","american","pork"]},{"id":"bc-hamburger-patties-all-beef","title":"Hamburger Patties","cuisine":"American","category":"Recipe","ingredients":["1 lb ground beef, 20% or more fat ratio","Onion, chopped or powder (optional)","Garlic, chopped or powder (optional)"],"steps":["Form patties with the beef. Use high-fat ground beef, you won't need oil","Place into a pan, pre-heated or otherwise, at medium/med-high temperature","Add salt, pepper, and optional seasonings","Cook until done, flipping occasionally to prevent burning"],"time":null,"servings":4,"image":"","source":"https://based.cooking/hamburger-patties-all-beef","page":"hamburger-patties-all-beef","tags":["american","quick","beef","basic"]},{"id":"bc-hamburger-patties","title":"Hamburger Patties","cuisine":"American","category":"Recipe","ingredients":["1 cup soft bread crumb","1/2 cup milk","1 1/2 pound ground beef","1 medium onion, chopped","1/2 teaspoon salt","dash pepper","1/2 teaspoon cayenne","1 teaspoon Worcestershire sauce","2 tablespoons of fat or salad oil"],"steps":["Combine all ingredients except fat: mix well; shape into 6 patties","Heat fat in skillet","Brown patties on all sides; lower heat; cook to desired degree of"],"time":null,"servings":6,"image":"","source":"https://based.cooking/hamburger-patties","page":"hamburger-patties","tags":["american","quick","beef","sandwich"]},{"id":"bc-maque-choux","title":"Maque Choux","cuisine":"American","category":"Recipe","ingredients":["A little sugar","A good bit of grease (about a handful)","Handful of chopped onion","Handful of chopped bell pepper","Eight ears of corn","Handful of chopped tomatoes","Salt & Pepper (to taste)"],"steps":["Clean the corn and cut lengthwise about a thumbnail (1/4 in) from the top and scrape down using the soft end of a knife (to keep the juices)","Mix all ingredients in a bowl excluding the grease. Salt & pepper to taste","Pour mixture into a pot with hot grease in it at low heat","Cover pot and cook for 45 minutes, and stir as you get up for more beers","Serve. (Serves 4-6)"],"time":null,"servings":null,"image":"","source":"https://based.cooking/maque-choux","page":"maque-choux","tags":["american","corn","fasting"]},{"id":"bc-meatloaf","title":"Meatloaf","cuisine":"American","category":"Recipe","ingredients":["4 1/2 pounds Ground beef","1 Onion","2 Slices of bread","4 Eggs","1/4 Cup of milk","Garlic salt","Onion powder","Mustard","Sugar free ketchup","3 Cubes of brown sugar","1 Can of Campbell's tomato soup","Franks RedHot sauce (Optional)"],"steps":["Once thawed, put all of your beef into a bowl. The next 4 steps will all go into this same bowl","Dice the onion and bread slices into small pieces. Add them","Crack and put in all of your eggs","Pour in your milk, and a moderate amount of mustard and ketchup","Add garlic salt and onion powder","Now you must use your (sanitized) hands and mix everything in the big bowl well. Make sure you get the bottom","Evenly distribute your mixed meat into 2 or 3 oven safe greased up dishes. Try to flatten the surface as much as you can","In each dish, create a small channel in the middle of each meatloaf. This is to maintain the shape as it's cooking","Put all of your meatloaf filled dishes into the oven on 180 Celsius for 1 hour","Once you have about 15 minutes left on your timer, get started on your sauce","Toss your 3 sugar cubes into a bowl with a little bit of hot water to melt them","Add your tomato soup, 1/4 Cup of ketchup and mustard (each)","Stir sauce until it's a thick, light red color","Once 1 hour is up, take out all of your meatloaf. Make sure to cut open the thickest meatloaf and confirm the beef is cooked","Coat the top of each of your meatloaves with the sauce, evenly","Once coated, put back into the oven for 10 minutes","Take out all of your meatloaf. Once cool, slice it up and serve!"],"time":70,"servings":6,"image":"https://based.cooking/pix/meatloaf.webp","source":"https://based.cooking/meatloaf","page":"meatloaf","tags":["beef","american","supper"]},{"id":"bc-pavlova","title":"Pavlova","cuisine":"American","category":"Dessert","ingredients":["2 egg whites","1 1/2 cups caster sugar","1/2 tsp salt","1 tsp white vinegar","1 tsp cornflour","4 Tbsp boiling water","(optional) Whipped cream, fresh fruit such as kiwifruit, passionfruit, and strawberries"],"steps":["Beat all ingredients until smooth, stiff and shines","Continue beating mixture until soft peak forms when lifting beater (approx 12 minutes)","Place on baking paper on tray","Bake in middle of oven at 180˚C (350-360˚F) for 10 minutes","Drop temperature down to 150˚C (300˚F) for 45 minutes","Turn off oven and leave to cool in oven","(Optional) Serve with fruit salad and ice cream"],"time":55,"servings":6,"image":"https://based.cooking/pix/pavlova.webp","source":"https://based.cooking/pavlova","page":"pavlova","tags":["meringue","dessert","australian","new zealand","baking"]},{"id":"bc-perfect-potato-salad","title":"Perfect Potato Salad","cuisine":"American","category":"Salad","ingredients":["5 Potatoes, peeled and cut into bite-size chunks (about 2 lbs)","1 cup Plain Yogurt","1/2 cup Mayonnaise","1 Tbsp Prepared Horseradish","4 Radishes, thinly sliced","2 stalks Celery, diced","2 large Green Onions, thinly sliced","1/4 cup Fresh Parsley, chopped","1/4 cup Fresh Dill, chopped"],"steps":["Place potatoes in a pot and just cover with water. Partially lid and bring to a boil. Reduce heat and simmer partially covered just until potatoes are tender (5 mins). Don't overcook. Drain well","Meanwhile in a large bowl, stir yogurt with mayonnaise, horseradish, salt, and pepper. Stir in radishes, celery, green onions, parsley, and dill until mixed","Add warm potatoes and stir to combine. Refrigerate at least 1 hour before serving. Taste and adjust seasonings if desired"],"time":5,"servings":8,"image":"","source":"https://based.cooking/perfect-potato-salad","page":"perfect-potato-salad","tags":["potato","salad","american"]},{"id":"bc-savory-squash","title":"Savory Squash","cuisine":"American","category":"Side","ingredients":["1 Butternut Squash","1/2 Stick of butter","Salt, to taste","St. Augur Blue Cheese","Chives"],"steps":["Peel Butternut squash and discard both ends. Cut in half lengthwise, scoop and discard seeds. Cut in half lengthwise again","Place face down on greased baking sheet. Rotate to roast the other face after 20 minutes, Check at 45 mins with a toothpick for softness","Cut up into 2 inch chunks and toss into stand mixer. Mix on high and add a half stick of butter and salt to taste. Stir in half of the St. Augur blue cheese","Pour into casserole dish. Stir in any extra blue cheese to taste or crumble on top. Lower oven to 300 and bake the mashed squash for 15 minutes","Garnish with chopped chives on top"],"time":60,"servings":null,"image":"","source":"https://based.cooking/savory-squash","page":"savory-squash","tags":["american","side","fruit"]},{"id":"bc-shrimp-and-chicken-jambalaya","title":"Shrimp and Chicken Jambalaya","cuisine":"American","category":"Recipe","ingredients":["1/4 tsp Cayenne","3/4 tsp White Pepper","1 tsp Kosher Salt","1/4 tsp Thyme","1/2 tsp Rubbed Sage","1/4 tsp Dried Basil","1/2 tsp Black Pepper","1 Tbsp Unsalted Butter","1/2 cup Diced Andouille (or Chirozo sausage)","1/2 cup Diced Onion","1/2 cup Diced Bell Pepper","1/2 cup Diced Celery","1/2 cup Diced Fresh Tomatoes","1/2 cup Tomato Sauce","3/4 cup Enriched Long Grain Rice","1-1/4 cup Chicken Stock","1 Tbsp Worcestershire Sauce","2 Tbsp Minced Fresh Garlic","1/2 cup Diced Chicken (cooked or raw)","1-1/2 cup Medium Shrimp","1 Tbsp Finely Chopped Italian Parsley","3 Tbsp Finely Sliced Green Onions"],"steps":["Preheat the oven to 350 degrees F. Mix together the seasoning mix (herbs, salt, pepper)","Mix together the Holy Trinity (onion, celery, bell pepper)","In a Cast Iron Durch Oven, melt the butter over medium heat, add the Andouille and cook until it starts to brown","Add 1/2 of the Holy Trinity, cook until the vegetables are tender","Add the diced tomatoes and cook for one minute. Add the tomato sauce and cook for another minute","Add the rice and cook for 2 minutes, stirring constantly","Add the stock, remaining Holy Trinity, seasoning mix, Worcestershire, and the garlic","Taste the broth for seasoning, particularly salt","Add the chicken, stir well and put the pot in the preheated oven. Bake uncovered for 25 minutes","Stir in the raw shrimp, parsley, and green onions - place back into oven for another 10 minutes (or until the shrimp is cooked through)"],"time":40,"servings":null,"image":"","source":"https://based.cooking/shrimp-and-chicken-jambalaya","page":"shrimp-and-chicken-jambalaya","tags":["shrimp","chicken","cajun","tomato"]},{"id":"bc-shrimp-and-grits","title":"Shrimp and Grits","cuisine":"American","category":"Breakfast","ingredients":["2 lbs Large/Jumbo Shrimp","6 Slices of Bacon","1 cup Un-Cooked Grits","3 cups Chicken Broth","2 cups Shredded Cheddar Cheese","3 tbsp Butter","3 tbsp Chopped Fresh Parsley","1 tbsp Creole / Cajun seasoning","2 Cloves of Garlic, minced","2 tsp Worcestershire Sauce","1 tbsp Lemon Juice"],"steps":["Add bacon to hot pan. Meanwhile, in separate pot , bring chicken broth to a boil","Add grits to chicken broth and stir. Cover and simmer per instructions on box","Once grits are done, add butter plus salt and pepper to taste. Stir until combined","Add cheese. Stir until combined","Once bacon is done, keep bacon fat in the pan. Add shrimp and fry on medium-high heat","Add Creole seasoning, lemon juice, Worcestershire Sauce, garlic and toss","Fry until shrimp turns white on each side which is about 5-7 minutes total","In a bowl, serve shrimp and bacon over grits. Top with parsley"],"time":20,"servings":2,"image":"","source":"https://based.cooking/shrimp-and-grits","page":"shrimp-and-grits","tags":["american","fish","breakfast"]},{"id":"bc-gumbo-shrimp-and-sausage","title":"Shrimp and Sausage Gumbo","cuisine":"American","category":"Rice","ingredients":["2-3 lbs Shrimp","2 lbs Andouille Sausage","2 (32 oz) Chicken Broth","1 cup olive oil","1 cup All Purpose Flour","1 cup finely chopped Yellow Onion","1 cup finely chopped Green Pepper","1 cup finely chopped Celery","2 tbsp minced Garlic","1 tbsp Worcestershire Sauce","1 tbsp Cajun or Creole Seasoning (Creole Kick)","1 12 oz. bottle of Beer","1 tsp dried Thyme","1 tsp dried Parsley","3 - 5 Bay Leafs","1/2 cup Green Onions","1-2 cups White Rice","(Optional) 1 Jalapeño Pepper","(Optional) Instead of chicken broth, you can use your own shrimp stock"],"steps":["Prep the vegetables","Get the roux started: Mix oil and flour over heat until it turns into a dark chocolate color. Low - medium heat for about 30 minutes or medium - high for 15 - 20 minutes if you're feeling brave","Ensure to stir frequently while adding the following ingredients","Add onion. Cook for 5 minutes","Add celery and peppers. Cook for 5 minutes","Add garlic. Cook for 1 minute","Add beer","Add broth","Add seasonings and Worcestershire Sauce","Add sausage and bring to a boil","Lower heat, cover, simmer for 90 minutes","Increase heat to medium. Add shrimp and cook for 5-7 minutes","Turn off the heat and serve over white rice","(Optional) For leftovers, boil gumbo with dry white rice and turn it into a jambalaya"],"time":null,"servings":4,"image":"","source":"https://based.cooking/gumbo-shrimp-and-sausage","page":"gumbo-shrimp-and-sausage","tags":["american","fish","rice"]},{"id":"bc-shrimp-creole","title":"Shrimp Creole","cuisine":"American","category":"Recipe","ingredients":["2 cups Green Bell Pepper, diced","1 5-inch Yellow or White Onion, diced","2 cups of Celery, diced (try to get one with lots of green leaves)","1/4 cup of olive or cooking oil","1 cup Heinz chili sauce (it looks like ketchup but is not)","[optional] 3 tbsp Frank's RedHot sauce","1 cup of seedless Golden Raisins","1 cup of Slivered Almonds","3x 14.5oz cans of diced tomato - optionally blend one","1 teaspoon each: pepper, thyme, salt","2 tsp curry powder","1/2 cup parsley","2 lb cleaned and shelled shrimp","cooked white rice"],"steps":["Sauté raw vegetables in oil","add remaining ingredients except shrimp","simmer 1 hour","Add shrimp and cook for 5 minutes","Serve over cooked rice","[optional] Best if cooked a day ahead and reheated"],"time":300,"servings":8,"image":"https://based.cooking/pix/shrimpcreole-mitchmarq42.webp","source":"https://based.cooking/shrimp-creole","page":"shrimp-creole","tags":["shrimp","stew","southern"]},{"id":"bc-smoked-turkey","title":"Smoked Turkey","cuisine":"American","category":"Recipe","ingredients":["1 turkey, 5-15 lb. (thawed)","1-2 cups whipped butter (room temperature)","2 cup chicken broth","1-4 tbsp garlic powder (optional)","1 lb mixed vegetables (carrots, potatoes, broccoli, etc.) (optional)"],"steps":["Mix garlic powder into the whipped butter","Remove giblets and other materials from the turkey cavity","Rinse the turkey and pat dry with a towel","Liberally coat the turkey with the whipped butter mixture. Ensure the entire surface is coated","Place turkey in a foil baking pan with mixed vegetables. If available, use a rack to elevate the turkey from the bottom of the pan","Add chicken broth until it coats the bottom of the pan","Cover the pan in foil","Ignite the charcoal grill; arrange the coals for indirect cooking. Try to maintain a temperature of 300-400°F","Place the turkey in pan on the grill and cook indirectly for 1 hour","Remove the foil, and continue cooking over indirect heat","Periodically (every 15-30 minutes) baste the turkey with its own juices. If the bottom of the pan is dry, add chicken broth and reduce heat","Remove when the turkey reaches an internal temperature of 160°F in the breast","Allow to rest for 10 minutes before carving"],"time":180,"servings":4,"image":"https://based.cooking/pix/smoked-turkey.webp","source":"https://based.cooking/smoked-turkey","page":"smoked-turkey","tags":["basic","american","turkey"]},{"id":"bc-southern-biscuits","title":"Southern Biscuits","cuisine":"American","category":"Recipe","ingredients":["2 cups AP flour","1 tsp white sugar","1 tbsp baking powder","1 tsp kosher salt","8 tbsp sweet butter","3/4 cup whole milk"],"steps":["Preheat oven to 425°F","In a bowl combine dry ingredients","Cube butter and add to dry ingredients","Mix butter with hands or fork until a cornmeal consistency is achieved","Add milk and mix until homogeneous","Roll biscuits out to approx. 3/4 of an inch thick","Use a mug, cup, or cookie cutter to cut out rounds of dough","Arrange rounds in a cast iron pan","Bake for 12 to 15 minutes","Remove from oven and eat hot","Will keep on counter or in a brisker"],"time":null,"servings":null,"image":"","source":"https://based.cooking/southern-biscuits","page":"southern-biscuits","tags":["american"]},{"id":"bc-bean-salad","title":"Three Bean Salad","cuisine":"American","category":"Salad","ingredients":["1/3 cup Salad Oil (olive oil, canola, or sunflower)","1/2 cup Cider Vinegar","1 tsp Salt","1/2 tsp Pepper","1/4 cup Sugar","1/2 tsp Celery Seed","1 can Cut Green Beans","1 can Cut Waxed Beans","1 can Red Kidney Beans","1 Carrot, thinly sliced","1 small Onion, chopped","1 Bell Pepper"],"steps":["Put dressing ingredients in a large salad bowl an whisk until blended","Empty cans of beans into a colander and rinse under cold water","Chop remaining vegetables and add to dressing. Add beans and gently stir","Refrigerate for at least an hour before serving, stirring occasionally"],"time":null,"servings":8,"image":"","source":"https://based.cooking/bean-salad","page":"bean-salad","tags":["salad","american","fasting","quick"]},{"id":"bc-dulce-de-leche","title":"Dulce de Leche","cuisine":"Argentine","category":"Recipe","ingredients":["1 liter of milk","350 grams of sugar","Half a teaspoon of baking soda","A vanilla bean, or essence (Optional)","Two glass marbles (Optional, but it is a traditional way to prevent sticking, and they will not break in the process.)"],"steps":["Heat all ingredients in a pan (with the marbles, if you want,) on a medium-heat stove, constantly mixing with a wooden spoon","Once the sugar dissolves, set heat to very low, and keep mixing once in a while for approximately two hours. It should not boil, if it happens, set it aside, keep mixing and once the temperature lowers put it back on the heat","Once the preparation gets thicker, be more careful and mix it more frequently so that it does not stick (and burn)","Once you get a consistency similar to that of a custard, set it aside and keep mixing for 10 minutes, until it gets","Once cold, put it on a glass jar and leave it in the fridge, or sterilize it"],"time":180,"servings":null,"image":"","source":"https://based.cooking/dulce-de-leche","page":"dulce-de-leche","tags":["argentinian","milk","slowcooked","traditional"]},{"id":"bc-oven-asado","title":"Oven Asado","cuisine":"Argentine","category":"Recipe","ingredients":["Beef chuck short ribs (bone in preferrably)","Celusal BBQ Salt - Iodized (including the specific type of salt due to smaller salt grains not working well)"],"steps":["Heat oven to 400F/200C","Take beef out of fridge and let thaw or reach near room temperature","[OPTIONAL] Rinse each end of the beef to get rid of any remaining bone fragments from when the meat was cut","Pat all sides of beef dry with a paper towel","Salt each side of the beef generously , salt will drip off of the meat due to the fat as the meat cooks","Place beef on a rack and place in oven bone-side down , and be sure to add a tray below the rack to catch all the fat that drips off","20 minutes into cooking, flip each piece over (should be bone-side top now)","After another 20 minutes, flip each piece again","Take out of the oven after a total of 40 - 45 minutes, and let rest for 5 - 10 minutes"],"time":45,"servings":null,"image":"","source":"https://based.cooking/oven-asado","page":"oven-asado","tags":["argentinian","meat"]},{"id":"bc-torta-frita-criolla","title":"Torta Frita Criolla (Argentinian frybread)","cuisine":"Argentine","category":"Bread","ingredients":["1.1 pound (1/2 kilo) of all-purpose flour","4 tablespoons of lard or butter","1/2 cup of water mixed with a teaspoon of salt","Oil or grease of choice for frying. (Modern Argentines use refined tallow or sunflower seed oil, but for the real gaucho way, unrefined lard or tallow is the right choice)","Sugar, cinnamon, or herbs and spices of choice (Optional)"],"steps":["Add the flour on a bowl, and the grease in ambient temperature in the middle","Mix flour and grease with your fingertips, while slowly adding the salt water, until you end up with a dough ball","Knead it energically, until the dough forms bubbles on its surface","Let it rest for 1 or 2 hours, and then form little balls, the size you'd do for a chocolate chip cookie, smash them to a disc shape, then poke a small hole in the middle","Fry it on abundant grease until golden brown, remove it with a perforated spoon, then put it on a bowl with paper towels to absorb excess grease","Add garnishes, but it is not essential, due to how rich and filling the dish is"],"time":10,"servings":10,"image":"","source":"https://based.cooking/torta-frita-criolla","page":"torta-frita-criolla","tags":["argentinian","fry","bread"]},{"id":"bc-beijinho","title":"Beijinho","cuisine":"Brazilian","category":"Dessert","ingredients":["A can of sweetened condensed milk (395g)","Unsalted butter (30g)","Table cream (200g)","Unsweetened Shredded Coconut (80g)","Cloves (optional)"],"steps":["Mix the sweetened condensed milk, the butter, the table cream, 30g of coconut and a pinch of salt in a saucepan;","On medium-low heat, stir constantly until it thickens","The right point it's when you use the spatula through the mixture and create a 'path' that takes a while to close","Turn off the stove, put the dessert on a plate and cover it with plastic wrap","Take it to the refrigerator and let it cool","Grease your hands with butter and make small balls with the mixture you just prepared (the size of each ball is on you, I recommend 18g each);","Roll the balls in the rest of the shredded coconut, place them into small paper cups, and, traditionally, we stick a clove on the top"],"time":10,"servings":27,"image":"https://based.cooking/pix/beijinho.webp","source":"https://based.cooking/beijinho","page":"beijinho","tags":["dessert","coconut","traditional","brazilian"]},{"id":"bc-brigadeiro","title":"Brigadeiro","cuisine":"Brazilian","category":"Dessert","ingredients":["One can of condensed milk","Three or four spoons of chocolate powder or cocoa powder","One spoon of butter (Actual butter and preferably unsalted. No margarine!)","Sprinkles (Optional)"],"steps":["Add all ingredients into a pan","Put it under low heat and stir it (preferably with a wooden spoon) until it stops sticking to the bottom of the pan","Remove it from the pan and eat it with a spoon or roll it into small balls","If you chose to roll it into balls, you may also roll them around in sprinkles while still hot"],"time":null,"servings":null,"image":"https://based.cooking/pix/brigadeiro.webp","source":"https://based.cooking/brigadeiro","page":"brigadeiro","tags":["dessert","quick","brazilian","cheesefare"]},{"id":"bc-cuca-italiana","title":"Cuca \"Italiana","cuisine":"Brazilian","category":"Recipe","ingredients":["3 cups of all-purpose flour","1 1/2 cups of sugar","3/4 of a cup of warm water","2 eggs","6 tablespoons of milk","2 tablespoons of lard or butter","1 tablespoon of instant dry yeast","A pinch of nutmeg","1 teaspoon of vanilla essence (optional)","Optional herbs and spices: Fennel seeds, cinammon, cloves. Don't put too many though","1 cup of sugar","1/2 cup of flour","2 tablespoons of lard or butter","1 teaspoon of vanilla essence"],"steps":["Add the sifted flour, the nutmeg and a pinch of salt into a bowl. In another one, add the sugar, the warm water, the fat of choice, the yeast and the vanilla essence","Unite both mixes and knead it until an homogenous dough forms. Put it in a properly floured and greased baking tray that you would use for baking bread, or a tall, round tray for cake","Prepare the \"farofa\" mixing the sugar, the flour, the fat and the vanilla essence with your fingertips, until they form crumbles. Now put the \"farofa\" over the dough, cover it with a cloth and leave it to rest for 2 hours","Then, bake it at a pre-heated 180C (356F) oven for 40 minutes","Have it with fruit jam (grape is my favourite) or dulce de leche, and some coffee"],"time":40,"servings":8,"image":"","source":"https://based.cooking/cuca-italiana","page":"cuca-italiana","tags":["brazilian","cake","traditional"]},{"id":"bc-galinha-caipira","title":"Galinha Caipira","cuisine":"Brazilian","category":"Recipe","ingredients":["A whole ckicken weighing close to 2,5kg (roughly 3 pounds). Avoid industrially grown birds, as those can make the stew very greasy and flavorless","A cup of diced onions of any kind","Half a cup of diced chives","A tablespoon of lard","A full kettle of boiled water"],"steps":["Cut the chicken into pieces. Remove offal or small bones, if you want. Salt and pepper to taste now","In a pan (best if cast iron), add the lard and heat it up very well","Add the chicken and lower the heat","After the meat sears, add the diced onions","When the onions brown, cover the pot with boiling water, and let it simmer for two hours. If it dries, add more water","After those two hours, add the diced chives and simmer it for more thirty minutes"],"time":30,"servings":null,"image":"","source":"https://based.cooking/galinha-caipira","page":"galinha-caipira","tags":["chicken","stew","brazilian"]},{"id":"bc-beef-wellington","title":"Beef Wellington","cuisine":"British","category":"Recipe","ingredients":["1lb of Fillet Beef","Extra Virgin Olive Oil","1lb of mushrooms","4 Thinly Cut Slices of Ham","2tbsp of Yellow Mustard","7oz of Puff Pastry","2 Egg Yolks Beaten"],"steps":["Season the fillet with salt and black pepper","With a nicely-oiled pan on high heat, sear the fillet on all sides, including the ends. For the standard medium-rare beef wellington, do not cook the fillet, just sear it, tough if you want something more cooked than medium-rare, it's wise to give it more heat here. Put it aside on a plate","Brush the fillet with yellow mustard immediatly after taking it out of the pan. This allows the musturd's flavour to be absorbed by the fillet and thus preserve a mildly hot flavor","Chop the mushrooms. Put them in a food processor. Transfer the purée to a sauté pan that has been heated to medium high heat to cook. Allow the mushrooms to release their moisture; once the moisture has been boiled away take the mushrooms out of pan to cool","Lay out the slices of ham on plastic wrap and spread the mushroom mixture over the ham. Place the fillet in the middle. Wrap the fillet into a tight barrel shape twist the end of the plastic wrap to secure the wrap and the refrigerate the whole thing for 20 minutes","Preheat the oven to 302°F/150°C","On a lightly floured surface, roll out a sheet of puff pastry to a size that will fit the fillet. Preserve a little excess pastry. Unwrap the fillet-mushroom-ham from the plastic wrap and place in the middle of the pastry dough. Brush the edges of the pastry with the beaten egg yolks","Place the pastry-wrapped thing on a baking tray. Brush the exposed surface again with the beaten eggs. Optionally, score the top of the pastry with a knife, to give it a better presentation. Scratch the surface of it but don't cut it through. Season it through with coarse salt","Bake at 302°F/105°C for 35-42 minutes. The pastry should be nicely golden when done. Let it rest for about 10 minutes and cut it into 1in/2.54cm-thick slices for presentation"],"time":120,"servings":4,"image":"","source":"https://based.cooking/beef-wellington","page":"beef-wellington","tags":["english","beef"]},{"id":"bc-cheesy-ham-and-potato-bake","title":"Cheesy Ham and Potato Bake","cuisine":"British","category":"Recipe","ingredients":["~ 1 kg (~2.2lb) of potatoes","~ 300g (~0.7 lb) of smoked ham","1 onion chopped","~ 200g (~0.5 lb) grated cheddar","2 dl (~1 cup) cream","cayenne pepper (optional)","thyme (optional)"],"steps":["Saute the chopped onion on a medium hot pan in a bit of butter or oil, until it's mildly translucent","Wash and slice the potatoes into thin less than 1 cm slices","Cut the ham into strips","Place the potatoes into a large oven dish and place the ham on top of the potatoes","Pour the cream evenly into the dish","Add salt and ground black pepper to taste. Additionally, you can add a bit of cayenne pepper powder and thyme to give the dish a bit of spiciness","Spread the grated cheddar evenly on top of the other ingredients","Bake in the oven in 200C (400F) for 1h 3omin. Cover with aluminum foil once the cheese has got a bit of colour"],"time":30,"servings":4,"image":"https://based.cooking/pix/cheesy-ham-and-potato-bake.webp","source":"https://based.cooking/cheesy-ham-and-potato-bake","page":"cheesy-ham-and-potato-bake","tags":["pork","potato","cheese","finnish"]},{"id":"bc-cinnamon-waffles","title":"Cinnamon Waffles","cuisine":"British","category":"Recipe","ingredients":["1/2 lb butter","1 cup sugar","2 tsp cinnamon","3 eggs","flour"],"steps":["Cream the butter and sugar","Beat in the eggs 1 at a time and add cinnamon","Work in enough flour to make a soft dough","Form into small balls","Place several in a hot waffle iron, suitably spaced, press down top and bake"],"time":600,"servings":null,"image":"","source":"https://based.cooking/cinnamon-waffles","page":"cinnamon-waffles","tags":["cookies","baking","dutch","pennsylvania"]},{"id":"bc-country-crisp-cereals","title":"Country Crisp Cereals","cuisine":"British","category":"Breakfast","ingredients":["Oat Flakes (270 g - 800 mL)","Rice Flour (or any other flour) (20 g - 55mL)","Sugar (100 g)","Crushed Hazelnuts (20 g)","Oil (any type) (60 g - 75 mL)","Water (50 g)","Chocolate (70 g) (optional)","Vanilla Extract (1/2 tsp) (optional)"],"steps":["Preheat the oven at 120°C","Prepare the cooking support with for example, a parchment paper on a cooking plate","Mix the sugar and the water, until the sugar dissolves","In a large container (like a salad bowl) introduce the Flour, the Oat Flakes, and the Crushed Hazelnuts (and optionally the Vanilla Extract), and mix","Introduce in the previous mixture, the Sugar Syrup and the Oil, and mix again","Deposit the paste obtained on the cooking plate without exceeding 2 cm in height","Bake the mixture in the 120°C oven until it becomes hard (in approximately 2 hours)","Break the hardened mixture to obtain cereals","Add if you want some broken chocolate (or chocolate chips) in the cereals, or anything you want"],"time":5,"servings":7,"image":"","source":"https://based.cooking/country-crisp-cereals","page":"country-crisp-cereals","tags":["breakfast","english"]},{"id":"bc-erwtensoep","title":"Erwtensoep (Dutch pea soup)","cuisine":"British","category":"Soup","ingredients":["7 1/2 cups / 1.75 liters water","1 1/2 cups / 300 grams peas (dried green split)","3 1/2 ounces / 100 grams pork belly (Dutch speklapjes or thick-cut bacon)","1 pork chop","1 bouillon cube (vegetable, pork or chicken)","2 ribs celery","2 to 3 carrots (peeled and sliced)","1 large potato (peeled and cubed)","1 small onion (chopped)","1 small leek (sliced)","1 cup celeriac (cubed)","1 pound sausage (chopped rookworst, smoked sausage)","Salt and pepper"],"steps":["In a large soup pot, bring water, split peas, pork belly or bacon, pork chop, and bouillon cube to a boil","Reduce the heat to a simmer, cover and let cook for 45 minutes, stirring occasionally and skimming off any foam that rises to the top","Remove the pork chop, debone, and thinly slice the meat. Set aside","Add the celery, carrots, potato, onion, leek, and celeriac to the soup","Return to the boil, reduce the heat to a simmer and let cook, uncovered, for another 30 minutes","Add the smoked sausage for the last 15 minutes of cooking time","When the vegetables are tender, remove the bacon and smoked sausage, slice thinly, and set aside","If you prefer a smooth consistency, purée the soup with a stick blender","Season to taste with salt and pepper","Add the meat back to the soup, setting some slices of sausage aside","Serve in heated bowls or soup plates, garnished with slices of rookworst and chopped celery leaf. Enjoy!"],"time":90,"servings":4,"image":"","source":"https://based.cooking/erwtensoep","page":"erwtensoep","tags":["dutch","soup","vegetables"]},{"id":"bc-finnish-salmon-soup","title":"Finnish Salmon Soup","cuisine":"British","category":"Soup","ingredients":["2 pcs salmon fillet","4 cups water or stock","1 leek","1/4 cup butter","5-7 potatoes","1-2 carrots","1 cup heavy cream","salt and pepper to taste","dill to garnish"],"steps":["Wash, clean, and dice all vegetables","Remove scales from salmon fillet or remove skin entirely, up to you. Dice","In a pot, melt butter. Add diced leeks and cook on medium-high about 5 minutes until the leeks wilt a bit","Add water (or stock) and other vegetables. Bring to a boil and cook on medium heat about 10-15 minutes until the potatoes are ready","Add diced salmon fillet and heavy cream. Cook for additional 5-10 minutes to cook the salmon","Add salt and pepper to taste at the end. Serve with dill as garnish"],"time":30,"servings":6,"image":"","source":"https://based.cooking/finnish-salmon-soup","page":"finnish-salmon-soup","tags":["salmon","soup","finnish","fish","easy"]},{"id":"bc-full-english-breakfast","title":"Full English Breakfast","cuisine":"British","category":"Breakfast","ingredients":["4 raw sausages (English sausages to be authentic)","4 slices of bacon (English back bacon to be authentic)","2 eggs","half a tin (200g) of baked beans","2 slices of bread","1 large tomato","half a cup (120g) of button mushrooms"],"steps":["Preheat your oven to 250°c or 480°F","Prepare you mushrooms by cutting off the ends of the woody stems, and washing them in a colander","Prepare your tomato by cutting off the stem, and slicing it in half","Crack your eggs into a bowl and whisk them until homogeneous","Place your sausages onto a oven tray, and begin cooking them for 15 minutes","Place your bacon into a cold pan and begin to cook on high","Once the bacon is crispy on one side, flip and begin browning on the other","When cooked, place the bacon onto a plate with paper towels to drain","If fifteen minutes have passed at this point, take the sausages out of the oven and flip them to get colour on the other side,","Set your pan to medium, and scramble the whisked eggs in the same pan,","Once the egg's curd has set somewhat, push the eggs to the side of the pan and place your tomato into it (cut side down); building colour,","Add your mushrooms to the same pan","Add your baked beans to a pot set to medium. Once they are simmering, they are done","Toast your bread as preferred","If half an hour has passed at this point, take your sausages out of the oven","Plate up by taking each ingredient and giving it its own portion on the plate"],"time":40,"servings":2,"image":"","source":"https://based.cooking/full-english-breakfast","page":"full-english-breakfast","tags":["english","breakfast"]},{"id":"bc-kaiserschmarrn","title":"Kaiserschmarrn","cuisine":"British","category":"Recipe","ingredients":["200g flour","30g sugar","4 eggs","300ml milk","40g butter","30g raisins (optional)"],"steps":["Separate the egg whites and yolks","Put the egg yolks, flour, sugar, pinch of salt, and milk in a bowl and stir until the clumps are gone","Beat the egg whites to stiff peaks in a different bowl and then add to the other bowl","Melt the butter in a flat pan on high heat and then add the dough. Heat up on both sides","Put the pan in the preheated oven (180°C hot air setting) for around 10 minutes or until lightly browned","Cut up the dough with a spatula into bite-sized pieces","Sprinkle some sugar on top (add raisins here)"],"time":10,"servings":3,"image":"","source":"https://based.cooking/kaiserschmarrn","page":"kaiserschmarrn","tags":["sweets","sweet","german","austrian"]},{"id":"bc-korv-stroganoff","title":"Korv Stroganoff","cuisine":"British","category":"Recipe","ingredients":["1/2 kg Swedish falukorv","1 yellow onion","1 tbsp olive oil","4 tbsp tomato purée","2 1/2 dl cream","1 dl milk","1 tbsp soy sauce","1 tbsp Dijon mustard"],"steps":["Cut the sausage into sticks and dice the onion","Fry the sausage and onion in oil for about ten minutes. Add the tomato purée and cook for another minute","Stir in cream, milk, soy sauce and Dijon mustard. Let it simmer for at least five minutes","Season to taste with plenty of pepper, and possibly salt","Serve with boiled rice. Optionally top with freshly ground pepper and/or garnish with chopped parsley"],"time":20,"servings":4,"image":"https://based.cooking/pix/korv-stroganoff.webp","source":"https://based.cooking/korv-stroganoff","page":"korv-stroganoff","tags":["swedish","quick","sausage"]},{"id":"bc-kropsua","title":"Kropsua (Finnish Baked Pancake)","cuisine":"British","category":"Breakfast","ingredients":["1 Cup (stick) unsalted butter","2 Large eggs","2 Tablespoons sugar","1/2 Teaspoon salt","2 Cups whole milk","1 Cup all-purpose flour","1/4 Teapsoon nutmeg","Maple syrup"],"steps":["Set oven to preheat 400 degrees F","While oven is heating up, mix dry ingredients in a large mixing bowl: flour, sugar, and salt","Add milk and eggs to dry ingredients and mix with a hand mixer","Once the oven has reached 400F, add one stick of butter into a 9x13 inch glass baking pan, then place it in the oven for a few minutes until the butter has completely melted. Avoid burning the butter by leaving it in the oven too long","Using heavy oven mitts, remove pan from oven and pour batter into hot pan containing melted butter","Bake for 40 minutes or until the pancake puffs up and is nicely browned","Remove from oven and sprinkle additional small amount of nutmeg over the top of of your kropsua","To serve, cut the pancake into squares. Top with maple syrup and serve immediately"],"time":40,"servings":4,"image":"https://based.cooking/pix/kropsua.webp","source":"https://based.cooking/kropsua","page":"kropsua","tags":["finnish","pancake","breakfast"]},{"id":"bc-quarkbaellchen","title":"Quarkbällchen – Fried curd balls","cuisine":"British","category":"Recipe","ingredients":["420ml quark (plain yoghurt can be used as a replacement)","2 eggs","6 or 7 tbsp of sugar","2 packets of vanilla sugar","400g flour (500g if using yoghurt)","2 packets of baking powder","1L sunflower oil for frying","(Optional) icing sugar","(Optional) Alcohol by eye so that they do not soak up so much oil"],"steps":["Mix ingredients (quark, eggs, sugar, flour, baking powder) in one bowl","Pour the sunflower oil into a cooking pot and heat up the hotplate","Form balls from the dough and put them into the cooking pot","Once they are brown-ish, put them onto a plate","(Optional) add icing sugar","Enjoy!"],"time":null,"servings":null,"image":"https://based.cooking/pix/quarkbaellchen.webp","source":"https://based.cooking/quarkbaellchen","page":"quarkbaellchen","tags":["german","fry","sweet","cheesefare"]},{"id":"bc-risengroed","title":"Risengrød","cuisine":"British","category":"Recipe","ingredients":["Water 3 dl","Pama porridge rice 180 g","Whole milk 1 liter","Salt 2 pinches","Sugar 4 tablespoons","Cinnamon 2 teaspoons","Butter 50 g"],"steps":["Bring water and rice to a boil in a deep pot. Boil the rice at steady heat and with active stirring for approximately 2 minutes","Add milk and bring the concoction to a boil. Boil the pot at low heat, still with active stirring for approximately 10 minutes","Put on lid and boil for approximately 30 minutes. Stir the pot often. If the porridge seems too thin, boil it for another 5-10 minutes","Add salt","Mix sugar and cinnamon to form cinnamon sugar in a bowl or container","Serve warm with cinnamon sugar on top and a bit of butter in the middle","Enjoy!"],"time":40,"servings":2,"image":"https://based.cooking/pix/risengroed.webp","source":"https://based.cooking/risengroed","page":"risengroed","tags":["danish","christmas"]},{"id":"bc-sand-tarts","title":"Sand Tarts","cuisine":"British","category":"Recipe","ingredients":["2 cups sugar","1 cup butter","4 eggs","flour"],"steps":["Work butter and part of the sugar together, then the remainder of the sugar and the eggs should be mixed in. Use enough flour to make very stiff","Roll thin, cut out in small squares, wet top with two eggs beaten, sprinkle with sugar, cinnamon and chopped almonds","Bake in moderate oven, 10 minutes"],"time":10,"servings":null,"image":"","source":"https://based.cooking/sand-tarts","page":"sand-tarts","tags":["cookies","baking","dutch","pennsylvania"]},{"id":"bc-sauerkraut","title":"Sauerkraut","cuisine":"British","category":"Side","ingredients":["1 head of cabbage","2-4% sea salt by cabbage weight"],"steps":["Prepare and clean as many glass jars as you think you'll need","Chop or shred cabbage and rinse under cold water. Sprinkle with salt","Knead the cabbage with clean hands for about 10 minutes until there is enough liquid to cover it","Stuff the cabbage into a glass jar, pressing the cabbage underneath the liquid. If necessary, add a bit of water to completely cover the cabbage","Cover the jar with a tight lid, airlock lid, or coffee filter secured with a rubber band","Culture at room temperature (60-70°F/15-20°C is preferred) for at least 2 weeks, until desired flavor and texture is achieved. If using a tight lid, burp it daily to release excess pressure","Once the sauerkraut is finished, put a tight lid on the jar and move to cold storage. The sauerkraut's flavor will continue to develop as it ages"],"time":null,"servings":null,"image":"https://based.cooking/pix/sauerkraut.webp","source":"https://based.cooking/sauerkraut","page":"sauerkraut","tags":["german","cabbage","side","fasting"]},{"id":"bc-scouse","title":"Scouse","cuisine":"British","category":"Recipe","ingredients":["beef mince","a white onion","garlic","bayleaf","potatoes","carrots","beef stock ~1 pint","beef gravy granules","parsnips(optional)","swede(optional)","cabbage(optional)"],"steps":["Finely dice the onions and garlic. Chop the carrots, potatoes, parsnips and/or swede into a uniform size","Fry the diced onion with a bit of oil until brown, in a deep pot. Then quickly fry the garlic (until you can smell it)","Add the mince whole and sear (flipping to sear the other side before breaking up)","Once the mince is properly browned, Pour in the beef stock","Add your root vegetables now, along with your bayleaf, salt and lots of pepper","Leave to boil for about a half hour then remove the bayleaf. Adding the cabbage half way through","Stir in the gravy granules until you get the thickness you want and Serve"],"time":30,"servings":4,"image":"","source":"https://based.cooking/scouse","page":"scouse","tags":["beef","stew","english"]},{"id":"bc-shepherds-pie","title":"Shepherd's Pie","cuisine":"British","category":"Recipe","ingredients":["600 grams (g) of mealy/floury potatoes","2 onions","2 carrots","4 tablespoons (tbsp.) of oil","800 g of minced lamb","100 g of frozen peas","2 tbsp. of tomato paste/puree","300 milliliters (ml) beef stock","1 tbsp. of sweet or smoked paprika","30 g of butter","200 ml of milk","1 pinch of nutmeg"],"steps":["Peel potatoes, cut into cubes and boil in saltwater for 20 minutes. Peel the onions and carrots and cut into small cubes","Heat the oil in a pan and fry the minced meat until crumbly. Add the onions, carrots and peas. Add the tomato paste and beef stock. Stir well and season with paprika, pepper and salt","Drain potatoes and mash with butter. Add milk, season with nutmeg and stir until creamy","Preheat the oven to 200°C. Grease a casserole dish with butter, put the minced meat in it and spread the mashed potatoes on it with a piping bag. Put the dish in the oven for 30-40 minutes"],"time":40,"servings":8,"image":"","source":"https://based.cooking/shepherds-pie","page":"shepherds-pie","tags":["english","lamb","pie"]},{"id":"bc-soleier","title":"Soleier (pickled eggs)","cuisine":"British","category":"Snack","ingredients":["peels of five onions","10 eggs","2 loorber leaves","3 cloves","4 allspice","1Tbsp peppercorns","1Tbsp caraway seeds","1Tbsp mustard seeds","1tsp of Szechuan pepper (optional)","1tsp lovage (optional)","1tsp nutmeg (optional)","100mL vinegar","3 cloves of garlic"],"steps":["Put 750mL of water and the peels of five onions in a pot and let them cook for five minutes. Remove the peels about twenty minutes later","Put the eggs, one teaspoon of sugar, two tablespoons of salt and all spices (but vinegar and garlic) in the pot, bring it to a boil and cook them for seven minutes","Use a spoon to remove the eggs from the pot and crack them all around. Do not remove the eggshell!","Place the eggs and the garlic in a jar, fill it with the spiced water and add the vinegar. Add water, if needed, so that the eggs are covered","Let them rest for at least three days and at most two weeks at room temperature or slightly below"],"time":10,"servings":10,"image":"https://based.cooking/pix/soleier.webp","source":"https://based.cooking/soleier","page":"soleier","tags":["snack","german","eggs","pub"]},{"id":"bc-spiced-apple-pancakes","title":"Spiced Apple Pancakes","cuisine":"British","category":"Breakfast","ingredients":["1 cup flour","1 large apple, peeled","1 tbsp sugar","1 tbsp cinnamon (or more to taste)","1/2 tsp baking powder","1 tsp vanilla extract","2/3 cup milk","1 egg"],"steps":["In a medium bowl, combine flour, sugar, cinnamon, baking powder, and 1 pinch of salt","Separate the egg yolk and egg white. Add the egg yolk to the dry ingredients","Whisk the egg white until foamy","Slice the peeled apple into thin strips. Alternatively, grate the apple","Combine dry ingredients, apple, vanilla extract, egg white, and milk into a homogenous batter","To a large pan, add 1 tbsp butter. Add the batter (about 3 tbsp per pancake) and cook for 2 min per side on medium-high heat"],"time":10,"servings":8,"image":"","source":"https://based.cooking/spiced-apple-pancakes","page":"spiced-apple-pancakes","tags":["apple","pancake","german","breakfast"]},{"id":"bc-spiced-cantaloupe","title":"Spiced cantaloupe","cuisine":"British","category":"Recipe","ingredients":["3 lbs cantaloupe","1/2 tbsp alum","2 qts water","3 cups sugar","1 pt vinegar","2 sticks cinnamon","1/2 tbsp whole cloves","1 tsp allspice"],"steps":["Pare the cantaloupe, remove seeds and cut into strips, 1x2 inch or squares","Dissolve the alum in the water and bring to a boil","Add the cantaloupe and cook for 15 minutes","Drain well","Combine vinegar, sugar and spices. Add the cantaloupe and simmer slowly until fruit is transparent (about 45 minutes)","Place in hot sterilized jars and seal"],"time":300,"servings":6,"image":"","source":"https://based.cooking/spiced-cantaloupe","page":"spiced-cantaloupe","tags":["cantaloupe","dutch","spiced","pennsylvania"]},{"id":"bc-swedish-pancakes","title":"Swedish Pancakes","cuisine":"British","category":"Breakfast","ingredients":["3 Eggs, beaten","1 tsp Salt","1 tbsp Sugar","1 cup Flour","1 - 2/3 cups Milk","6-8 tbsp Butter"],"steps":["At medium/low heat begin melting the butter, and continue with beating eggs in large bowl, add salt, sugar, milk, flour and mix","Add melted butter while stirring batter","Use about 1/2 cup batter on griddle and tilt until spread evenly over griddle surface","When edges of pancake start to firm-up use spatula and free up the outside inch or two to achieve a clean removal for flipping later","First side will take about a minute or more the second side will take half that time. Pick up at middle of pancake with spatula then place on plate and fold over. The pancake will then be four layers thick 10\" x 2\" long. Serve with syrup on top or anything you choose, my wife likes peanut butter and I prefer to spread a little butter on it before adding syrup. Maybe you prefer adding fruits of your choice"],"time":30,"servings":4,"image":"https://based.cooking/pix/swedish-pancakes.webp","source":"https://based.cooking/swedish-pancakes","page":"swedish-pancakes","tags":["breakfast","swedish","pancake"]},{"id":"bc-yorkshire-puddings","title":"Yorkshire Puddings","cuisine":"British","category":"Side","ingredients":["140g flour","4 eggs","200ml milk","sunflower oil"],"steps":["Preheat oven to 230°C / gas mark 8","Drizzle oil into 24 'cupcake tin' slots. (The pans you make cupcakes in). Heat in oven","Pour flour into bowl","Whisk eggs, add to bowl","Add milk to bowl in small amounts, beating/whisking after each addition. Until there are no lumps in the batter. You may season with salt & pepper","Tip batter into a jug so that you may pour into the cupcake pan slots evenly and carefully","Bake undisturbed ( opening oven will impede the rising ), until the puddings have puffed up and browned"],"time":20,"servings":2,"image":"https://based.cooking/pix/yorkshire-puddings.webp","source":"https://based.cooking/yorkshire-puddings","page":"yorkshire-puddings","tags":["english","side"]},{"id":"bc-dominican-spaghetti","title":"Dominican Spaghetti","cuisine":"Caribbean","category":"Pasta","ingredients":["1 box Spaghetti","1 Onion minced","1 Green Pepper minced","2 Garlic cloves minced","1 tbsp Chicken Bouillon Cube or Adobo","1 tbsp sazón","1 tbsp Tomato Paste","1 cup Tomato Sauce","1 tbsp Butter","¼ cup Evaporated Milk","2 tbsp Green Olives","1 tsp Sugar","1 cup Starchy Pasta Water"],"steps":["Boil spaghetti","In a separate pan, Sauté onions, peppers, and garlic until soft","Add seasonings and black pepper to taste. Mix until well combined","Add tomato paste, sauce, and the pasta water. Mix and let it come to a simmer. Simmer for 5 minutes","Add evaporated milk, butter, sugar, and olives","Taste for seasoning and heat to desired temperature","Add spaghetti and toss into the sauce"],"time":25,"servings":4,"image":"","source":"https://based.cooking/dominican-spaghetti","page":"dominican-spaghetti","tags":["pasta","supper","dominican","cheesefare"]},{"id":"bc-guobaorou","title":"Guobaorou (sweet-and-sour pork)","cuisine":"Chinese","category":"Rice","ingredients":["400g pork tenderloin or loin","250g potato starch or cornstarch","1/2 carrot","2 tbsp tomato paste","2 tbsp sugar","1 tbsp vinegar (rice one ideally. 1 teaspoon if high %)","1L oil (to fry)","1/2 tsp salt"],"steps":["Cut pork into thin slices about 2x2cm wide. They must be grabbable with chopsticks","Mix starch with water into thick cream-like batter. Coat pork slices, massage the batter into the meat. Marinate for 30 minutes. Massage it from time to time","Heat the oil. Fry pork in batches until golden and crispy. Drain on paper towels","Julienne that carrot","Mix 2 tbsp starch with 1 cup cold water","In a deep pan, combine tomato paste, sugar, and a splash (not more) of water. Cook on high heat, stir until bubbly","When the tomato-sugar mix boils, add vinegar and starch slurry. Stir until thickened a little","Toss fried pork. Stir. Add carrot in a bit. Fry until sauce clings to the pork and caramelizes slightly"],"time":30,"servings":2,"image":"","source":"https://based.cooking/guobaorou","page":"guobaorou","tags":["fry","pork","easy","chinese","sweet","rice"]},{"id":"bc-hoisin-pork-belly","title":"Hoisin Pork Belly","cuisine":"Chinese","category":"Recipe","ingredients":["400g high fat pork belly (no skin)","large thumb of ginger","4 cloves of garlic","1 scotch bonnet chili","2 tbsp ketchup","2 tbsp hoisin sauce","2 tbsp honey","2 tsp sesame oil","1 spring onion"],"steps":["Cut pork belly into 1 inch cubes","In a small frying pan place pork cubes fattiest side down in dry pan, put gas on lowest level possible flame, cover with lid. Ideally your pork covers the entire surface of the small pan---crowding is good for this recipe","Lard will render out of the pork allowing it to confit cook in its own juice. Low flame essential. Turn the pork 3 or 4 times until all sides are golden and fat is rendered to melt in mouth levels. This will take around 1hr","Remove pork belly and place in a bowl and cover. Remove around half the liquified lard and store for other uses","Add diced ginger, smashed garlic cloves and chopped chili and sauté in the remaining lard. Once these are softened add the ketchup, hoisin sauce and honey. Reduce over very low heat for a few minutes until thickened","Add the pork belly to the sauce and cook on low for a further 2 minutes. Leave to stand for 5 minutes then add thinly sliced spring onions to garnish. Enjoy with steamed white rice"],"time":75,"servings":2,"image":"https://based.cooking/pix/hoisin-pork-belly.webp","source":"https://based.cooking/hoisin-pork-belly","page":"hoisin-pork-belly","tags":["chinese","pork","spicy","sweet"]},{"id":"bc-hoisin-tofu-and-broccoli","title":"Hoisin Tofu and Broccoli","cuisine":"Chinese","category":"Recipe","ingredients":["One block of firm tofu (400g, extra firm will work too)","1 head (300 grams stemless) of Broccoli","2-4 cloves of garlic, diced","1/2 cup light soy sauce","1 cup dark soy sauce","2 tablespoons sugar","2 tablespoons rice vinegar (or any non-balsamic vinegar)","1/4 cup vegetable stock (or water)","2 tablespoons Shaoxing wine or dry cherry (optional)","1 tablespoon Hoisin sauce","1/2 tablespoon cornstarch","1/2 tablespoon sesame oil","2.5 tablespoon peanut oil (any oil will do)","water","50-100g ginger, diced (optional)"],"steps":["Cut the tofu into 3/4” (2 cm) cubes and place it in a sealable ziplock bag","Combine 1/4 cup soy sauce, 1/2 teaspoon dark soy sauce, sugar and rice vinegar ingredients in a bowl and stir to mix","A food prep rectangular Tupperware could work very well, as you need less marinade to submerge the tofu. Add tofu and refrigerate for half an hour","Combine vegetable stock, remaining soy sauce, wine, sesame oil, cornstarch and hoisin sauce into a bowl and stir until the cornstarch is dissolved","Cut the florets off the stalks of broccoli. Cut into 1cm chunks. Wash and drain if needed","Heat 1/3 cup of water in a large pan over medium/high heat until boiling. Add broccoli and cover with a lid. Steam for 2-3 minutes depending on how hard you want it, then drain and rinse the remaining water off. Put the broccoli aside","Add 2 tbsp of oil on the same pan. Cook tofu until the bottom is golden brown, flip and repeat. Stir a few times, then move to the side of the pan","Add more oil, garlic, ginger. Stir until it releases fragrance - generally less than a minute, then stir to combine the two","Cook together until sauce thickens, then add broccoli and stir to combine"],"time":10,"servings":4,"image":"","source":"https://based.cooking/hoisin-tofu-and-broccoli","page":"hoisin-tofu-and-broccoli","tags":["tofu","vegan","chinese"]},{"id":"bc-dou-sha-bao","title":"Red Bean Buns (豆沙包)","cuisine":"Chinese","category":"Snack","ingredients":["350g (~12 oz) wheat flour","1 sachet (~ 4g / 0.14 oz) baker's yeast","1 teaspoon baking powder","200g (7 oz) sugar","20cl (~ 0,05 gal) water","1 teaspoon sunflower oil","250g (~ 9 oz)red beans Azuki (soak 24h before recipe)","salt","6 baking paper square 7x7cm (~ 3x3inches)"],"steps":["24h after soaking, boil the beans during 5 minutes and rince to clean up impurities","Bring back the beans to simmering point during 1h30/2h. Drain when beans are easily squashable","Mix the beans until smooth paste. Feel free to ad some water if necessary","Put the bean paste in a low-heated pan with 150g (~ 5oz) sugar and a pinch of salt. Stir continuously to dry up the paste during around 10 minutes and let it cool","In a salad bowl, stir the flour, the rest of sugar (~ 50g / 1.7oz), a pinch of salt, the baking powder and baker's yeast","Knead the bun paste during 5 minutes then incorporate the oil, knead again during 2 minutes. Shape a bowl and let it for 1 hour","Shape 6 balls with red beans paste","Press the rested bun paste to remove the gas and knea it up for 1 minute","Sprinkle flour on working plan and make a sausage shape. Cut it in 6 equal shares and shape small balls with it","Spread these bun paste balls to obtain a 10/12cm (~ 4inch) diameter disc","Put the red bean paste in the center of the bun disc paste and close up the bao by making small folds around the ball. Solder well","Dispose baos in a covered steaming basket and let it rest during 10 minutes","After 10 minutes of rest, steam it during 20 minutes. After steaming, let it rest during 5 minutes without uncover it","Enjoy!"],"time":20,"servings":6,"image":"https://based.cooking/pix/dou-sha-bao.webp","source":"https://based.cooking/dou-sha-bao","page":"dou-sha-bao","tags":["chinese","snack","breakfast"]},{"id":"bc-ginataang-kalabasa","title":"Ginataang Kalabasa","cuisine":"Filipino","category":"Recipe","ingredients":["One medium sized squash that is easy to peel (butternut squash is usually best)","Two cans of coconut milk","One onion","A few cloves of garlic"],"steps":["Remove the seeds from your squash, then peel it and chop it up into large cubes, then set aside. (The easiest way to peel the squash while raw is to cut it into strips and cut the skin off of each strip individually)","Chop your onion and garlic and cook in an oiled stock pot until translucent","Once your onions are translucent add both cans of coconut milk to the pot along with your cubes of squash. Let simmer until squash is soft","When your squash is soft take a potato masher and mash about half of your squash leaving the rest of it as cubes","Take off heat and serve over rice"],"time":30,"servings":8,"image":"","source":"https://based.cooking/ginataang-kalabasa","page":"ginataang-kalabasa","tags":["filipino","squash"]},{"id":"bc-kalderetang-manok","title":"Kalderetang Manok","cuisine":"Filipino","category":"Recipe","ingredients":["1 lb of chicken","2 chopped potatoes","2 chopped carrots","1 chopped onion","2 chopped cloves of garlic","1 chopped tomato (optional)","3 cups of water","Tomato sauce","Chopped bell pepper","Dried peas","Liver spread","Fish sauce","Grated cheese"],"steps":["Sauté onions, garlic and (optional) tomato, in a pan of olive oil","Put chicken and cook until brown, add 2 tablespoons of salt and pepper. (Note: Make sure the chicken is cook all the way through.)","Add fish sauce before adding water and let the chicken boil for a few minutes and then add tomato sauce","Add potatoes, carrots, and liver spread. Mix the liver spread and let it boil until broth thickens, let it boil until carrots and potatoes are soft. Add more salt and pepper if needed","Add dried peas, bell pepper and grated cheese and let it cook for a minute","Cook until cheese melts before serving"],"time":60,"servings":5,"image":"","source":"https://based.cooking/kalderetang-manok","page":"kalderetang-manok","tags":["filipino","chicken"]},{"id":"bc-pininyahang-manok","title":"Pininyahang Manok","cuisine":"Filipino","category":"Recipe","ingredients":["1 lb chicken, cut into serving pieces","1 cup pineapple chunks","1 cup pineapple juice","2 chopped carrots","1 red bell pepper, sliced","1 chopped onion","3 cloves garlic, minced","1 cup evaporated milk (optional for creamy version)","2 tbsp fish sauce","Salt and pepper to taste","2 tbsp cooking oil"],"steps":["Heat cooking oil in a pan and sauté onions and garlic until fragrant","Add chicken pieces and cook until lightly browned","Pour fish sauce and stir for a minute","Add pineapple juice and simmer for 15–20 minutes until the chicken becomes tender","Add carrots and pineapple chunks, then continue cooking until vegetables soften","Pour evaporated milk for a creamy texture (optional)","Add bell peppers and season with salt and pepper","Simmer for another 3–5 minutes and serve hot"],"time":45,"servings":5,"image":"","source":"https://based.cooking/pininyahang-manok","page":"pininyahang-manok","tags":["filipino","chicken","pineapple"]},{"id":"bc-belgian-pear-syrup","title":"Belgian pear syrup","cuisine":"French","category":"Recipe","ingredients":["7 pears (Quality doesn't matter; you can argue that overripe pears are better because they have more sugar content.)","3 apples","a small handful of dates, raisins, dried apricots or prunes (optional -- you can experiment with these; they can bring out some nice flavors.)","150 grams sugar","1 glass of water","find sieve or cheese cloth","glass jar"],"steps":["Wash the outside of the fruit with water and cut it in 8 medium sized pieces. You don't have to core or deseed the fruit; everything can go in the pot","Place the fruit in a large pan with a thick bottom so you get even heat. I suggest you place the pears on the bottom, since they don't burn as fast. Add the glass of water","If you are using them, add the dried fruits at this point","Put the heat as low as possible and let it all slowly stew for 3 hours, stirring every now and then","At this point, you can boil your glass jars to sterilize them. Place the sterilized jars on a clean, dry towel","When the fruit is done cooking for 3 hours, grab your sieve or cheese cloth, and place it over a bowl, run your fruit through it until you have extracted all the clear liquid. You can discard the pulp","Quickly rinse the pot with water until clean and add the fruit liquid back. Place back on the stove","Add the sugar. Add a bit less sugar if you also used dried fruits","Cook for another 2 hours. After that, stir every so often, Be careful with the stirring; if you stir too often, it might caramelize too quickly","After two to two and a half hours, your syrup should be nearly done","At this point, it's up to you on how thick you want your syrup to be. A good way to test the viscosity is to drop a little bit on a cold plate or on your countertop to see how it is at room temperature","When you are happy with the viscosity, pour the syrup into your sterilized jars and immediately seal them"],"time":360,"servings":null,"image":"","source":"https://based.cooking/belgian-pear-syrup","page":"belgian-pear-syrup","tags":["syrup","fruit","belgian"]},{"id":"bc-breton-crepes","title":"Breton Crêpes (Breton Galettes)","cuisine":"French","category":"Recipe","ingredients":["500g buckwheat flour","1 egg","70cl water"],"steps":["Mix flour, salt, egg and water. (In this order to avoid dry flour)","Let it rest one hour at room temperature","Cook the galette on a crepe-maker or a big flat pan","When garnishing, heat the galette again with a bit of salted butter"],"time":null,"servings":null,"image":"","source":"https://based.cooking/breton-crepes","page":"breton-crepes","tags":["french","cheesefare"]},{"id":"bc-chicken-in-red-wine-vinegar-sauce","title":"Chicken in Red Wine Vinegar Sauce","cuisine":"French","category":"Recipe","ingredients":["3 tablespoons/~44 milliliters extra-virgin olive oil","1 tablespoon/~14 grams unsalted butter","1 whole chicken, cut into 10 pieces (alternatively, use breasts or legs)","4 shallots, finely chopped","1 cup/720 milliliters red wine vinegar","1 cup/240 milliliters crème fraîche or heavy cream","Finely chopped parsley (optional)"],"steps":["Rub each piece of chicken in salt and pepper mixture","Heat oil and melt butter in deep-sided, 12-inch (~30 centimeter) sauté pan on medium-high heat. When the oil is hot, but not smoking, use tongs to add chicken skin side down","Brown both sides until skin is golden brown and chicken is cooked, about 12-15 minutes. Remove chicken to a platter and cover loosely with aluminum foil to keep warm","Pour out half of oil from pan, and use other half to brown shallots over medium-high heat. Slowly add vinegar and boil until reduced to almost a syrup. Add crème fraîche/cream and cook until blended and brown, about 5 minutes. Return chicken to pan to coat and heat","Return chicken to platter. Add garnish if available, and serve"],"time":25,"servings":6,"image":"","source":"https://based.cooking/chicken-in-red-wine-vinegar-sauce","page":"chicken-in-red-wine-vinegar-sauce","tags":["chicken","french","wine"]},{"id":"bc-classic-bechamel-sauce","title":"Classic béchamel sauce","cuisine":"French","category":"Sauce","ingredients":["5 Teaspoons unsalted butter","5 Teaspoons flour","1 litre whole milk","Salt to taste","Pepper to taste","Pinch of nutmeg"],"steps":["Put your butter in your pot and let is slowly melt on medium to low heat","Once the butter is fully melted add the flour and stir it in to make a roux","Keep stiring your roux on medium low heat until it gets lightly golden brown and starts melling a bit nutty","Add about a glass of your whole milk and stir until combined, repeat this process until you have a thick sauce in your pan and new milk you add easily combines. Never stop stirring","At this point you can add the rest of your milk, if you skip the previous step you will end up with lumps of roux that are hard to get out","Lower your heat to low and keep stiring don't forget to get in the corners of the pot because your sauce will burn easily","Once your sauce has the desired thickness give it a taste and add your salt and pepper until it is to your liking. A pinch of nutmeg, preferably freshly grated, will also go a long way"],"time":20,"servings":null,"image":"","source":"https://based.cooking/classic-bechamel-sauce","page":"classic-bechamel-sauce","tags":["basic","sauce","french","italian"]},{"id":"bc-croque-monsieur","title":"Croque-monsieur bites","cuisine":"French","category":"Recipe","ingredients":["For the bechamel","50g Butter","50g Flour","1 Liter of milk","Salt","Ground Pepper","Nutmeg","For the bites","12 Slices of bread","2 Tbsp of Mustard","12 very thin slices of ham with Italian herbs","80g grated cheese (Emmental, Comté Gruyère Mimolette"],"steps":["Prepare the béchamel: melt the butter in a heavy-bottomed saucepan","As soon as it foams, sprinkle it with flour, salt, pepper, add a pinch of nutmeg, mix","Then pour in the milk, little by little (especially not all at once), stirring with a whisk each time, until the sauce thickens","Turn on the oven on th. 6/180°, take the baking sheet out of the oven and line it with aluminum foil","Spread 6 slices of bread in front of you, spread them with a little mustard, add a layer of béchamel, 1 slice of ham folded in 4, grated cheese, a layer of béchamel, put the other 6 slices of bread on the on top, add a thin layer of béchamel and distribute the rest of the grated cheese","Arrange the croque-monsieur on the baking sheet and put them in the oven for about 10 minutes","You can place them under the broiler for 3-4 minutes at the end"],"time":10,"servings":6,"image":"https://based.cooking/pix/croque-monsieur.webp","source":"https://based.cooking/croque-monsieur","page":"croque-monsieur","tags":["quick","cheese","french"]},{"id":"bc-croutons","title":"Croutons","cuisine":"French","category":"Salad","ingredients":["Hearty White Bread","Extra Virgin Olive Oil","Spices"],"steps":["Preheat oven to 350°F (roughly 180°C). Gently cut slices of white bread into squares with a chef's knife. One to two slices is usually enough for one person","In a large bowl combine olive oil, spices, and bread squares and gently mix to thoroughly season bread. Spices can be anything but I recommend oregano, paprika, black pepper, garlic powder or freshly minced garlic, and a small pinch of cayenne","Spread seasoned bread squares large face down onto a baking sheet evenly and put in oven for 6-8 minutes. Once the bread has crisped flip each square and put back in oven for another 6-8 minutes or until crispy throughout","Once fully baked, let rest until cool. These can be eaten immediately or saved in a sandwich bag for later"],"time":null,"servings":null,"image":"https://based.cooking/pix/croutons.webp","source":"https://based.cooking/croutons","page":"croutons","tags":["basic","french","salad","fasting"]},{"id":"bc-creme-brulee","title":"Crème brûlée","cuisine":"French","category":"Dessert","ingredients":["400 ml high fat cream","140 ml whole milk","85 g sugar (preferred brown)","5 egg yolk","1 vanilla bean (mark, optionally essence)","Lemon peel, rubbed","Sugar for the top crust"],"steps":["Mix cream, milk and yolks","Add sugar, vanilla and lemon","Let rest for at least 30 min (optionally over night)","Pour into 4-6 fireproof ramekins","Pre-heat oven to 150°C and put the grease pan on the middle rail","Put the ramekins onto the grease pan and fill it with boiling water","Let the crème cook for 55 min","Let the ramekins cool down to room temperature and put them in the fridge for at least 2 hours","Spread a teaspoon of sugar onto each ramekin","Use a blowtorch to flambé the sugar. Alternatively the grill of your oven may work too"],"time":30,"servings":4,"image":"","source":"https://based.cooking/creme-brulee","page":"creme-brulee","tags":["dessert","french"]},{"id":"bc-demi-glace","title":"Demi-glace","cuisine":"French","category":"Sauce","ingredients":["1 qt (32 oz, 946mL) low-sodium broth or stock (I prefer Pacific Foods)","1 1/4 oz (7g) packet unflavored, unsweetened gelatin","1 teaspoon (5mL) tomato paste","1 teaspoon (5mL) low-sodium soy sauce","1/2 teaspoon onion powder ( very optional)"],"steps":["Put the tomato paste in a large pot, then turn the heat on medium","Spread the paste around the bottom of the pot and stir until it just barely starts to brown","Deglaze with the broth","Stir in all other ingredients and boil over high heat until reduced to about 1/6th of its original volume","Freeze in ice cub trays"],"time":null,"servings":null,"image":"","source":"https://based.cooking/demi-glace","page":"demi-glace","tags":["sauce","basic","french"]},{"id":"bc-farci-tomatoes","title":"Farci tomatoes","cuisine":"French","category":"Recipe","ingredients":["2 tomatoes per person","300g of ground beef meat","1 or 2 onions","Condiments of your choice: parsley, origan or cumin","Olive oil","Gruyere cheese","Salt and pepper","Butter (optional)"],"steps":["Heat the oven to 200C","Slice the top to the tomatoes and place them in the oven tray","Empty the tomatoes using a spoon and reserve the interior of the tomatoes in a bowl","Mix the interior of the tomatoes with the rest of the ingredients","Restuff the tomatoes","Optionally add a thin layer of butter on top of the tomatoes","Put the \"lid\" on the tomatoes","Bake for 40 minutes in the oven","Enjoy!"],"time":40,"servings":4,"image":"https://based.cooking/pix/farci-tomatoes.webp","source":"https://based.cooking/farci-tomatoes","page":"farci-tomatoes","tags":["french","tomato","oven"]},{"id":"bc-flammkuchen","title":"Flammkuchen","cuisine":"French","category":"Recipe","ingredients":["400g Pizza dough (either bought or from Pizza Dough)","1 onion (I prefer the red ones for optical reasons)","150g bacon (you can replace it with mushrooms or other vegetables)","2 big spoons of sour creme or creme fraiche"],"steps":["we start by flattening the dough. Even if you buy thin crust that is already sold as 'super thin' you have to make it even thinner. Make it so thin that you can fill 2 baking sheets with it (yes, you will make two large flammkuchen - since they are thin you need one per person) :) I take two pieces of parchment paper, put the dough in between and flatten it using a bottle (e.g. wine). It has to be as thin as possible (1-2 mm)","once the dough is flat, put it on your baking tray and preheat the oven at 450 to 500 Fahrenheit (230 to 260 Celsius)","distribute the sour cream evenly (it should be a very thin layer, just barely covering the dough","cut the onion and bacon into small pieces and distribute onion, bacon/vegetables (also in small pieces) evenly","put in the oven for 10 minutes and take it out when it is getting a bit dark. The thin parts will get a bit brown","put salt and pepper"],"time":null,"servings":2,"image":"","source":"https://based.cooking/flammkuchen","page":"flammkuchen","tags":["french","pork","quick"]},{"id":"bc-fondue","title":"Fondue","cuisine":"French","category":"Recipe","ingredients":["1 garlic clove","4 dl (1.5 cups) white wine","800 g (1.7 lbs) swiss cheese (50/50 mix of Gruyère and Emmentaler recommended)","1 shot of kirsch (cherry brandy)","1 tsp lemon juice","1-2 tbsp starch flour","1 loaf (~800g/~1.7 lbs) of white bread","A pinch of nutmeg"],"steps":["Rub the Pot with garlic clove","Cut bread into small squares","Put cheese, starch, wine and lemon juice in pot and melt while stiring constantly","Season with a bit of pepper and nutmeg","Serve right away","Stick bread squares on fondue fork one by one and stir them in the fondue"],"time":30,"servings":4,"image":"","source":"https://based.cooking/fondue","page":"fondue","tags":["swiss","cheese"]},{"id":"bc-french-crepes","title":"French Crêpes","cuisine":"French","category":"Dessert","ingredients":["300g white flour","3 eggs","60cl milk","20cl beer","30g butter or 3 tablespoons of oil"],"steps":["Mix flour, salt, eggs and melted butter or oil. (In this order to avoid dry flour)","Slowly add milk and beer until the dough becomes fluid enough. (Pouring it from the ladle has to be fluid)","Let it rest one hour. (optional)","Cook the crêpe in a flat pan, one ladle at a time"],"time":null,"servings":null,"image":"","source":"https://based.cooking/french-crepes","page":"french-crepes","tags":["french","dessert","breakfast","cheesefare"]},{"id":"bc-french-mustard-sauce-porkchops","title":"French mustard sauce porkchops (Côtes de porc charcutières)","cuisine":"French","category":"Recipe","ingredients":["porkchops: 4","shallots: 2","gerkins: a dozen medium sized ones","white wine: 350ml | 1 1/2 cup","brown stock: 100ml | 1/2 cup","mustard: 2tbsp","butter","olive oil"],"steps":["Cut the shallots into small dices","Cut the gherkins into long strips","Sear the porkchops on high heat on cast iron or stainless steel pan until golden brown on each side, and cook them through on lower heat","Once the porkchops are cooked, set them aside in a warm environment","Sweat the shallots in the same pan","Deglaze with white wine, let it reduce until there's about two teaspoons left","Add the stock","Add the gherkins","Mix in the mustard","Let the sauce reduce until it gets a coating consistency","Mix in a knob a butter","Put the chops back in, flip them to coat them in sauce, warm them up for 30 seconds","Serve with a nice mashed potato or saute potatoes"],"time":null,"servings":4,"image":"","source":"https://based.cooking/french-mustard-sauce-porkchops","page":"french-mustard-sauce-porkchops","tags":["french","pork","quick"]},{"id":"bc-french-onion-soup","title":"French Onion Soup","cuisine":"French","category":"Soup","ingredients":["6-7 Onions, cut into quarter moons","1 stick of butter","1/2 cup Olive oil","Salt, to taste","1 Baguette Loaf, sliced","1 Can of Chicken Broth","3 Garlic cloves, finely chopped","1/4 cup brown sugar","Balsamic vinegar, to taste","Worcestershire Sauce, to taste","Soy Sauce, to taste","64oz Beef Broth","2-3 Bay Leaves","Melty cheese, preferably guereye or swiss"],"steps":["Sweat the onions in a covered Dutch oven over med-low heat, salt them, with 1 whole stick of butter and some olive oil for about 2 hours stirring occasionally but increasing in frequency as the heat gets raised over time","When the onions are soft and mostly shrunken down, and mostly covered by the butter, oil, and onion juice, strain and collect the juice in a bowl. Brush the onion juice over each side of slices of baguette bread","Return the strained onions to med-high heat, uncovered, stirring and deglazing with chicken broth frequently but not so frequent that they turn to mush. When the entire can of chicken broth has been added for deglazing, add 3 finely chopped garlic cloves, 1/4 cup brown sugar, balsamic vinegar, Worcestershire sauce, soy sauce. Wait until the pot dries and a fond is formed in between adding each liquid ingredient slowly. Keep slowly deglazing with the wooden spoon and caramelizing those onions","After onions are thoroughly caramelized and there are no more liquid ingredients to add, pour in 64oz beef broth and 2-3 Bay leaves. Cover on medium heat until it simmers. It is now ready to serve!","Put sliced (and onion-juice brushed) bread in 400F oven until toasted, then under the broiler covered in cheese until melted. Soup can be served poured over the bread slices or the bread floating on top"],"time":180,"servings":5,"image":"","source":"https://based.cooking/french-onion-soup","page":"french-onion-soup","tags":["french","soup"]},{"id":"bc-french-toast","title":"French Toast","cuisine":"French","category":"Breakfast","ingredients":["2 Eggs","1/2 Cup of milk (1/4 for a more solid consistency)","5 Slices of bread","Maple Syrup (Optional)","Butter"],"steps":["Butter up a frying pan and set it on the burner with low-medium heat.(May need to add more butter in-between slices)","Take your two eggs and crack them into a bowl together","Pour milk in the bowl with the eggs","Break the yolks and stir the eggs and milk well with a beater until it's a smooth, yellow liquid","Dip one side of bread into the bowl, making sure the liquid gets into all of the surface area of that side","Immediately bring the side back up and scrape off any access liquid on the side with a butter knife","Repeat steps 5-6, but for the other side of the bread","Drop into the hot pan","Cook both sides until golden brown, then plop onto a plate","Repeat steps 5 to 9 until you have cooked all of your bread","Drench french toast stack in Maple syrup (Optional)"],"time":25,"servings":1,"image":"https://based.cooking/pix/french-toast.webp","source":"https://based.cooking/french-toast","page":"french-toast","tags":["breakfast","french"]},{"id":"bc-gluehwein","title":"Glühwein - mulled wine","cuisine":"French","category":"Drink","ingredients":["300 ml Cassis-Juice (Johannesbeer), if you can't find it you can replace it with another juice, I did it e.g. with cranberry pomegranate juice","1 bottle 700ml red wine (I prefer Primitivo/Zinfandel), don't buy a cheap cooking wine, you want to drink it :)","50 g Sugar","25 g Raisins","1 orange","1 cinamon bark","1 spoon ginger powder (or a bit of fresh ginger)","1 spoon cloves","5 star anise","if you don't have the spices you can also just throw in sweet cinamon tea bags instead (or similar), they contain most spices - I took 6 teabags for 1 litre"],"steps":["cut the orange in nice looking pieces (since they are mainly decoration)","throw everything in a pot","warm up (don't boil)","enjoy"],"time":null,"servings":1,"image":"","source":"https://based.cooking/gluehwein","page":"gluehwein","tags":["drink","quick","swiss","german","french"]},{"id":"bc-lobster-bisque","title":"Lobster bisque","cuisine":"French","category":"Soup","ingredients":["1 live lobster that weighs ~750 grams","2 onions","2 carrots","1 shallot","2 garlic cloves","cognac","3 tbsp concentrated tomato puree","4 tomatoes","3 tbsp flour","1 glass dry white wine","2 litres fish stock","1 bayleaf","2 twigs of thyme","fresh parsley","heavy cream","olive oil","2 tbsp butter"],"steps":["Finely dice the onions, carrots, shallots and garlic and set aside for later","Blanche the lobster in boiling water for 2 minutes, remove from the water and let it leak","Cut it down the middle and remove the meat from the shell, set the meat aside for later","Place a stockpot on medium high heat and heat up enough oil to cover the bottom of the pan, add the lobster shells and cook them until they are bright red","Remove the oil from the pan and discard it, add your butter to the shells","Add all diced vegetables and let it sauté for 2 minutes, add a dash of cognac and flambé, lower the heat to medium low","Roughly dice the tomatoes and add them together with the tomato puree, once again let it sauté for 2 minutes","Add the flour and give it all a stir, let it dry up in the pan","Deglaze the pan with the white wine and once the wine has dried up a bit add the fish stock","Tie up your herbs using kitchen twine and add them to your pot","Let it simmer on low heat for 30 minutes, while the soup is boiling take the lobster meat and dice it into bite-sized pieces","After the soup is done boiling run it through a fine sieve","Bring the strained soup back to a light boil and add the diced lobster pieces","Let the soup boil for 4 more minutes to heat up the lobster and serve, add pepper and salt to taste","Finish off in the plate with a bit of heavy cream"],"time":30,"servings":2,"image":"","source":"https://based.cooking/lobster-bisque","page":"lobster-bisque","tags":["french","seafood","soup"]},{"id":"bc-quiche","title":"Quiche Lorraine - Lothringer Käsetorte","cuisine":"French","category":"Recipe","ingredients":["200g Flour (full sight)","100g Butter or Margarine","5 Tablespoons of Water","200g of Ham (alternatively cooked ham)","4 Eggs","1/4 Cream","125g grinded Edamer Cheese","For the Baking Tin: More Butter and Flour"],"steps":["Spread some butter on a 26cm Ø or two smaller baking tins and cover it with flour","Sieve the flour, mingle the butter/margarine in small flakes","Form a depression in the middle of the flour and add spoons of water","Mix all ingredients by hand until the dough becomes a homogenious mass","Wrap the dough in aluminium foil and let it rest in the fridge for two hours (around -4 °C)","Preheat the oven at 200°C","Spread the dough on a flour-covered surface. Roll it until it has a thickness of around 4mm. Form a crust on the sides","Use a fork to prick the dough for a more thorough heat penetration","Cut the ham in slices and distribute them evenly on the dough","Divide the yolk from the egg white","Whisk the yolk with cream","Add the grinded cheese","Whisk the egg white until it becomes foamy. Add it to the yolk-pepper-salt-cheese mixture","Cover the ham in the baking tin with the mixture. Equalize the surface","Bake the Quiche in the oven on the middle rail for 30 minutes","After baking leave it to rest for a few minutes, then serve while it's still warm"],"time":30,"servings":4,"image":"","source":"https://based.cooking/quiche","page":"quiche","tags":["cheese","french","ham"]},{"id":"bc-ratatouille","title":"Ratatouille","cuisine":"French","category":"Soup","ingredients":["3 1/2 lbs Tomatoes","1 1/2 lbs Eggplant","1 lb Zucchini","3 Bell Peppers","2 lbs Onions","6 cloves Garlic","Herbes de Provence (Basil, Thyme, Parsley)","Olive Oil","Salt","Pepper","140g Tomato Paste (optional if tomatoes aren't yummy)"],"steps":["Peel and drain the tomatoes (don't mind the seeds): cut out the stem cores; drop the whole tomatoes into boiling water for 2 minutes. Remove into a colander. The skin should split for easy removal; otherwise, make an X cut in the top, then peel off the skin","Chop the onion and garlic. Clean the bell pepper, cut into small strips","In a large cooking pot with thick bottom, put in olive oil, onions, and chopped garlic. Add in the bell pepper. Cover to keep in the moisture. Cook for 20 minutes, stirring frequently, and add olive oil as necessary to prevent burning","Add the tomatoes and Herbes de Provence. If you don't have good garden tomatoes with flavour, add a small can of tomato paste. Stir well and cook for another 15 minutes","Cut the eggplant into disks. Cut zucchini into disks","Add the eggplant and zucchini to the pot","Cook for about 30 minutes"],"time":75,"servings":12,"image":"","source":"https://based.cooking/ratatouille","page":"ratatouille","tags":["soup","french","tomato"]},{"id":"bc-roesti","title":"Rösti","cuisine":"French","category":"Side","ingredients":["~800g (~1.5lb) potatoes (firm/waxy)","2 carrots","500g (~1lb) peas or spinach","4 eggs","2 onions (medium size)","butter"],"steps":["Shred raw or cooked (but cool) potatoes with a grater. The shreds should be","Dice the first onion and mix together with potatoes. You can also add diced","Heat up some butter in a large pan. Add your mix to the pan on high heat","Reduce heat to medium-high. Form the Rösti into a round cack. It should fill","Add some more butter flakes around the inside of the pan to get it under the","It can take quite a while for a nice crust to form. Check after roughly 5-10","While the Rösti is cooking dice the other onion and the carrots. Steam","Alternatively you can use fresh or creamed spinach","When you're satisfied with the browning, flip the Rösti and set the heat to","When the Rösti crispness is to your liking, remove from pan and fry two","Top Rösti with eggs and serve with the peas or spinach"],"time":20,"servings":4,"image":"https://based.cooking/pix/roesti.webp","source":"https://based.cooking/roesti","page":"roesti","tags":["swiss","potato","side","cheesefare"]},{"id":"bc-schinkenfleckerl-gratinated","title":"Schinkenfleckerl überbacken, Viennese Mac'n'Cheese","cuisine":"French","category":"Recipe","ingredients":["1kg ham or smoked rolled roast","1kg cooked fusilli noodles or small square flat noodles (=Fleckerl)","500 ml cream","500 ml sour cream","1-2 eggs","Majoran, Muskat, Pepper","Optional","parmesan","chili flakes"],"steps":["Start cooking noodles","First slice, then cube ham into smaller than 1cm³ pieces","Whip cream in a big bowl","Add spices, eggs and sour cream to bowl and stir","Put ham cubes in and stir","Put noodles without water into bowl and mix","Put the mixture into one or two baking pans (with baking paper)","Bake at ~160°C for ~2 hours","Optionally gratin mozzarella or any other cheese on top for 5-10 minutes"],"time":120,"servings":8,"image":"","source":"https://based.cooking/schinkenfleckerl-gratinated","page":"schinkenfleckerl-gratinated","tags":["austrian","ham","noodles"]},{"id":"bc-schnitzel","title":"Schnitzel","cuisine":"French","category":"Recipe","ingredients":["4 veal cutlets (1 ~ 150g)","2 eggs","1 lemon","100g flour","150g bread crumbs","100g butter (or even better clarified butter)"],"steps":["Prepare 3 bowls. (One with flour, one with beaten eggs, one with bread crumbs seasoned with salt and paprika)","Wash the veal and gently dry it with kitchen roll","Put the veal on a board and beat it with a meat tenderizer (or a rolling pin) to a thickness of 0.5 cm. (Beating the veal makes it tender)","Season the veal with salt and pepper on both sides, dive it through the 3 bowls. (First flour, then eggs, finally bread crumbs)","Melt the butter in a deep pan. (Attention: not too hot. Butter should not turn brown)","Fry the veal on each side until it is gold brown. (e.g. 3 min on each side)","Serve with a piece of lemon"],"time":6,"servings":4,"image":"https://based.cooking/pix/schnitzel.webp","source":"https://based.cooking/schnitzel","page":"schnitzel","tags":["austrian","beef"]},{"id":"bc-smoked-salmon-quiche","title":"Smoked Salmon Quiche","cuisine":"French","category":"Recipe","ingredients":["1 3/4 cups Flour","1 cup + 2 1/2 Tbsp Butter, divided","Up to 1/3 cup Water, chilled","1/2 cup Onion, finely chopped","14 ounces Smoked Salmon, chopped","2 tsp Fresh Chives, chopped","1 clove Garlic, chopped","2 tsp Fresh Basil, chopped","5 whole Eggs","1 cup Milk","1 cup Whipping Cream"],"steps":["Combine all pastry ingredients in a food processor (mix flour and butter, then add water gradually while mixing)","Gather into a ball, cover with plastic wrap and chill 1 hour","Saute onion until shiny in the butter","Stir in salmon, chives, garlic, and basil. Cool","Preheat the oven to 400F","Roll out the dough to fit a 10\" tart pan. Prick with a fork","Arrange the salmon mixture in the pre-baked tart shell","Whisk eggs with milk and cream, season with pepper and pour in the tart shell","Bake about 30 minutes at 325F, until puffed and golden"],"time":30,"servings":6,"image":"","source":"https://based.cooking/smoked-salmon-quiche","page":"smoked-salmon-quiche","tags":["fish","eggs","french"]},{"id":"bc-stoemp","title":"Stoemp","cuisine":"French","category":"Recipe","ingredients":["500g potatoes","300g carrots","100g bacon","50g butter","100ml heavy cream","1/2 teaspoon ground nutmeg"],"steps":["Cut bacon into bits","Sauté bacon until well colored","Peel and dice into small chunks potatoes, peel and slice carrots","Boil for 20-25 minutes potatoes and carrots in salted water","Drain vegetables and mash with a fork, so that the texture remains slightly chunky","Mix with bacon bits, butter, cream, nutmeg, salt, pepper"],"time":30,"servings":4,"image":"","source":"https://based.cooking/stoemp","page":"stoemp","tags":["belgian","potato"]},{"id":"bc-stoofvlees","title":"Stoofvlees","cuisine":"French","category":"Recipe","ingredients":["2 Large onions","1 tablespoon butter","1kg chuck roast, cut in bite-sized pieces","2 33cl bottles of brown beer","2 bayleaves","2 twigs of thyme","1 clove (spice)","2 tablespoons of belgian apple/pear syrup (optional, ill write up a recipe for this soon)","2 teaspoons of vinegar","1 slice of bread","mustard"],"steps":["Peel the onions and cut them into medium sized pieces, don't cut the onion too small","Place a large saucepan or dutch oven on low heat and add 1 tbsp butter. Once melted add your onions, cook until translucent","While your onions are cooking place a large frying pan on medium high heat and melt your second spoon of butter","Fry up your beef until it has a nice brown crust, to prevent overcrowding the pan you should sear the meat in separate batches, be careful to not burn the fond on the bottom of the pan.season the meat with salt and pepper while its cooking","When a piece of beef is done searing add it to the pot with the onions, once you're done searing all of your meat add your beer to the frying pan and use it to deglaze, scrape off all the pieces stuck to the frying pan","Add the beer you used to deglaze to the pot with the onions and beef","Add the bayleaf and thyme, optionally you can bind them together with some kitchen twine so they are easier to pick out later","Add your clove and if you have it the syrup","Take your piece of preferably brown bread and generously spread it with mustard on both sides, place it in the sauce","let it simmer on low heat, stirring once every 10-15 minutes. when the sauce has reached your desired thickness place a lid on the pot","The cooking time will depend on the quality of your meat, start checking the if your meat is done once its been simmering for about 2 hours","The meat is done when the pieces hold together when gently stirring the sauce, but are easily cut with a fork or spoon","Finish the sauce by gently stirring in the vinegar to brighten up the flavors and serve"],"time":240,"servings":4,"image":"","source":"https://based.cooking/stoofvlees","page":"stoofvlees","tags":["beef","stew","belgian"]},{"id":"bc-tiroler-groestl","title":"Tiroler Gröstl","cuisine":"French","category":"Recipe","ingredients":["1 kg / 2 lbs potatoes","2 red onions","500 g / 1 lbs porkchops","400 g / 14 ounce bacon (smoked)","5 eggs","3 cloves of garlic","Ample amount of chopped parsley","Marjoram and cumin to taste"],"steps":["Clean potatoes and boil with skin","Chop onion, squeeze and mince the garlic","Dice pork and bacon","Slice cooked potatoes in thick wedges","Fry potato wedges in butter, add more butter while stirring","Add pork and bacon and bake until crispy","Add and stir the rest of the ingredients, except eggs","Fry the eggs separately and serve on top"],"time":30,"servings":5,"image":"","source":"https://based.cooking/tiroler-groestl","page":"tiroler-groestl","tags":["austrian","bacon","potato"]},{"id":"bc-zopf","title":"Zopf","cuisine":"French","category":"Bread","ingredients":["1kg white wheat flour","½L milk","125g butter","14g dry yeast","1½T salt","1 egg"],"steps":["Cut or tear up butter and put in skillet with milk on low heat (This is so the ingredients are not too clod, temperature should not exceed 31 C)","Put the flour in a large bow with the yeast, salt, milk and butter","Mix and kneed for at least 15 minutes making sure to stretch the dough a lot","Let the dough rest in a warm spot for at least one hour (temperature should not be higher than 31 C)","Start heating an oven at 200 C (no need to preheat, it will be a good temperature once you are done braiding)","Cut the dough in two or three sections (different according to region), then stretch and roll into long pieces","Braid the strips, place on a parchment lined baking sheet and brush down with a beaten egg","Bake for 30 minutes testing with a wooden skewer in the widest part when done. IF the skewer comes out clean, you are done, if not add 5 minutes and repeat","Wait for the bread to cool before cutting"],"time":30,"servings":null,"image":"","source":"https://based.cooking/zopf","page":"zopf","tags":["swiss","bread","cheesefare"]},{"id":"bc-zurich-sytle-meat-saute","title":"Zurich-Style Meat Saute","cuisine":"French","category":"Recipe","ingredients":["600g Beef, finely sliced","250g Mushrooms, finely sliced","1 Onion","1 tbsp Flour","200ml White whine","200ml Cream","1 tbsp chopped parsley"],"steps":["Fry the meat in butter at high heat until it starts loosing liquid","Take the meat out of the pan and set aside","Saute the onions","Add the mushrooms, saute, then add a tbsp of flour and mix well. The flour","Add the white wine and let it boil for a few minutes","Add cream, boil until the sauce is very creamy","Add the meat, boil until the meat is warm","Add parsley, and serve"],"time":15,"servings":4,"image":"","source":"https://based.cooking/zurich-sytle-meat-saute","page":"zurich-sytle-meat-saute","tags":["beef","cream","swiss","quick"]},{"id":"bc-aelplermagronen","title":"Älplermagronen (Alpine macaroni)","cuisine":"French","category":"Pasta","ingredients":["~150g (1/3 lb) bacon cubes","3 onions (medium size)","400g (15 oz) potatoes (firm/waxy)","1 - 2L (1/4 - 1/2 gal) milk","400g (15 oz) macaroni (dry weight)","~150g (1/3 lb) medium soft cheese. Appenzeller works best. Gruyère would be my go-to alternative","a jar of apple sauce"],"steps":["Fry bacon cubes in pot (this pot will be used for everything so choose an appropriately large one)","Cut onions into half-rings and let them sweat in the same pot. Add some butter if your bacon was not fatty enough","Peel potatoes and cut them into ~1 cm/half inch cubes","When the onions have become sufficiently cooked, add potatoes","Top everything with milk and let the potatoes cook for about 10 minutes","Add macaroni and the remaining milk to cover everything. Most of the milk will be absorbed by the macaroni","Shred your cheese","A minute or two before the macaroni are done, add the shredded cheese into the pot. It should appear a bit too runny in the pot. While cooling it will increase in viscosity quite a bit. If the final texture is not creamy enough, it is most likely due to using the wrong cheese","Season to taste. (Needs quite a bit of salt). Nutmeg also works well here","Serve with apple sauce. Should be eaten together, not as a dessert"],"time":30,"servings":4,"image":"https://based.cooking/pix/aelplermagronen.webp","source":"https://based.cooking/aelplermagronen","page":"aelplermagronen","tags":["swiss","pork","potato","pasta"]},{"id":"bc-babas-feta-pasta","title":"Baba's Feta Pasta","cuisine":"Greek","category":"Pasta","ingredients":["Medium Sweet Onion (Finely Chopped)","Virgin olive oil (not extra-virgin)","White Sugar","3 Fresh Medium Garlic Cloves (Chopped Fine)","15-20 Kalamon/Kalamata Olives (Cut into thirds)","Whole small courgette (Cut to small pieces)","6 Medium Mushrooms (Cut smallish and small stalk)","1/2 Broccli (Chopped small)","8-10 Finely sliced cherry tomatoes","1/2 Block of feta (Washed)","1 Chicken stock (Added to 3/4 Mug boiling water)","Overfilled Teaspoon Mixed Spice","3/4 Bowls fusilli pasta","Overfilled tablespoon Creme Cheese","1/3 Mug whole milk"],"steps":["Get a small deepish pan and heat it to low-medium temperature. Add a good amount of virgin olive oil and place one of the small onion pieces into the pan. Wait until it starts to sizzle and add the rest of the onion. Mix well and make sure the temperature is not too high as it can damage ingredients. Optional: You can sprinkle some sugar over the onion to make it sweeter. Then after a few minutes, when the onion has browned/softened, add in the garlic and wait 1-2 minutes, then you can turn off heat and put it to the side for later","Get a medium-large sized deepish pan, heat with oil and then add in the olives, courgettes and mushrooms. Sprinkle salt every now and then to enhance taste. After a few minutes when they are soft and are around the same color, then add in the onion and garlic from the smaller pan","Wait a couple minutes and then add the broccoli and tomato slices to the mix. Wait 2-3 more minutes and then get your rinsed feta and melt it in the pan (chop to speed up)","Start cooking the pasta","When the feta has nearly finished melting, add in the stock to the mix. Turn the pan temperature down slightly and then let it bubble for 5 mins (add a timer). Make sure to add the cover to the pan to keep in the flavor","After the 5 mins timer is up, add the overfilled tablespoon creme cheese to the main mix, stir, then re-add lid","Wait 2-3 more minutes and then you can test the sauce if you want. If you feel there is some missing, add more mixed spice or herbs such as parsley to it","Turn down the main mix again slightly and add the 1/3 Mug of Whole milk to the mix","Strain and serve your pasta and cover with the sauce. Enjoy!"],"time":30,"servings":null,"image":"","source":"https://based.cooking/babas-feta-pasta","page":"babas-feta-pasta","tags":["greek","feta","pasta","supper"]},{"id":"bc-greek-easter-cookies","title":"Greek Easter Cookies","cuisine":"Greek","category":"Dessert","ingredients":["1 lb of unsalted butter","3 cups of sugar","10 eggs","6 tsps baking powder","2 tsps baker’s ammonium","1 pinch of baking soda","2 tsp powder vanilla","Zest of 3 oranges","Zest of 2 lemons","1/2 cup orange juice","1 cup warmed milk","1 egg yolk whisked to brush cookies","Enough flour to make a soft pliable dough (about 9 cups or a bit more)"],"steps":["Cream butter and sugar together until fluffy. Add eggs one at a time and blend well between each","Add ammonium to the warmed milk and add to the butter, sugar, and egg mixture","Start adding flour to the wet mixture and at this time also add the baking powder, vanilla, lemon/orange zest, salt and orange juice","Mix well and start adding flour slowly until you are able to roll the dough easily between your hands. (This is a big batch, if your mixer can’t handle the volume, then knead by hand)","Form dough in a ball and place in a big bowl. Let it rest for about 30 minutes, cover it with saran wrap and keep in oven or draft free area","Line pans with parchment paper","Form dough by hand in ½ inch thick 3 inch long strips and then twist together or any shape you like. If the dough is sticky dip hands in oil","Brush with beaten egg yolks and bake at 350F for about 20 minutes or 325F convection. Watch carefully as they can burn easily!"],"time":22,"servings":null,"image":"","source":"https://based.cooking/greek-easter-cookies","page":"greek-easter-cookies","tags":["dessert","cookies","snack","greek","easter"]},{"id":"bc-greek-salad","title":"Greek Salad","cuisine":"Greek","category":"Salad","ingredients":["2 cup assorted Lettuce, chopped or torn","4 whole Tomatoes, wedged or sliced","1 whole Cucumber, seeded and sliced","1 Bell Pepper, seeded and sliced","1 small Onion, sliced","1/2 cup pitted Black Olives (preferably brine-cured), coarsely chopped","3/5 cup Feta Cheese, crumbled","6 Tbsp Olive Oil","1 tsp Red Wine Vinegar","1/2 tsp Fresh Garlic, chopped","1/2 tsp Oregano","1/2 tsp dill weed","1/4 cup Parsley, chopped","Salt and freshly ground Black Pepper","2 Tbsp Lemon juice, fresh"],"steps":["Combine the lettuce, tomatoes, cucumber, onion, bell pepper, olives in a bowl","In the small bowl, whisk together oil, vinegar, herbs, spices, and the lemon juice","Drizzle dressing over the salad","Sprinkle cheese over and serve"],"time":null,"servings":4,"image":"","source":"https://based.cooking/greek-salad","page":"greek-salad","tags":["salad","greek","mediterranean","tomato"]},{"id":"bc-butter-chicken-masala","title":"Butter Chicken Masala Curry","cuisine":"Indian","category":"Recipe","ingredients":["Boneless Chicken 1/2lb, cubed","Butter Melted 2 tbsp","Onions 2 medium-sized, minced","Tomato 2 medium-sized, pureed","Oil 2 tbsp","Lemon juice 1 tbsp","Garlic cloves 3, minced/crushed","Ginger 1tbsp, minced/paste","Garam Masala/Chicken Masala 1 tbsp","Cream 4tbsp (or cashew paste)","Chilli Powder 1 tbsp","Turmeric powder 1/4 tbsp","Crushed fenugreek leaves 1/4 tbsp","1 small bunch of coriander leaves / cilantro, for ganish"],"steps":["In a bowl, mix chicken with salt, pepper, 1/2 tbsp ginger-garlic paste, 1/2 tbsp chili powder, turmeric powder, and lemon juice for the chicken marinade; let marinate for an hour","Roast the marinated chicken in an oven at medium temperature for 5 to 10 minutes. The chicken should be three-fourths done","Heat butter in a pan. Fry the onions until it turns translucent","Add garlic-ginger and sauté for a minute, then add garam masala. Cook for a few seconds making sure not to burn the paste","Add tomato puree, salt, and chili powder. Let simmer for about 5 minutes, occasionally stirring until sauce thickens and becomes a deep brown-red color","Add the marinated chicken, butter, fresh cream, the crushed fenugreek leaves, and sliced green chilies. Cook for an additional 5 to 10 min until the chicken is cooked","Adjust salt, garnish with the coriander leaves. Serve over rice or naan"],"time":30,"servings":2,"image":"https://based.cooking/pix/butter-chicken-masala.webp","source":"https://based.cooking/butter-chicken-masala","page":"butter-chicken-masala","tags":["indian","curry","chicken"]},{"id":"bc-chicken-tikka-masala","title":"Chicken Tikka Masala","cuisine":"Indian","category":"Recipe","ingredients":["1 can (29 ounces) tomato puree","1-1/2 cups plain yogurt","1/2 large onion, finely chopped","2 tablespoons olive oil","4-1/2 teaspoons minced fresh gingerroot","4 garlic cloves, minced","1 tablespoon garam masala","2-1/2 teaspoons salt","1-1/2 teaspoons ground cumin","1 teaspoon paprika","3/4 teaspoon pepper","1/2 teaspoon cayenne pepper","1/4 teaspoon ground cinnamon","2-1/2 pounds boneless skinless chicken breasts, cut into 1-1/2-inch cubes","1 jalapeno pepper, halved and seeded","1 bay leaf","1 tablespoon cornstarch","1 cup heavy whipping cream","Hot cooked basmati rice","Chopped fresh cilantro, optional"],"steps":["In a 5-qt. slow cooker, combine the first 13 ingredients (Can blend these first for convenience). Add chicken, jalapeno and bay leaf. Cook, covered, on low 4 hours or until chicken is tender. Remove jalapeno and bay leaf","In a small bowl, mix cornstarch and cream until smooth; gradually stir into sauce. Cook, covered, on high 15-20 minutes or until sauce is thickened. Serve with rice. If desired, sprinkle with cilantro"],"time":240,"servings":8,"image":"","source":"https://based.cooking/chicken-tikka-masala","page":"chicken-tikka-masala","tags":["chicken","slowcooked","indian"]},{"id":"bc-coriander-chicken","title":"Coriander Chicken","cuisine":"Indian","category":"Recipe","ingredients":["500g boneless chicken breast","250g fat free yoghurt","250g coriander leaves","Mustard oil / Sunflower oil","Sugar","Ginger","Garlic","2 medium onions","Green chillies","Garam masala","2/3 Cardamom pods","1 Bayleaf","1 Cinnamom stick"],"steps":["Cut the boneless chicken into small bite sized pieces","In a mixer, put 250g coriander leaves, 2/3 green chillies, 250g yoghurt, 20g ginger, 9/10 cloves of garlic, 2 medium sized onions and mix well","Add the green chillies according to your taste","Pour half of the mixture from step 2 into a bowl and mix it thoroughly with the chicken","Into this chicken mixture add 1 tbsp Garam Masala and salt to taste","Keep the resulting marinated chicken aside for about 30 minutes","In a frying pan add 3 tbsp of either mustard oil or sunflower oil","Once the oil is hot, add 1 tbsp sugar and cook until the sugar melts into the oil","Add 2/3 cardamom pods, 1 small cinnamon stick, and 1 bayleaf into the hot oil","Simmer for about 1 minute, then lower the heat to medium","On medium heat, add the marinated chicken mixture and cook till oil starts separating from the chicken","Add salt to taste and keep stirring the chicken to make sure it does not burn or stick to the bottom of the pan","Once the oil separates, add the remaining mixture which was left behind after step 4","Stir until it has a thick consistency. Serve with naan or rice"],"time":20,"servings":3,"image":"","source":"https://based.cooking/coriander-chicken","page":"coriander-chicken","tags":["indian","lunch","spicy"]},{"id":"bc-curry-sauce","title":"Curry sauce","cuisine":"Indian","category":"Sauce","ingredients":["25g butter","1 onion, sliced","2 garlic cloves, sliced","Thumb of ginger, sliced","2 tbsp curry powder","1/2 tsp turmeric","1 tbsp malt vinegar","1 star anise","250ml chicken stock","1 tbsp cornflour","2 tbsp water","Lemon juice (optional)"],"steps":["Melt the butter in a large saucepan over medium heat","Add in the sliced onion, sliced garlic, and ginger","Fry for 15 min, until the onion is soft","Add the curry powder, turmeric, vinegar, and star anise","Fry for 1 minute","Pour in the stock","Simmer for 30 minutes while stirring","Remove the star anise","Add the cornflour and water","Simmer for 5 minutes while stirring","Blend the sauce. Add in some lemon juice if you want"],"time":60,"servings":4,"image":"","source":"https://based.cooking/curry-sauce","page":"curry-sauce","tags":["sauce","indian","curry"]},{"id":"bc-garam-masala","title":"Garam Masala","cuisine":"Indian","category":"Recipe","ingredients":["4 Green Cardamom","2 Black Cardamom","1 tbsp Coriander","2 Cloves","1 tbsp Cumin","1 tbsp Fennel seeds","5/6 Bayleaf","5/6 Black pepper pods","1 Star anise (Optional)","Mace (Optional): Mace is a dried flower originating from the Nutmeg plant. Use no more than 3 strands of this flower"],"steps":["Star anise and Mace are normally not added to Garam masala. They are added specially if someone is making Biriyani","Cloves will make the masala really hot. So make sure to add only as much as you want to eat","Too much Mace makes the masala quite bitter. So make sure you do not add more than what has been recommended. The amount of other spices can be changed according to taste","Wash all the dry spices really well","If you live in a place which is very sunny, sun dry your washed spices for about 1 day. If not then on a frying pan with a heavy bottom, place all the spices and dry roast them until aromatic","Cool the dry spices and put them into a mixer. Mix thoroughly","Sieve the powder and add the larger pieces into the mixer once again and mix it again until everything turns into a fine powder. This step might need to be repeated a few times","The resulting mixture is garam masala. Store it in airtight glass jars","You can store this mixture for about 2/3 months in a cool dry place"],"time":null,"servings":null,"image":"","source":"https://based.cooking/garam-masala","page":"garam-masala","tags":["indian","spice"]},{"id":"bc-indian-tea","title":"Indian tea","cuisine":"Indian","category":"Drink","ingredients":["8 g fresh ginger","10 cardamom seeds","1.5 cup milk","2 tablespoon black tea"],"steps":["Peel off the ginger and cut it to small pieces","Crush ginger and cardamom seeds","Bring 1 l water to boiling","Turn off the stove","Add ginger, cardamom seeds, black tea and milk to the water and cover the pot","Wait 5-10 minutes for infusion","Serve with a teaspoon sugar per cup"],"time":10,"servings":4,"image":"","source":"https://based.cooking/indian-tea","page":"indian-tea","tags":["drink","easy","indian","milk","traditional"]},{"id":"bc-lamb-biriyani","title":"Lamb Biriyani","cuisine":"Indian","category":"Recipe","ingredients":["4-5 pods of Cardamom","2-3 Bay leaves","3-4 Cinnamon Sticks","8 Cloves","400gm Basmati Rice","600gm Mutton / Lamb (Boneless)","2 Onions (Preferably Red)","2 Tomatoes","1 Green chilli (Optional)","10 Garlic pearls","5cm piece of Ginger","1/2 Tbsp of Garam Masala","1 Tbsp of Chilli Powder or Hungarian Smoked Paprika","Juice of 1/2 Lemon or 1 tsp of Vinegar","Dash of Tumeric Powder","Dash of Curry Powder","1 Sprig of Mint / Coriander (Garnish)"],"steps":["Wash the rice till the water turns clear and let the rice soak for at least 30 mins","Chop the tomatoes down into tiny cubes and the onions into julienne slices. Grind the ginger and garlic into a paste","For the green chilli slice it midway to maintain it in one piece","In a big pot, Add 30 ml of neutral oil and toast the spices for 30 sec on medium heat","Add the onions and saute for around 3 min","Add the tomatoes, ginger and garlic paste and saute for another 3 min","Add the mutton/ lamb and 2 cups (500ml) of water. Add one Tbsp of salt","Turn the heat up to high and add the green chilli, turmeric powder, chilli powder and 2 Tbsp of salt and let the mutton cook for about 40 -50 min","Ensure that the pot does not run out of water and top up with more if required","Add about 2 cups of water or to about 800 gm of water in the pot while accounting for water left in the pot (1:2 ratio of rice to water)","Once boiling again, Add the rice, Garam Masala and Lemon juice / Vinegar to the pot","Once 80% of the standing water has evaporated, Turn to the heat down to as low as possible and check the salt and spice levels and add more as required","Now with a lid on, let the pot simmer for another 10 mins","Serve with onion raitha and boiled Eggs and Garnish with coriander or mint sprigs. Enjoy!"],"time":75,"servings":4,"image":"https://based.cooking/pix/lamb-biriyani.webp","source":"https://based.cooking/lamb-biriyani","page":"lamb-biriyani","tags":["lamb","mutton","indian"]},{"id":"bc-naan-bread","title":"Naan Bread","cuisine":"Indian","category":"Bread","ingredients":["All-purpose flour 3 cups","Active dry yeast 1 tbsp","Sugar 2 tbsp","Warm Milk 1 cup","Butter melted 2 tbsp","Oil - little to grease","Salt - 1 1/2 teaspoons"],"steps":["Put the yeast and sugar to warm milk in a large mixing bowl and stir well. Leave it for 3-5 minutes","Put the flour and salt into a large mixing bowl and whisk to combine. Sprinkle additional flour as needed to keep the dough from sticking to the sides","Once the dough is soft and ready, apply oil on it and cover it with a soft cloth. Rest it for 2–3 hours","Knead the dough again, sprinkle all-purpose flour, and knead until smooth","Divide dough into 4 equal pieces. Form pieces into balls. Roll out dough balls to desired thickness (about the size of a small tortilla)","Now transfer the naan to the foiled baking tray and bake in preheated at 180 C for 30-35 minutes","After baking, brush the top with butter and cut it into four pieces and serve. Enjoy!"],"time":30,"servings":4,"image":"https://based.cooking/pix/naan-bread.webp","source":"https://based.cooking/naan-bread","page":"naan-bread","tags":["indian","bread","fasting"]},{"id":"bc-onion-raitha","title":"Onion Raitha (Indian Tzatziki)","cuisine":"Indian","category":"Sauce","ingredients":["500 gm of Greek Yogurt","One Red onion","50 gm of Cucumber","Sprigs of Mint","Dash of Honey","Hint of Chilli Powder (Spicy option)/ Hint of sugar (Sweet option)"],"steps":["Chop the onion into tiny cubes (0.5-1cm or 3/8 inches sized cubes)","Slice the cucumber into tiny strips (Julienne). Hand crush the mint","Prep the serving bowl with yogurt and add the onions and cucumber","Add the mint, honey, 1 tsp of salt and the sugar/chilli powder (Depending on the sweet/spicy choice)","Mix well and serve. Garnish with additional mint as required"],"time":5,"servings":4,"image":"","source":"https://based.cooking/onion-raitha","page":"onion-raitha","tags":["quick","sauce","indian"]},{"id":"bc-paneer-tikka-masala","title":"Paneer Tikka Masala","cuisine":"Indian","category":"Recipe","ingredients":["250g cubes paneer","1 onion","1 capsicum","200ml tomato puree","1 tsp red chilli powder","1 tsp turmeric powder","1 tsp coriander powder","1/2 tsp garam masala powder","100ml thick yogurt","1 tsp fenugreek powder","dry fenugreek leaves","cardamom","cumin seeds","shaved ginger","20ml garlic paste","1 bowl corn"],"steps":["Take a glass container, and mix the cubed paneers with half a tea spoon of red chilli powder, turmeric powder, coriander powder, garam masala powder, fenugreek powder, and 50g yogurt","Let the mix marinade for at least an hour","Preheat the oven to 200°C (392°F), and place the marinated paneer cubes, with onion, capsicum, and tomato on the skewers. Let them grill in the oven using skewer support, by continuously flipping them every 5 minutes until the outer crust looks crispy enough","Start heating some oil in a pan to add some cardamom and cumin seeds. Let it heat until the flavour is transfused for about a minute or two","Now add chopped onions and tomatoes to the sautee. Add some shaved ginger and garlic paste and let it sauté until some raw flavour disappears","Add the tomato purée, dry fenugreek leaves, and let it cook for about 15 minutes","As the spice and tomato purée looks cooked, add some water to the mixture and let it cook more","Now add the grilled paneer, some chopped vegetables of choice, corn and stir the mixture well","One the added water seems to be evaporated, and the mixture looks a little thicker, turn off the heat and garnish with lemon juice, fresh coriander. (It can be served with bread of any preference.)"],"time":null,"servings":null,"image":"https://based.cooking/pix/paneer-tikka-masala.webp","source":"https://based.cooking/paneer-tikka-masala","page":"paneer-tikka-masala","tags":["indian","lunch","spicy"]},{"id":"bc-pineapple-lentil-curry","title":"Pineapple Lentil Curry","cuisine":"Indian","category":"Recipe","ingredients":["1 cup dried red lentils, rinsed","1 tbsp olive oil","1 onion, diced","2 cloves garlic, minced","1 tbsp curry powder","1 can (14oz) diced tomatoes","1 can pineapple chunks, drained","1 can coconut milk","2 cups vegetable broth","cooked rice, for serving"],"steps":["Heat oil in a large pot over medium heat","Add onion and garlic. Sauté about 5 minutes, until soft","Stir in curry powder and cook about 1 minute, until fragrant","Add all other ingredients. Stir well","Bring to a boil and then reduce to a simmer. Cover and cook for 25-30 minutes, stirring occasionally, until lentils are soft","Season with salt and pepper","Serve over rice"],"time":30,"servings":6,"image":"https://based.cooking/pix/pineapple-lentil-curry.webp","source":"https://based.cooking/pineapple-lentil-curry","page":"pineapple-lentil-curry","tags":["indian","lentil","curry","coconut","spicy","fasting"]},{"id":"bc-potato-and-eggplant-curry","title":"Potato and Eggplant (Aubergine) Curry","cuisine":"Indian","category":"Recipe","ingredients":["1 large eggplant (aubergine)","2 medium potatoes","3 tbsp olive oil","2 onions (finely sliced)","2 garlic cloves (crushed)","2 tsp garam masala","2 tsp turmeric","2 tsp ground coriander","400 ml can chopped tomatoes","400 ml can coconut milk","rice"],"steps":["Heat the oven to approximately 200 °C (392 °F)","Cut the eggplant into 1 cm (⅓\") slices and place on a tray. Cover with a layer of oil and bake for 20 minutes","Cook the sliced onions with oil until soft on medium (about 5-6 minutes)","Add the garlic, garam masala, turmeric and ground coriander and allow to release aroma for a minute or two","Tip in the canned tomatoes and coconut milk. Add the eggplant, and chunks of potato","It is possible to add additional vegetables at this step. I have on occasion added carrots and red peppers (capsicums)","Cover and simmer for ~15-20 minutes","Boil 2 serves of rice","Remove the lid and cook for a further 5 minutes, or until reduced","A nice optional addition at this point is paneer","Serve with the rice"],"time":null,"servings":null,"image":"","source":"https://based.cooking/potato-and-eggplant-curry","page":"potato-and-eggplant-curry","tags":["indian","curry","potato","fasting"]},{"id":"bc-red-lentil-dahl","title":"Red Lentil Dahl","cuisine":"Indian","category":"Recipe","ingredients":["3 Tbsp Olive Oil","1 medium Yellow Onion","1 Tbsp Fresh Ginger, grated","4 Garlic Cloves, minced","2 Tbsp Yellow Curry (mild madras)","1 tsp Sea Salt","1 cup dried Red Lentils","4 - 5 cups Water","5 Plum Tomatoes, chopped","juice of 1 Lemon","1 cup Fresh Cilantro, chopped and lightly packed","Dried Red Chili's or cayenne pepper, to taste","1/4 tsp Ground Cinnamon"],"steps":["Heat oil in a soup pot and saute onions for 5 minutes","Add garlic and ginger and saute 5 more minutes","Add spices and salt, saute 5 minutes more","Add 4 cups of water and stir. Add tomatoes and lentils. Bring to a boil and then lower the heat a bit and simmer for 20 minutes","Add the lemon juice and cilantro and more water if it's too thick. Simmer 10 more minutes, or until lentils are completely tender. This may take a while"],"time":50,"servings":6,"image":"","source":"https://based.cooking/red-lentil-dahl","page":"red-lentil-dahl","tags":["indian","curry","tomato","vegetables"]},{"id":"bc-bebek-mropol","title":"Bebek Mropol","cuisine":"Indonesian","category":"Recipe","ingredients":["1 whole duck, cut into pieces","2 cans of coconut milk","2 lemongrass stalks, bruised","4 kaffir lime leaves","4 bay leaves","4 cloves of garlic, minced","4 shallots, minced","2 red chilies, sliced","2 tsp of salt","1 tsp of sugar","1 tsp of tamarind paste"],"steps":["Heat up a large pot over medium-high heat, and add the duck pieces skin side first to render the fat. Flip and cook until the duck is browned on all sides","Add the minced garlic, shallots, and sliced chilies to the pot, and stir-fry for a few minutes until fragrant","Pour in the coconut milk, and add the lemongrass, kaffir lime leaves, bay leaves, salt, sugar, and tamarind paste. Stir well to combine","Bring the mixture to a boil, then reduce the heat to low and let it simmer for about 1 hour, or until the duck is tender and the sauce has thickened","Serve the Bebek Mprol hot with a side of white rice"],"time":60,"servings":4,"image":"","source":"https://based.cooking/bebek-mropol","page":"bebek-mropol","tags":["duck","indonesian"]},{"id":"bc-colcannon-bake","title":"Colcannon Bake","cuisine":"Irish","category":"Recipe","ingredients":["3 Potatoes, peeled and quartered","7 Tbsp Butter, cut into small chunks","1/2 cup Sour Cream","1 Egg","1 Tbsp Milk","3 cup Cabbage, shredded","2 Leeks, chopped","1 small Onion, chopped","2 cubes Chicken Bouillon","1/2 cup Cheddar Cheese, shredded"],"steps":["Place the potatoes into a large pot and cover with salted water. Bring to a boil, then reduce heat to medium-low, cover and simmer until tender, about 20 minutes. Drain and allow to steam dry for a minute or two. Season the potatoes with salt, and mash with 6 Tbsp of the butter, the sour cream, egg, and milk","Preheat oven to 350F. Grease a 2-quart casserole dish","Heat the remaining butter in a skillet over medium heat. Stir in the cabbage, leeks, and onion until the cabbage is tender and the onion is translucent (10 mins)","Crush the bouillon cubes into the cabbage mixture, and stir to blend and dissolve the cubes. Stir the cabbage mixture into the potato mixture until thoroughly mixed, and spoon into the prepared casserole dish","Bake in the preheated oven for 40 minutes, top with cheddar cheese, and return to oven until the cheese melts (10 mins)"],"time":70,"servings":6,"image":"","source":"https://based.cooking/colcannon-bake","page":"colcannon-bake","tags":["cheesefare","potato","irish"]},{"id":"bc-irish-potato-casserole","title":"Irish Potato Casserole","cuisine":"Irish","category":"Recipe","ingredients":["2 cups Potatoes, peeled and shredded","1/2 cup Butter, melted","2 whole Eggs, beaten","1 tsp Onion, minced","1 tsp Salt","1/4 tsp Paprika","1/2 cup Milk","1/2 cup Sharp Cheddar Cheese, shredded"],"steps":["Preheat oven to 350F. Butter a 1.5 quart baking dish","In a medium bowl, combine the potatoes, butter, eggs, onion, salt, and paprika. Mix well","Place potato mixture into the prepared baking dish and pour milk over top. Bake in the preheated oven for 40 minutes. Sprinkle top with cheese, return to oven until cheese melts and is slightly browned"],"time":45,"servings":6,"image":"","source":"https://based.cooking/irish-potato-casserole","page":"irish-potato-casserole","tags":["irish","baking"]},{"id":"bc-beef-stew","title":"Traditional beef or lamb stew","cuisine":"Irish","category":"Recipe","ingredients":["Lamb shoulder or beef chuck","Onion, celery, carrot and garlic","Thyme, rosemary and some bay leaves","Beef or chicken stock","(Optional) a bottle of stout or porter for some extra flavour"],"steps":["Cut up the onion, carrot and celery into bite-sized chunks roughly the same size as the meat. The garlic can go in whole","Brown the meat on all sides. Get a large pot with some oil and sear the edges of the meat. Do this in batches and try not to overcrowd the pot. Browning the meat on the outside will give it a much nicer texture when you go to eat this and should not be skipped for convenience","Remove the meat and add in the vegetables. Adding some salt will help remove the moisture in the veg and will help deglaze the caramelised bits at the bottom of the pot","(Optional) If you have a Guinness or some other stout add the meat back in an deglaze with about a third of the can. This will add some extra flavour. Wait until the alcohol has completely evaporated until you stir or continue","Add back in the meat and add in the stock and herbs. Lower the heat and allow to simmer for about 2 - 2.5 hours","After 2 hours the stew will be a bit thicker but probably still watery. The easiest thing to do is add some cut up potatoes for the last half hour. The starch will help thicken the stew considerably. Otherwise you can mix a teaspoon of flour with water in a cup and slowly add this to the stew while whisking"],"time":null,"servings":null,"image":"","source":"https://based.cooking/beef-stew","page":"beef-stew","tags":["irish","stew","lamb","beef"]},{"id":"bc-baked-mostaccioli","title":"Baked Mostaccioli","cuisine":"Italian","category":"Pasta","ingredients":["24 oz or 1 jar of Fradiavolo Sauce","1 box mostaccioli rigati or penne rigate","~8 oz shredded mozzarella cheese","I've found that pre-shredded cheese doesn't taste as good as shredding it right before cooking"],"steps":["Bring a pot to a boil and cook pasta for 6 minutes (very al dente)","Put pasta and sauce in baking dish(es) and mix well","Cover pasta and sauce generously with grated cheese until you can't see the pasta","Bake at 350°F / 175°C for 20 minutes, or 375°F / 190°C for 15 minutes on convection bake"],"time":20,"servings":8,"image":"https://based.cooking/pix/baked-mostaccioli.webp","source":"https://based.cooking/baked-mostaccioli","page":"baked-mostaccioli","tags":["pasta","italian"]},{"id":"bc-baked-pasta-with-broccoli","title":"Baked pasta with broccoli, boiled eggs and scamorza cheese","cuisine":"Italian","category":"Pasta","ingredients":["500g pasta","500g broccoli","4 eggs","200g scamorza cheese","400g béchamel","sage (optional)","parmesan cheese (optional)"],"steps":["Boil water and add salt (a handful for every liter), put pasta inside","Boil broccoli and eggs for 10 minutes","While everything is boiling dice scamorza cheese, prepare a pan","Put a layer of béchamel","Put a layer of pasta","Put a layer of broccoli, diced scamorza cheese, pepper, salt","Go to step 4 and repeat until ingredients end","Add sage leafs on top (optional)","Put the pan inside the (preheated) oven at 180°C for 15~20 minutes","End with 5~10 minutes of cooking with the grill function"],"time":30,"servings":4,"image":"https://based.cooking/pix/baked-pasta-with-broccoli.webp","source":"https://based.cooking/baked-pasta-with-broccoli","page":"baked-pasta-with-broccoli","tags":["italian","pasta","broccoli","cheesefare"]},{"id":"bc-basic-meatballs","title":"Basic Meatballs","cuisine":"Italian","category":"Recipe","ingredients":["1 pound ground beef (preferably 90/10 or 93/7)","1 pound ground pork","1/2 cup italian breadcrumbs","1/3 cup milk (I use 2% but doesn't matter too much)","1/4 cup yellow onion diced (about 1/2 small yellow onion)","1 egg","1/2 cup shredded parmesan","1/4-1/2 cup chopped parsley","2 tbsp red pepper flakes","2 tbsp dried oregano","1 tbsp rosemary","1 tbsp basil","1 tbsp garlic powder","Salt and pepper to taste"],"steps":["Preheat oven to 200°C/400F","In a bowl, combine all ingredients","Hand form into balls by packing with your hands and then rolling. Set aside on a baking sheet, preferably one with a cooling rack","I prefer large meatballs (larger than a golf ball) and shoot for 16-20 for 2 lbs of meat, but if you prefer smaller meatballs you can opt for as many as 48","Either halfway through the packing process or after forming all meatballs, heat a large skillet to medium-high heat","Add 1-2 tbsp of oil to the skillet (enough to evenly coat the skillet), and bring to heat","Fill the skillet with meatballs, start by browning one face, flip once at after 2-3 minutes, and then remove to the baking sheet after another 2-3 minute. Continue in batches until all meatballs have been browned","It is OK and expected for the meatballs to lose some of their spherical shape at this point","You can skip this step and go straight the oven if you want to cut corners","Transfer to the oven, and cook until the inside registers 60°C/140F on an instant read thermometer. This should be about 20 minutes for large meatballs (16 per batch), maybe 10 for small (48 per batch)","Serve with pasta or on a meatball sub"],"time":25,"servings":4,"image":"","source":"https://based.cooking/basic-meatballs","page":"basic-meatballs","tags":["basic","italian","beef","pork"]},{"id":"bc-bolognese-sauce","title":"Bolognese Sauce","cuisine":"Italian","category":"Sauce","ingredients":["extra virgin olive oil","2 carrots","2 celery sticks","1 large onion","2 garlic cloves (optional, but not traditional)","200 grams pancetta (optional)","300 grams beef mince","350 grams pork mince","350 grams veal mince (if you cant find veal replace with pork)","140 grams concentrated tomato paste","690 grams diced tomatoes","water","1 can peeled tomatoes","1-2 glasses wine (whatever you have open)","1 glass of milk (optional)","1 glass of beef/vegetable stock (optional)"],"steps":["Finely dice the carrots, celery, onion and pancetta, if your blender can handle it you can optionally blend all this to speed it up","Heat up a large saucepan or dutch oven on medium low heat and put enough olive oil in to cover the bottom of the pan","Put in your diced veggies and pancetta and let it slowly sauté for about 10 minutes until everything is fragrant and soft","If you are using garlic add it here and let it sweat for a minute","Add in your minced meat and break it up into small clumps about the size of a rice grain with a spoon, keep stiring until all your meat is lightly cooked","Once all your meat is cooked and looks a bit grey add your wine, add enough to fully deglaze the pan (I usually add a little bit extra for the flavor)","Once your pan is somewhat dry you can add the tomato paste to the beef, let it cook for a minute to remove the slight metallic taste","Add your canned and peeled tomatoes and use your spoon to break them up, you don't have to be too thorough since they will soften up while the sauce cooks","add the diced tomatoes, fill the jar your tomatoes came in with water give it a shake and add that to the pot, do the same with your can of peeled tomatoes","lower your heat to the lowest setting and slightly cover the pan with your lid","let it simmer for as long as you can wait, preferably at least 4 hours, if it starts getting a bit too dry you can add a bit more water to make sure the sauce doesn't burn","Once it's done simmering for as long as you can muster and its nice and thick, the liquid should not come above your meat and should be pretty concentrated","You can add your glass of milk, let it simmer for 10 more minutes and serve"],"time":240,"servings":null,"image":"https://based.cooking/pix/bolognese-sauce.webp","source":"https://based.cooking/bolognese-sauce","page":"bolognese-sauce","tags":["sauce","italian","pasta"]},{"id":"bc-cacio-e-pepe","title":"Cacio e Pepe","cuisine":"Italian","category":"Pasta","ingredients":["Spaghetti","Grated Pecorino Romano","Peppercorns (you can also use pepper but it will change the flavour)"],"steps":["Cook your chosen amount of spaghetti 3-4 minutes under the time on the package","Meanwhile place the peppercorns on a cutting board and mash them with a pestle","Place half of the peppercorns in a pan and toast them at medium heat","Drain the pasta, place it in the pan and save the boiling water for later use","Add the pasta with the pepper with 2 spoons of the water previously saved","Prepare the Pecorino by putting half of it a bowl with a spoon of the pasta water you saved; continue mixing the cheese with the water until a cream is formed","When the pasta is almost cooked, add the cream and mix (you can add more water if the pasta is too dry)","Serve on a plate with the Pecorino left before on top"],"time":null,"servings":null,"image":"https://based.cooking/pix/cacio-e-pepe.webp","source":"https://based.cooking/cacio-e-pepe","page":"cacio-e-pepe","tags":["italian","quick","pasta","cheesefare"]},{"id":"bc-caesar-salad","title":"Caesar Salad","cuisine":"Italian","category":"Salad","ingredients":["Romaine Lettuce","Grated Parmesan Cheese","Croutons","Caesar Salad Dressing"],"steps":["Prepare a whole head of Romaine Lettuce by chopping off the root and rising thoroughly with water. Dry completely","Once the lettuce is fully dry, put in a mixing bowl with lettuce and the Caesar Salad dressing. Toss to cover each leaf completely","Add croutons","Grate Parmesan over salad","Eat with hands"],"time":null,"servings":null,"image":"https://based.cooking/pix/csalad.webp","source":"https://based.cooking/caesar-salad","page":"caesar-salad","tags":["italian","salad","cheesefare"]},{"id":"bc-cannellini-bean-salad","title":"Cannellini Bean Salad","cuisine":"Italian","category":"Salad","ingredients":["1 can Cannellini beans, drained and rinsed","2 tbsp minced garlic","1/2 onion","1 tsp smoked paprika","1/2 tsp ground cumin","1 15 oz can diced tomatoes","1 tbsp parsley flakes","Prosciutto","Arugula"],"steps":["Sauté garlic and onions in olive oil until onions are translucent","Add diced tomatoes, seasonings, and salt and pepper to taste. Simmer for 3 minutes","Add the beans, season to taste, mix until combined, and simmer for an additional 2 minutes","Serve over arugula and top with bits of prosciutto"],"time":10,"servings":2,"image":"","source":"https://based.cooking/cannellini-bean-salad","page":"cannellini-bean-salad","tags":["beans","italian","salad"]},{"id":"bc-carbonara","title":"Carbonara","cuisine":"Italian","category":"Pasta","ingredients":["Spaghetti: 320 g | 11 oz","Eggs: 5","Guanciale or Smoked Pancetta (cleaned and cubed): 150 g | 5 oz","Pecorino Romano or Parmigiano-Reggiano (grated)(optional)"],"steps":["Crack the eggs in a bowl but only add the yolks. Add a generous amount of your preferred grated cheese (Pecorino or Parmigiano) around 35g (you can optionally add a dash of black pepper)","Fill a pot with water and salt it less than typical pasta water. When it boils, cook the pasta one minute less than advised","Fry the preferred pork (Guanciale or Smoked Pancetta) in an iron or nonstick pan (if using a different kind of pan add a dash of extra virgin olive oil) on low to medium heat until the sides are crisp but the insides are chewy","While everything is being cooked and fried, beat the eggs manually using a fork until everything is entirely liquid. Remember to watch the time","When your pasta is done (-1 minute), drain it and put it in the bowl with eggs. At this step you may consider the timing: if the pasta is too hot you will cook the eggs, and some people don't like it this way, so just wait for a minute. Keep moving and stirring to fully incorporate the eggs. Add guanciale and as many fats remaining in the pan as you want. Keep moving and stirring","Plate and optionally garnish with the preferred grated cheese and black pepper. Voila"],"time":25,"servings":4,"image":"https://based.cooking/pix/carbonara.webp","source":"https://based.cooking/carbonara","page":"carbonara","tags":["italian","pasta","quick","cheesefare"]},{"id":"bc-casio-in-pastelletto","title":"Casio in pastelletto","cuisine":"Italian","category":"Recipe","ingredients":["2 slice cheese. Use a cheese that is mid-aged, not too savoury and not too delicate","sugar","cinnamon","butter or lard"],"steps":["Place the cheese in a pan with frying butter or lard","Immediately sprinkle sugar and cinnamon all over it","As soon as it softens, remove it from the pan","Serve warm"],"time":5,"servings":1,"image":"https://based.cooking/pix/casio-in-pastelletto.webp","source":"https://based.cooking/casio-in-pastelletto","page":"casio-in-pastelletto","tags":["cheese","cheesefare","easy","italian","medieval"]},{"id":"bc-castagnole","title":"Castagnole","cuisine":"Italian","category":"Recipe","ingredients":["5 eggs","5 tablespoons sugar","1 glass milk","3 tablespoons olive oil","flour","instant yeast","oil or lard","half a glass mistrà (optional)","honey (optional)"],"steps":["Mix eggs, sugar, milk, flour, yeast and mistrà and knead them in a soft dough","Roll out to about 1.5 cm thick","Cut it to squares about 5 cm long","Fry them for about 5 minutes","Dry them and sweeten with sugar or honey"],"time":5,"servings":15,"image":"https://based.cooking/pix/castagnole.webp","source":"https://based.cooking/castagnole","page":"castagnole","tags":["fry","italian","sweet","traditional"]},{"id":"bc-cheesy-pasta-bake","title":"Cheesy Pasta Bake","cuisine":"Italian","category":"Pasta","ingredients":["300-400g Pasta (Fusilli recommended but not essential)","50g Butter","100g Flour","200ml Milk","400g Cheddar Cheese","6 Rashers of bacon (optional)"],"steps":["Grate the cheese","Chop up the bacon into roughly 2cm x 2cm squares","Start cooking the pasta","Start melting the butter in another saucepan","Once melted, add flour and mix until the mixture forms a paste that does not stick to the sides. The quantity of flour required may vary","Now start adding the milk slowly, while mixing, as to avoid lumps","Heat on low heat while stirring until the sauce becomes thick. If unsure, taste the sauce, and if you cannot taste the flour, it is ready for the next step","Add 80% of the cheese and stir until melted in","Drain the pasta and add to baking dish","Add the sauce and mix in","If using bacon, fry it up and mix into the dish, making sure to include any fat that comes out of the bacon for extra flavour","Use the rest of the cheese to cover the top","Bake at gas mark 6 for about 30 minutes"],"time":60,"servings":4,"image":"","source":"https://based.cooking/cheesy-pasta-bake","page":"cheesy-pasta-bake","tags":["bacon","cheese","italian","pasta"]},{"id":"bc-chicken-parmesan","title":"Chicken Parmesan","cuisine":"Italian","category":"Recipe","ingredients":["chicken breasts","tomatoes (San Marzano is best)","mozzarella cheese","parmesan cheese","bread crumbs","eggs","flour","pasta sauce"],"steps":["Slice the chicken breasts through their width so that they are as flat as possible","Pound breasts as flat as possible","Add flour to a bowl or basin large enough to fit a breast, add pepper","Crack eggs into another large bowl or basin and whisk them","Add breadcrumbs to yet another large bowl or basin. Add generous amounts of grated parmesan","One by one, take each breast and dip and cover it in the flour, then the egg, then the bread crumbs","Cover a pan with olive oil and heat it just under when it begins to smoke","Fry the bread crumb-coated chicken breasts in the oil. Add butter generously while frying to ensure frying oil does not evaporate","Move fried breasts to an oiled or buttered pan, add mozzarella and parmesan on them","Broil/cook the breasts only long enough for the cheese to melt","Serve the breasts with pasta sauce either above or below. This is often served with pasta"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicken-parmesan","page":"chicken-parmesan","tags":["italian","chicken"]},{"id":"bc-chicken-pasta-casserole","title":"Chicken Pasta Casserole","cuisine":"Italian","category":"Pasta","ingredients":["16oz (450g) macaroni (elbow, penne)","24oz (700g) raw chicken breast, diced","9oz (250g) mozzarella cheese, shredded","1.5oz (40g) parmesan cheese, grated","1.5oz (40g) bread crumbs","16oz (450g) diced tomatoes","Some oil and butter","(Optional) More mozzarella and parmesan for fans of cheese"],"steps":["Preheat oven to 400F/200C","Dice chicken and pan cook with oil until fully cooked","Cook the pasta for a few minutes less than usual (about 7-8 minutes)","Add chicken and pasta into a casserole dish. Mix together. Add diced tomato and shredded mozzarella cheese and keep mixing. Top with parmesan cheese and bread crumbs for an even coat. Add about a spoonful of butter evenly on the top","Cook in the oven for 22-25 minutes, until the top looks golden"],"time":35,"servings":4,"image":"https://based.cooking/pix/chicken-pasta-casserole.webp","source":"https://based.cooking/chicken-pasta-casserole","page":"chicken-pasta-casserole","tags":["chicken","italian","pasta"]},{"id":"bc-chipolata-in-balsamic-vinegar","title":"Chipolata Sausage in Balsamic Vinegar","cuisine":"Italian","category":"Recipe","ingredients":["12 chipolata sausages","4 red onions","500g of cherry tomatoes (preferably mixed species)","4 garlic cloves","Fresh basil leaves","Black balsamic vinegar","1 loaf of ciabatta bread"],"steps":["Pre-heat the oven to 200c (400f)","Put the chipolata sausages in an oven dish","Cut 4 red onions into quarters spread them out in the oven dish","Mince 2 of the garlic cloves and add them to the oven dish","Add the 2 remaining garlic cloves to the oven dish, This can be done with the skin to create a garlic spread for the bread","Add 3 tablespoons of oil to the oven dish and toss to cover everything in oil","Put the dish in the oven for 30 minutes. Toss everything around at 15 minutes to ensure even baking","Cut half of the cherry tomatos in half keep the other half intact","After 30 minutes take the dish out of the oven","Add all the tomatoes to the oven dish","Add 3 tablespoons of balsamic vinegar to the oven dish","Put the dish back into the oven for another 30 minutes at 200c (400f)","After 30 minutes take the dish out of the oven and reheat the oven as per instructions on the ciabatta bread","Tear the fresh basil leaves and add to the oven dish. Let it rest while you wait for the bread","Take the bread out of the oven and serve along with the oven dish. Bread can be used to dip in the oven dish"],"time":60,"servings":4,"image":"","source":"https://based.cooking/chipolata-in-balsamic-vinegar","page":"chipolata-in-balsamic-vinegar","tags":["beef","baking","italian"]},{"id":"bc-cinque-pi","title":"Cinque Pi","cuisine":"Italian","category":"Pasta","ingredients":["pasta: 800g | 1 1/2 lb","Cream: 4dl | 1 1/2 cups","Tomato paste 2 TS","Parmigiano (grated)","Parsley"],"steps":["Start cooking the pasta","Mix the cream with the tomato paste and bring to a boil","Turn the heat down to medium and add as much grated parmigiano as you like","Let it cook on medium to low heat until the pasta is done","Add chopped parsley and pepper","You can either add the sauce to the pasta or serve separately","Serve with some additional parmigiano and a leaf of parsley"],"time":15,"servings":4,"image":"https://based.cooking/pix/cinque-pi.webp","source":"https://based.cooking/cinque-pi","page":"cinque-pi","tags":["italian","pasta","quick"]},{"id":"bc-crostata","title":"Crostata","cuisine":"Italian","category":"Dessert","ingredients":["8 servings shortcrust pastry","300 g jam or marmalade"],"steps":["Set aside about 1/6 of the shortcrust pastry and roll out the remaining so that it is slightly larger than the tray","Place rolled shortcrust pastry in a baking mold and arrange the border along those of the mold, so that the pastry can contain jam","Pour the jam in the shortcrust pastry \"container\" you just created and spread it with a spoon","Use the pastry you set aside to create rolls and place them in a criss-cross pattern all over the surface","Preheat the oven to 180 °C","Cook in the oven for about 45 minutes","Let the cake cool down to room temperature before removing from the mold, otherwise it will easily break"],"time":45,"servings":8,"image":"https://based.cooking/pix/crostata.webp","source":"https://based.cooking/crostata","page":"crostata","tags":["baking","cake","cheesefare","dessert","italian","jam"]},{"id":"bc-easy-pizza-sauce","title":"Easy Pizza Sauce","cuisine":"Italian","category":"Sauce","ingredients":["2 onions","3 garlic cloves","olive oil","700g tomato sauce","6 spoon tomato concentrate","0.5 spoon sugar","1 spoon salt","1 spoon pepper","1 spoon thyme/rosemary (finely chopped)","1 spoon oregano (finely chopped)","2 spoon basil (finely chopped)"],"steps":["Finely chop onions and garlic into a pot","Cover them with olive oil","Cook mixture on medium heat (~4/10) until glazed","Add tomato sauce, tomato concentrate, sugar, salt, pepper, thyme/rosemary, oregano and basil to the mixture","Let the mixture boil on low heat (~2.5/10) for ~60min"],"time":60,"servings":8,"image":"https://based.cooking/pix/easy-pizza-sauce.webp","source":"https://based.cooking/easy-pizza-sauce","page":"easy-pizza-sauce","tags":["pizza","sauce","italian"]},{"id":"bc-fritatem-pomeranciis","title":"Fritatem pomeranciis","cuisine":"Italian","category":"Dessert","ingredients":["2 eggs","1 orange","1 teaspoon sugar","1 teaspoon olive oil"],"steps":["In a bowl, beat the eggs with sugar, orange juice, and a pinch of salt","Cook in a pan with frying oil","Serve warm"],"time":5,"servings":2,"image":"https://based.cooking/pix/fritatem-pomeranciis.webp","source":"https://based.cooking/fritatem-pomeranciis","page":"fritatem-pomeranciis","tags":["cream","dessert","eggs","fasting","italian","medieval"]},{"id":"bc-frittata","title":"Frittata","cuisine":"Italian","category":"Recipe","ingredients":["4-6 Eggs","1/2 Onion","1 Bell Pepper","2 Tbsp Heavy Cream","Thinly sliced meat (prosciutto, shaved chicken, sandwich steak, etc.) (Optional)","Shredded cheese of choice (Optional)"],"steps":["Dice peppers and onions and saute in an oven safe pan at medium heat","Add in meat to the pan and set oven to low broil","Beat eggs, cream, salt, and pepper together in a bowl","Add in egg mixture to the pan and mix together until even","Cook egg and vegetable mixture in pan until eggs begin to firm up and edges begin to pull away. Place into oven","Keep in Oven until completely firm. At this point you can add shredded cheese on top and put back into the oven until melted (about 2 more minutes)","Flip out of pan and cool to room temperature to ensure settling"],"time":30,"servings":4,"image":"","source":"https://based.cooking/frittata","page":"frittata","tags":["eggs","italian","cheesefare"]},{"id":"bc-fume-sauce","title":"Fumé sauce","cuisine":"Italian","category":"Pasta","ingredients":["200 g milk cream","150 g tomato sauce","100 g pancetta","olive oil","onion","paprica","parsley (optional)"],"steps":["Cut onion to small pieces and pancetta to cubes about 1 cm long","Fry them on low fire until onion darkens","Add milk cream and tomato sauce and stir","Add a small pinch of sugar, then season with salt and paprica","Cook stirring slowly on low fire for 10 minutes or until the sauce thickens"],"time":10,"servings":2,"image":"https://based.cooking/pix/fume-sauce.webp","source":"https://based.cooking/fume-sauce","page":"fume-sauce","tags":["cheesefare","italian","pasta","sauce"]},{"id":"bc-seafood-pasta","title":"Garlic Butter Seafood Pasta","cuisine":"Italian","category":"Pasta","ingredients":["spaghetti or fettucine","butter","heavy cream","garlic","oregano","white wine (Pinot Grigio or Sauvignon Blanc recommended)","lemon/lemon juice (optional)","red pepper flakes (optional)","seafood, choose from","mussels","squid","shrimp","clams","lobster"],"steps":["Prepare your pasta, if you don't know how I recommend to follow [these","Defrost/Deshell your seafood of choice","Chop a half tablespoon of garlic into small pieces","In a large pan on medium heat, saute your chopped garlic in salt and butter for a","Add and saute the seafood. Season with oregano, red pepper flakes and salt","Add a half cup heavy cream and a third cup of white wine to the pan. Cook until you have the","Drain your pasta (Which should be cooked by now) and pour contents of the pan into the pasta"],"time":null,"servings":null,"image":"","source":"https://based.cooking/seafood-pasta","page":"seafood-pasta","tags":["italian","pasta","quick","seafood","shrimp"]},{"id":"bc-gnocchi","title":"Gnocchi","cuisine":"Italian","category":"Side","ingredients":["potatoes","flour","tomato","parmesan","butter","sage or oregano or thyme"],"steps":["Boil potatoes (with their skins) until mashable","Slice potatoes in two and scoop them out of their skin","Mash with a potato-masher while adding kosher salt","Slowly begin to add flour while mashing and kneading until there are no lumps of potato and the potato/flour mixture takes on a dough-like consistency","Begin to boil more water with lots of kosher salt added","Flour a work surface, pinch off some of the dough and roll it on the surface into a long chubby snake","Slice the dough snake into small pieces. Press the pieces with your finger to make an indentation","Add the pieces to the boiling water. They will rise to the top when they are ready","In a pan, melt butter and add sprigs of sage (oregano or thyme will work as well, albeit are less traditional). Smashed tomato juices are also a nice addition","Add the cooked gnocchi to the pan and roast them in butter for a minute or two until slightly browned. As pan begins to dry, add some pasta water","Serve gnocchi on a plate, grate on Parmigiano-Reggiano cheese liberally. Add garnish if desired"],"time":null,"servings":null,"image":"","source":"https://based.cooking/gnocchi","page":"gnocchi","tags":["italian","potato","side","fasting"]},{"id":"bc-granita","title":"Granita","cuisine":"Italian","category":"Recipe","ingredients":["3 lemons","125 g sugar"],"steps":["Squeeze the lemons","Put in a pot the sugar, 175 g of lemon juice and pulp, and 300 ml of water","Boil for 10 minutes","Add 700 ml of water and stir","Wait for the solution to cool down to room temperature","Pour it in a container that can be frozen","Put it in the freezer","Now, for the most boring part: you must prevent the separation of the ingredients due to the freezing process, and the formation of one huge ice block","stir even if you don't see any ice yet : there may already be small crystals","if you find any ice block, make sure to break them down","don't worry if the ice melts when you stir: the water stays cold and will freeze again fast enough","Depending on the temperature, the whole thing may take much time to freeze: it's not unusual for it to require up to 20 hours","If you don't consume all granita at once, it may freeze to a block"],"time":null,"servings":6,"image":"https://based.cooking/pix/granita.webp","source":"https://based.cooking/granita","page":"granita","tags":["fasting","italian","lemon","sweet","traditional"]},{"id":"bc-grostoli","title":"Grostoli","cuisine":"Italian","category":"Recipe","ingredients":["A cup of sugar","800g of flour","A tablespoon of baking powder","A pinch of salt","4 eggs","3 tablespoons of lard or butter","4 tablespoons of a 40% a.b.v. spirit. Cachaça is the main one, Rum or Grappa will do","A cup of milk"],"steps":["Add sugar, flour, baking powder, salt and mix all these dry ingredients","Add eggs, grease, liquor, milk and mix it","Knead it in a table until it is homogenous","Divide the dough into smaller pieces and roll them with a pin on the table","Sprinkle the flour and finally, cut the dough into rectangles","Make a vertical cut in the middle, and twist the sides","Fry it in lard until it browns and sprinkle it on sugar and cinnamon"],"time":10,"servings":null,"image":"","source":"https://based.cooking/grostoli","page":"grostoli","tags":["Fry","Italian","Brazilian"]},{"id":"bc-herbs-pizza","title":"Herbs pizza","cuisine":"Italian","category":"Recipe","ingredients":["Dough","350 g flour (0 or 00)","25 g butter","15 g brewer's yeast","extra-virgin olive oil or lard","Stuffing","500 g boiled herbs (e.g. spinach, chicory, ribwort)","250 g ricotta","pepper (optional)","nutmeg (optional)"],"steps":["Carefully dry the herbs and cut them finely","Mix them with ricotta, salt, pepper and nutmeg","Knead flour with warm water and a little salt, and oil or lard","Add softened butter and yeast and knead a soft dough","Divide the dough in two parts and roll out each of them to a thickness of about 1 cm","Place the first disc on baking paper in a baking tray","Cover with the other disc and stick them together all over the border","Cover with a cloth and let it rise","Pierce gently all over the top layer with a fork","Preheat the oven to 180 °C","Place the pie in the oven and cook for 30 minutes"],"time":30,"servings":4,"image":"https://based.cooking/pix/herbs-pizza.webp","source":"https://based.cooking/herbs-pizza","page":"herbs-pizza","tags":["cheesefare","italian","baking","pie"]},{"id":"bc-italian-bread","title":"Italian Bread","cuisine":"Italian","category":"Bread","ingredients":["600g or 5 cups bread flour (or all-purpose if not available)","1 packet (appr. 2 1/4 tsp or 7g) active dry yeast","olive oil for greasing"],"steps":["Follow directions on the packet to activate yeast in a bowl large enough for mixing the dough","Add enough water for a total of 400g or 1 3/4 cups (i.e. add 400g minus however much water was used to activate the yeast)","Optionally add 12g or 2 tsp salt (Unsalted bread is normal in Central Italy, but it's an acquired taste)","Slowly mix in flour until it forms a dough that will be easy to work with and not overly sticky. Make sure there are no wet or dry pockets in the dough","Cover and let rest for 15 minutes","Knead the dough and let it rise covered for 1 hour in a warm place until doubled in size","Split the dough in half and shape it into two loaves. Make sure the seams are at the bottom","Place the loaves on a lightly greased baking sheet and let it rise covered for 1 hour in a warm place until doubled in size","Make sure the oven is preheated to 200°C (400°F) before the resting period is over","Score the loaves and place the baking sheet in the oven","Bake for 25-30 minutes","Let cool for 15 minutes before serving"],"time":30,"servings":null,"image":"","source":"https://based.cooking/italian-bread","page":"italian-bread","tags":["bread","italian","fasting"]},{"id":"bc-lasagna","title":"Lasagna","cuisine":"Italian","category":"Pasta","ingredients":["Parmesan cheese","Emental cheese (optional)","Dry mozzarella cheese","Fresh Bolognese sauce or about 1 litre worth of store-bought sauce","Béchamel sauce or ricotta lasagna filling","Lasagna pasta sheets"],"steps":["Prepare the bolognese or jared pasta sauce","When the sauce is almost done cooking prepare your béchamel or ricotta filling","If you want you can add 3-4 handfuls of grated emental cheese to the béchamel","If necessary, boil the lasagna noodles following the instructions on the packaging, start preheating your oven to 175°C/350°F","Spread a thin layer of pasta sauce on the bottom of a large, deep baking tray","Cover with lasagna sheets and spread a layer of béchamel sauce or ricotta, cover with lasagna sheets and spread a layer of pasta sauce if you want you can finely grate a little bit of parmesan on each layer of bolognese","Rinse and repeat the previous step until the tray is nearly full or you are running low on béchamel sauce/ricotta filling, take care that the last layer should be bechamel or ricotta","Grate some parmesan on top of your final layer and cover with Dry mozzarella cheese, wrap the top in aluminum foil","Place the tray in the centre of your pre-heated oven and let it cook for 30-35 minutes, after that remove the foil to let the top brown","Once it is done cooking take it out of the oven and cover again with aluminum foil, let it rest for 10 minutes before serving"],"time":45,"servings":6,"image":"https://based.cooking/pix/lasagna.webp","source":"https://based.cooking/lasagna","page":"lasagna","tags":["italian","pasta"]},{"id":"bc-limoncini","title":"Limoncini","cuisine":"Italian","category":"Dessert","ingredients":["Dough","250 g milk","25 g brewer's yeast","20 g sugar","50 g butter","650 g 00 or 0 flour","2 eggs","a pinch of salt","Stuffing","3 lemon untreated. Make sure the skin is edible!","250 g sugar"],"steps":["Cut the butter and let it soften","Dissolve the yeast in warm milk and softened butter","Add sugar and stir","Add the other dough ingredients and knead for a few minutes until you have a soft dough","Cover the dough and let it rise for about an hour","Meanwhile, grate the skin of the lemons","Add sugar and mix","Store the stuffing in a dry place","Roll out the dough to 1 or 2 a rectangles about 3 mm thick","Spread the stuffing on all the surface of the dough","Roll up the rectangle(s) tightly","Cut the rolls in slices about 1 cm thick","Lay them on baking paper in an oven tray","Let them rise again for another hour","Preheat the oven to 180 °C","Cook for about 20 minutes"],"time":20,"servings":20,"image":"https://based.cooking/pix/limoncini.webp","source":"https://based.cooking/limoncini","page":"limoncini","tags":["baking","dessert","dough","italian","lemon","sweet"]},{"id":"bc-mushroom-risotto","title":"Mushroom risotto","cuisine":"Italian","category":"Rice","ingredients":["Olive oil","1 shallot","4 cloves of garlic","300g button or crimini mushrooms","400g risotto rice (Arborio, Carnaroli or Vialone Nano)","1/2 cup white wine (optional)","Mushroom or chicken stock","Butter","Grated Pecorino or Parmesan cheese"],"steps":["Finely mince the shallot and garlic and slice the mushrooms into large pieces","Heat a pan with some olive oil on medium-high heat. Ideally this should be a wide skillet with tall sides, but a pot will also do the job","Saute the vegetables until fragrant, then add the mushrooms with a pinch of salt and cook them down until they're nicely browned, about 10 minutes or so","Add the rice in and let it toast for about a minute or so. This will develop some nice nutty flavors, but overdoing this will affect the creaminess of the finished dish","Deglaze with white wine and let the alcohol cook off. After that start ladling in the stock bit by bit stirring constantly for about 20-30 minutes (depending on the brand of rice used), until the rice is cooked but has a slight bite to it","Turn off the heat and add a couple tablespoons of cold butter and grated cheese, and stir well to emulsify. Check for final seasoning and serve"],"time":30,"servings":4,"image":"","source":"https://based.cooking/mushroom-risotto","page":"mushroom-risotto","tags":["italian","mushrooms","wine","rice"]},{"id":"bc-one-pot-chicken-tetrazzini","title":"One-Pot Chicken Tetrazzini","cuisine":"Italian","category":"Pasta","ingredients":["3 Tbsp Butter","8 oz Mushrooms, sliced","1 small Red Pepper, chopped","1 small Onion, finely chopped","1 clove Garlic, minced","3 Tbsp All-Purpose Flour","4 cups Milk","2 Tbsp Worcestershire Sauce","8 oz Extra Broad Egg Noodles","5 oz Boursin Garlic and Fine Herbs","3 cup Deli Chicken, cooked and cut into bite-size pieces","1/2 cup Frozen Peas","1/2 cup Fresh Parsley, chopped","Small Fresh Basil Leaves (optional)","Parmesan, grated"],"steps":["Melt butter in a large saucepan over medium-high heat. Add mushrooms, red pepper, onion and garlic; cook, stirring about 5 minutes until tender","Sprinkle with flour and stir. Gradually whisk in milk then Worcestershire, salt and pepper. Stirring occasionally, bring to a boil","Add noodles, reduce heat to a low boil. Stirring constantly and around edges of pan, cook until pasta is tender, about 7 minutes","Stir in chunks of Boursin, then chicken, peas, and parsley, stirring until chicken is hot and Boursin is melted. Serve sprinkled with basil and Parmesan"],"time":20,"servings":5,"image":"","source":"https://based.cooking/one-pot-chicken-tetrazzini","page":"one-pot-chicken-tetrazzini","tags":["chicken","pasta","italian"]},{"id":"bc-pasta","title":"Pasta (store bought)","cuisine":"Italian","category":"Pasta","ingredients":["pasta","basil (optional)","butter (optional)"],"steps":["Fill a large pot about half or 3/4th full with water","Salt the water profusely. The rule of thumb is that water for boiling pasta should taste as salty as the sea","Bring water to a rolling boil","Now add pasta","Keep it boiling, but decrease heat as it tries to overflow","Wait until pasta is at the preferred softness (see below), then strain it","While the pasta is sitting in your strainer, you may add basil leaves or other herbs and aromatics. I also recommend taking a knob or so of room temperature butter and add it in and stirring it, melting it into the pasta"],"time":null,"servings":null,"image":"","source":"https://based.cooking/pasta","page":"pasta","tags":["italian","pasta","quick","basic","fasting"]},{"id":"bc-pasta-alla-norma","title":"Pasta Alla Norma","cuisine":"Italian","category":"Pasta","ingredients":["3 aubergines (900g)","300g spaghetti","100ml olive oil","5 garlic cloves, minced","1 chilli (or 1 tsp of dried chilli flakes)","2 x 400g tinned chopped tomatoes","1 teaspoon dried oregano","1 teaspoon caster sugar","Fresh basil"],"steps":["Preheat oven to 220c (fan), or gas mark 7","Use a peeler to shave off alternating strips on your aubergines, so they looked striped, like zebras","Then cut the aubergine widthways into 1cm thick slices. Place into a bowl with 75ml of olive oil, a good pinch of salt and black pepper. Coat the aubergines, then spread them onto two or three baking paper-lined trays. Roast for 30-35 minutes until dark brown","Whilst the aubergines are cooking, put two tablespoons of olive oil into a frying pan or pot on a medium-high heat. Add garlic and chilies and fry for 1 minute (don't burn them!). Add tinned tomatoes, oregano, sugar and a pinch of salt and pepper to the pot. Reduce heat to medium low and cook until the sauce has thickened","Cook the pasta according to packet instructions, once al dente, drain and retain some of the pasta water","Once cooked, add the aubergine to the pasta sauce and mix well. Then add the spaghetti to the aubergine and sauce mixture, making sure everything is evenly coated. Add some of the pasta water if required to loosen the sauce, then top with fresh basil","Check for seasoning, then serve immediately"],"time":40,"servings":4,"image":"","source":"https://based.cooking/pasta-alla-norma","page":"pasta-alla-norma","tags":["italian","pasta","fasting"]},{"id":"bc-pasta-arrabbiata","title":"Pasta Arrabbiata","cuisine":"Italian","category":"Pasta","ingredients":["Pasta","Olive oil","Chilli flakes or diced chilli peppers","Crushed garlic cloves","Crushed tomatoes (about 800 gramms for 500 gramms of pasta)","Chopped parsley","Grated Pecorino Romano or Parmigiano Reggiano (optional, but highly recommended)"],"steps":["Start heating up water for the pasta","Heat up a few tablespoons of olive oil over low heat","Crush several cloves of garlic into the olive oil, add the chilli flakes or chilli peppers and fry them for a short time, while being careful not to burn the garlic","Add your crushed tomatoes, together with some salt and pepper, increase the heat to medium and let simmer for 10-15 minutes or until it looks nicely thickened","When the water starts boiling, put a handful of salt into it and then your pasta of choice. Ideally leave the pasta slightly undercooked, because it will go in the hot sauce and finish cooking there","When the sauce is almost ready, add most of your chopped parsley and stir it around. Save some to top the dish later","When the pasta is ready (ideally at the same time as the sauce or slightly later), strain it and add it to the sauce, which should be off the heat. If the sauce looks a bit too thick, add some of the pasta water. Mix well","Add some of the grated cheese of your choice and stir it in","Serve with some more grated cheese and chopped parsley on top"],"time":20,"servings":null,"image":"https://based.cooking/pix/pasta-arrabbiata.webp","source":"https://based.cooking/pasta-arrabbiata","page":"pasta-arrabbiata","tags":["pasta","quick","italian"]},{"id":"bc-pasta-sauce","title":"Pasta sauce","cuisine":"Italian","category":"Sauce","ingredients":["a can of San Marzano tomatoes (or home-grown with some extra pulp)","onion or garlic","olive oil","oregano or basil (Dried or diced)"],"steps":["Heat up olive oil on saucepan","Add and roast either diced or grated onion or crushed and sliced garlic until translucent","Add San Marzano tomatoes, include the liquids from the can if possible","Simmer contents of the pan and crush the tomatoes on the pan with your instrument of choice","Additionally add desired herbs"],"time":null,"servings":null,"image":"","source":"https://based.cooking/pasta-sauce","page":"pasta-sauce","tags":["italian","basic","sauce","fasting"]},{"id":"bc-pesto-chicken-quinoa-bowls","title":"Pesto Chicken Quinoa Bowls","cuisine":"Italian","category":"Recipe","ingredients":["1 1/2 cups raw quinoa","1 lb chicken breasts","2 tbsp olive oil, plus more for the pan","1 tbsp lemon juice","1 tsp Italian seasoning (or dried oregano)","1 tsp garlic powder (or 2 cloves, minced)","1/2 tsp red pepper flakes (optional)","2 cups cherry tomatoes","1 medium zucchini, quartered and sliced","1/4 cup pesto, plus more to serve","Fresh basil and grated parmesan, to serve (optional)"],"steps":["Boil salted water, add the quinoa, and cook about 15 minutes until tender. Drain well in a fine mesh strainer","Whisk the olive oil, lemon juice, Italian seasoning, garlic powder, and red pepper flakes in a large bowl with salt and pepper to taste. Add the chicken and toss to coat","Sear the chicken in an oiled skillet over medium-high heat, 5-6 minutes per side, until it reaches 165°F inside. Rest 5 minutes, then slice","Toss the tomatoes and zucchini in the leftover marinade bowl, then cook in the same pan over medium heat, 3-4 minutes, until the zucchini is tender and the tomatoes burst","Stir the pesto into the drained quinoa","Build the bowls with pesto quinoa, sliced chicken, and the vegetables. Finish with more pesto, basil, and parmesan"],"time":20,"servings":4,"image":"","source":"https://based.cooking/pesto-chicken-quinoa-bowls","page":"pesto-chicken-quinoa-bowls","tags":["chicken","quinoa","pesto","italian","bowl"]},{"id":"bc-ragu","title":"Ragù","cuisine":"Italian","category":"Pasta","ingredients":["1 pound tubular dried pasta","1 pound sweet Italian sausage","1 onion, minced","1 carrot, minced","1 celery stalk, minced","28oz (825 ml) can of whole tomatoes","3 tablespoon of tomato paste","1/4 cup fresh parsley","1 sprig of fresh thyme","1 sprig of fresh rosemary","grated Parmesan cheese (optional)","extra-virgin olive oil"],"steps":["Sauté sausage crumbles in a large pan or dutch oven over medium-low heat","Add minced onion, carrot, and celery, and parsley to the pan","Add canned tomatoes and their juice","Bring to a simmer then add thyme and rosemary","Continue simmer uncovered for 20 minutes, until thickened","Mix tomato paste with 1 cup of hot water","Cook about 10 minutes until the sauce is dark red and glistens with oil","Remove herb sprigs and add pepper to taste","Meanwhile, boil large pot of salted water then cook and drain the pasta","Serve ragù over plate of pasta and top with grated parmesan cheese;"],"time":null,"servings":null,"image":"","source":"https://based.cooking/ragu","page":"ragu","tags":["italian","pasta","cheesefare","fasting"]},{"id":"bc-red-sauce","title":"Red Sauce (Ragu all'Italiana)","cuisine":"Italian","category":"Sauce","ingredients":["1/3 lb salt pork","2 lb chuck roast","3 Cloves of garlic","Crushed hot red pepper","Sweet onion","Large carrot","2 Bay leaves","2 tbsp. Olive oil (she used mazola oil)","12 oz. Can tomato paste","29 oz. Diced tomatoes","29 oz. Tomato puree"],"steps":["Mince the garlic, peel the carrot, peel and cut the onion in half","Pour the oil in a large pot at medium low heat","Chop the salt pork and chuck roast simmer in oil with garlic","Simmer until the meat has browned","Add the tomato, full carrot, and onion","Add bay leaf and red pepper then give it a good stir","Lower heat let simmer for a few hours","Occasionally stir, and add water if sauce gets too thick","Add salt and pepper to taste"],"time":null,"servings":7,"image":"","source":"https://based.cooking/red-sauce","page":"red-sauce","tags":["italian","sauce"]},{"id":"bc-ricotta-lasagna-filling","title":"Ricotta lasagna filling","cuisine":"Italian","category":"Recipe","ingredients":["Ricotta cheese","One large egg","Parmesan cheese","Oregano (Optional)"],"steps":["Mix the ricotta cheese together with a handful of finely grated parmesan","Add the oregano and the egg and mix","Add salt and pepper to taste"],"time":null,"servings":5,"image":"","source":"https://based.cooking/ricotta-lasagna-filling","page":"ricotta-lasagna-filling","tags":["basic","italian","cheese"]},{"id":"bc-aglio-e-olio","title":"Spaghetti aglio e olio","cuisine":"Italian","category":"Pasta","ingredients":["1 pound (500g) spaghetti (or similarly shaped pasta)","1/2 cup (110g) extra virgin olive oil","5-6 cloves of garlic","1/4 tsp red pepper flakes","A bunch of fresh parsley"],"steps":["Heat a large skillet on medium-high heat, start cooking the pasta","Finely slice or mince the garlic and finely chop the parsley","Add the oil and garlic to the skillet and gently cook it until it's lightly golden brown","Add the red pepper flakes to the skillet and turn down the heat to let its flavor infuse the oil","When the pasta has finished cooking, drain it, and reserve at least around a cup of the cooking water","Now add the drained pasta with some of the cooking water to the skillet and toss vigorously. The starch in the pasta water will help the sauce emulsify and get it to the right consistency","At the very last second add the parsley, to preserve its freshness. Adjust the seasoning to taste if necessary"],"time":15,"servings":4,"image":"","source":"https://based.cooking/aglio-e-olio","page":"aglio-e-olio","tags":["italian","pasta"]},{"id":"bc-spaghetti-all-amatriciana","title":"Spaghetti all'amatriciana","cuisine":"Italian","category":"Pasta","ingredients":["Pecorino romano cheese preferably or Parmesan 1.5oz (40g)","Fresh chili pepper (as many as you'd like)","Extra virgin olive oil 1/4 cup (40g)","Guanciale preferably or Bacon 3.5oz (100g)","White wine 1/4 cup (60g)","Tomato passata 10oz (300g)","Spaghetti or similar long pasta 12oz (350g)","(optional) Extra pecorino romano or parmesan"],"steps":["Grate the pecorino and keep it aside","Mince the chili pepper(s) and keep it/them aside","Cut the guanciale in thin stripes and cook them in the oil with the minced pepper(s) for about 3 minutes on medium/high heat","Douse with the wine and turn up the heat. Cook until the alcohol has evaporated","Start cooking the pasta","Lower the heat to medium and add the passata, some salt and plenty of pepper. Cook for about 15 minutes","Once finished, drain the pasta and add the sauce and the pecorino/parmesan, mix well and serve immediately. Optionally you can add some pecorino or parmesan on top"],"time":25,"servings":4,"image":"https://based.cooking/pix/spaghetti-all-amatriciana.webp","source":"https://based.cooking/spaghetti-all-amatriciana","page":"spaghetti-all-amatriciana","tags":["italian","pasta"]},{"id":"bc-spaghetti-alla-puttanesca","title":"Spaghetti alla puttanesca","cuisine":"Italian","category":"Pasta","ingredients":["Pot of water","320g italian spaghetti","2 garlic cloves","10g salted capers","25g anchovies in oil","800g peeled tomatoes \"sugo\"","1 bunch of parsley","100g Gaeta olives","2 chopped chillies","A pinch of salt"],"steps":["Wash capers from salt, then cut them","Pit and crush Gaeta olives","Wash and chop the bunch of parsley","Start cooking the pasta until al dente","Pour the oil, the peeled garlic cloves and the chopped dry chilli peppers into a large pan","Add the anchovy fillets and capers","Brown over medium heat for 5 minutes, stirring often, so the anchovies will melt","Now add peeled tomatoes \"sugo\"; mix it with a spoon and cook for another 10 minutes over medium heat","When the sauce is ready, remove the garlic cloves","Add crushed olives and chopped parsley","Drain spaghetti directly in the pan and sauté it for half a minute","The dish is ready"],"time":7,"servings":4,"image":"","source":"https://based.cooking/spaghetti-alla-puttanesca","page":"spaghetti-alla-puttanesca","tags":["italian","pasta"]},{"id":"bc-spaghetti-sauce","title":"Spaghetti Sauce","cuisine":"Italian","category":"Sauce","ingredients":["4 28 oz cans of whole or diced tomatoes","1 6 oz can of tomato paste","12 garlic gloves","3/4 cup of olive oil","basil (optional)","red pepper flakes (optional)"],"steps":["Peel and mince garlic","Heat 1/2 a cup of olive oil in a large pot (high-low to low-medium heat), and heat the garlic until golden and fragrant","Add the tomato paste and 4 cans of tomatos and bring to a simmer. If adding red pepper flakes add them now","Cook uncovered for 45 minutes, stirring occasionally","Add a pinch of salt, the remaining 1/4 cup of olive oil, and basil if you are adding that"],"time":45,"servings":10,"image":"","source":"https://based.cooking/spaghetti-sauce","page":"spaghetti-sauce","tags":["tomato","sauce","fasting","pasta","italian"]},{"id":"bc-spicy-sausage-pasta","title":"Spicy Sausage Pasta","cuisine":"Italian","category":"Pasta","ingredients":["2 red onions, chopped","Olive oil","6 spicy Italian sausages","1 sprig rosemary, needles finely chopped","1 red chilli, deseeded and diced","A large glass of red wine (approx. 250ml)","2 x 400g tins chopped plum tomatoes","300g pasta, preferably penne","50g parmesan","300ml double cream"],"steps":["Fry red onions with a splash of oil in a deep frying pan. Add the sausage meat (discarding the casings if need be). Add the rosemary and chilli","Increase the heat and break up the sausage meat with a wooden spoon. Once meat has browned, pour in red wine and reduce by half. Add the chopped tomatoes and reduce the sauce, uncovered, for about 30 mins. Cook the pasta according to packet instructions","Grate the parmesan into a bowl. Drain the pasta and stir into the sauce with the parmesan, double cream and some seasoning","Serve :)"],"time":50,"servings":4,"image":"https://based.cooking/pix/spicy-sausage-pasta.webp","source":"https://based.cooking/spicy-sausage-pasta","page":"spicy-sausage-pasta","tags":["italian","sausage","pork","pasta","cream","spicy"]},{"id":"bc-tiramisu","title":"Tiramisù","cuisine":"Italian","category":"Dessert","ingredients":["4 eggs","100 g sugar","500 g mascarpone","300 g savoiardi biscuits","coffee at room temperature","cocoa powder"],"steps":["Separate albumen and yolks and beat the latter with the sugar in a bowl","Add the mascarpone and stir until uniform","In another bowl, beat the albumens until stiff","Add beaten albumens to the mascarpone cream gradually, stirring gently to not destroy the foam","Cover the bottom of a baking tray with a layer of cream","Cover it with a layer of savoiardi biscuits soaked in coffee","Add another layer of cream, then another of coffee-soaked savoiardi","Add one last layer of cream","Sprinkle cocoa powder on top","Store in the fridge for three hours"],"time":null,"servings":8,"image":"https://based.cooking/pix/tiramisu.webp","source":"https://based.cooking/tiramisu","page":"tiramisu","tags":["dessert","italian","sweet"]},{"id":"bc-tortellini","title":"Tortellini","cuisine":"Italian","category":"Pasta","ingredients":["Tortellini","1-2 eggs","Cooking cream","Cheese (optional)"],"steps":["Buy tortellini (prefer meat or spinach)","Bring water to a boil","Add salt to water only after boiling","Add tortellini in","Cook for 3 minutes","Drain water from the pot while keeping tortellini in","Add cooking cream and mix at medium heat until reduced a bit so it's more creamy","Turn off the heat and add 1 or 2 eggs","Mix in and let eggs cook using heat from the pot and tortellini","Serve on a plate. Add pepper, more salt if needed, and optionally, shredded cheese on top for extra creaminess"],"time":null,"servings":null,"image":"","source":"https://based.cooking/tortellini","page":"tortellini","tags":["italian","pasta","quick","cheesefare"]},{"id":"bc-tuscan-style-pork-roast","title":"Tuscan Style Pork Roast","cuisine":"Italian","category":"Recipe","ingredients":["1 pork Roast","2-3 Tbsp fresh rosemary","8 cloves garlic, minced","⅓ cup high quality olive oil","1 lemon","4 oz pancetta or bacon","1 tsp fresh parsley"],"steps":["Preheat oven to 275°F (135°C)","Butterfly the roast by cutting into three parts by cutting into the side starting a third of the way up the roast. When you get to the end of the roast open it up and repeat for the remaining roast. You're opening it up like a pamphlet. Refer to the video linked above if you're confused","Cover with plastic wrap and beat with meat mallet to pound the pork to an even levelness","Mince garlic cloves(8) with the rosemary(2 Tbsp). Place into a cold pan with olive oil(⅓ cup) and zest of lemon(1). Keep lemon for later","Bring to slow simmer on medium low heat for 2-3 minutes. Strain the herbs making sure to squeeze all excess oil. Reserve oil for later","Add pancetta/bacon(4 oz) to food processor. Pulse a few times before adding the garlic/rosemary mixture. Process until a smooth paste forms","Salt and pepper both sides of the roast before placing the roast fat side down and spreading the paste over the roast leaving about a 2 inch gap on one side","Roll tightly towards the 2 inch gap and use butchers twine to secure the roll. Place a knot every inch or so","Bake at 275°F (135°C) for 2 hours or until internal temperature reads 135°F (57°C) in the thickest part","Add olive oil to cast iron skillet and heat on high until ripping hot. Cut remaining lemon in half. Brown all sides of pork roast and lemon using tongs","Juice the lemon into the remaining oil from the garlic/rosemary herb spread. Add freshly chopped parsley. Whisk with fork until emulsified. Season with salt and pepper","Slice roast into ½ inch thick slices and top with lemon herb vinaigrette"],"time":120,"servings":6,"image":"https://based.cooking/pix/tuscan-style-pork-roast.webp","source":"https://based.cooking/tuscan-style-pork-roast","page":"tuscan-style-pork-roast","tags":["italian","pork","roast"]},{"id":"bc-wholemeal-pizza","title":"Wholemeal Pizza","cuisine":"Italian","category":"Recipe","ingredients":["1 serving Wholemeal Wheat Flour Pizza Dough","1 serving Easy Pizza Sauce","~80g mozzarella cheese","~40g Edam cheese","~40g Tilsitter cheese","salami (optional)","ham (optional)","salsiccia (optional)","aubergine (optional)","zucchini (optional)","mushrooms (optional)","olives (optional)","arugula salad (add after pizza is done) (optional)","fresh basil leaves (add after pizza is done) (optional)"],"steps":["Cover a baking tray fully with a thin layer of olive oil","Roll out the dough until it barely fits in the baking tray and place it in there","Spread the sauce on the pizza","Add any ingredients you want to add on top of the sauce (cheese last)","Bake the pizza for 10 minutes in the oven at 250°C","Add any fresh ingredients now","Cut into slices and serve"],"time":10,"servings":1,"image":"https://based.cooking/pix/wholemeal-pizza.webp","source":"https://based.cooking/wholemeal-pizza","page":"wholemeal-pizza","tags":["wholemeal","pizza","italian"]},{"id":"bc-wholemeal-wheat-flour-pizza-dough","title":"Wholemeal Wheat Flour Pizza Dough","cuisine":"Italian","category":"Recipe","ingredients":["500g flour (Wholemeal Wheat Flour)","280ml lukewarm water","8g dry yeast","3.5 spoon olive oil","1.5 teaspoon salt"],"steps":["Combine all the ingredients in a bowl and knead into a dough","Let it rest for ~60 minutes somewhere lukewarm"],"time":null,"servings":4,"image":"https://based.cooking/pix/wholemeal-wheat-flour-pizza-dough.webp","source":"https://based.cooking/wholemeal-wheat-flour-pizza-dough","page":"wholemeal-wheat-flour-pizza-dough","tags":["wholemeal","pizza","dough","italian"]},{"id":"bc-winter-risotto","title":"Winter Risotto","cuisine":"Italian","category":"Rice","ingredients":["3/4 cup Arborio Rice","1 cup Baby Spinach","2 Garlic Cloves","4 1/2 cup Vegetable Broth","1/4 cup Parmesan Cheese, shredded","1/2 lb Baby Tomatoes","1 Tbsp White Wine Vinegar","1/4 cup Walnuts, chopped","1/2 cup Leek, sliced","1 cup Mushrooms","3 Tbsp Unsalted Butter"],"steps":["Combine vegetable broth in a medium pot. Cover and bring to a gentle boil over medium heat. While broth comes to a boil, peel and mince/grate the garlic. Roughly chop the spinach. Thinly slice mushrooms","Heat a large non-stick pan over medium heat. When hot, add the butter, onions, leeks, and mushrooms. Season with salt. Cook, stirring occasionally, until softened (2-3 mins). Add rice, garlic, and vinegar. Cook, stirring constantly until fragrant (1-2 min)","Add 1 cup broth from the medium pot to the pan with rice. Stir until broth has been absorbed by rice. Continue adding broth 1 cup at a time, stirring regularly, until liquid is absorbed, the texture is creamy and the rice is tender (28-30 mins)","While risotto cooks, add tomatoes and a tablespoon of oil to a parchment-lined baking sheet. Season with salt and pepper, then toss to coat. Roast on the middle rack of the oven until tomatoes start to burst (10-11 mins)","When the last cup of broth has been absorbed and rice is tender and creamy, add Parmesan and spinach to risotto. Stir until spinach wilts (3-4 mins). Stir in roasted tomatoes. Divide risotto between bowls. Sprinkle walnuts over top"],"time":40,"servings":4,"image":"","source":"https://based.cooking/winter-risotto","page":"winter-risotto","tags":["mushrooms","rice","italian"]},{"id":"bc-grilled-mackerel-with-miso-soup-and-squash","title":"Grilled Mackerel with Miso Soup and Squash","cuisine":"Japanese","category":"Soup","ingredients":["2 Norwegian Mackerel Fillets","1 tbsp Sake","2 tbsp Miso paste","1/2 Onion","1 Summer Squash","1 tbsp butter","1 cup Jasmine Rice (optional)","Soy Sauce (optional)"],"steps":["Place the mackerel fillets in a small container at room temperature. Pour sake on both sides of the fillets and let rest in the container, covered, for 30 min","Cut onion into large slices","To a saucepan, add two cups of water, sliced onions, and miso paste. Whisk the solution until the miso paste is fully dissolved","Bring to a boil. Let the miso soup boil for about 10-15 min, then bring to a simmer","While the miso boils, peel the summer squash. Cut squash into 1/4 in half moons","In a large pan, melt 1 tbsp butter at medium-high heat","Grill squash in the pan for 5-10 min, until both sides of the squash are golden brown. Add salt and pepper to taste","Push squash one side of the pan","Season each fillet with about 1 tsp of salt","Place the fillets in the pan with the squash. Grill each side of the mackerel for about 4 min","Serve with rice and soy sauce"],"time":15,"servings":2,"image":"","source":"https://based.cooking/grilled-mackerel-with-miso-soup-and-squash","page":"grilled-mackerel-with-miso-soup-and-squash","tags":["fish","soup","japanese"]},{"id":"bc-japanese-noodle-soup","title":"Japanese Noodle Soup","cuisine":"Japanese","category":"Soup","ingredients":["750ml Chicken stock","4 Pork chops OR 4 Chicken Breasts","Set honey","3 Garlic cloves","Soy sauce","Worcestershire sauce","Ginger, sliced","Chinese 5 Spice","1 Red Chilli, sliced and deseeded (Optional, but recommended)","375g Ramen Noodles (Medium Egg Noodles work well too)","100g Spinach (Optional)","4 Tbsp Sweetcorn (Optional)","Sesame seeds (Optional)","4 Boiled Eggs (Optional)","1 Sheet of Dried Nori (Optional)","Spring Onion, chopped (Optional)"],"steps":["For the broth, add 700ml of chicken stock to a large boiling pot with the garlic, ginger, soy sauce, chinese five spice, chili, and 300ml of water","Bring this to the boil, then turn the heat to low and simmer for around 5 mins","Add a pinch of sugar and more soy sauce to taste","Fry the pork chops until cooked (My Sticky Pork Chops recipe works really well with this dish)","Hard boil 4 eggs","Cook the ramen noodles as per packet instructions","Strain the stock into another pan, then reheat","Divide ramen between 4 bowls, then top with 1 sliced pork chop, 1/4 of the spinach (if applicable) sweetcorn, and one boiled egg (halved)","Divide the stock into the bowls, then sprinkle over sesame seeds, shredded nori and the spring onion"],"time":20,"servings":4,"image":"https://based.cooking/pix/japanese-noodle-soup.webp","source":"https://based.cooking/japanese-noodle-soup","page":"japanese-noodle-soup","tags":["japanese","chicken","soup"]},{"id":"bc-miso-ginger-pork","title":"Miso Ginger Pork","cuisine":"Japanese","category":"Recipe","ingredients":["ground pork","sushi rice","green onion","fresh ginger","miso paste","pickled daikon","zucchini or bok choy","sesame oil (or olive oil)","broth (optional)"],"steps":["cook sushi rice","slice daikon, and pickle in a quick brine (rice vinegar, sugar, water)","dice white parts of green onion, mince green ends for garnish","mince fresh ginger","chop zucchini or bok choy into half inch (1-1.5 cm) chunks","heat up 2 tablespoons sesame oil","break up and brown ground pork till almost cooked through","salt and pepper the pork","add 1/2 cup to 1 cup (250-500 mL) water or broth","add white parts of green onion and ginger","add miso paste to taste","simmer stirring occasionally","add zucchini or bok choy, cook al dente","serve pork & veggies over bed of rice, garnish with green onion","(optional) add some spice! Sriracha or crushed red pepper are great"],"time":null,"servings":null,"image":"","source":"https://based.cooking/miso-ginger-pork","page":"miso-ginger-pork","tags":["japanese","pork"]},{"id":"bc-miso-soup","title":"Miso-soup","cuisine":"Japanese","category":"Soup","ingredients":["dashi stock","miso paste","tofu(optional)","seaweed(optional)","green onion(optional)"],"steps":["put about half of the water in the pot and bring the water to a boil","put the dashi stock in the pot","if you use tofu or seaweed, cut the ingredients into bite-sized pieces, place the ingredients in the pot and bring to a boil","Melt the miso in the water and bring the water to a boil","serve into small bowls","if you use green onion, slice them and put in a small bowls"],"time":null,"servings":null,"image":"","source":"https://based.cooking/miso-soup","page":"miso-soup","tags":["japanese","soup"]},{"id":"bc-okonomiyaki","title":"Okonomiyaki","cuisine":"Japanese","category":"Recipe","ingredients":["125g flour","1 egg","125ml water","Thinly sliced meat, any kind can do, sliced pork, beef, even bacon","Dashi powder or any desired seasonings","2-4 leaves cabbage","Pinch salt to taste","The following options are traditional but can be substituted with any desired toppings","Tonkatsu sauce (sometimes known as Bulldog sauce) in squirt bottle","Mayonnaise in squirt bottle","Sriacha in squirt bottle","Katsuobushi (Dried bonito flakes)","Nori (Dried roasted seaweed)"],"steps":["Chop cabbage into thin strips","Whisk water and egg together in a bowl and then whisk in flour, salt, and seasonings","Fold cabbage into batter with as few folds as possible to completely work the cabbage in","Fry meat in a pre-heated cast-iron pan or griddle on medium-high heat until brown on one side, flip, and immediately pour batter on top after flipping","Allow to cook for 2-3 minutes and either flip the pancake, or move under a broiler to cook the top for another 2-3 minutes","Move pancake to a serving plate meat side up and squirt tonkatsu sauce, mayonnaise, and sriracha over the top in a zig-zag pattern","Sprinkle katsuobushi and nori on top of the sauces and the okonomiyaki is ready to serve"],"time":10,"servings":1,"image":"","source":"https://based.cooking/okonomiyaki","page":"okonomiyaki","tags":["quick","japanese"]},{"id":"bc-spicy-mayo","title":"Spicy Mayo","cuisine":"Japanese","category":"Sauce","ingredients":["chili sauce (e.g Sriracha)","mayonnaise","sesame oil"],"steps":["Add 2 parts mayonnaise to 1 part chili sauce in a bowl","Add 1 tbsp of sesame oil for every cup of mayonnaise you use","Mix all of the ingredients together, and taste test it for more chili sauce or mayonnaise"],"time":null,"servings":null,"image":"","source":"https://based.cooking/spicy-mayo","page":"spicy-mayo","tags":["basic","sauce","japanese"]},{"id":"bc-sticky-porkchops","title":"Sticky Porkchops","cuisine":"Japanese","category":"Soup","ingredients":["4 Pork chops","2 heaped tbsp Set honey","3 Garlic cloves, crushed","Soy sauce","Ginger (thumb sized piece), sliced","1 tbsp Chinese Five Spice"],"steps":["Fill a shallow dish with soy sauce to about half the thickness of your porkchops. The level shouldn't be able to fully submerge them","Mix in the honey until fully combined with the soy sauce, then mix in the garlic, ginger and chinese five spice","Place your porkchops in the dish, then flip them","Cover the dish with clingfilm, then chill in the fridge for 1h 30mins","Take the dish out of the fridge, flip the porkchops, then recover the dish and chill for a further 1h 30mins","Heat some olive oil in a pan over medium heat, then place your porkchops in the pan and cook for 10-15mins or until cooked through","Take the porkchops out the pan, then rest for a couple of minutes before slicing and serving"],"time":10,"servings":4,"image":"","source":"https://based.cooking/sticky-porkchops","page":"sticky-porkchops","tags":["japanese","pork","soup"]},{"id":"bc-zaatar","title":"Zaatar","cuisine":"Lebanese","category":"Recipe","ingredients":["1 cup zaatar leaves (without the stalks), cleaned and dried","1 cup sesame (optionally roasted)","1 cup sumac","1 teaspoon salt","citric acid salt (optional), for extra kick if the sumac wasn't enough for you"],"steps":["Lightly roast the sesame in a wide pan until it get a golden brown color","Wait for the sesame to completely cool down","Mix everything together, starting from the zaatar and sesame while adjusting the sumac (optionally citric acid) and salt to taste","Store in an airtight jar or container"],"time":null,"servings":null,"image":"","source":"https://based.cooking/zaatar","page":"zaatar","tags":["palestinian","lebanese","mediterranean","middle eastern","spice"]},{"id":"bc-aljotta","title":"Aljotta","cuisine":"Mediterranean","category":"Soup","ingredients":["Fish stock (see 2.)","Fish, raw","Onion, roughly chopped","Garlic, sliced or diced","Tomatos, chopped","frying oil/lard","Extra virgin olive oil","Marjoram","Black pepper (optional)","Mint, small amount (optional, I never use it myself as it's too overpowering)","Lemon wedge/juice (optional, also overpowering)","Rice (optional)"],"steps":["Cook some rice and set aside. White short-grain is best but other types will do as long as it's not starchy. Don't use arborio or sushi rice","Prepare the stock, possibly the day before, by boiling fish and fish bones in a tall stock pot on medium heat for 1-2 hours. It's customary to have loose chunks of fish in the soup so you can boil the fish and separate the meat as it starts to cook. As an example, the head, tail, skin and spine from the anglerfish fillet recipe were used to make stock, then half a fillet and meat that separated from the offal became part of the soup","In a pot, heat some oil on low heat and add in the onions. Saute until translucent","Add the garlic, tomato, herbs and salt if desired. Switch to medium heat, stirring occasionally until the water starts to boil","Add the fish and let simmer on low heat until the fish are cooked thoroughly, being careful not to break them. Turn the heat off and add the olive oil","Take the fish out to be served separately. They are traditionally served topped with olive oil and a squeeze of lemon with steamed vegetables","If you are using lemon juice or rice, add them to each serving according to your preference","Leave some for tomorrow. It always tastes better the next day"],"time":null,"servings":null,"image":"","source":"https://based.cooking/aljotta","page":"aljotta","tags":["fish","soup","mediterranean"]},{"id":"bc-ardei-umpluti","title":"Ardei umpluti with meat","cuisine":"Mediterranean","category":"Recipe","ingredients":["2 yellow peppers per person","Around 120g of ground beef meat per person","1 or 2 onions","Condiments of your choice: Parsley, origan or cumin","Olive oil","Salt and pepper","Tomato sauce","Bechamel (optional)"],"steps":["Heat the oven to 200C","Empty the peppers and remove the seeds","Slice the top to the peppers and place them in the oven tray, you may need to slice the bottom a litte bit to make them stand together. (Hint: Put the peppers inside a pan over the oven tray)","Cover the peppers with aluminum and cook in the oven for 1h30min","Meanwhile, saute the onions, garlic and last, the meat","Mix with fresh tomato soup","When the peppers are finished, remove the aluminum, fill the peppers with the mix and cook in the oven for another 45 minutes","Optionally: (Not traditional!) Add the bechamel a couple of minutes before the time is up and finish cooking in the oven","Optionally: Instead of bechamel you can use sour cream","Enjoy"],"time":40,"servings":4,"image":"https://based.cooking/pix/ardei-umpluti.webp","source":"https://based.cooking/ardei-umpluti","page":"ardei-umpluti","tags":["romanian","peppers","baking","meat"]},{"id":"bc-chicken-paprikash","title":"Chicken Paprikash","cuisine":"Mediterranean","category":"Recipe","ingredients":["8 bone-in, skin-on chicken thighs","salt to taste","pepper to taste","2 cups chicken or beef broth","2 tablespoons olive oil","2 medium sized onions","1 tablespoon powdered garlic","3 tablespoons tomato paste","1/4 cup Hungarian paprika or regular paprika","1 tablespoon cayenne pepper (optional)","1 cup sour cream (optional)"],"steps":["Pat raw chicken thighs with paper towels for crispier skin. Season with salt and pepper","Heat up a heavy, deep-sided pan on high heat with a little olive oil","Add the chicken thighs skin-side down. Brown the thighs for five minutes on each side then remove each thigh and place them aside once browned","Add chopped onions to the pan with the chicken fat and sauce until the onions are golden","Add powdered garlic and tomato paste. Stir this another 5 minutes to create a tomato-roux","Add Hungarian paprika and stir another minute","Add chicken or beef broth and bring it to a medium temperature","Reduce the heat to medium low and transfer the chicken thighs from the plate back into the pan. Be sure not to waste any chicken fat","Cover the pan with a lid and simmer the dish for 45 to 60 minutes","With a fork, test to see that the chicken is tender. Add salt and pepper to taste afterwards","Plate the chicken with an optional dusting of cayenne pepper and serve it with some nice hearty bread. This dish has sour cream added to it traditionally, however if dairy is not your thing it’s delicious without it also. So for this last step you can add some sour cream to the sauce and stir it or add the sour cream at the end when you plate the chicken. Then garnish with herbs and enjoy!"],"time":85,"servings":8,"image":"","source":"https://based.cooking/chicken-paprikash","page":"chicken-paprikash","tags":["stew","chicken","hungarian"]},{"id":"bc-lebanese-lentil-soup","title":"Lebanese Lentil Soup","cuisine":"Mediterranean","category":"Soup","ingredients":["3 cups red lentils","12 cups water","1 large red onion, diced","2 small Yukon gold potatoes, diced","1 medium zucchini, diced","4 cups Swiss chard, chopped","1 bunch of cilantro, chopped","¼ cup of lemon juice, more to taste","1 teaspoon cumin"],"steps":["In a large pot, add lentils and water and place on medium heat to boil","In a pan, sauté onions until pink, about 5 minutes. Add chopped Swiss chard and sauté together until chard is wilted, 2-3 minutes","After lentils have cooked about 8 minutes, add onion chard mixture, along with diced potatoes and zucchini to the boiling water","Add salt and pepper to taste","Reduce heat to medium-low, cover the pot, and cook until the potatoes and lentils are completely cooked, about 12 minutes","Add the chopped cilantro. Stir and cook for about 5 minutes","Add lemon juice and cumin before serving"],"time":30,"servings":8,"image":"","source":"https://based.cooking/lebanese-lentil-soup","page":"lebanese-lentil-soup","tags":["soup","mediterranean","lebanese"]},{"id":"bc-lemon-and-oregano-chicken-traybake","title":"Lemon and oregano chicken traybake","cuisine":"Mediterranean","category":"Recipe","ingredients":["8 chicken thighs (skin on)","500g new potato","100g bacon lardon","8 shallots","5 oregano sprigs / heavy sprinkle of oregano leaves","2 tbsp olive oil","2 lemons","200ml chicken stock","100ml white wine"],"steps":["Heat oven to 220C/200C with fan/gas 7. While oven is heating up cut the new potatoes into 0.5cm - 1cm slices and tip them into a roasting tray. Drizzle 1tbsp of olive oil on the sliced potatoes, season well and toss to ensure a good coating. Then put the roasting tray into the oven for 20 minutes, or however long until the potatoes start to crisp","In a separate, temporary, tray place the chicken thighs and season them. Cut up the shallots into 1/8 parts, then the lemons into 1/4 wedges. Once this is done, take out the roasting tray and transfer the chicken, challots, lemon wedges and bacon lardons into it, with a final drizzle of 1tbsp of olive oil over the tray's items. Cook for another 20 minutes","Prepare the chicken stock and wine to take out the roasting tray for the last time before serving. Pour 200ml of chicken stock and 100ml of white wine over the tray's contents and return it to the oven for a final 20 minutes of cooking"],"time":60,"servings":4,"image":"https://based.cooking/pix/lemon-and-oregano-chicken-traybake.webp","source":"https://based.cooking/lemon-and-oregano-chicken-traybake","page":"lemon-and-oregano-chicken-traybake","tags":["mediterranean","chicken","baking"]},{"id":"bc-slow-cooked-lamb-with-lemon","title":"Slow-cooked Lamb with Lemon","cuisine":"Mediterranean","category":"Recipe","ingredients":["Lamb shoulder, or something similar, like lamb shank, preferably on the bone. Get something that will fit in your pot, with room for vegetables around it. For example, I usually get half a shoulder, 2 – 3 lbs, 1 – 1.5kg","a whole head of garlic","2 carrots","1 leek","1 onion","2 lemons","oregano","rosemary","potatoes (optional)","yoghurt (optional, to serve)","fresh bread (optional, to serve)"],"steps":["On the night before: Mix up some olive oil, the juice of half a lemon, the oregano, the rosemary, and some salt and pepper. Rub this mixture into the meat and leave it in the fridge overnight to marinate","The next day: Heat the oven to 375°F/190°C/gas mark 5","Break apart the garlic. You can leave the skin on the cloves, or you can peel them, as you prefer. Chop the carrots, leek, onion, the remaining lemon, and the potatoes into chunks","Arrange the meat in the pot with the vegetables underneath and around it. Pour in any marinating juices, as well as a cup of water","Cook for 2½ – 3 hours. Half way through it's a good idea to check and see if it needs some more water to keep things from burning","Remove the lid and let the meat brown for a few minutes if you think it needs it","Pull the meat apart and serve, with yoghurt and fresh bread. You can use the juices as a gravy"],"time":null,"servings":null,"image":"https://based.cooking/pix/slow-cooked-lamb-with-lemon.webp","source":"https://based.cooking/slow-cooked-lamb-with-lemon","page":"slow-cooked-lamb-with-lemon","tags":["lamb","roast","lemon","mediterranean"]},{"id":"bc-tabouleh","title":"Tabouleh","cuisine":"Mediterranean","category":"Salad","ingredients":["2 cups Cracked Wheat (bulghur)","2 cups Very Hot Water (or as directed)","1 Cucumber, chopped","2 small Tomatoes, chopped","1 bunch Green Onions, sliced","1/2 cup Mint (fresh), chopped","2 cup Parsley (fresh), chopped","1 clove Garlic, minced","1/2 cup Lemon Juice (fresh)","3/4 cup Olive Oil","1 Tbsp Pepper","2 tsp Salt"],"steps":["Soak the cracked wheat in the hot water until the water is absorbed, about 30 minutes","Drain any excess water, if necessary, and squeeze dry","Combine the salad ingredients (all but the oil, lemon juice, salt and pepper dressing ingredients) in a medium bowl","Mix the dressing ingredients together and stir into the salad mix","Serve chilled or at room temperature"],"time":30,"servings":12,"image":"","source":"https://based.cooking/tabouleh","page":"tabouleh","tags":["salad","mediterranean"]},{"id":"bc-zaatar-chicken-bulgur-bowls","title":"Za'atar Chicken Bulghur Bowls","cuisine":"Mediterranean","category":"Recipe","ingredients":["4 chicken breasts","1 cup bulghur wheat","1 oz mixed olives, drained","4 oz baby spinach, chopped","2 tbsp za'atar spice blend","2 Roma tomatoes","1 lemon","1/2 cup feta cheese, crumbled","2 garlic cloves, minced/grated","2 tbsp white vinegar","1 tsp sugar","oil"],"steps":["Preheat oven to 450F. Add 1 1/2 cup water and 1/4 tsp salt to a medium pot. Cover and bring to a boil over high heat. While water comes to a boil, cut tomato into 1/4\" pieces. Zest and juice the lemon","Add garlic and bulghur to the boiling water. Stir to combine, remove pot from heat, cover, and let stand until bulghur is tender and liquid is absorbed (15 mins)","While bulghur rehydrates, pat chicken dry and season with Za'atar spice blend, salt, and pepper. Heat a large non-stick pan over medium-high heat. Add 1/2 tsp oil, then the chicken. Sear until golden-brown. Transfer chicken to a sheet and bake on the middle rack in the oven until chicken is cooked through (10-12 mins)","Meanwhile, whisk together vinegar, lemon juice, lemon zest, 1 tsp oil, and 1/2 tsp salt in a small bowl. Set aside","When bulghur is done, fluff with a fork. Add olives, spinach, tomatoes, and half the dressing to the pot. Season with salt and pepper, then stir to combine","Thinly slice chicken. Divide bulghur salad between plates, then top with chicken. Sprinkle with feta and drizzle remaining dressing over top"],"time":20,"servings":4,"image":"","source":"https://based.cooking/zaatar-chicken-bulgur-bowls","page":"zaatar-chicken-bulgur-bowls","tags":["chicken","mediterranean","turkish"]},{"id":"bc-chicharrones","title":"Chicharrones","cuisine":"Mexican","category":"Recipe","ingredients":["Pork Butt with fat","Adobo Goya all purpose","Cumin","Goya Naranja juice","Corn oil (preferred)"],"steps":["Cut pork butt to around bite sized pieces with fat attached for frying and flavor","Add Adobo Goya and spread evenly throughout the pork","Add Black pepper 1 ml","Add Cumin 1 ml","Add Salt 5 ml","Add Goya Naranja 15 ml","Rub all of it to spread the spices along the meat","Have a colander to put the Chicharonnes in after having fried it and have another pot on the bottom that has some paper inside for oil","Put it in deep dish skillet around Medium (3-4) heat cover with lid for around 30-35 mins till you see it's cooked, turning to make sure everything is cooking evenly","After it dries up at around 30-35 mins put the temperature to High (6-7) without the lid","Put some oil to make sure it doesn't stick too much","Use spoon to spin/stir and fry until a golden brown","Take out the Chicharonnes and put into the colander. You may keep some of the fried bits that come off to eat as well"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicharrones","page":"chicharrones","tags":["mexican","pork"]},{"id":"bc-chili-con-carne","title":"Chili Con Carne","cuisine":"Mexican","category":"Recipe","ingredients":["Canned Whole Peeled Tomatoes","Red Peppers","White Onions","Chili Pepper","Garlic","Ground Beef","Kidney Beans","Dark Chocolate","Chili Powder","Tomato Paste","Beef Stock (optional)","Neutral Oil","Cilantro","Sugar","seasoning","cumin","paprika","chili flakes"],"steps":["Brown the beef by adding it to a pot with neutral oil. Start breaking it into small pieces. Allow water to leave the meat. Salt it to expel more water. Once water is gone, the sound will change and it will start to fry. Let it get a dark brown. Remove beef and set aside","Dice onions, red peppers, and chili peppers into small pieces (dice). Sautee until translucent. Add finely chopped garlic, chili flakes, paprika, cumin, and oregano","Add tomato paste to vegetables and let brown","Add meat to the vegetables","Add whole peeled tomatoes and some water (or stock)","Simmer for at least 45-60 minutes. Stir occasionally and add liquid if getting too dry","Stir in kidney beans and dark chocolate","Serve over rice and garnish with fresh cilantro"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chili-con-carne","page":"chili-con-carne","tags":["mexican","beef","beans"]},{"id":"bc-pork-based-chili-con-carne","title":"Chilli con Carne","cuisine":"Mexican","category":"Recipe","ingredients":["Chorizo pork sausage","Pork mince","Bacon strips","Tomato sauce","Chilis","Kidney beans","Olive oil","Wine","Butter","(spices)"],"steps":["As pan heats: Slice chilies and chorizo as desired","Olive oil in pan heat on high","Pork mince in","Butter add","Bacon add","Add 3/4 of tomato sauce","Add chilies and chorizo","Add spices and beans. Then wait until audible spitting of sauce has lasted for around 40 min","Add remainder of sauce","Add wine","Lower flame, cover pan, then maintain a gentle simmer for 20-40 min"],"time":120,"servings":null,"image":"","source":"https://based.cooking/pork-based-chili-con-carne","page":"pork-based-chili-con-carne","tags":["mexican","beans","pork"]},{"id":"bc-chimichanga","title":"Chimichanga","cuisine":"Mexican","category":"Recipe","ingredients":["taco-meat","1 Onion","Diced Tomatoes","1 Bell Pepper","Burrito sized tortilla","Plain Greek Yogurt or Sour Cream","Any other vegetables you want","Shredded cheese of choice (Optional)"],"steps":["Dice peppers, tomatoes, and onions and saute","Add in meat. Season and cook until browned or fully cooked through","Warm your tortilla and place small layer of yogurt, cheese, and filling on the bottom half of the tortilla","Wrap by folding bottom over filling, folding sides in, and then rolling","Fry using your preferred method (info on a couple of methods below)"],"time":30,"servings":4,"image":"","source":"https://based.cooking/chimichanga","page":"chimichanga","tags":["mexican","beef","basic"]},{"id":"bc-corn-salsa","title":"Corn Salsa","cuisine":"Mexican","category":"Sauce","ingredients":["2 pounds frozen corn, defrosted","1/2 Red onion, finely chopped","4 Radishes, sliced thin and chopped","Few pinches of Cilantro, finely chopped","1-2 Jalepenos, finely chopped (optional)","Juice of 2-3 Limes","Salt and pepper, to taste"],"steps":["Chop everything to pieces smaller than the corn kernels. Mix well and let sit covered in the fridge for at least an hour, even better overnight"],"time":60,"servings":null,"image":"","source":"https://based.cooking/corn-salsa","page":"corn-salsa","tags":["sauce","mexican"]},{"id":"bc-diannes-southwest-salad","title":"Dianne's Southwestern Cornbread Salad","cuisine":"Mexican","category":"Salad","ingredients":["1 (6-ounce) package Mexican cornbread mix","1 (1-ounce) envelope buttermilk Ranch salad dressing mix","1 small head romaine lettuce, shredded","2 large tomatoes, chopped","1 (15-ounce) can black beans, rinsed and drained","1 (8-ounce) package shredded Mexican four-cheese blend","6 bacon slices, cooked and crumbled","5 green onions, chopped"],"steps":["Prepare cornbread according to package directions, cool, and crumble. Then set aside","Prepare salad dressing according to package directions","Layer a large bowl with half each of cornbread, lettuce, and the next 6 ingredients: spoon half of dressing evenly over top. Repeat layers with remaining ingredients and dressing. Cover and chill at least 2 hours"],"time":15,"servings":10,"image":"https://based.cooking/pix/diannes-cornbread-salad.webp","source":"https://based.cooking/diannes-southwest-salad","page":"diannes-southwest-salad","tags":["salad","mexican"]},{"id":"bc-fajita-seasoning","title":"Fajita Seasoning","cuisine":"Mexican","category":"Recipe","ingredients":["1/2 tsp Garlic Powder","1/2 tsp Onion Powder","1/2 tsp Paprika","1/2 tsp Smoked Paprika","1/2 tsp Ground Cumin","1/2 tsp Ground Coriander","1/2 tsp Oregano","1/2 tsp Cayenne Pepper","1 tsp Salt","1 tsp Brown Sugar","1.5 tsp Chili Powder"],"steps":["Mix seasonings in a bowl. Adjust amounts depending on how much is needed"],"time":null,"servings":null,"image":"","source":"https://based.cooking/fajita-seasoning","page":"fajita-seasoning","tags":["basic","mexican","fasting"]},{"id":"bc-guacamole","title":"Fresh Guacamole","cuisine":"Mexican","category":"Snack","ingredients":["2 Hass avocados","1/4 medium onion","1 small tomato","Cilantro","1 lime"],"steps":["Cut the avocados in half, open them and place the pulp in a bowl","Mash the avocados, add lime juice, mix and mash some more","Mince the cilantro, tomato and onion and add them to the avocado mix","Add salt and black pepper to taste and mix thoroughly","Enjoy fresh with some totopos!"],"time":null,"servings":null,"image":"https://based.cooking/pix/guacamole.webp","source":"https://based.cooking/guacamole","page":"guacamole","tags":["mexican","spread","snack","fasting"]},{"id":"bc-frijol-con-puerco","title":"Frijol con puerco","cuisine":"Mexican","category":"Recipe","ingredients":["1 kg of black beans , rinsed and drained","2 kg of pork loin or ribs cut into 5 cm pieces, it can be mixture of the two","1 white onion without skin cut, in half","4 branches of fresh epazote , or 15 branches of coriander tied with kitchen twine","8 to 10 radishes , julienned or striped","1 cup of chopped cilantro","1 Mexican avocado , halved, pitted, pulp cut into squares","4 lemons , quartered","Yucatan style tomato sauce or Chiltomate to taste ( optional )","Mexican tortillas"],"steps":["In a large pot, put the black beans and 6 liters of water","Bring to a boil over medium heat and cook, with the lid half-open, for 45 minutes","Add the pork, onion, epazote or cilantro, and salt","Stir well. Cook for another hour and a half , with the pot partially covered, until the pork is cooked and tender","Make sure the broth does not dry out. You can add about 4 extra cups of boiling water after adding the pork","Put out the fire. Make sure the seasoning is OK","Serve the beans with pork with the radishes, cilantro, avocado, lemons, chiltomate sauce and habaneros","Enjoy with some authentic mexican tortillas"],"time":60,"servings":8,"image":"","source":"https://based.cooking/frijol-con-puerco","page":"frijol-con-puerco","tags":["beans","mexican","yucatecan","pork"]},{"id":"bc-loaded-mexican-rice","title":"Loaded Mexican Rice","cuisine":"Mexican","category":"Rice","ingredients":["1 Cup uncooked long grain white rice","1/2 Cup frozen peas","1/2 Cup frozen corn","2 Caned adobo chilies chopped","5 Tbsp tomato paste","1 Can of black or pinto beans","1/2 Cup ground meat (optional)","1/4 Onion diced (optional)"],"steps":["Cook rice per manufactures instructions","Pore enough neutral oil in a large pan to cover the bottom entirely, and turn on to medium heat","Once pan is hot add rice, brake up the rice to ensue there are no clumps","Add tomato paste and chilies to the pan, mix until rice is coated add water if needed","Strain and add the beans, corn, and peas; if you are adding meat and or onion do so now","Mix well, ensue peas and corn thaw","Serve hot as either a burrito or bowl with your choice of fillings/toppings"],"time":null,"servings":null,"image":"","source":"https://based.cooking/loaded-mexican-rice","page":"loaded-mexican-rice","tags":["rice","mexican","american"]},{"id":"bc-mexican-meat-loaf","title":"Mexican Meat Loaf","cuisine":"Mexican","category":"Recipe","ingredients":["1 lb Lean Ground Beef","1 cup Black Beans (canned), rinsed and drained","1 cup Salsa, divided","1/2 cup Corn (frozen)","1/2 cup Bread Crumbs","Cooking Spray"],"steps":["In bowl, place all ingredients except spray and using 3/4 cup of the salsa - mix well","Spray a loaf pan (approx. 5\"x9\"), and add above mix","Bake for 50 to 60 minutes - sit 15 minutes","Top with last 1/4 cup of salsa"],"time":60,"servings":4,"image":"","source":"https://based.cooking/mexican-meat-loaf","page":"mexican-meat-loaf","tags":["beef","baking","mexican","american"]},{"id":"bc-quesadilla","title":"Quesadilla","cuisine":"Mexican","category":"Recipe","ingredients":["1-2 tortillas. Any brand works, but you can decide if you want the tortilla folded in half, or 2 tortillas together","~4 small pinches of (Mozzarella, Oaxaca, or Montery Jack cheese)","Most cheeses are fine, but the taste of oaxaca cheese is more authentic","If you don't have pre-grated cheese, you can cut thin slices off of the block of cheese","A thin coating of oil on the pan. It will be more traditional, but also more unhealthy. (Optional)","Any ingredients you want. ie, veggies, chicken, mushrooms (cooked), or beans"],"steps":["Heat a pan to medium with an (optional) thin coating of oil","Lay a single tortilla down on the pan and arrange cheese on the edges","Arrange on 1 edge if you are making a folded quesadilla. Do both edges if using 2 tortillas. The cheese will help make sure the ingredients don't fall out when flipping","Add the ingredients onto one half of the tortilla if using 1, or the entire surface if using 2","Fold empty half of the tortilla in the pan onto itself if you are only using one tortilla","If you are using 2 simply place the second on top of the first","Periodically flip the tortilla until both sides are golden brown","This may be hard if using 2 tortillas, so try your best or transfer it to a plate, flip it with your hands, and transfer it back to the pan"],"time":null,"servings":null,"image":"https://based.cooking/pix/quesadilla.webp","source":"https://based.cooking/quesadilla","page":"quesadilla","tags":["mexican","quick","cheesefare"]},{"id":"bc-refried-beans","title":"Refried Beans","cuisine":"Mexican","category":"Recipe","ingredients":["400-500g can of pre-cooked beans","1/4 onion","3-4 garlic cloves","Cumin","Paprika","2-4 spoonfuls butter","Cooking oil (can be olive oil)"],"steps":["Add the oil and the butter to the frying pan and heat to medium heat","Chop the onion and mince the garlic","Once the frying pan is heated, add the onion and garlic to the pan, and fry","Add salt, cumin, and paprika to taste. Usually I add paprika until the mix is","Open the can of beans and pour the beans into the pan. Depending on how","Mash the beans and mix. Let them fry at medium-low to medium heat for about 5","Serve, and enjoy with some totopos"],"time":null,"servings":null,"image":"https://based.cooking/pix/refried-beans.webp","source":"https://based.cooking/refried-beans","page":"refried-beans","tags":["mexican","beans","fasting"]},{"id":"bc-salsa","title":"Salsa","cuisine":"Mexican","category":"Recipe","ingredients":["1 1/4 lbs (600 grams) tomatoes","1 14.5 oz (400 grams) canned tomatoes","1 green onion","1 red onion","1 jalapeño pepper","1 handfull fresh cilantro","1 clove garlic","1/2 lime, juice squeezed (optional)","1 chili pepper (optional)","1/4 tsp ground cumin (optional)"],"steps":["Add all ingredients to a food processor and burst shortly for desired degree of chunkyness","Refrigerate until consumption. (max 1 week)"],"time":null,"servings":14,"image":"","source":"https://based.cooking/salsa","page":"salsa","tags":["quick","basic","mexican","tomato"]},{"id":"bc-salsa-verde","title":"Salsa Verde","cuisine":"Mexican","category":"Sauce","ingredients":["1 pound (450g) tomatillos, husks removed","1 clove garlic","2 jalapeño or serrano chilies","1/2 cup (26g) chopped onion","3 Tbsp (40ml) oil","cilantro"],"steps":["Place tomatillos, garlic, and chilies in a medium saucepan and cover with water. Simmer until tomatillos turn pale green, about 10 minutes","Transfer tomatillos, garlic, and chilies into a blender or food processor. Add the onion and cilantro. Puree until smooth, then salt to taste, usually a teaspoon (6g) will suffice","Heat oil in a medium saucepan until hot but not smoking. Pour puree into the pan and cook, stirring occasionally, until thickened somewhat, about 6-8 minutes"],"time":null,"servings":null,"image":"","source":"https://based.cooking/salsa-verde","page":"salsa-verde","tags":["mexican","sauce"]},{"id":"bc-chicken-tacos","title":"Slow-cooked Chicken Tacos","cuisine":"Mexican","category":"Recipe","ingredients":["chicken breasts","two or three onions (preferably red)","seasoning","adobo seasoning","paprika","cheese (either shredded Mexican blend or crumbling cheese)","small tortillas","lime","cilantro, tomato, lettuce, other desired taco contents"],"steps":["Quarter two onions and spread on the bottom of a slow-cooker","Place chicken breasts on top of onions","Season slow-cooker contents liberally with adobo seasoning, paprika and any other desired seasonings, squeeze half of a lime too if desired","Let cook on low for 8 hours. Cooking on high for less time is possible as well, but a slower cook is preferable","Dice the tomato, cilantro, any lettuce and the third onion for taco contents","Shred chicken with forks once cooked. Optionally add a dash more seasoning for taste or appearance","Add chicken, cheese and all the diced ingredients to tortillas","Squeeze remainder of lime over finished product"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicken-tacos","page":"chicken-tacos","tags":["mexican","chicken","slowcooked"]},{"id":"bc-pork-carnitas","title":"Slow-cooked Pork Carnitas","cuisine":"Mexican","category":"Recipe","ingredients":["2 ½ lbs. boneless pork shoulder","6 cloves of garlic, cut into slivers","1 ½ teaspoons cumin","½ teaspoon sazon","¼ teaspoon dry oregano","¾ cup low sodium chicken broth","2-3 chipotle peppers in adobo sauce","2 bay leaves","¼ teaspoon dry adobo seasoning"],"steps":["Season pork with kosher salt and pepper","In a medium sauté pan on medium-high heat, brown pork on all sides","Remove from heat and allow to cool, about 10 minutes","Using a sharp knife, insert blade into pork, cutting small holes and insert garlic slivers as far in as you can","Pour chicken broth in slow cooker","Add pork and season with cumin, adobo, sazon, and oregano","Add bay leaves and chipotle peppers","Cover and cook low for 8 hours","After 8 hours, shred pork using 2 forks and combine with juices","Let cook for another 15-30 mins"],"time":510,"servings":10,"image":"","source":"https://based.cooking/pork-carnitas","page":"pork-carnitas","tags":["pork","slowcooked","mexican"]},{"id":"bc-taco-meat","title":"Taco Meat","cuisine":"Mexican","category":"Recipe","ingredients":["1 pound (about 500 g) ground beef or turkey","1 medium onion, finely chopped (or 1 1/2 teaspoon onion powder)","1 medium tomato, chopped (or 1 small can of tomato sauce)","1 teaspoon chili powder (or 1/3 teaspoon each oregano, cumin, garlic powder)","1 teaspoon oregano (ground or leaf)","1/4 teaspoon cumin","dash of pepper (1/8 teaspoon or less)"],"steps":["Brown beef and onion together. Drain grease","Add the rest of the ingredients to the browned meat","Stir well","Heat this mixture thoroughly","Add more tomato sauce if the mixture is dry","Cover and simmer for 20 minutes, or less if the mixture begins to dry out"],"time":null,"servings":null,"image":"","source":"https://based.cooking/taco-meat","page":"taco-meat","tags":["mexican","beef"]},{"id":"bc-challah-bread","title":"Challah Bread","cuisine":"Middle Eastern","category":"Bread","ingredients":["600ml ( 1 Pint ) warm water","1 tablespoon dry active baking yeast","7 tablespoons honey","1.5kg flour","3 eggs","1 tablespoon salt","1 tablespoon poppy seeds","4 tablespoons olive oil"],"steps":["Fill a large bowl with the water, and sprinkle with the yeast","Whisk together: honey, oil, 2 eggs, and salt. Add to bowl","Add flour to bowl in small amounts, beating/whisking after each addition","Once the mixtures becomes a viscous dough, begin kneading until smooth and elastic, and no longer sticky","Cover bowl with a damp cloth and let rise for 1-2 hours, or until dough has doubled in size","Sprinkle flour onto a chopping board, place the dough onto it and divide in half","Knead each half, adding flour as needed to keep the dough non-sticky","Divide each half into thirds and roll into a long snake about 4cm (1.5in) in girth","Pinch the ends of the each three snakes together firmly and plait them together, making two items of braided dough","Grease two baking trays or use baking paper, cover with dry cloth and let rise for one hour. Preheat oven to 190°C / Gas mark 5","Whisk an egg and brush onto each plait, sprinkle with seeds","Bake until bread has a hollow sound when tapped, cool on a rack for an hour before slicing"],"time":40,"servings":2,"image":"","source":"https://based.cooking/challah-bread","page":"challah-bread","tags":["israeli","bread"]},{"id":"bc-pilaf","title":"Pilaf","cuisine":"Middle Eastern","category":"Rice","ingredients":["150ml cooking oil","1kg long grain rice","1.5kg meat (lamb or any other kind of meat)","500g onions","500g carrots","2 tbsp salt","5 cloves of garlic","raisins, cardamom, paprika, coriander, cinnamon, cumin, turmeric (all optional)"],"steps":["Put the cooking oil in a cauldron and heat it until the oil is boiling, add a head of onion until it is black, then throw it out","Throw coarsely chopped meat into the cauldron and let it boil until it's golden brown, then add a pinch of salt","Add the chopped onions, then wait 2 minutes and add the sliced carrots, boil for another 2 minutes","Add 500 ml of water diluted with tomato paste, boil for 5 minutes","Rinse the rice and put it into the cauldron but do not mix","Add another 500 ml of water diluted with tomato paste and wait until it is boiling","Reduce the heat to minimum, then add two table spoons of salt","Close the cauldron and leave it on low heat for 1.5-2 hours","1 hour before it is ready(or when you can't see water above the rice), add the garlic","You can now turn over the rice if it is undercooked and add some raisins","Keep boiling until all water is evaporated"],"time":null,"servings":null,"image":"","source":"https://based.cooking/pilaf","page":"pilaf","tags":["uzbek","rice","lamb"]},{"id":"bc-tajine","title":"Tajine Maadnous","cuisine":"Moroccan","category":"Recipe","ingredients":["1 lb chicken breasts diced","1 medium onion chopped","1 large potato peeled and diced","1 cup water","1 small bunch parsley (about 1.5 cups, chopped, loosely packed)","8 large eggs","6 oz cheese","2 tbsp olive oil"],"steps":["Mix the spices together (grinding any whole spices if necessary) and set them aside","In a large frying pan or pot over medium heat, saute the onions in about 1 tbsp of olive oil until tender","Toss chicken with 1/2 of the spice mix. Add this to the pan and brown","Add the potatoes and the water to the pan. Bring to a gentle simmer, then cook uncovered until potatoes are tender and most of the liquid has evaporated","Stir chopped parsley into the cooked mixture and set aside to cool","Preheat oven to 350°F (180°C), and grease a medium (2 quart/liter) baking pan with the remaining olive oil","Thoroughly whisk the eggs in a large bowl, then mix in the cheese. Stir in the chicken, potato, and parsley mixture, along with the remaining spice mixture. Stir until well-combined, then pour into the oiled baking dish","Bake for 30-35 minutes, or until set in the center. Allow to cool, and serve warm or at room temperature. Serve with some harissa, if you like"],"time":35,"servings":12,"image":"https://based.cooking/pix/tajine-maadnous.webp","source":"https://based.cooking/tajine","page":"tajine","tags":["tunisian","Eggs"]},{"id":"bc-couscous","title":"Tunisian Couscous","cuisine":"Moroccan","category":"Recipe","ingredients":["2 lb lamb stew meat , cut into large pieces","6 cups couscous fine semolina (or medium)","2 onions , finely chopped","2 cloves garlic , pressed","4 tablespoons tomato paste","2 tablespoons harissa","2 tablespoons ground caraway","1 tablespoon ground coriander","1 teaspoon chili powder","4 turnips , cut in half","6 medium carrots , peeled","4 zucchini , peeled lengthwise, alternately leaving a layer of skin","6 small potatoes , peeled","10 oz. chickpeas (canned)","4 green hot peppers , fried in oil (optional)","Vegetable oil","Salt","Pepper"],"steps":["Add ½ cup (120ml) of oil into a large pan. Fry the onion over medium heat for 2 minutes","Add the garlic, tomato paste and harissa and continue frying for 2 minutes","Add the caraway, coriander, and chili powder. Mix and continue cooking for another 2 minutes","Add the lamb meat and mix well so that the pieces are covered with the sauce. Cook for 5 minutes stirring regularly","Cover with water. Add the turnips and carrots, and cook on low/medium heat for 45 minutes","Meanwhile, prepare the couscous semolina as indicated on the package, with boiling water, salt, and oil","After 45 minutes, add the zucchini, potatoes and chickpeas","Cook for at least another 30 to 40 minutes over low to medium heat. Monitor the cooking of the vegetables. If some vegetables are cooked before the meat, remove them from the pan and place them on a serving platter. Proceed in the same way with all the vegetables to prevent them from cooking too much","10 minutes before the end of cooking, get a few ladles of broth (one at a time) and wet the couscous semolina. Mix the semolina well after each ladle until it gets moistened enough","Arrange the semolina in a tajine pot. Decorate the dish with the vegetables and the meat all around. Garnish with fried green hot peppers (optional)"],"time":100,"servings":6,"image":"https://based.cooking/pix/couscous.webp","source":"https://based.cooking/couscous","page":"couscous","tags":["tunisian"]},{"id":"bc-tunisian-tajine","title":"Tunisian Tajine (laidback version)","cuisine":"Moroccan","category":"Recipe","ingredients":["4 medium sized potatoes","1 small onion (not super small)","200 grams of your favorite melty cheese","A dozen olives","5 eggs","A can of Tuna / 100 grams of shredded chicken","A small bunch of parsley / 150 grams of spinach leaves","Frying oil"],"steps":["Start by dicing the potatoes and onion, then thinly slicing the parsley/spinach. The smaller you chop the potatoes and onion, the faster they’ll cook","In a large pan, cook the parsley/spinach until it wilts and releases its moisture. Set aside","In the same pan, half-fry the potatoes and onion until they soften and turn lightly golden. If your pan isn’t deep enough to fully submerge them in oil, fry in batches. Once done, drain them well on a paper towel","In a large bowl, combine the potatoes, onion, parsley, olives, cheese, eggs, and your meat of choice. Mix thoroughly","Season with half a teaspoon of salt, a good pinch of black pepper, and a pinch of paprika if you it to have a bit of a kick","Pour the mixture into a baking dish and bake at 200°C until it passes the knife test (usually around 20-25 minutes)","Serve and enjoy!"],"time":20,"servings":null,"image":"https://based.cooking/pix/tunisian-tajine.webp","source":"https://based.cooking/tunisian-tajine","page":"tunisian-tajine","tags":["tunisian","baked","meat","vegetables","mediterranean","oven"]},{"id":"bc-air-fryer-zucchini","title":"Air Fryer Zucchini","cuisine":"Other","category":"Recipe","ingredients":["2 zucchinis","Pinch of season salt","Olive oil","Garlic powder (optional)","Onion powder (optional)"],"steps":["Chop the zucchinis into medium-sized squares","Put zucchini into a bowl and lightly add olive oil, season salt, garlic powder (optional), and onion powder (optional)","Cook in air fryer for 8 minutes at 400 F or until crispy"],"time":8,"servings":2,"image":"","source":"https://based.cooking/air-fryer-zucchini","page":"air-fryer-zucchini","tags":["zucchini","easy","quick"]},{"id":"bc-apple-strudel","title":"Apple strudel","cuisine":"Other","category":"Dessert","ingredients":["Puff pastry","Apricot jam (about 300 g | 10 oz)","3 apples","Ground cinnamon","Breadcrumbs / crushed cookies","Butter (optional)","Powdered sugar (optional)"],"steps":["Peel and cut the apples in thin slices","Roll out the puff pastry with a rolling pin","Spread the jam over the puff pastry with a spoon","Arrange the apple slices over the jam","Sprinkle with cinnamon and breadcrumbs","Cut tiny pieces of butter and arrange them over the apple slices","Roll the puff pastry edges over, overlapping them","Bake for around 40 minutes at 180°C (360° F)","Cover with powdered sugar"],"time":40,"servings":6,"image":"https://based.cooking/pix/apple-strudel.webp","source":"https://based.cooking/apple-strudel","page":"apple-strudel","tags":["dessert","breakfast"]},{"id":"bc-assam-tea","title":"Assam Tea","cuisine":"Other","category":"Drink","ingredients":["2 teaspoons of Assam Tea","150 ml of fresh water","Sugar (Optional)","Milk (Optional)"],"steps":["Add 150 ml of water to a small pan and bring it to boil","Then add 2 teaspoons of tea into it and reduce the heat to low","Strain the tea using a tea filter into a cup","Add sugar and milk to taste"],"time":5,"servings":1,"image":"https://based.cooking/pix/assam-tea.webp","source":"https://based.cooking/assam-tea","page":"assam-tea","tags":["drink","quick"]},{"id":"bc-autumn-soup","title":"Autumn Soup","cuisine":"Other","category":"Soup","ingredients":["1 Medium Squash","3 Potatoes","4 Carrots","1 Small Onion","1 Chicken Boullion Cube","1 cup Water","2 cups Milk","Salt","Pepper"],"steps":["Peel and chop squash, potatoes, carrots, and onion, add to oven-safe pot","Add boullion and enough water to avoid burning (1 cup), place pot in oven (350F) to bake until veggies are soft","If there is too much stock, don't be scared to pour some down the drain","Puree (I use electric beaters) while adding the milk","Add the salt and pepper, as desired"],"time":40,"servings":4,"image":"","source":"https://based.cooking/autumn-soup","page":"autumn-soup","tags":["vegetables","soup"]},{"id":"bc-ayran","title":"Ayran","cuisine":"Other","category":"Drink","ingredients":["1 part yogurt (2 parts if you prefer a creamier variety)","1 part ice-cold water","salt","mint (optional)","basil (optional)"],"steps":["Combine the yogurt and the ice-cold water","Mix well until no clumps remain","Add salt to taste","The traditional way to drink it is plain, but you can add some additional flavours with chopped mint or basil"],"time":null,"servings":null,"image":"","source":"https://based.cooking/ayran","page":"ayran","tags":["drink","dairy","breakfast"]},{"id":"bc-baked-salmon","title":"Baked Salmon","cuisine":"Other","category":"Recipe","ingredients":["Salmon Steaks","Red Pepper Flakes","Lemon Juice","Butter","Cooking oil / spray","Aluminum Foil"],"steps":["Season salmon with salt, black pepper, and red pepper to taste","Spray or rub in cooking oil on aluminum foil and place on cookie sheet or in baking pan","Squeeze lemon juice and place a teaspoon of butter on each salmon steak","Bake at 400°F / 200°C for 19 mins"],"time":19,"servings":null,"image":"","source":"https://based.cooking/baked-salmon","page":"baked-salmon","tags":["basic","fish"]},{"id":"bc-baked-trout","title":"Baked Trout","cuisine":"Other","category":"Recipe","ingredients":["cleaned trout","bacon","garlic (or garlic power)","butter","cayenne (optional)"],"steps":["Clean the trout and wrap each fish in a very thin slice of bacon, sprinkled with minced garlic (or garlic powder), and seasoned with cayenne (optional)","Cut a thin slice of butter and set in the middle of the trout","Enclose each fish in foil, cut larger than to fit so there is some overlap","Lay the trout in a pan, and bake them in the foil at 350 F/175 C for 15 minutes","To confirm the fish is finished, the skin of the trout should peel easily from the meat","Remove from foil and serve"],"time":null,"servings":null,"image":"","source":"https://based.cooking/baked-trout","page":"baked-trout","tags":["fish"]},{"id":"bc-banana-oatmeal-cookies","title":"Banana and oatmeal cookies","cuisine":"Other","category":"Snack","ingredients":["2 ripe bananas (250 g/9 oz peeled)","100g (3.5 oz) of oatmeal","1 table spoon of cinnamon powder (optional)","1 table spoon of honey (optional)"],"steps":["Pre-heat the oven to 180°C (350°F)","Peel the bananas and squash them not too finely in a bowl","Incorporate the oatmeal","Incorporate cinnamon powder and/or honey (optional)","On the oven tray, place parchment paper and form discs of the mix, each around 8 cm (3 in)","Cook with rotating heat for around 20 minutes, until outside becomes golden and slightly crispy","Eat warm or cold. Can be kept a couple of days in a sealed container"],"time":20,"servings":3,"image":"https://based.cooking/pix/banana-oatmeal-cookies.webp","source":"https://based.cooking/banana-oatmeal-cookies","page":"banana-oatmeal-cookies","tags":["snack","quick","dessert","cookies"]},{"id":"bc-banana-bread","title":"Banana Bread","cuisine":"Other","category":"Bread","ingredients":["2 cups all purpose flour","1 1/2 teaspoon baking powder","1/2 teaspoon baking soda","Spices","1 teaspoon cinnamon","1/4 teaspoon nutmeg","1/4 teaspoon ginger","1/4 teaspoon salt","1 1/2 cups mashed bananas (this is around 4-5 bananas)","2 eggs","1 cup sugar (brown or white is fine)","1/2 cup butter","1/4 cup crushed walnuts"],"steps":["Preheat oven to 350°F (175°C)","Mix the wet ingredients (eggs, bananas, butter, sugar) in one bowl","Mix the dry ingredients (flour, baking soda/powder, spices, salt) in another","Slowly add the wet to the dry while mixing","Mix until dry bits of flour are gone","Pour into lightly buttered or oiled loaf pan","Bake for around an hour (it's definitely ready when a wooden skewer or"],"time":null,"servings":null,"image":"","source":"https://based.cooking/banana-bread","page":"banana-bread","tags":["bread","dessert","sweet","fasting"]},{"id":"bc-banana-muffins-with-chocolate","title":"Banana Muffins with Chocolate","cuisine":"Other","category":"Dessert","ingredients":["3 bananas","100 g / ½ cups butter","150 g / ¾ cups sugar","2 eggs","1½ tsp. cooking powder","260 g / 2⅛ cups wheat flour","50 g / 1¾ oz dark chocolate","50 g / 1¾ oz milk chocolate","some vanilla sugar (optional)"],"steps":["Peel the bananas and mush them together","Whip the two eggs and mix them with the sugar","Melt the butter, cut the chocolate into smaller pieces, and whip the eggs","Pour the butter into the bananas, then add the flour, then the cooking powder, the chocolate, the whipped eggs and sugar, and the optional vanilla sugar; stirring it all the time","Pour the mass into your muffin dish","Heat up the oven to 160 °C / 320 °F and bake the muffins for around 20-30 minutes at 170 °C / 340 °F"],"time":30,"servings":null,"image":"https://based.cooking/pix/banana-muffins.webp","source":"https://based.cooking/banana-muffins-with-chocolate","page":"banana-muffins-with-chocolate","tags":["dessert","sweet","snack","cake","fasting","muffins"]},{"id":"bc-banana-pancakes","title":"Banana Pancakes","cuisine":"Other","category":"Breakfast","ingredients":["1 cup flour (2.5 dl)","1 tablespoon sugar","2 teaspoon baking powder","1 cup milk (2.5 dl)","1 egg","2 very ripe bananas"],"steps":["Combine flour, sugar, baking powder and a little bit of salt in a large mixing bowl","Whisk milk and egg into the flour mixture until no clumps remain in the resulting batter","Add mashed bananas and mix well","Add some butter to a medium warm frying pan","Make smaller or bigger pancakes, up to you. Wait until tiny air bubbles form on top (2 to 5 minutes), turn and continue frying until the bottom is browned. Repeat"],"time":10,"servings":4,"image":"","source":"https://based.cooking/banana-pancakes","page":"banana-pancakes","tags":["breakfast","quick","sweet","pancake","cheesefare"]},{"id":"bc-sweet-potato-fries","title":"Basic Sweet Potato Fries Recipe","cuisine":"Other","category":"Snack","ingredients":["1-2 Sweet Pototoes (try different types)","Olive Oil","Cinnamon","Rosemary (optional)"],"steps":["Set oven heat to 425°F (220°C)","Grab a pan and put a layer of parchment paper (or aluminum foil) on it","Chop the potato(es) on your cutting board with a sharp knife throwing them onto the pan","Drizzle the fries with olive oil. Toss the fries with clean hands to coat the fries in olive oil. Now wash your hands with soap to remove excess olive oil","Top generously with cinnamon and salt. Pepper and/or rosemary may be added for additional flavor if desired","Put in preheated oven. Setting timer for 20 minutes","At 20 minutes, flip the fries. Rubber tongs make it easy to grab and turn a lot","Return to oven setting timer for another 10-20 minutes depending on quality of the oven and desired crispiness","Enjoy. Maybe them put in a glass bowl"],"time":null,"servings":null,"image":"https://based.cooking/pix/sweet-potato-fries.webp","source":"https://based.cooking/sweet-potato-fries","page":"sweet-potato-fries","tags":["potato","snack","side","fasting"]},{"id":"bc-basic-waffles","title":"Basic Waffles","cuisine":"Other","category":"Dessert","ingredients":["250g butter","200g sugar","2 pcks vanilla sugar (16g) or other vanilla flavouring","5 eggs","500g flour","2 tbsp baking powder","350-400ml milk"],"steps":["Beat the eggs till creamy","Gradually add all the sugar and the vanilla flavouring","Melt and then mix in the butter","Add the baking powder","Add the milk and flower in alternation. Stir constantly while doing so","Blend and mix until you got a smooth dough. Use the highest speed of your mixer","Let the dough rest for a couple of minutes. Turn on & preheat your waffle maker, then pour in the dough. Bake inside the waffle maker till golden brown"],"time":20,"servings":null,"image":"https://based.cooking/pix/basic-waffles-01.webp","source":"https://based.cooking/basic-waffles","page":"basic-waffles","tags":["sweet","basic","dessert"]},{"id":"bc-batter-pudding","title":"Batter Pudding","cuisine":"Other","category":"Dessert","ingredients":["Six eggs","Eight table-spoonfuls of sifted flour","One quart of milk","A spoonful of salt"],"steps":["Stir the flour, gradually, into the milk, carefully dissolving all the lumps. Beat the eggs very light, and add them by degrees to the milk and flour. Put in the salt, and stir the whole well together","Take a very thick pudding-cloth. A square cloth, which when tied up will make the pudding of a round form, is better than a bag. Dip it in boiling water, and flour it","Pour into it the mixture and tie it up, leaving room for it to swell","Boil it hard, one hour, and keep it in the pot, till it is time to send it to table","Serve it up with wine-sauce"],"time":null,"servings":null,"image":"","source":"https://based.cooking/batter-pudding","page":"batter-pudding","tags":["batter","dessert","pudding"]},{"id":"bc-beef-and-broccoli","title":"Beef and Broccoli","cuisine":"Other","category":"Rice","ingredients":["1/2 lb Beef, cut into strips","2 Tbsp Vegetable Oil","1 Tbsp Ginger, minced","2 cloves Garlic, minced","1 cup Carrots, sliced","Snow Peas","Bean Sprouts","1 cup Broccoli Pieces","1/2 cup Beef Bouillon","1 Tbsp Corn starch","1 Tbsp Soy Sauce"],"steps":["Heat oil, add beef and stir-fry until meat is browned and push to sides of pan","Add broccoli and carrots. Cover and steam vegetables until they are only slightly crunchy","Remove vegetables to a bowl. Add bouillon, salt and pepper to meat","Combine corn starch, 2 Tbsp water, and soy sauce. Add to meat to thicken sauce","Add vegetables and heat. Serve over rice"],"time":20,"servings":3,"image":"","source":"https://based.cooking/beef-and-broccoli","page":"beef-and-broccoli","tags":["beef","asian","rice"]},{"id":"bc-beef-goulash","title":"Beef Goulash","cuisine":"Other","category":"Recipe","ingredients":["500g beef","300-400g potatoes","1 carrot","1 medium onion","12 tablespoons tomato paste","500ml water","3-4 garlic cloves","3-4 bay leaves","Curcuma","Paprika","Oregano","Parsley","Caraway","Basil (optional)","Cilantro (optional)","2-3 champignon mushrooms (optional)"],"steps":["Heat up the frying pan and add some oil","Cut the potatoes into small pieces and fry them on the frying pan over","Chop the onion","Cut the beef into small enough pieces and dust with flour","After about 15 minutes of frying the potatoes, add the onions and beef to the","While the beef, potatoes and onions are frying, cut the carrot and mushrooms,","Once the beef is brown, add water to the pan, and add the rest of the","Mix thoroughly, cover the pan with a lid and stew for about 60-80 minutes","Remove from stove, serve hot and enjoy with some beer or cider (or your"],"time":90,"servings":2,"image":"https://based.cooking/pix/beef-goulash.webp","source":"https://based.cooking/beef-goulash","page":"beef-goulash","tags":["beef","stew"]},{"id":"bc-beef-jerky","title":"Beef Jerky","cuisine":"Other","category":"Snack","ingredients":["¾ tsp. salt","¼ tsp. pepper","1 tbsp. brown sugar","¼ tsp. garlic","2 tbsp. Worcestershire sauce or Teriyaki sauce","¼ tsp. Liquid Smoke","1 Lb. (450 g) beef (flank or skirt steak is ideal)","Other common seasonings may include (¼ tsp. of) cayenne pepper, cheese powder, and/or white pepper"],"steps":["Mince or press garlic","Mix all ingredients except beef to make brine","Slice beef into ¼\" (½ cm) thick strips. Small chunks, about ¾\" (2 cm), of stewing beef may also be used. If possible, cut along the grain of the meat rather than across it. It may be easier to freeze the meat before attempting to cut it, as this will stop the meat pulling and deforming so easily","Marinate meat in overnight, or at least for an hour or two","Place meat on racks and dry in a food dehydrator at 145 °F (63 °C) for 6-8 hours. May be dried in a 150 °F (65 °C) oven with foil-covered racks. In oven, turn meat over 3-4 hours into drying time and reduce temperature to 130 °F (55 °C)","Meat should bend but not break when properly dried"],"time":null,"servings":null,"image":"","source":"https://based.cooking/beef-jerky","page":"beef-jerky","tags":["beef","snack"]},{"id":"bc-beef-kidney","title":"Beef Kidney","cuisine":"Other","category":"Recipe","ingredients":["1 beef kidney","60g butter","2 onions","2 shallots","1 sprig of fresh parsley","3 bay leaves","400g croutons or toasted bread in pieces"],"steps":["clean the kidney and remove the fat","cut the kidney into small chunks (2cm or 3/4\")","put butter in a casserole dish","add kidney, parsley, bay leaf, salt, pepper","brown in the casserole for 10 minutes while stirring (don't burn)","add 2 glasses of dry white wine","add half a glass of water so that the mixture is well-bathed","simmer for 35 minutes","add about 400g of toasted bread in pieces","simmer for another 10 minutes"],"time":45,"servings":2,"image":"","source":"https://based.cooking/beef-kidney","page":"beef-kidney","tags":["beef"]},{"id":"bc-bloody-mary-mix","title":"Bloody Mary Mix","cuisine":"Other","category":"Drink","ingredients":["1 (46 fluid ounce) bottle tomato-vegetable juice cocktail","1 fruit, without seeds lemons, juiced","1 teaspoon brown sugar","1 tablespoon steak sauce","1 tablespoon Worcestershire sauce","1 teaspoon prepared horseradish","1 teaspoon hot pepper sauce","1/2 teaspoon celery salt"],"steps":["In a large pitcher, combine juice cocktail, lemon juice and brown sugar. Season with Worcestershire sauce, horseradish, hot sauce and celery salt. Cover, and refrigerate 8 to 12 hours to allow flavors to meld"],"time":5,"servings":8,"image":"","source":"https://based.cooking/bloody-mary-mix","page":"bloody-mary-mix","tags":["drink","sweet","breakfast"]},{"id":"bc-blueberry-muffins","title":"Blueberry Muffins","cuisine":"Other","category":"Recipe","ingredients":["2 cups all-purpose flour","1 cup granulated sugar","1 tablespoon baking powder","1/2 teaspoon salt","1/2 cup unsalted butter, melted","1 cup milk","2 large eggs","1 teaspoon vanilla extract","1 1/2 cups fresh blueberries"],"steps":["Preheat the oven to 375°F (190°C). Line a muffin tin with paper liners or just grease the tin directly","In a large mixing bowl, combine the dry ingredients: flour, sugar, baking powder, and salt","In a separate bowl, whisk together the wet ingredients: melted butter, milk, eggs, and vanilla extract","Pour the wet ingredients into the dry ingredients and stir until just combined. Do not overmix","Gently fold in the fresh blueberries","Spoon the batter into the prepared muffin tin, filling each cup about three-quarters full","Bake in the preheated oven for 20-25 minutes, or until a toothpick inserted into the center of a muffin comes out clean","Remove the muffins from the oven and allow them to cool in the tin for a few minutes","Transfer the muffins to a wire rack to cool completely before serving"],"time":30,"servings":12,"image":"","source":"https://based.cooking/blueberry-muffins","page":"blueberry-muffins","tags":["berries","muffins","baking"]},{"id":"bc-blueberry-smoothie","title":"Blueberry Smoothie","cuisine":"Other","category":"Drink","ingredients":["1 Cup of from Blueberries","1 Cup of Whole Milk","1/2 Cup of Whole Greek Yogurt","A dab of Raw, Unfiltered Honey (optional)","Oats/Granola (optional)","A Drop or Two of Vanilla (optional)"],"steps":["Put it all in a blender","Blend it for like 10 seconds","Profit"],"time":5,"servings":1,"image":"https://based.cooking/pix/blueberry-smoothie.webp","source":"https://based.cooking/blueberry-smoothie","page":"blueberry-smoothie","tags":["fruit","drink","smoothie"]},{"id":"bc-bread","title":"Bread","cuisine":"Other","category":"Bread","ingredients":["1 1/2 cups warm water","2 and 1/4 teaspoons Active Dry Yeast","1 Tsp sugar","2 Tbsp maple syrup, agave, or honey","1/2 Tbsp salt","3 3/4 cups Unbleached All-Purpose Flour (plus more for rolling / dusting)"],"steps":["Proof the yeast. To do this warm 1/4 cup water to about bath water heat (110 degrees F, 43 degrees C) add active dry yeast and 1 Tsp sugar. Let sit for about 10 minutes, mixture should at least be doubled in size after waiting","Combine rest of water, yeast mixture, maple syrup (or other sweetener), salt, and flour in a large mixing bowl and stir. The result will be a sticky, rough dough. Use a spoon to stir until well combined and when it can no longer do the job, knead and turn it in the bowl with your hands","Lift the dough out and lightly grease the bowl with nonstick spray or olive oil. Cover and let rise for 2 hours at room temperature","Transfer dough to a lightly floured work surface and knead until dough is elastic. Rule of thumb is 10 minutes of kneading","Place seam-side down in a lightly greased loaf pan or baking sheet. Loosely cover with plastic wrap and let rest for 45-60 minutes","Preheat oven to 425 degrees F (218 C) toward the end of the dough resting time and place a metal pan (NOT glass, Pyrex, or ceramic) on the lowest oven rack. Also have 1 cup of hot water ready","When the oven is preheated, slash the bread 2 or 3 times with a knife, making a cut about ½-inch deep","Place in oven on middle rack. Then carefully pour hot water into the shallow pan on the rack beneath. Expect it to bubble and steam; then close oven door quickly","Bake the bread for 26 to 35 minutes, or until deep golden brown and risen. Tapping the top of the loaf should produce a hollow sound","Remove the bread from the oven and let rest in the pan for 5 minutes. Then carefully remove from pan and transfer to a cooling rack to cool. Let it cool completely before slicing for best results (otherwise it can be doughy in the middle)","Store leftovers in a plastic bag at room temperature for up to a few days. Transfer to freezer for longer term storage"],"time":null,"servings":null,"image":"https://based.cooking/pix/bread.webp","source":"https://based.cooking/bread","page":"bread","tags":["basic","bread","fasting"]},{"id":"bc-bread-pudding","title":"Bread Pudding","cuisine":"Other","category":"Bread","ingredients":["A quarter of a pound of grated stale bread","A quart of milk, boiled with two or three sticks of cinnamon, slightly broken","Eight eggs","A quarter of a pound of sugar","A little grated lemon-peel"],"steps":["Boil the milk with the cinnamon, strain it, and set it away till quite cold","Grate as much crumb of stale bread as will weigh a quarter of a pound. Beat the eggs, and when the milk is cold, stir them into it in turn with the bread and sugar. Add the lemon-peel, and if you choose, a table spoonful of rosewater","Bake it in a buttered dish, and grate nutmeg over it when done. Do not send it to table hot. Baked puddings should never be eaten till they have become cold, or at least cool"],"time":null,"servings":null,"image":"","source":"https://based.cooking/bread-pudding","page":"bread-pudding","tags":["bread","dessert","pudding"]},{"id":"bc-breakfast-wrap","title":"Breakfast Wrap","cuisine":"Other","category":"Breakfast","ingredients":["2 sausages","2 bacon rashers","1 egg","2 wraps","milk","ketchup (optional)"],"steps":["Begin by cutting the sausages in half and frying them ensuring that they're cooked the whole way through","Next, fry the bacon","Next, possibly while the bacon is frying, crack an egg into a bowl, add a dash of milk and whisk it","Then, put the egg mixture into the microwave for a minute, take it out and whisk it again, do this twice again or until the scrambled egg is ready","Add the sausage, bacon and scrambled egg to a wrap (I recommend two sausage halves, a bacon rasher and half the bowl of scrambled egg per wrap). Add ketchup if desired"],"time":10,"servings":1,"image":"","source":"https://based.cooking/breakfast-wrap","page":"breakfast-wrap","tags":["breakfast","quick","basic","eggs"]},{"id":"bc-ginger-garlic-broccoli","title":"Broccoli with Ginger and Garlic Sauce","cuisine":"Other","category":"Side","ingredients":["1-2 Broccoli (fresh best, frozen works too)","Minced garlic (1 tablespoon)","Minced ginger (1 tablespoon)","Sherry or regular white wine (you cook with what you drink with!) (1 tablespoon)","Soy sauce (1-2 tablespoon)"],"steps":["Cut broccoli into little flourettes (hold the broccoli upside down and cut around the stem with a pairing knife)","Fill your pan (or wok) around half inch (1.57cm) with water and bring to a rapid boil","Put broccoli in and steam with lid on for approx. 3 minutes","Drain broccoli and wipe pan dry","One teaspoon of oil and saute garlic and ginger (use sesame seed oil for Asian touch, but neutral or olive oil works well too)","Deglaze with sherry, put half a cup (approx 120 ml) of warm water or chicken stock. Reduce on medium-high heat","Stir in soy sauce, brown sugar and lemon juice to your taste","Thicken sauce with corn starch","Put dry cooked broccoli back in and saute for very short time (you want it nice and crunchy)"],"time":10,"servings":2,"image":"","source":"https://based.cooking/ginger-garlic-broccoli","page":"ginger-garlic-broccoli","tags":["side","quick","asian","fasting"]},{"id":"bc-broiled-trevally","title":"Broiled Trevally","cuisine":"Other","category":"Recipe","ingredients":["giant trevally","eggplants","squash (or zucchini)","carrots","onion","garlic","ginger","tomatoes","bay leaf","olive oil","thyme","basil","butter"],"steps":["Dice carrots, eggplant, squash, tomatoes and onions. Place these on a pan","Put basil, thyme, bay leaf, salt, and pepper on each of the fish's side. Place the fish above the veggies","Crush garlic and ginger (with mortar and pestle, of course) and place this in and around the fish","Give it all a good splash of olive oil","Cover the pan and set to medium-low fire, until everything looks cooked","Flip the fish on the other side, just to make sure that it's properly cooked","Check the doneness of the squash: if it's cooked, everything is","Let everything set for 5 mins. before serving"],"time":null,"servings":null,"image":"","source":"https://based.cooking/broiled-trevally","page":"broiled-trevally","tags":["fish","cheesefare"]},{"id":"bc-broiled-venison-steaks","title":"Broiled Venison Steaks","cuisine":"Other","category":"Recipe","ingredients":["venison","butter","wine","jelly (cranberry, peach, or grape)"],"steps":["Cut the steaks not quite an inch thick","Trim them nicely, and season them with a little black pepper and salt","Have ready, over a bed of clear bright hot coals from a wood fire (or a stove), a gridiron with grooved bars to catch the gravy","Put down the steaks, and when one side is quite done turn the other, and broil that. (Venison should always be very thoroughly done.)","Before you take up the steaks, lay a bit of nice fresh butter upon each","Take them up on a hot dish, and keep them warm","Pour off the gravy into a small saucepan. Give it a boil over the fire, and skim off all the fat from the surface","Stir into it some nice wine, and serve up with the steaks a deep dish of cranberry, or peach sauce, or a large cup of grape jelly"],"time":null,"servings":null,"image":"","source":"https://based.cooking/broiled-venison-steaks","page":"broiled-venison-steaks","tags":["venison","meat"]},{"id":"bc-cinnamon-biscuits","title":"Brown Butter Cinnamon Sugar Biscuits","cuisine":"Other","category":"Dessert","ingredients":["1 stick (½ cup / 113g) unsalted butter","2 cups (250g) all-purpose flour, plus extra for dusting","2 tablespoons (25g) granulated sugar","2½ teaspoons (12g) baking powder","1 teaspoon (6g) fine sea salt","½ tablespoon (4g) ground cinnamon","½ cup + 2 tablespoons (150ml) cold whole milk","4 tablespoons (½ stick / 57g) unsalted butter (for glaze)","¼ cup (50g) granulated sugar (for glaze)","1 teaspoon (3g) ground cinnamon (for glaze)"],"steps":["In a saucepan, melt 1 stick of butter over medium heat. Swirl until it foams, turns golden brown, and smells nutty. Pour into a bowl and refrigerate until solid and cold (30-45 minutes)","In a large bowl, whisk together the flour, 2 tablespoons sugar, baking powder, salt, and ½ tablespoon cinnamon","Cut the cold browned butter into cubes. Using a pastry cutter or your fingers, work it into the flour mixture until it resembles coarse crumbs","Make a well in the center and pour in the cold milk. Gently stir with a fork until a shaggy dough forms","Turn dough onto a floured surface. Gently knead 4-5 times, then press into a rectangle. Fold the dough into thirds like a letter. Rotate 90 degrees, press out, and repeat the folding process 3 more times","After the final fold, shape dough into a 1-inch thick square. Trim off the edges with a floured knife, then cut into 9 equal squares. Gather scraps and shape into 1-2 more biscuits","Preheat oven to 425°F (218°C). Place biscuits close together in a buttered skillet or on a parchment-lined sheet","Bake for 18-22 minutes, until tops are golden brown","While biscuits bake, melt the 4 tablespoons of butter for the glaze. Mix ¼ cup sugar with 1 teaspoon cinnamon in a small bowl","As soon as biscuits come out of the oven, brush tops liberally with melted butter, then immediately sprinkle or dip in the cinnamon sugar mixture. Serve warm"],"time":20,"servings":9,"image":"","source":"https://based.cooking/cinnamon-biscuits","page":"cinnamon-biscuits","tags":["biscuit","dessert","breakfast","pastry"]},{"id":"bc-brown-sauce","title":"Brown Sauce","cuisine":"Other","category":"Sauce","ingredients":["1 onion","75g butter","1dl flour","1l bouillon","Black pepper freshly grounded"],"steps":["Chop and sauté the onions and put the aside for a while","Melt the butter on a pan and add the flour to it","Brown the flour on medium heat until the mixture is dark brown","Add the bouillon in small batches while stirring with a whisker","Let the sauce boil and thicken for few minutes","Add the onions and ground some pepper in the sauce","(optional) Add preferred meat to the sauce or use as is"],"time":20,"servings":6,"image":"","source":"https://based.cooking/brown-sauce","page":"brown-sauce","tags":["sauce"]},{"id":"bc-butter-biscuits","title":"Butter Biscuits","cuisine":"Other","category":"Recipe","ingredients":["Half a pound of butter","Two pounds of flour, sifted","Half a pint of milk, or cold water","A salt-spoonful of salt"],"steps":["Cut up the butter in the flour, and put the salt to it. Wet it to a stiff dough with the milk or water. Mix it well with a knife","Throw some flour on the paste-board, take the dough out of the pan, and knead it very well","Roll it out into a large thick sheet, and beat it very hard on both sides with the rolling-pin. Beat it a long time","Cut it out with a tin, or cup, into small round thick cakes. Beat each cake on both sides, with the rolling-pin. Prick them, with a fork. Put them in buttered pans, and bake them of a light brown in a slow oven"],"time":null,"servings":null,"image":"","source":"https://based.cooking/butter-biscuits","page":"butter-biscuits","tags":["biscuit","basic"]},{"id":"bc-butter-cake","title":"Butter Cake","cuisine":"Other","category":"Dessert","ingredients":["250g unsalted butter (warm to room temperature first)","130g caster sugar","1tsp vanilla extract","4 egg yolks","200g sifted self-raising flour (use as little as 180g for a moister texture)","60mL milk","(optional) 30g cocoa powder (for a marbled appearance)","50g caster sugar","Egg whites separated from the yolks above"],"steps":["Beat butter, sugar, and vanilla extract until incorporated","Beat in egg yolks one at a time","Beat in half of the sifted flour, then the milk. Take care not to overwork the gluten after the flour is added. You may well find that manually stirring in the flour yields better results","Beat or stir in the remainder of the flour until just incorporated","(optional) Separate approximately one-third of the batter and mix in with it cocoa powder","To make the meringue, beat egg whites at high speed while gradually adding sugar until firm peaks form","Fold the meringue into the batter. If you have done the fifth optional step, then you'll need to portion out approximately one-third of the meringue for the cocoa batter, and the remainder for the normal one","Pour the batter(s) into a cake tin, and tap it on the countertop to get rid of any large air pockets","(optional) For the marbled appearance, run a skewer or chopstick through the batter a few times. Do not overdo this lest you end up with a homogenously light brown cake rather than a yellow cake with dark brown streaks","Bake at 175°C/350°F (conventional non-fan-forced) for 40-60min depending on the resulting batter thickness in your specific cake tin. Just keep an eye on it and you'll be fine; test its doneness by inserting a skewer and seeing whether it comes out clean"],"time":50,"servings":8,"image":"","source":"https://based.cooking/butter-cake","page":"butter-cake","tags":["dessert","sweet","snack"]},{"id":"bc-carbonade","title":"Carbonade Flamande (Traditional Flemish beef stew)","cuisine":"Other","category":"Recipe","ingredients":["beef (chuck, brisket, oxtail...): 1kg | 2 1/4lb","gingerbread: 5 slices","brown sugar: 1tbsp","brown beer (try to get a strong, tasty one): 1L | 4 cups","onions: 400g | 1lb","diced smoked bacon: 250g | 1/2lb (optional)","mustard","butter","olive oil","thyme","cloves (not garlic cloves, just cloves): 5","juniper berries: 5","bay leaves: 2"],"steps":["Cut meat into big chunks","Dice onions","Sear the meat on high heat in a large stainless or cast iron pot until golden brown, using olive oil. Don't overcrowd the pot. Meanwhile, start sweating the onions in a pan, with the butter, and the smoked bacon","Set meat aside, deglaze the pot with a bit of beer, put in the onions, bacons and the brown sugar","Once the sugar is melted and the pot is deglazed properly, put the meat back in","Pour the rest of the beer into the pot","Toast the slices of gingerbread with a bit of mustard, put in the pot","Add thyme, bay leaves, cloves, juniper berries","Add salt","Let it simmer for 4 to 8 hours. Check on it regularly and add water if you feel like the sauce is too thick and you need to cook it longer","Serve with a nice mashed potato"],"time":480,"servings":4,"image":"","source":"https://based.cooking/carbonade","page":"carbonade","tags":["stew","beef"]},{"id":"bc-cheddar-crusted-chicken","title":"Cheddar-Crusted Chicken","cuisine":"Other","category":"Recipe","ingredients":["2 Chicken Breasts","2 Tbsp Mayonnaise","1/4 cup Panko Breadcrumbs","1/4 cup Cheddar Cheese, shredded","1 Tbsp Smoked Paprika-Garlic Blend"],"steps":["Combine panko, cheese, and smoked paprika-garlic blend in a shallow dish. Preheat oven to 425F","Pat chicken dry with paper towel. Carefully slice into the centre of each chicken breast lengthwise and parallel to the cutting board - leaving 1/2 inch intact on the other end. Open up chicken like a book, and season both sides with salt and pepper","Coat one side of each chicken breast with mayo. Firmly press mayo-coated side into panko mixture to adhere, one at a time","Transfer chicken to a parchment-lined baking sheet, coated-side up. Bake chicken on the middle oven rack until cooked through (18-20 mins)"],"time":20,"servings":2,"image":"","source":"https://based.cooking/cheddar-crusted-chicken","page":"cheddar-crusted-chicken","tags":["chicken"]},{"id":"bc-cheesy-meatballs","title":"Cheesy Meatballs with Tomato Sauce","cuisine":"Other","category":"Recipe","ingredients":["300-400g of ground beef meat","1/4 of an onion","~70g of cheese; I have made with different cheese types, but usually I use","Parsley","1-2 garlic cloves","1 egg","~1/5 metric cups (~50ml) of bread crumbs","250ml of water","8 spoonfuls of tomato paste","Oregano","Basil","Black pepper"],"steps":["Beat the egg(s) in a large bowl","Add in the ground beef, and the bread crumbs and mix","Chop the onion into small pieces and add it to the bowl","Mince the garlic cloves and add to the bowl","Dice the parsley leaves and add to the bowl","Salt the beef mix and mix it thoroughly","Cut the cheese into cubes. The amount of cubes you will need will depend on","Take a cheese cube and wrap with enough ground meat to completely cover it","Heat the frying pan, add some olive oil, and add the meatballs. Cook over","When the meatballs look done, pour the water and tomato paste; add the dried","Cook over medium-low heat for about ten minutes rolling the meatballs so","Serve with some side dish and enjoy!"],"time":null,"servings":null,"image":"https://based.cooking/pix/cheesy-meatballs.webp","source":"https://based.cooking/cheesy-meatballs","page":"cheesy-meatballs","tags":["beef","cheese"]},{"id":"bc-chicken-biscuit-potpie","title":"Chicken Biscuit Potpie Recipe","cuisine":"Other","category":"Recipe","ingredients":["1-2/3 cups frozen mixed vegetables, thawed","1-1/2 cups cubed cooked chicken","1 can (10-3/4 ounces) condensed cream of chicken soup, undiluted","1/4 teaspoon dried thyme","1 cup biscuit/baking mix","1/2 cup whole milk","1 large egg"],"steps":["Preheat oven to 400°F (200°C). In a large bowl, combine the vegetables, chicken, soup and thyme. Pour into an ungreased deep-dish 9-in. pie plate. Combine the biscuit mix, milk and egg; spoon over chicken mixture","Bake until topping is golden brown and toothpick inserted in the center comes out clean, 25-30 minutes"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicken-biscuit-potpie","page":"chicken-biscuit-potpie","tags":["chicken"]},{"id":"bc-chicken-soup","title":"Chicken Soup","cuisine":"Other","category":"Soup","ingredients":["2 chicken breasts","1 Onion","2 carrots","2 celery stalks","32 oz / 950ml Chicken Stock or Broth","Pasta (Optional)"],"steps":["Cook chicken breasts, shred, and set aside in a bowl","Cut up carrots and celery, place in pot and saute","Add in chicken and stock or broth and mix together well. Season with salt, pepper, hot sauce, whatever you desire","Allow it to simmer on low heat for 2 hours mixing every so often","If adding noodles, add in pasta and allow pasta to cook until al dente"],"time":120,"servings":null,"image":"","source":"https://based.cooking/chicken-soup","page":"chicken-soup","tags":["chicken","soup"]},{"id":"bc-chicken-stock-bone-broth","title":"Chicken Stock or Bone Broth","cuisine":"Other","category":"Recipe","ingredients":["a whole raw chicken with organs removed (Drumsticks or thighs alone might suffice if a whole chicken is unavailable.)","onions","celery","carrots","optional aromatic ingredients","a bay leaf","thyme","rosemary","crushed peppercorns"],"steps":["Cut onions, celery and carrots into large chunks (you don't even need to remove the onion peels), add to a large empty pot (stock pot)","Add the chicken to the pot as well. It is fine to butcher the chicken to reduce its size, but include all bones and tendons as well","Add any aromatic seasonings","Fill the pot with water up slightly past all the ingredients","Bring contents to a boil, then reduce heat and let simmer for at least 45 minutes","You may want to remove with a spoon or other instrument the bubbles that form on the top. This will give you a clearer stock, but it is not necessary","Strain the liquid, now stock, into another container for storage or use"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicken-stock-bone-broth","page":"chicken-stock-bone-broth","tags":["chicken","stock","basic"]},{"id":"bc-chicken-tenders-airfried","title":"Chicken Tenders Airfried","cuisine":"Other","category":"Recipe","ingredients":["Raw chicken strips","Flour","Egg wash","Bread crumbs","Olive oil","Seasoning: salt and pepper with cayenne or paprika (optional)"],"steps":["In a plate, mix a little over a table spoon of spices into your flour","Dip the chicken into the flour one strip at a time coating the entire surface","Dip the floured chicken into the eggwash","Press the chicken into the breadcrumbs trying to pick up as much as possible","Repeat until all strips have been floured egged and breaded","Coat both sides of the tenders with a light amount of olive oil","Place the tenders into your airfryer, do not layer them on top of each other","Set your airfryer to chicken mode and cook for 20 minutes at 360 degrees fahrenheit","Serve with honey mustard for maximum effect"],"time":20,"servings":null,"image":"","source":"https://based.cooking/chicken-tenders-airfried","page":"chicken-tenders-airfried","tags":["chicken","fry"]},{"id":"bc-chicken-tomato-spinach-curry","title":"Chicken, Tomato and Spinach Curry","cuisine":"Other","category":"Recipe","ingredients":["500g or 1lb of chicken breast","Virgin olive oil (1/2 cup or ~100ml)","Fresh tomatoes of any variety (10 - 15 medium sized)","Two medium sized onions","250g or 1/2lbs of fresh spinach","Curry powder of your favourite variety","Red chilies (or red chilli paste)","Any extra herbs or spices to your taste"],"steps":["Dice your onions, begin to fry in the pot at a medium-low temperature","While the onions are cooking, dice the chicken into medium sized (1x1x1 inch pieces ideally) and fry along with the onions. Flip the chicken pieces regularly to prevent them from burning or overcooking","Add your desired amount of curry powder to the frying chicken. Too much may be too salty or overwhelming so be sure to not overdo it","As the chicken cooks through, dump all of your tomatoes and extra ingredients into a food processor and turn it all into a thin tomato paste. Add the paste to the curry directly. If you do not wish to use a food processor you can skin the tomatoes and add them to the curry anyway","Add all of your wanted spinach, and don't be shy about doing so. At first it may seem like you are adding too much but it quickly shrivels up in the curry and you'll need to add more","Make sure the chicken is cooked all the way through and serve"],"time":null,"servings":null,"image":"","source":"https://based.cooking/chicken-tomato-spinach-curry","page":"chicken-tomato-spinach-curry","tags":["curry","chicken"]},{"id":"bc-chocolate_cake","title":"Chocolate Cake","cuisine":"Other","category":"Recipe","ingredients":["100g (or 3/4 cup) of Flour","150g (or 1/2 cup) of Butter","100g (or 3/4 cup) of Cocoa","300g (or 1 cup) of Sugar","100ml of Coffee","6 Eggs","2 tea spoons of Baking Powder"],"steps":["Melt the sugar with the coffee in a Bain Marie","Break the eggs separate yolks from whites in different containers","Melt butter in sugar coffee Bain Marie","Whisk whites 'till they froth","Pour cocoa into Bain Marie and mix well","Preheat the oven (180 & 176;C)","Pour the yolks into the Bain Marie, mix well","Pour the mixture in the Bain Marie into the bowl with the whites","Sieve the flour and baking powder into the bowl with the whites","Mix everything in the bowl in a folding manner","Butter the baking pan and pour in the mixture","Leave in oven for 45 min. If after 45 min the cake hasn't come away from the sides"],"time":105,"servings":12,"image":"https://based.cooking/pix/chocolate_cake.webp","source":"https://based.cooking/chocolate_cake","page":"chocolate_cake","tags":["chocolate","cake","coffee"]},{"id":"bc-chocolate-chip-cookies","title":"Chocolate Chip Cookies","cuisine":"Other","category":"Dessert","ingredients":["230 g melted butter (2 sticks)","330 g bread flour","5 g salt","5 g baking soda","100-200 g white sugar","100-200 g brown sugar","1 egg","15 g milk","5 g vanilla","225 g 50-70% dark chocolate chips or semi-sweet milk chocolate chips"],"steps":["Preheat oven to 375°F","Mix the flour, baking soda, and salt in a bowl","Using a mixer or whisk, beat the butter, sugar, eggs, vanilla and milk in a separate bowl for a few mins","Combine and stir in the dry ingredients, then the chocolate chips","Use an ice cream scooper or spoon to make uniform balls of cookie dough to the size you like and evenly space them out on a parchment paper lined baking sheet (you may need more than one sheet depending on the size of the cookies)","Bake in the oven one baking sheet at a time for around 8-10 minutes, taking them out when they start to brown","Cool for a few minutes then put them on a cooling rack"],"time":10,"servings":4,"image":"https://based.cooking/pix/chocolate-chip-cookies.webp","source":"https://based.cooking/chocolate-chip-cookies","page":"chocolate-chip-cookies","tags":["dessert","cookies","sweet","chocolate"]},{"id":"bc-cocoanut-pudding","title":"Cocoa-nut Pudding","cuisine":"Other","category":"Dessert","ingredients":["A quarter of a pound of cocoa-nut, grated","A quarter of a pound of powdered white sugar","Three ounces and a half of fresh butter","The whites only of six eggs","A table-spoonful of wine and brandy mixed","Half a tea-spoonful of rose-water"],"steps":["Break up a cocoa-nut, and take the thin brown skin carefully off, with a knife. Wash all the pieces in cold water, and then wipe them dry, with a clean towel. Weigh a quarter of a pound of cocoa-nut, and grate it very fine, into a soup-plate","Stir the butter and sugar to a cream, and add the liquor and rose-water gradually to them","Beat the whites only, of six eggs, till they stand alone on the rods; and then stir the beaten white of egg, gradually, into the butter and sugar. Afterwards, sprinkle in, by degrees, the grated cocoa-nut, stirring hard all the time. Then stir all very well at the last","Have ready a puff-paste, sufficient to cover the bottom, sides, and edges of a soup-plate. Put in the mixture, and bake it in a moderate oven, about half an hour","Sprinkle granulated sugar over it, when cool"],"time":null,"servings":null,"image":"","source":"https://based.cooking/cocoanut-pudding","page":"cocoanut-pudding","tags":["cocoa","dessert","pudding"]},{"id":"bc-coconut-oil-coffee","title":"Coconut Oil Coffee","cuisine":"Other","category":"Drink","ingredients":["1 cup hot coffee","1 tbsp coconut oil","1 tbsp unsalted butter"],"steps":["Blend coffee, coconut oil, and butter together in a blender until oil and butter are melted and coffee is frothy"],"time":null,"servings":1,"image":"","source":"https://based.cooking/coconut-oil-coffee","page":"coconut-oil-coffee","tags":["drink","sweet","breakfast"]},{"id":"bc-collard-greens-with-smoked-duck-and-parnips","title":"Collard Greens with Smoked Duck and Parsnips","cuisine":"Other","category":"Side","ingredients":["1/2 smoked duck breast (skin on) chopped","1 large onion sliced","1 small parsnip julienned","1 large bunch collard greens chopped into ribbons","1/2 green cabbage cut into ribbons (optional)","1–2 tablespoons olive oil and/or butter","1 teaspoon ground coriander","1/2 teaspoon cinnamon","1/2 teaspoon garam masala"],"steps":["In a large dutch oven (or a big pot with a lid) on low heat, add the chopped duck breast and olive oil and/or butter to the pot for a couple of minutes. Then add the spices, and cook for a minute or two before adding the sliced onion. Let cook for 5 minutes and then add the parsnip and sweat","Add the ribboned cabbage and collard greens, a few twists of freshly ground pepper, and two tablespoons of water to the pot and cover. Cook until the greens are wilted and tender to the bite"],"time":20,"servings":2,"image":"","source":"https://based.cooking/collard-greens-with-smoked-duck-and-parnips","page":"collard-greens-with-smoked-duck-and-parnips","tags":["vegetables","side","duck"]},{"id":"bc-cooked-chickpeas","title":"Cooked Chickpeas","cuisine":"Other","category":"Recipe","ingredients":["1 can chickpeas / garbanzo beans, drained","1 tbsp olive oil","1 tsp garlic powder","1 tsp cumin","1 tsp paprika","1 tsp cayenne pepper"],"steps":["Heat oil in pan. Add chickpeas and seasonings","Cook over medium-high heat for 10-15 minutes. Salt and pepper to taste"],"time":15,"servings":3,"image":"","source":"https://based.cooking/cooked-chickpeas","page":"cooked-chickpeas","tags":["basic","beans","fasting"]},{"id":"bc-creamy-mashed-potatoes","title":"Creamy Mashed Potatoes","cuisine":"Other","category":"Side","ingredients":["1kg potatoes","200ml milk","200ml mayonnaise","~100g cheese","Garlic powder","12-16 strips of bacon","Butter","3-4 green onions","Black pepper","Salt"],"steps":["Peel and cut the potatoes into medium sized pieces","Put the potatoes in a pot with some water so that it covers the potatoes and","About ten minutes before removing the potatoes from the boiling water, cut","Warm up the milk and mayonnaise","Shred the cheese","When the potatoes are done, remove all water from the pot, add the warm milk","Add some salt, black pepper and garlic powder to taste and continue mashing","Once the mix is somewhat homogeneous and the potatoes are properly mashed,","Serve and top with chopped green onions"],"time":null,"servings":null,"image":"https://based.cooking/pix/creamy-mashed-potatoes.webp","source":"https://based.cooking/creamy-mashed-potatoes","page":"creamy-mashed-potatoes","tags":["potato","side","cheesefare"]},{"id":"bc-crunchy-coated-chicken-breasts","title":"Crunchy Coated Chicken Breasts","cuisine":"Other","category":"Recipe","ingredients":["5 boneless, skinless chicken breasts, about 6 ounces each","~55 Saltine crackers","1/2 cup grated Parmesan cheese","1 tsp dried thyme","4 tbsp olive oil","Dijon mustard (optionally substitute honey mustard)"],"steps":["Preheat the oven to 400º F","Line a baking sheet with aluminum foil","Crush the crackers into a medium bowl","Add the thyme, Parmesan cheese, and generously salt and pepper. Drizzle with the olive oil and mix well","Place chicken breasts on cutting board to trim fat and tenderize till flat and even","Cover the bottom of a large plate with a layer of the crumb mixture","Salt and pepper both sides of one chicken breast. Coat one side with mustard. Place mustard side down on crumb mixture, then coat the exposed with mustard and pat with crumb mix. Repeat for the other chicken breasts","Bake for ~ 18 minutes, or until juices run clear and the chicken is fully cooked through"],"time":30,"servings":5,"image":"","source":"https://based.cooking/crunchy-coated-chicken-breasts","page":"crunchy-coated-chicken-breasts","tags":["chicken","oven"]},{"id":"bc-damper","title":"Damper","cuisine":"Other","category":"Bread","ingredients":["4 cups self-raising flour","1 tablespoon butter, softened","1 cup milk"],"steps":["Preheat the oven to 425 degrees F (220 degrees C). Grease a baking sheet","Mix all the ingredients together, adding a half cup of water and a teaspoon salt","Knead the bread on a floured surface","Put the bread into the oven for 25 minutes, then lower the temprature to 175 degrees C for 5 to 10 minutes"],"time":30,"servings":15,"image":"","source":"https://based.cooking/damper","page":"damper","tags":["bread","quick"]},{"id":"bc-danish-pancake","title":"Danish Pancake","cuisine":"Other","category":"Breakfast","ingredients":["375g wheat flour","a little bit of salt (1/3 of a teaspoon)","1 ½ tablespoon sugar","9 dl milk","4 eggs"],"steps":["Put all the ingredients in a bowl and stir until it's all mixed up","Preheat a pan with butter or margarine","Turn when one side starts turning brown","They are done when both sides start turning brown","Add Butter or Margarine when needed"],"time":null,"servings":null,"image":"https://based.cooking/pix/danish-pancake.webp","source":"https://based.cooking/danish-pancake","page":"danish-pancake","tags":["quick","breakfast","sweet","pancake","cheesefare"]},{"id":"bc-dried-tomato-plum-spread","title":"Dried tomato & plum bread spread","cuisine":"Other","category":"Bread","ingredients":["10 dried plums","1 jar of dried tomatoes","1 tsp of smoked paprika","pinch of dried coriander (optional)","pinch of chilli (optional, if you like it to be spicy)"],"steps":["Put plums in hot water from kettle for couple of minutes, in order to make them softer","After that put plums (without the water) and rest of the ingredients into blender and mix it until you're satisfied","If you want to make it more liquid you can add water from the plums"],"time":null,"servings":null,"image":"","source":"https://based.cooking/dried-tomato-plum-spread","page":"dried-tomato-plum-spread","tags":["bread","quick","snack","spread","fasting"]},{"id":"bc-drunken-beans","title":"Drunken beans (Pintos Borrachos)","cuisine":"Other","category":"Recipe","ingredients":["1 small yellow onion","3 gloves of garlic","2 tomatoes. chopped","4 cups of water","1 1/2 cups of pinto beans (can be dried or canned)","1 tbsp oregano","3/4 tsp cumin","2 tbsp chilli powder(depends how hot you like it)","12oz of Beer/dark ale"],"steps":["Sauté onions","Add garlic, sauté bit longer","Add tomatoes, water, beans, oregano, cumin, chilli powder, beer and salt, gradually bring to boil","When boiled, reduce to simmer","When beans are al dente (about 1 hour if using dried), bring to quick boil and evaporate remaining liquid until beans are stew-like","Remove from the heat and mashup, or skip this step if you want more of a bean stew"],"time":null,"servings":null,"image":"","source":"https://based.cooking/drunken-beans","page":"drunken-beans","tags":["beans","stew"]},{"id":"bc-easy-chicken-and-rice-casserole","title":"Easy Chicken and Rice Casserole","cuisine":"Other","category":"Recipe","ingredients":["1/2 cup Onion, chopped","1/2 cup Celery, chopped","2 Tbsp Butter or margarine","2 cups Chicken, cooked and chopped","1 3/4 cups Hot water","2/3 cup Long Grain White Rice","1 can (10 oz) Mushrooms with liquid","1 cup Frozen Peas and Carrots","1 tsp Dried Thyme and Rosemary"],"steps":["In large fry pan, cook onion and celery in butter until soft","Stir in remaining ingredients","Bake in covered 8 cup baking dish in preheated (350F) oven for about 30 minutes or until rice is cooked"],"time":40,"servings":4,"image":"","source":"https://based.cooking/easy-chicken-and-rice-casserole","page":"easy-chicken-and-rice-casserole","tags":["chicken","quick","easy"]},{"id":"bc-eggroll-in-a-bowl","title":"Egg Roll in a Bowl","cuisine":"Other","category":"Recipe","ingredients":["1 pound ground turkey","1 bag coleslaw mix","1 small onion","2-3 cloves of garlic","1 tbsp fresh ginger","1/4 cup Hoisin sauce","soy sauce","sesame oil"],"steps":["Grate or mince ginger finely. Process with the garlic cloves by grinding with salt under the edge of a knife. Finely mince the onion. Optional Marinade the ground turkey in 2 Tbsp of soy sauce and 1 tsp baking soda for 15 minutes to improve browning","In a hot wok or skillet add a few tablespoons of cooking oil, preferably peanut, and a tsp of sesame oil. Add the ground turkey and cook until no longer raw seasoning with soy sauce","Add the onion and cook until translucent and the meat is nicely browned. Add in the garlic and ginger mixture and cook for approximately 1 minute or until fragrant ensuring not to burn the garlic","Add in the coleslaw mix and season with more soy sauce. Cook until the cabbage is just softened. Add 1/4 cup of hoisin sauce and stir to combine. Check seasoning and add salt to taste. Serve in a bowl with sweet chili sauce and green onions"],"time":15,"servings":2,"image":"","source":"https://based.cooking/eggroll-in-a-bowl","page":"eggroll-in-a-bowl","tags":["quick","asian","cabbage"]},{"id":"bc-egyptian-lentils","title":"Egyptian Lentils","cuisine":"Other","category":"Rice","ingredients":["1 cup Lentils","1 cup Elbow Macaroni","2 Fresh Chili or Bell Peppers","2 Tbsp Lime Juice","1 1/2 cup Regular Rice","3 Tbsp Oil","2 medium Tomatoes, chopped","1 large Onion, diced"],"steps":["Place lentils in a saucepan and cover by 1\" or more of water. Turn heat to high and bring to a boil, then turn down heat to simmer, and cook covered for 35 minutes or until tender. Drain and transfer to a large bowl. Set aside","Bring 3 cups of water to a boil, add rice. Turn down to simmer for 20 minutes and fluff up rice with a fork and add to lentils","Boil 2 quarts of water, add elbow macaroni and cook until tender. Add to lentils","In a small skillet add 1 Tbsp of oil and saute chopped peppers finely for two minutes. Add the tomato, 1/2 cup of water, bring to a boil and simmer for 5 minutes. Add the lime juice. Fold this sauce into the lentils","In another skillet heat 2 Tbsp oil, add onions and saute until brown. Garnish lentil mixture with the browned onions"],"time":40,"servings":5,"image":"","source":"https://based.cooking/egyptian-lentils","page":"egyptian-lentils","tags":["rice","pasta"]},{"id":"bc-exotic-ginger-cumin-chicken","title":"Exotic Ginger Cumin Chicken","cuisine":"Other","category":"Recipe","ingredients":["1 Tbsp Vegetable Oil, divided","2 lbs Boneless Skinless Chicken, cut bite-size","2 tsp Garlic, minced","1/2 cup Onion, chopped","1 Tbsp Ginger Root, minced","1/2 tsp Cayenne Pepper","1 tsp Cumin","1 tsp Turmeric","1/2 cup Chicken Stock","1 can (19oz) Stewed Tomatoes","2 Tbsp Tomato Paste","1 tsp Sugar","3/4 cup Low Fat Plain Yogurt"],"steps":["In large saucepan heat 2 tsp oil over medium heat. Add half of the chicken and cook 3 minutes until brown. Remove from pan and set aside. Repeat with remaining chicken","Add remaining oil to pan; add garlic, onion, and ginger. Reduce heat to medium and cook, stirring constantly for 5 minutes or until soft. Stir in cayenne, cumin, and turmeric; saute for 1 minute","Stir in stock, tomatoes, tomato paste, and sugar; return chicken to pan. Bring to boil; reduce heat and simmer 5 minutes","Stir in yogurt and simmer 2 minutes"],"time":20,"servings":8,"image":"","source":"https://based.cooking/exotic-ginger-cumin-chicken","page":"exotic-ginger-cumin-chicken","tags":["chicken"]},{"id":"bc-fajitas","title":"Fajitas","cuisine":"Other","category":"Recipe","ingredients":["1/4 cup + 1/2 tsp Lime Juice, divided","3 Tbsp Olive Oil, divided","4 cloves Garlic, crushed","3 tsp Soy Sauce, divided","1 tsp Salt","1/2 tsp Liquid Smoke","1/2 tsp Cayenne Pepper","1/4 tsp Black Pepper","1 lb Chicken Breasts or Skirt Steak, bones/skin removed","2 Tbsp Water","1 large Spanish Onion, thinly sliced","1/2 each Green, Red, and Yellow Bell Pepper, thinly sliced"],"steps":["Combine 1/4 cup lime juice, 2 Tbsp of the oil, garlic, 2 tsp soy sauce, the salt, liquid smoke, cayenne pepper, and black pepper in a resealable container, add chicken/steak, cover, and refrigerate for at least 2 hours or overnight","Combine water, remaining soy sauce and lime juice, and a dash of salt and pepper - set aside","Grill meat over a medium-high flame for 4-5 minutes per side, or until cooked through","Cut meat into thin strips - set aside and keep warm","In a large skillet over medium-high heat, cook onion and peppers in remaining oil until brown - remove from heat and pour reserved liquid mixture over onions and peppers","Toss together meat, onions, and peppers","Can serve with warm tortillas, pico de gallo, cheese, sour cream, and guacamole"],"time":15,"servings":4,"image":"","source":"https://based.cooking/fajitas","page":"fajitas","tags":["beef","chicken"]},{"id":"bc-fall-vegetable-and-chickpea-curry","title":"Fall Vegetable and Chickpea Curry","cuisine":"Other","category":"Recipe","ingredients":["1 Tbsp Butter","1 Onion, chopped","2 Tbsp Thai Red Curry Paste","1 Tbsp Ginger, minced","1 large Sweet Potato, peeled and cut into half-inch chunks","1 small Zucchini, cut into half-inch chunks","1 Red Pepper, cut into half-inch pieces","28 oz can Chickpeas, rinsed and drained","1 Lime","3 Tbsp Wheat Flour","1 1/2 cup Milk","1/2 cup Fresh Coriander, chopped"],"steps":["In a large non-stick frying pan, heat butter over medium-high heat. Cook onion, stirring (2 mins). Add curry paste and ginger. Cook, stirring (1 min)","Add sweet potato, zucchini, red pepper, salt, and half a cup of water. Stir. Cook covered, stirring occasionally until vegetables soften (10 mins). Add chickpeas and finely grated zest and juice from lime. Stir frequently until vegetables are tender and liquid has evaporated (5 mins)","Whisk flour into milk. Gradually stir into pan. Bring to a simmer, stirring constantly. Reduce heat to medium heat for a simmer, stirring occasionally (5 mins)","Stir in coriander and salt if needed"],"time":25,"servings":4,"image":"https://based.cooking/pix/fall-vegetable-and-chickpea-curry.webp","source":"https://based.cooking/fall-vegetable-and-chickpea-curry","page":"fall-vegetable-and-chickpea-curry","tags":["fasting","curry"]},{"id":"bc-fennel-beans-and-kale-soup","title":"Fennel White Bean and Kale Soup","cuisine":"Other","category":"Soup","ingredients":["½ cup olive oil","2 small fennel bulbs, small-diced","2 small yellow onions, small-diced","4 teaspoons minced fresh rosemary or thyme","10 cloves of garlic, minced or pressed","½-1 teaspoon red-pepper flakes","10-12 oz kale, (escarole, swiss chard, or spinach can also be used)","4 cans cannellini beans, rinsed","4 cups chicken broth","2 tablespoons lemon juice","6 tablespoons grated parmesan, plus extra for serving if desired"],"steps":["In a large soup pot, heat olive oil over medium","Add fennel, onion, rosemary and mix until tender (4-6 min)","Add garlic, red pepper flakes, cook until fragrant (1 min)","Add one handful of greens at a time, stirring until leaves wilt","Add white beans, broth, and black pepper,","Bring to boil then bring to simmer while mashing some of the beans with a wooden spoon. Simmer until liquid has reduced and simmered (6-8 mins)","Take off heat, stir in lemon juice and parmesan. Serve with some toasted bread that is good at scooping up soup. Enjoy!"],"time":20,"servings":6,"image":"https://based.cooking/pix/fennel-bean-kale-soup.webp","source":"https://based.cooking/fennel-beans-and-kale-soup","page":"fennel-beans-and-kale-soup","tags":["soup","vegetables","beans"]},{"id":"bc-fried-potatoes","title":"Fried Potatoes","cuisine":"Other","category":"Side","ingredients":["Potatoes","Oil or Crème Fraîche","Onions"],"steps":["Peel and cut the potatoes to desired size","Cut the onions","Put a bit of Oil or Crème Fraîche in your pan","Put both the potatoes and the onions into the pan","Cook them until they're golden-brown","Enjoy"],"time":null,"servings":null,"image":"","source":"https://based.cooking/fried-potatoes","page":"fried-potatoes","tags":["potato","quick","side","fasting"]},{"id":"bc-garlic-toast","title":"Garlic Toast","cuisine":"Other","category":"Bread","ingredients":["Any kind of firm, thin, sliced bread (Sourdough, Baguette)","Garlic-infused olive oil (Optionally substitute butter or regular olive oil)","Garlic salt"],"steps":["Preheat oven to 180°C (350°F)","Place sliced bread on a baking tray lined with aluminium foil","Generously coat bread slices with garlic-infused olive oil","Season with garlic salt, to taste","Bake for 10-15 minutes or until crunchy throughout","Serve with cheese, charcuterie, pickles, dips, or to accommodate a soup"],"time":15,"servings":null,"image":"","source":"https://based.cooking/garlic-toast","page":"garlic-toast","tags":["basic","bread","quick","side"]},{"id":"bc-gooseberry-pudding","title":"Gooseberry Pudding","cuisine":"Other","category":"Dessert","ingredients":["A pint of stewed gooseberries, with all their juice","A quarter of a pound of powdered sugar","Two ounces of fresh butter","Two ounces of grated bread","Three eggs"],"steps":["Stew the gooseberries till quite soft. When they are cold, mash them fine with the back of a spoon, and stir into them two ounces of sugar. Take two ounces more of sugar, and stir it to a cream with two ounces of butter","Grate very fine as much stale bread as will weigh two ounces","Beat three eggs, and stir them into the butter and sugar, in turn with the gooseberries and bread","Lay puff-paste in a soup plate. Put in the mixture, and bake it half an hour"],"time":null,"servings":null,"image":"","source":"https://based.cooking/gooseberry-pudding","page":"gooseberry-pudding","tags":["berries","dessert","pudding"]},{"id":"bc-grands-peres","title":"Grands-pères au sirop d'érable (Maple Dumplings)","cuisine":"Other","category":"Dessert","ingredients":["1 cup flour","2 TSP baking powder","1 pinch salt","2 TB butter, cut into pieces","½ cup milk","1 cup water","1 cup maple syrup"],"steps":["Stir together flour, baking powder and salt until aerated and no longer clumpy","Work in the butter with your fingertips and add milk. Form into 5-6 balls","In a saucepan equipped with a lid, bring water and syrup to a simmer. Add dough balls and cover. Simmer on low 12-15 minutes"],"time":15,"servings":5,"image":"https://based.cooking/pix/grands-peres.webp","source":"https://based.cooking/grands-peres","page":"grands-peres","tags":["quebec","dessert"]},{"id":"bc-granola","title":"Granola","cuisine":"Other","category":"Breakfast","ingredients":["3 cups oats","1/2 cup olive oil","1/2 cup maple syrup","1 cup chopped nuts (almonds, pumpkin seeds, etc)","1 tsp ground cloves","1 tsp ground cardamom","1 cup dried fruit (apricots, unsweetened cranberries, dates, etc)"],"steps":["Preheat oven to 315° F","In a large bowl, mix: oats, oil, maple syrup, chopped nuts and spices","Cover two large baking sheets with parchment paper","Spread the mixture thinly and evenly on baking sheets, put in oven","Bake 15 minutes, take out of oven, stir, put back in oven (swap oven locations for even cooking)","Bake 15 minutes, take out of oven, stir, put back in oven (swap oven locations for even cooking)","Bake 10 minutes, take out of oven, do not stir (helps form clumps), let it cool","Coarsely chop dried fruit and mix in","Serve with yogurt, milk, fresh fruit, etc"],"time":40,"servings":5,"image":"","source":"https://based.cooking/granola","page":"granola","tags":["breakfast"]},{"id":"bc-greek-yogurt","title":"Greek Yogurt","cuisine":"Other","category":"Recipe","ingredients":["2 thermos, ½l capacity each","thermometer","1 cheesecloth","1l milk","100ml yogurt"],"steps":["bring the milk to 45°C (113°F)","pour the yogurt into the milk","wisk well","bring the milk to 45°C (113°F) again (don't go higher than that, please)","boil some water (about 100ml) and use it to wash the thermos from inside","let the water out and pour the milk into the thermos","leave the thermos in the oven(or in any other place whithout air flow) for 12h","pour the newly obtained yogurt into the cheesecloth","hang the cheesecloth for 30 minutes to 4 hours, depending on the desired density (the longer the denser)","store in the fridge"],"time":null,"servings":null,"image":"","source":"https://based.cooking/greek-yogurt","page":"greek-yogurt","tags":["basic","cheesefare"]},{"id":"bc-gypsy-soup","title":"Gypsy Soup","cuisine":"Other","category":"Soup","ingredients":["3 Tbsp Olive Oil","2 cup Chopped Onion","2 cloves Chopped Garlic","2 cup Sweet Potatoes, chopped and peeled","1/2 cup Chopped Celery","1 cup Chopped Fresh Tomatoes","3/4 cup Chopped Sweet Peppers","1-1/2 cup Cooked Chickpeas","3 cup Stock or Water","2 tsp Paprika","1 tsp Turmeric","1 tsp Basil","1 tsp Salt","dash Cinnamon","dash Cayenne","1 Bay Leaf","1 Tbsp Tamari Soy Sauce"],"steps":["In a soup kettle or large saucepan, saute onions garlic, celery, and sweet potatoes in olive oil for about five minutes","Add seasonings, except tamari, and the stock/water. Simmer covered, for fifteen minutes","Add remaining vegetables, chickpeas, and tamari","Simmer another 10 minutes or so - until all the vegetables are as tender as you like them"],"time":30,"servings":4,"image":"","source":"https://based.cooking/gypsy-soup","page":"gypsy-soup","tags":["soup","fasting","tomato"]},{"id":"bc-hakka-style-meatballs","title":"Hakka-Style Meatballs","cuisine":"Other","category":"Rice","ingredients":["1/2 lb Ground Beef","1/4 cup Panko Breadcrumbs","2 Tbsp Soy Sauce, divided","4 tsp Chili Garlic Sauce","1/2 oz Ginger, minced","2 medium Green Bell Peppers","1 small Onion, chopped","3/4 cup Basmati Rice","2 oz Green Peas","1/2 cup Cilantro, loosely packed","1 Tbsp Moroccan Spice Blend, divided","4 Tbsp Sweet Chili Sauce","Oil"],"steps":["Preheat oven to 450F. Add 1 1/4 cup water and 1/4 tsp salt to a medium pot. Cover and bring to a boil over a medium-high heat. Add rice and reduce heat to low. Cover and cook until rice is tender and liquid is absorbed (12-14 mins). Add peas halfway through cooking. When rice is done, remove pot from heat, and leave covered","While rice cooks, combine beef, panko, half the ginger, a quarter of the soy sauce and a third of the Moroccan spice blend. Roll mixture into 9 equal-sized meatballs. Arrange meatballs on a parchment-lined baking sheet. Bake on the middle rack in the oven until golden-brown and cooked through (8-10 mins)","Meanwhile, core and cut the green peppers into 1/2\" pieces and roughly chop cilantro. Stir together sweet chili sauce, remaining soy sauce, 1/4 cup water and chili garlic sauce in a small bowl","Heat a large non-stick pan over medium-high heat. Add 1 Tbsp oil, then onion and peppers. Cook, stirring occasionally, until slightly softened (2-3 mins). Add remaining ginger and remaining Moroccan spice blend. Cook, stirring constantly, until fragrant (30 sec)","Add meatballs and the stir-fry sauce to the pan with veggies. Cook, stirring gently, until sauce thickens slightly and coats meatballs (1 min). Season with salt and pepper, to taste","Add half the cilantro to rice, then fluff with a fork. Divide rice between plates, then top with meatballs, veggies, and any sauce in the pan. Sprinkle remaining cilantro over top"],"time":20,"servings":3,"image":"","source":"https://based.cooking/hakka-style-meatballs","page":"hakka-style-meatballs","tags":["beef","rice","asian"]},{"id":"bc-ham-and-lentil-soup","title":"Ham and Lentil Soup","cuisine":"Other","category":"Soup","ingredients":["2 cup Lentils","1/2 lb Ham, diced","1 Onion, chopped","1 Bay leaf","2 ribs Celery, chopped","1 clove Garlic, minced"],"steps":["Combine all ingredients with 2 quarts water in the Crock Pot","Cook on low, covered, 8 to 10 hours","Adjust seasonings and serve"],"time":480,"servings":6,"image":"","source":"https://based.cooking/ham-and-lentil-soup","page":"ham-and-lentil-soup","tags":["pork","soup","easy"]},{"id":"bc-burger-dressing","title":"Hamburger dressing","cuisine":"Other","category":"Sauce","ingredients":["3 tbsp mayonnese or aioli","2 tbsp ketchup","1 tbsp sriracha","1 clove garlic, if using mayonnese and not aioli (optional)"],"steps":["Mix ingredients in a bowl"],"time":5,"servings":null,"image":"https://based.cooking/pix/burger-dressing.webp","source":"https://based.cooking/burger-dressing","page":"burger-dressing","tags":["sauce","basic","dressing"]},{"id":"bc-hangover-eggs","title":"Hangover Eggs","cuisine":"Other","category":"Snack","ingredients":["Tony Chachere's","Green onions","Olive oil","Loaf of French Bread","Eggs","Tabasco","Beer"],"steps":["Bring a cast iron pan to medium-high heat and add a second or two of olive oil when things start to warm up","While the pan heats up, use your hands and tear off pieces of bread that are roughly the size of your hand","Make sure you have one piece of bread per egg you want to make. I've dabbled with the egg:bread ratios, and this seems to work","Once the olive oil starts smelling a bit (or smoke comes off of it), crack in however many eggs you care to eat. Turn down the heat to medium","Act fast! As the eggs start cooking, prepare a plate with two handfuls of chopped green onion and Tabasco","After about four minutes (or when the tops of the eggs start to set), take out eggs and place on top of bed of onions & Tabasco","Turn heat back to medium-high and add a touch more olive oil. Place pieces of bread in pan","Every so often, move the pieces of bread around to soak up the oil","When the bread is about to turn a good shade of golden-brown, add a generous sprinkle of Tony Chachere's to the plated eggs (on top of them)","Turn off the heat and move the pan off the burner. Take out bread pieces and place on the same plate as the eggs","Serve with glass of ice-cold beer"],"time":null,"servings":null,"image":"","source":"https://based.cooking/hangover-eggs","page":"hangover-eggs","tags":["eggs","snack","quick","cheesefare"]},{"id":"bc-hearty-breakfast-oatmeal","title":"Hearty Breakfast Oatmeal","cuisine":"Other","category":"Breakfast","ingredients":["1/2 cup Large Flake Oats (no partially cooked quick-oats allowed!)","Almonds","Pecans","1 Tbsp Roasted Flax Seed","1 Tbsp Hemp Hearts","Cranberries (adjust amount to preference)","1/2 Banana (mashed)","1 cup Milk (3.25% if possible)","Cinnamon (adjust amount to preference)","1 Egg","ON Vanilla Ice Cream Protein Powder (optional)"],"steps":["Chop or mash nuts and fruit","Combine nuts, fruit, and other dry ingredients in a saucepan","Add milk and cook mixture over medium heat until oats are desired tenderness (5-10 mins)","Add egg and protein powder and cook for a few more minutes","Enjoy"],"time":10,"servings":1,"image":"https://based.cooking/pix/hearty-breakfast-oatmeal.webp","source":"https://based.cooking/hearty-breakfast-oatmeal","page":"hearty-breakfast-oatmeal","tags":["breakfast","quick"]},{"id":"bc-hellfire-steak","title":"Hellfire Steak","cuisine":"Other","category":"Recipe","ingredients":["Steak","Kosher Salt","Mustard Powder","Tabasco Sauce"],"steps":["Rub a generous amount of salt all over the steak","Coat the entire steak with mustard powder","Pour Tabasco Sauce onto both sides of the steak, don't be afraid to put more on than you think you might otherwise be comfortable with the salt will cancel out a lot of the spice while grilling","Grill over low heat until steak is cooked to your preference"],"time":null,"servings":null,"image":"","source":"https://based.cooking/hellfire-steak","page":"hellfire-steak","tags":["beef","quick"]},{"id":"bc-homemade-ice-cream","title":"Homemade Ice Cream","cuisine":"Other","category":"Dessert","ingredients":["1 can (400-500 ml) condensed milk","500 ml heavy whipping cream (approx. 2 cups)","1 teaspoon vanilla extract","2 handfuls blended blueberries (or any mix-in of your choice)"],"steps":["Beat the condensed milk with a mixer for about 2 minutes until smooth. Set aside","In a separate bowl, whip the heavy cream for about 4 minutes until thick and stiff peaks form","Gently fold the condensed milk into the whipped cream. Add vanilla extract and blended blueberries, or your preferred mix-ins. Mix by hand until just combined","Transfer to a clean 1 kg (approx. 35 oz) container. Spread evenly, press lightly to remove air pockets, and shake gently from side to side to level the surface","Cover with plastic wrap, then secure with a lid. Freeze for 5-6 hours until firm"],"time":null,"servings":6,"image":"","source":"https://based.cooking/homemade-ice-cream","page":"homemade-ice-cream","tags":["dessert","icecream"]},{"id":"bc-honey-garlic-chicken","title":"Honey Garlic Chicken with Broccoli and Brown Rice","cuisine":"Other","category":"Rice","ingredients":["1/2 cup ( 100g ) brown rice","1/2 cup ( 70g ) frozen peas","1 head broccoli (you can use really any amount of broccoli)","2 chicken breasts","1 tbsp honey","1 tbsp low-sodium soy sauce","1 tbsp minced garlic"],"steps":["Cook rice in a pot. Instructions are on the bag it comes in","While rice is cooking, cut chicken breasts into cube. Season with olive oil, black pepper, and","Put chicken cubes into a hot pan and cook for ~3 minutes. After 3 minutes add honey, soy sauce,","Add frozen peas to rice and stir, they will heat up quickly","Add rice and peas to chicken and stir"],"time":null,"servings":2,"image":"","source":"https://based.cooking/honey-garlic-chicken","page":"honey-garlic-chicken","tags":["chicken","broccoli","rice","quick"]},{"id":"bc-honey-sriracha-chicken-thighs","title":"Honey Sriracha Chicken Thighs","cuisine":"Other","category":"Recipe","ingredients":["5-6 bone-in, skin-on chicken thighs","1 tablespoon olive oil","1/3 cup honey","2 tablespoons sriracha hot sauce","1/2 teaspoon kosher salt","1/2 teaspoon black pepper","Sesame seeds as a garnish (optional)"],"steps":["Preheat oven to 350°F","Season the chicken. Rub the thighs with some olive oil and season liberally with salt and pepper","Place the chicken thighs in a cold skillet, skin-side down. Cook for 15 minutes on medium-low heat without touching them","Prepare Sriracha sauce by stirring honey and sriracha together in a bowl","Flip the chicken thighs. Cook for another 10 minutes","Place chicken thighs on baking tray (or just use skillet if using a cast-iron skillet). Drizzle the sriracha sauce on both sides of the chicken, coating it. You do not have to use all of it","Bake chicken thighs for 15 minutes","Test chicken for doneness. Chicken should reach internal temperature of 165°F","If chicken is near done (or done), you can baste a second time with the remaining sauce (you can make more sauce if you need) and return to oven for 5 more minutes. Do not worry about overcooking; chicken thighs are difficult to overcook","When chicken is done, let cool for a few minutes and garnish with sesame seeds before serving"],"time":45,"servings":4,"image":"https://based.cooking/pix/honey-sriracha-chicken-thighs.webp","source":"https://based.cooking/honey-sriracha-chicken-thighs","page":"honey-sriracha-chicken-thighs","tags":["chicken","spicy"]},{"id":"bc-honey-vanilla-ice-cream","title":"Honey Vanilla Ice Cream","cuisine":"Other","category":"Dessert","ingredients":["1 pint heavy cream","1 cup milk (whole milk recommended)","2 Tbsp vanilla extract","1/2 cup honey","1 cup sugar"],"steps":["Add milk and sugar to medium sized bowl and mix until dissolved","Add heavy cream and vanilla extract and mix","Stir in honey","Chill in refrigerator for at least 2 hours","Add to ice cream maker and let it go for 30 minutes","Swiftly remove from ice cream maker (I use a silicone spatula as it allows for sides to be scraped down) and put into container","Freeze ice cream overnight - a few hours will do in a pinch but overnight is better","Scoop out of container and serve! Goes great with honey cake"],"time":null,"servings":8,"image":"","source":"https://based.cooking/honey-vanilla-ice-cream","page":"honey-vanilla-ice-cream","tags":["icecream","honey","dessert"]},{"id":"bc-hummus","title":"Hummus","cuisine":"Other","category":"Snack","ingredients":["One can of garbanzo beans (chickpeas) OR a cup (about 200 g) of dry garbanzo beans","1/2 teaspoon baking soda","1/2 cup of tahini (also known as tehina)","1/4 cup (or more, to taste) of lemon juice, fresh preferred - this is about 1 1/2 to 2 lemons' worth","1 (or 2) clove(s) of garlic, roughly chopped (fresh or frozen pre-chopped is fine, but not dry)","1/4 teaspoon cumin, ground (if you have whole, toast in a dry pan until fragrant before grinding)","1/4 teaspoon za'atar (optional, if you can find it)","1 Tablespoon of olive oil, plus more for serving","Fresh parsley (optional for serving)"],"steps":["If the garbanzo beans are dry, put them in a container, cover completely with water, and let soak for 8-12 hours","Drain the water and rinse the garbanzo beans","Place garbanzo beans in a small saucepan or pot, add 1 teaspoon baking soda (this alters the pH to encourage the beans to break down and shed their skins), and cover with a few inches of water. Bring to a boil and cook for 20 minutes, until the skins begin to fall off and the beans look overcooked/mushy. You may need to reduce the heat after a few minutes to prevent boil-overs","While the garbanzo beans are boiling, combine the garlic and lemon juice with 1/4 teaspoon salt in the workbowl of your food processor. Pulse until a fine, uniform consistency is achieved. You may need to scrape down the top and sides of the bowl to ensure the garlic is chopped finely enough. Leave the mixture for at least 10 minutes for the raw garlic taste to mellow","Add the tahini to the food processor. Blend until creamy. Scrape down the sides and bottom of the bowl","While the food processor is running on \"high,\" slowly drizzle in two tablespoons of ice-cold water. Continue to run on high, scraping down the bowl as necessary (1-3 times), until the mixture has enough air worked into it that it lightens in color and thickens in texture substantially","Once the garbanzo beans are ready (typically 20 minutes of boiling if the garbanzo beans had been canned, and around 2-2.5 hours otherwise), drain the garbanzo beans and their skins in a mesh strainer, then rinse for at least 30 seconds with cold water to remove any lingering taste from the baking soda","Scrape down the bowl again, then add the garbanzo beans and cumin (and za'atar, if you have it). Pulse a few times, then set the food processor to high again. Drizzle in 1 tablespoon of olive oil, as slowly as you can manage","Continue to process the hummus on high for at least one minute longer, up to three minutes longer if it hasn't become smooth enough yet. You can make the hummus thinner at this point by slowly adding ice water a teaspoon at a time while processing on high. Taste the hummus at this point to determine if it needs more lemon juice or more salt for flavor","Transfer the hummus into a serving bowl and smooth out the surface with the back of a spoon, creating swirls or indentations for olive oil as desired. Top with additional olive oil and optionally finely chopped fresh parsley, more za'atar, or a sprinkling of sumac (a spice mixture) or dukkah (a seed mixture)","Serve immediately or transfer to an airtight container and store in the refrigerator for up to one week"],"time":null,"servings":null,"image":"https://based.cooking/pix/hummus.webp","source":"https://based.cooking/hummus","page":"hummus","tags":["basic","snack","spread","fasting","vegan"]},{"id":"bc-irish-coffee","title":"Irish Coffee","cuisine":"Other","category":"Drink","ingredients":["1 (1.5 fluid ounce) jigger Irish cream liqueur","1 (1.5 fluid ounce) jigger Irish whiskey","1 cup hot brewed coffee","1 tablespoon whipped cream","1 dash ground nutmeg"],"steps":["In a coffee mug, combine Irish cream and Irish whiskey. Fill mug with coffee. Top with a dab of whipped cream and a dash of nutmeg"],"time":5,"servings":1,"image":"","source":"https://based.cooking/irish-coffee","page":"irish-coffee","tags":["drink","sweet","breakfast"]},{"id":"bc-jam","title":"Jam","cuisine":"Other","category":"Recipe","ingredients":["1 kg fruit of your choice","1 kg sugar"],"steps":["Cut the fruit in small pieces and place it in a pot","Cook on the stove, on low fire","As soon as some juice collects on the bottom of the pot, add sugar and stir until it is no longer visible","Keep the pot on low fire, stirring often and in particular the bottom, which will otherwise burn very easily","Jam must boil for at least 2 hours","If fruit pieces are still visible, you may blend them","Pour boiling-hot jam in glass jars and close them immediately"],"time":5,"servings":null,"image":"https://based.cooking/pix/jam.webp","source":"https://based.cooking/jam","page":"jam","tags":["fasting","fruit","jam"]},{"id":"bc-ketchup","title":"Ketchup","cuisine":"Other","category":"Sauce","ingredients":["2 1/2 quart (15 to 17 medium-sized) sliced tomatoes","1 large garlic clove, chopped","1 cup vinegar","1/4 cup chopped onion","1/2 cup sugar","3 - inch piece stick cinnamon","1 1/4 teaspoon salt","1 teaspoon paprika","1 teaspoon whole cloves","a dash cayenne pepper"],"steps":["Simmer together tomatoes and onion for 20 to 30 minutes; press through a sieve","Put the cinnamon, cloves, and garlic loosely in a clean, thin, white cloth; tie top tightly; add to vinegar and simmer 30 minutes","Remove spice bag","Boil tomato mixture rapidly until you have but one-half the original amount","Stir frequently to prevent sticking","Add spiced vinegar, sugar, salt, paprika, and cayenne pepper to tomato mixture","Boil rapidly, stirring constantly, about 10 minutes or until slightly thickened","Pour into hot, sterile jars, fill jars to top, and seal"],"time":null,"servings":null,"image":"","source":"https://based.cooking/ketchup","page":"ketchup","tags":["basic","sauce","fasting"]},{"id":"bc-coconut-flour-bread","title":"Keto Coconut Bread","cuisine":"Other","category":"Bread","ingredients":["6 Medium Eggs (or 5 Extra Large)","1 Tbsp Coconut Oil","¾ cup Coconut Flour","1 tsp Baking Powder","Pinch of Salt","½ tsp or less of Xanthan Gum (optional, to have a more stick bread)"],"steps":["Mix all dry ingredients in a big bowl","Add the whole eggs and the coconut oil","Mix well with a spoon until it gets thick. You can add extra coconut flour if you feel it is too liquid","Pre-heat your oven to 350°F (175°C)","Pour the dough evenly into a Bread/Loaf form (coated with butter or parchment paper) and cook for 35 to 45 min","After cooking, remove it from the oven and let it sit while it cools down","Some variations can be done, like using butter instead of coconut oil or adding pumpkin pure to the mix and having a cake-like texture"],"time":45,"servings":12,"image":"https://based.cooking/pix/coconutbread-lufemas.webp","source":"https://based.cooking/coconut-flour-bread","page":"coconut-flour-bread","tags":["bread","coconut","baking","keto","bariatric"]},{"id":"bc-kettle-chips","title":"Kettle Chips","cuisine":"Other","category":"Snack","ingredients":["1 Russet Potato, or other potato with high starch and low moisture. The amount of starch effects the crunchiness of the chip","Peanut Oil for frying (at least 1 to 2 inches in the pan)","Salt or seasoning of your choice"],"steps":["Set a wok or pot over medium-low heat and add the peanut oil about 1 to 2 inches up the pot. Set a thermometer to monitor the temperature to reach 315 F (157 C)","Wash the exterior of the potato. Using a mandolin set on 2 mm (~1/16th inch), a very sharp knife or a potato peeler cut the potatoes into thin chip slices","Add the potatoes to the hot oil and cook for 9 to 11 minutes while stirring fairly constantly. <br","Once golden browned and completely crisp with no bubbling, remove the chips with a slotted spoon and add to a paper towel over a wire rack to absorb excess oil. Seasoning immediately with salt and any seasoning of your choice","Don't throw away your oil! Let it cool. Place a paper towel in a metal strainer and strain it into a glass or plastic container for next time"],"time":11,"servings":1,"image":"","source":"https://based.cooking/kettle-chips","page":"kettle-chips","tags":["snack","quick","potato"]},{"id":"bc-kettlecorn","title":"Kettle Corn","cuisine":"Other","category":"Snack","ingredients":["2 tablespoons vegetable oil, or oil of your choice","1/4 cup of popcorn kernels","2 tablespoons of sugar (brown sugar works too)","salt to taste"],"steps":["Add oil into your saucepan and 3 popcorn kernels","Cover with lid and set stove to medium-high heat","Once all 3 kernels pop, add in the rest of your kernels and shake to coat in oil. Pour sugar directly onto the kernels","Shake the pot for 3 seconds, rest for 3 seconds, and repeat till the kernels start to pop steadily. Depending on your stove, you may need to lift the pot to shake","Once kernels start popping, shake pot every 1-2 seconds","Important . Once you no longer hear pops for about 3 seconds, immediately transfer into a bowl to avoid burning"],"time":5,"servings":14,"image":"https://based.cooking/pix/kettlecorn.webp","source":"https://based.cooking/kettlecorn","page":"kettlecorn","tags":["snack","sweet","quick"]},{"id":"bc-kombucha","title":"Kombucha","cuisine":"Other","category":"Drink","ingredients":["5l (1 gallon) jar","3-5 tbsp black (or green) tea","2 cups sugar","kombucha scoby","optional additional teas","optional juices, fruits, spices","patience ;)"],"steps":["Boil 1-2l of water","Rinse all the dishes you will be working with boiling water; this is","Steep 3-5 tbsp (or 5-6 bags) of tee in 3-5 cups of water","Strain the leaves from the tea and add 2 cups of sugar (or honey)","Add other optional teas to your liking; I like to add a good handful of","Add 4l of water to the tea concentrate and pour into a wide mouthed jar","Let the tea sit until it is less than 40°C; add ice cubes if it has to go","Add your scoby to the jar and seal the mouth tightly with a cloth or paper","Let the jar sit in a warm dark spot for 10-14 days","Taste the brew after 10-14 days; if it has started to carbonate and the","Once ready, strain 4/5 of the brew through a sieve into re-sealable glass","Make another batch of primary brew and refill the big jar; the remaining old","If you wish you can add juices, fruits, or spices to your brew. These will","Let the bottles sit in a warm dark spot for another 3-14 days; the","When you are satisfied with the carbonation and the flavor, put the bottles","Enjoy your kombucha, rinse, and repeat"],"time":null,"servings":null,"image":"","source":"https://based.cooking/kombucha","page":"kombucha","tags":["drink","sweet"]},{"id":"bc-kvass","title":"Kvass","cuisine":"Other","category":"Drink","ingredients":["100 g of raisins","100 g of sugar","3 slices of black bread (e.g. pumpernickel bread, rye bread)","1-2 lemons","1 pkg (7 g) of active dry yeast","A handful of coffee beans (optional)","Non-citrus fruits, e.g. plums, apples, kiwi (optional)"],"steps":["Bring 1 L of water in a pot to a boil","Burn black bread in a toaster or in an oven until it is thoroughly scorched to blackness on the outside","Once the water has come to boil, remove off heat. Add burned black bread, a handful of raisins, a few slices of lemon, and coffee beans to the pot","Leave contents of the pot to cool down to room temperature","Filter out everything from the pot through a strainer, and pour contents into a separate, sterilized container. Add sugar and yeast into","Add rest of raisins, and non-citrus fruits of your choice. The fruits will positively impact flavour of the final product","If mixture is not already in a mason jar, pour the mixture into a sterile mason jar, and seal the lid. Place the jar in a warm place (26-30°C; 79-86°F),","Remove all raisins and fruits from the jar","Squeeze lemon juice from lemons into the mixture. You may drink the now-complete kvass right away, or refrigerate it before drinking"],"time":null,"servings":null,"image":"","source":"https://based.cooking/kvass","page":"kvass","tags":["drink","bread"]},{"id":"bc-lavacake","title":"Lavacake","cuisine":"Other","category":"Dessert","ingredients":["1 Egg","25g Flour","25g Butter","75g Chocolate"],"steps":["Cover the baking tin with some butter","Heat the oven for 200°C","Mix all of the ingredients","Fill dough in the baking tins pits","Bake for 7 min. in the oven at 200°C","Serve hot with berries and vanilla ice-creame"],"time":7,"servings":4,"image":"https://based.cooking/pix/lavacake.webp","source":"https://based.cooking/lavacake","page":"lavacake","tags":["chocolate","dessert","quick"]},{"id":"bc-lemon-juice-salad-dressing","title":"Lemon juice salad dressing","cuisine":"Other","category":"Salad","ingredients":["Lemon juice from half a lemon","Tablespoon of olive oil","Clove of garlic"],"steps":["Combine lemon juice and oil in small bowl","Add salt and pepper to taste","Add the garlic, pressed or finely minced","Mix well before adding to salad"],"time":null,"servings":null,"image":"","source":"https://based.cooking/lemon-juice-salad-dressing","page":"lemon-juice-salad-dressing","tags":["salad","basic","fasting"]},{"id":"bc-lemon-pudding","title":"Lemon Pudding","cuisine":"Other","category":"Dessert","ingredients":["One small lemon, with a smooth thin rind","Three eggs","A quarter of a pound of powdered white sugar","A quarter of a pound of fresh butter—washed","A table-spoonful of white wine and brandy, mixed","A tea-spoonful of rose-water"],"steps":["Grate the yellow part of the rind of a small lemon. Then cut the lemon in half, and squeeze the juice into the plate that contains the grated rind, carefully taking out all the seeds. Mix the juice and rind together","Put a quarter of a pound of powdered white sugar into a deep earthen pan, and cut up in it a quarter of a pound of the best fresh butter. If the weather is very cold, set the pan near the fire, for a few minutes, to soften the butter, but do not allow it to melt or it will be heavy. Stir the butter and sugar together, with a stick or wooden spoon, till it is perfectly light and of the consistence of cream","Put the eggs in a shallow broad pan, and beat them with an egg-beater or rods, till they are quite smooth, and as thick as a boiled custard. Then stir the eggs, gradually, into the pan of butter and sugar. Add the liquor and rose water by degrees, and then stir in, gradually, the juice and grated rind of the lemon. Stir the whole very hard, after all the ingredients are in","Have ready a puff-paste made of five ounces of sifted flour, and a quarter of a pound of fresh butter. The paste must be made with as little water as possible. Roll it out in a circular sheet, thin in the centre, and thicker towards the edges, and just large enough to cover the bottom, sides, and edges of a soup-plate. Butter the soup-plate very well, and lay the paste in it, making it neat and even round the broad edge of the plate. With a sharp knife, trim off the superfluous dough, and notch the edges. Put in the mixture with a spoon, and bake the pudding about half an hour, in a moderate oven. It should be baked of a very light brown. If the oven is too hot, the paste will not have time to rise well. If too cold, it will be clammy. When the pudding is cool, grate loaf-sugar over it"],"time":null,"servings":null,"image":"","source":"https://based.cooking/lemon-pudding","page":"lemon-pudding","tags":["lemon","dessert","pudding","fruit"]},{"id":"bc-lenten-chili","title":"Lenten Chili","cuisine":"Other","category":"Recipe","ingredients":["1 large onion, chopped","3 cloves garlic, minced","4 15oz cans of kidney beans (or 6 cups cooked beans)","1 29oz large can tomato sauce (or 4 cups fresh tomato sauce)","1 15oz can diced tomatoes (or 1 large diced tomato with skin removed)","1/2 can of sweet corn","1 cup cooked white or brown rice","1 tsp cumin","1 tsp smoked paprika","1 tsp garlic powder","1 tsp onion powder","1 tbsp chili powder","1 tbsp crushed red pepper","2-3 tbsp olive oil"],"steps":["Chop the large onion and mince the garlic cloves","On medium-low heat in a large tall pot add 2-3 tbsp olive oil","Add the chopped onions into the pot with oil and constantly stir for 5-10 minutes until they begin to brown","Just before onions are done add the minced garlic to the pot and let cook for 1-2 minutes","Add the tomato sauce, diced tomatoes, sweet corn, beans, and rice","Turn up the heat to medium","Add each of the spices, taste the chili, and adjust flavoring accordingly","Let cook for 20-30 minutes, stirring occasionally"],"time":30,"servings":4,"image":"https://based.cooking/pix/lenten-chili.webp","source":"https://based.cooking/lenten-chili","page":"lenten-chili","tags":["fasting"]},{"id":"bc-lenten-lentil-curry","title":"Lenten Lentil Curry","cuisine":"Other","category":"Recipe","ingredients":["200 g (7 oz) green lentils","50 g (1¾ oz) vermicelli","1 tsp curry powder","½ tsp paprika powder","½ tsp cinnamon powder","½ tsp ground sumac"],"steps":["Thoroughly rinse the lentils and drain the water","Put the lentils in the pot, and add 1 L (0.26 gal) of water","Bring to a boil, and gently boil for about 15-20 minutes","Drain the water","Add the other ingredients to the pot","Add 1½-2 tsp of salt and a little bit of ground black pepper","Add 0.5 L (0.13 gal) of boiling water","Simmer for about 10 minutes"],"time":35,"servings":2,"image":"https://based.cooking/pix/lenten-lentil-curry.webp","source":"https://based.cooking/lenten-lentil-curry","page":"lenten-lentil-curry","tags":["spicy","curry","lentil","fasting"]},{"id":"bc-limoncello","title":"Limoncello","cuisine":"Other","category":"Recipe","ingredients":["5-7 organic lemons (regular lemons are covered in wax)","300ml 95% ABV grain alcohol","700ml water","500ml sugar"],"steps":["Pour the alcohol into a 1 liter mason jar","Peel the lemons avoiding the white pith (it will make your limoncello bitter) and submerse them in the alcohol","Cover the jar and let the lemons infuse the alcohol for 20 days","After the infusion is completed, create a simple syrup by boiling the water and dissolving the sugar in the water","Allow the water to cool completely, then strain the alcohol into the sugar water and stir","Bottle or put it back into the mason jar","Feel free to scale the recipe up or down, and adjust the sugar to the sweetness you like, but the ABV should remain somewhere around 28-30%"],"time":null,"servings":22,"image":"https://based.cooking/pix/limoncello.webp","source":"https://based.cooking/limoncello","page":"limoncello","tags":["alcohol","lemon","digestivo","liquor"]},{"id":"bc-beef-liver-and-onions","title":"Liver and Onions","cuisine":"Other","category":"Recipe","ingredients":["1 lb Beef Liver","1-2 Onions","1-2 Carrots, and/or Celery Stalks (optional)","250g of Corn and/or Green Peas (optional)"],"steps":["Heat up the pan to medium with oil / animal fat","Chop up the onions into long pieces or small squares, to your preference","Put onions in pan. Wait a couple minutes, turn the heat to high, and add the liver. Stir frequently to prevent onions from burning. Cook for about 10 minutes","If pieces of beef liver are large, cut them into smaller pieces. About half a finger in size is best","Add other vegetables. (optional)","Season generously with salt and any seasoning you like. Various spice rubs work well"],"time":12,"servings":4,"image":"","source":"https://based.cooking/beef-liver-and-onions","page":"beef-liver-and-onions","tags":["beef","basic","easy","liver","quick"]},{"id":"bc-liverpate","title":"Liver Pate","cuisine":"Other","category":"Recipe","ingredients":["1lbs./500g liver (chicken, beef, poultry etc.)","1 Cup Carrots","1 Cup Onions","2 Teaspoon Nutmeg","2 Tablespoon Butter or Ghee"],"steps":["Cut liver into cubes","Put into a pot and cover with cold water, add 1tsp salt. Bring to a boil and boil for 10-15 minutes","Grate carrots and dice onions. Stew in a frying pan with a little bit of water until soft","In a food processor blend all ingredients together"],"time":null,"servings":null,"image":"","source":"https://based.cooking/liverpate","page":"liverpate","tags":["pate","liver"]},{"id":"bc-long-cooked-chuck-steak","title":"Long-cooked Chuck Steak With Vegetables","cuisine":"Other","category":"Soup","ingredients":["800g chuck steak","200g tomatoes (or 400g canned chopped tomatoes)","1 fennel","1 onion","1/4 of a cauliflower","50ml olive oil (Optional)"],"steps":["Add a little of the olive oil to the long cooker, put in the meat, and set it to high","Chop the onion and add it","Cut the cauliflower to sizes you prefer and add","Chop or slice 1/3 of the fennel and add","Crush the tomatoes and add (or add the canned chopped tomatoes)","Add the rest of the olive oil and let it be for at least 6 hours","Serve with the rest of the fennel (chop or sliced)"],"time":360,"servings":4,"image":"","source":"https://based.cooking/long-cooked-chuck-steak","page":"long-cooked-chuck-steak","tags":["beef","soup","keto"]},{"id":"bc-manhattan","title":"Manhattan","cuisine":"Other","category":"Recipe","ingredients":["2oz whisky (generally a rye or bourbon)","1oz sweet vermouth","2-3 dashes aromatic bitters","Cherry or lemon twist to garnish (optional)"],"steps":["Stir the wiskey, sweet vermouth, and bitters in a mixing glass with ice","Strain into a coupe glass","Garnish as desired"],"time":null,"servings":1,"image":"","source":"https://based.cooking/manhattan","page":"manhattan","tags":["alcohol","liquor"]},{"id":"bc-marinated-pork-steaks","title":"Marinated pork steaks","cuisine":"Other","category":"Recipe","ingredients":["6 tablespoons olive oil","¼ cup soy sauce","¼ cup of honey","Juice from 1 lime","3 peeled cloves garlic","4 ¼ inch thick boneless pork shoulder steaks"],"steps":["Mix olive oil, soy sauce, honey and lime juice until you have an even marinade. Add pepper and crushed garlic","Add the pork steaks to the marinade and leave in room temperature for 30 minutes or a bit longer","Preheat your grill/frying pan. Add marinated steaks, grill for 2 minutes, flip, repeat until you've grilled them for 10 minutes total. Towards the last minutes pour the remaining marinade over the steaks","Let the steaks rest for 10 minutes before serving"],"time":10,"servings":3,"image":"","source":"https://based.cooking/marinated-pork-steaks","page":"marinated-pork-steaks","tags":["pork","steak"]},{"id":"bc-matcha-cookies","title":"Matcha Cookies","cuisine":"Other","category":"Snack","ingredients":["115g Unsalted butter","60g Caster sugar","115g Brown sugar","55g Egg","153g Plain flour","12g Matcha powder","2g Baking soda","1g Salt","3g Vanilla extract","70g White coverture chocolate","45g Macadamia nut"],"steps":["Melt butter in a bath or microwave","Add white sugar, brown sugar and salt and mix with a whisk","Add egg and vanilla extract and mix with a whisk until well mixed","Add flour, matcha powder and baking soda and mix with a whisk until you can hardly see the powder","Add white coverture chocolate and macadamia and mix evenly with spatula","Allow 30 minutes to 1 hour in the refrigerator until the dough hardens","Pan with a 5cm diameter cookie and bake at 170°C (338°F) for 9 minutes. (Unox convection oven)","Preheat the oven beforehand. My oven is very hot, so raise the oven temperature a little bit higher if you have common oven","If you bake too little, it will not be cooked. If you bake too long, it will become hard","The white coverture chocolate melts smoothly in your mouth, and the white chocolate chip has a more chewy texture. So you can choose anything to your taste"],"time":null,"servings":null,"image":"","source":"https://based.cooking/matcha-cookies","page":"matcha-cookies","tags":["snack","cookies","sweet","dessert","cheesefare"]},{"id":"bc-mayonnaise-or-aioli","title":"Mayonnaise or aioli","cuisine":"Other","category":"Sauce","ingredients":["1 whole egg or 2 egg yolks, preferably at room temperature","2.5 dl/ 1 cup neutral oil","1-2 tbsp vinegar or lemon juice","1 tbsp pickle juice (optional)","2-4 cloves of garlic for aioli, don't include for mayonnaise","1 tsp dijon mustard (optional)"],"steps":["Place egg, vinegar, mustard a pinch of salt and pepper in a beaker or narrow and tall container. Add diced garlic for aioli","Add oil as the very last ingredient. It should be on the top of the other ingredients, or the mayonnaise/aioli could seperate","Place hand blender at the very bottom. Don't start it yet","Use full power, and work your way upwards slowly until all the oil is mixed in","Feel free to taste and mix in extra spices and vinegar afterwards"],"time":5,"servings":null,"image":"https://based.cooking/pix/mayonnaise-or-aioli.webp","source":"https://based.cooking/mayonnaise-or-aioli","page":"mayonnaise-or-aioli","tags":["sauce","basic"]},{"id":"bc-medieval-beef-soup","title":"Medieval Beef Soup","cuisine":"Other","category":"Soup","ingredients":["One beef roast","Around three to four large turnips with their greens attached","Two cups of chicken stock","1/10 grams of Saffron","1/4 a stick of butter","A slow cooker","A bowl of warm water"],"steps":["Cube the roast into bite sized pieces and place them in a large skillet with the butter","Heat the pan on medium-high heat and brown the meat with the melted butter until the outside is evenly cooked, sprinkle with pepper as it browns","While the meat is browning, cut the greens off the turnips and set them aside. Cut the turnips into bite sized pieces making sure to cut the top and bottom ends off first. If you can not find turnips with their greens still attached Mustard greens can be substituted","Put the cut up turnips in the slow cooker and pour in the chicken stock","Take the meat and dump it into the slow cooker drippings and all. If the amount of liquid looks a bit low to you, you can pour in another cup or so of water at your discretion","Sprinkle more pepper over the soup and put the saffron in the bowl of warm water and let it seep for five minutes. Then dump it and the warm water into the soup","Cut the stems off of the greens and then chop the greens vertically","Cook the soup on high for 2 to 2 1/2 hours or until the turnip and meat are soft and tender. About 20 minutes before it is to be done take the chopped greens and put them in the soup. Don't worry if it overfills the slow cooker, the greens will shrink a ton. Cook for about 20 minutes until done","Taste the soup, if it's still too bland you can add spices of your choice and season to your taste"],"time":null,"servings":null,"image":"https://based.cooking/pix/medieval-beef-soup.webp","source":"https://based.cooking/medieval-beef-soup","page":"medieval-beef-soup","tags":["beef","soup","roast"]},{"id":"bc-milus-fast-kvass","title":"Milu's Fast Kvass","cuisine":"Other","category":"Drink","ingredients":["500g (1.1 lbs) of the darkest rye bread you can find","0.5g (1/8 tsp) dry instant yeast","130g (2/3 cup) sugar","2 tsp sugar per bottle for carbonation"],"steps":["Preheat oven to 180°C (350°F). Cut the rye bread into cubes and bake for 40-45 minutes, turning every 5-10 minutes to ensure even toasting. The bread should be dark brown but not burnt","Place the toasted bread cubes in a large bowl and pour 2.5 liters (10.5 cups) of boiling water over them. Let soak for 2 hours","Add an additional 2 liters (8.5 cups) of boiling water to the mixture (add 1 more liter/4 cups if the bread absorbed a lot of water). Let sit for another 15-20 minutes","In a small bowl, mix 0.5g (1/8 tsp) dry yeast with 1 teaspoon sugar and 100ml (1/3 cup) lukewarm water. Mix well and let sit for 15 minutes until frothy","Strain the bread mixture through a fine mesh sieve or cheesecloth into another large bowl, squeezing out as much liquid as possible. Add 130g (2/3 cup) sugar and stir until dissolved","Let the mixture cool to room temperature. Once cooled, add the yeast mixture and stir well","Pour the kvass into clean glass jars or bottles, leaving 5 cm (2 inches) of space at the top. Cover with a cloth or loose lid to allow fermentation gases to escape","Let the jars sit at room temperature for 24 hours to ferment. The longer it ferments, the more sour it will become","Pour the kvass into clean plastic bottles, leaving any sediment behind. Add 2 teaspoons of sugar per bottle. Seal bottles tightly and leave at room temperature for 6-12 hours until the bottles feel firm to the touch","Check bottles after 6 hours by gently squeezing. When firm, release some gas by briefly opening, then reseal and refrigerate","Chill in refrigerator for 1 day before serving. If it still tastes yeasty, wait an additional 12-24 hours until the yeast flavor disappears and sediment forms at the bottom"],"time":45,"servings":null,"image":"","source":"https://based.cooking/milus-fast-kvass","page":"milus-fast-kvass","tags":["drink","bread"]},{"id":"bc-mushroom-sauce","title":"Mushroom sauce","cuisine":"Other","category":"Sauce","ingredients":["Champignons","Onion","A glass of cream or milk","Butter","Wheat flour"],"steps":["Place the butter in a frying pan and place over medium heat","Add all the chopped onions, mix well and leave for 10 minutes until the onions turn a little translucent golden","Add finely chopped champignons, mix well and add salt. Close the lid for 5 minutes","Add a tablespoon of flour, stir","After 3 minutes, add a glass of cream (or milk), mix well and close the lid for 10 minutes","Add salt, pepper and mix"],"time":30,"servings":3,"image":"","source":"https://based.cooking/mushroom-sauce","page":"mushroom-sauce","tags":["mushrooms","sauce","pasta","basic"]},{"id":"bc-nashville-chicken","title":"Nashville Chicken Sandwich","cuisine":"Other","category":"Recipe","ingredients":["2 Cups Buttermilk","1/3 Cup Hot sauce","2 1/2 Cups All-purpose flour","3 tbsp Cornstarch","3 tbsp Seasoned salt","1 tbsp Paprika","2 tsp Cayenne pepper","2 tsp Black pepper","1 tbsp Garlic powder","1 tbsp Onion powder","2 tsp Dry mustard powder","2 tbsp Nashville Hot Chicken seasoning","2 tbsp Adobo honey seasoning","2 tbsp Dark brown sugar","1 tsp Chili powder","1 tsp Garlic powder","1 tsp Smoked paprika","1 1/2 Cups Cooking oil Used to fry the chicken","3 tbsp Mayo","1 tbsp Ketchup","2 tbsp Sweet relish","1 tbsp Hot sauce"],"steps":["Prep your chicken by trimming it into less than a 1/2\" patties for frying","Prepare your batter and flour in two separate bowls","Dunk your chicken into the flour, then batter and then flour again. While your chicken is sitting with the battered flour pour 2 1/2 cups of cooking oil into your pan over medium heat or 350 degrees. Let it come to temp, about 20 mins","Once your oil has reached the temp of 350, go ahead and fry 3-4 pieces of chicken at one time. You are going to fry for 7 mins (flipping at the midway point) and then pull the chicken and let sit for 5 mins then refry for the second time 3 mins, this depends on the thickness of the chicken","Now that your chicken is fried make sure you have a wire rack with a sheet pan under it so the crispy chicken can sit and rest on. During this resting time, you are going to add your Nashville Hot Chicken seasoning together with 1 1/2 cups of the cooking oil you just used. It will simmer but quickly whisk until it comes still. Now you want to brush that amazing sauce all over the crispy chicken or dunk it","Have some toasted buns ready and create your sandwich. First, you want to sauce your top and bottom buns, add shredded romaine lettuce, chicken patty, tomato and then complete with the top bun for an amazingly delicious creation","Feed the family and enjoy! This one gets spicy, E N J O Y< :)"],"time":30,"servings":4,"image":"","source":"https://based.cooking/nashville-chicken","page":"nashville-chicken","tags":["chicken","spicy"]},{"id":"bc-newfoundland-cod-chowder","title":"Newfoundland Cod Chowder","cuisine":"Other","category":"Soup","ingredients":["4 Slices Bacon","2 Onions, sliced","1 tsp Savoury","6 Potatoes, peeled and cubed","3 Carrots, sliced","1 1/2 lbs Cod Fillets","1 can Evaporated Milk","2 Tbsp Fresh Parsley or Chives, chopped"],"steps":["In a large, heavy saucepan, cook bacon over medium-high heat for about 10 minutes or until crisp. Chop coarsely and set aside","Drain off all but 1 tbsp. fat from saucepan. Add onions and savoury. Cook, stirring occasionally for 5 minutes or until softened","Add potatoes, carrots, water and salt. Bring to boil, cover, reduce heat and simmer for about 20 minutes or until tender","Cut cod into 1-inch chunks. Add to vegetables and simmer for about 5 minutes or until fish flakes easily","Add milk and white pepper, heat through. Garnish with bacon and parsley"],"time":30,"servings":8,"image":"","source":"https://based.cooking/newfoundland-cod-chowder","page":"newfoundland-cod-chowder","tags":["fish","soup","seafood"]},{"id":"bc-no-knead-bread","title":"No-knead Bread","cuisine":"Other","category":"Bread","ingredients":["3 c flour","1 tsp salt","1/4 tsp instant yeast or 1.25/4 tsp active dry yeast","1 1/2 cups warm water","Oven-safe pan"],"steps":["Mix the dry ingredients then add the hot water. It should come out as a firm dough","Leave the dough at room temperature for 12 hours. You can then keep the dough in the fridge for up to 48 hours before cooking","Preheat oven and pan to 450 F (230 C)","Bake for 30 minutes covered (e.g. aluminum foil), then 20 minutes uncovered"],"time":50,"servings":8,"image":"https://based.cooking/pix/no-knead-bread.webp","source":"https://based.cooking/no-knead-bread","page":"no-knead-bread","tags":["bread","dough"]},{"id":"bc-no-knead-pizza-dough","title":"No-knead pizza dough","cuisine":"Other","category":"Recipe","ingredients":["200g flour","2g instant yeast (dry)","5g salt","5g olive oil","140g luke warm water"],"steps":["Mix dry ingredients in a bowl","Mix in olive oil and water. No need for hands or kneading!","Cover bowl air tight, and let it sit in room temperature for at least 7 hours, and up to 24 hours. It should have dramatically increased in size","The dough can be kept in the refrigerator for some days, so feel free to double/triple the ingredients for more pizzas for the same amount of work and time"],"time":600,"servings":1,"image":"","source":"https://based.cooking/no-knead-pizza-dough","page":"no-knead-pizza-dough","tags":["basic","pizza","dough"]},{"id":"bc-oat-milk","title":"Oat Milk","cuisine":"Other","category":"Drink","ingredients":["1L of ❄️ cold water","250ml of oats","0.5 teaspoon of salt","0.7 tablespoon of peanut butter"],"steps":["Put your water in the fridge so that it's at roughly 4 degrees C. You can also add ice to make it colder","Add all ingredients into blender","Blend for 15 seconds at high speed","Pass result through cheese cloth"],"time":null,"servings":null,"image":"","source":"https://based.cooking/oat-milk","page":"oat-milk","tags":["Oats","Milk","Drink","Breakfast","Coffee"]},{"id":"bc-oatmeal-cookies","title":"Oatmeal Cookies","cuisine":"Other","category":"Dessert","ingredients":["1 cup butter","2 eggs","1 tsp vanilla","2 cups sugar","2 cups flour","1.5 tsp cinnamon","1 tsp salt","3 cups oats","cranberries/raisins/coconut/nuts (optional)"],"steps":["Whisk butter, eggs, vanilla and sugar together","Add and combine flour, cinnamon, salt, oats, and optional add-ins","Mold and place ~24 golf sized balls of dough on trays with parchment paper","Cook for ~10 minutes or until edges begin to brown"],"time":10,"servings":24,"image":"","source":"https://based.cooking/oatmeal-cookies","page":"oatmeal-cookies","tags":["dessert","cookies","cheesefare"]},{"id":"bc-oatmeal-pancakes","title":"Oatmeal Pancakes","cuisine":"Other","category":"Breakfast","ingredients":["2 eggs","40g sugar (3 tbsp)","20g honey (1 tbsp)","60ml milk (4 tbsp) (you can use water instead)","120g oat flour (1 cup)","1 tsp baking powder (or baking soda + some acid to activate it)","Raspberry jam (optional)"],"steps":["Mix eggs, sugar, honey and milk","In another bowl mix oat flour and baking powder","Combine two mixtures and let the batter rest for about 15 minutes","Preheat the pan for 5 minutes over low (~33%) heat, cook for about 1 - 1.5 minutes then flip when you see bubbles come out and cook for another 45s - 1 minute","Eat them with raspberry (or any other) jam"],"time":15,"servings":8,"image":"https://based.cooking/pix/oatmeal-pancakes.webp","source":"https://based.cooking/oatmeal-pancakes","page":"oatmeal-pancakes","tags":["breakfast","sweet","dessert","pancake"]},{"id":"bc-oats","title":"Oats","cuisine":"Other","category":"Breakfast","ingredients":["oats","water","pinch of salt","chopped banana","any berries","cinnamon","peanut butter"],"steps":["Bring water (with pinch of salt) to boil","Add oats. Use a 2:1 water-to-oats ratio (by volume) for rolled oats, 3:1 for","Boil on medium heat until most of the water has been absorbed/evaporated","Pour over fruit in bowl (if having fruit)","Sprinkle cinnamon (if having cinnamon)","Mix","Add a spoonful of peanut butter (if having peanut butter)"],"time":null,"servings":null,"image":"","source":"https://based.cooking/oats","page":"oats","tags":["sweet","breakfast","quick","fasting"]},{"id":"bc-oaty-pancakes","title":"Oaty Pancakes","cuisine":"Other","category":"Breakfast","ingredients":["3⁄4 cup milk","3⁄4 cup rolled oats","1 egg","1⁄2 teaspoon salt","2-3 tablespoon sugar","1⁄2 cup flour","2 teaspoon baking powder","2 teaspoon baking soda","25g butter (melted)"],"steps":["Pour milk over rolled oats. Add remaining ingredients","Mix with fork (or in a food processor) just enough to","Put spoonfuls of mixture onto preheated, greased or","Turn pancakes as soon as bubbles form and","Put a dab of butter on cooked surface of several","Pile up so butter is between pancakes. Pour","Serve Oaty pancakes for breakfast or brunch, with juice"],"time":10,"servings":4,"image":"","source":"https://based.cooking/oaty-pancakes","page":"oaty-pancakes","tags":["breakfast","quick","sweet","pancake","cheesefare"]},{"id":"bc-omelet","title":"Omelet","cuisine":"Other","category":"Recipe","ingredients":["2 tablespoon quick-cooking tapioca","1/2 teaspoon salt","1/8 teaspoon pepper","3/4 cup milk, scalded","1 tablespoon butter, or margarine","4 egg yolks, beaten until thick","4 egg whites, beaten stiff","Cheddar Cheese (optional for Cheese Omelet)"],"steps":["Add tapioca, salt and pepper to milk; cook in double boiler 15 minutes or until tapioca is clear and mixture thickened, stirring frequently","Add butter","Allow it to cool; combine with egg yolks, stirring occasionally","Fold in egg whites","Set oven for moderate 350°F","Pour egg mixture into hot buttered frying pan","Cook over low heat 3 minutes","Transfer to oven; bake 15 minutes","Omelet is done when an inserted knife comes out clean","Cut across at right angles to handle of pan, being careful not to cut all the way through","Fold carefully from handle to opposite side and serve on hot platter"],"time":30,"servings":4,"image":"","source":"https://based.cooking/omelet","page":"omelet","tags":["eggs","quick","cheesefare"]},{"id":"bc-orange-glorious","title":"Orange Glorious","cuisine":"Other","category":"Drink","ingredients":["1 (6 ounce) can frozen orange juice concentrate","1 cup milk","1 cup water","1/2 cup white sugar","1 teaspoon vanilla extract","12 cubes ice"],"steps":["In a blender, combine orange juice concentrate, milk, water, sugar and vanilla. Add ice cubes and blend until smooth. Pour into glasses and serve"],"time":5,"servings":4,"image":"","source":"https://based.cooking/orange-glorious","page":"orange-glorious","tags":["drink","sweet","breakfast"]},{"id":"bc-orange-jam","title":"Orange jam","cuisine":"Other","category":"Recipe","ingredients":["4 medium sized oranges","1 lemon","1 1/2 cup sugar"],"steps":["Zest all fruit","Peel off the albedo (the white part under the skin)","Blend the fruit (not too much, it doesn't need to become an even mush, just","Combine the blended fruit, zest, and sugar in a pot","Bring to boil and boil for 30-40 minutes on low heat. The mixture will"],"time":null,"servings":null,"image":"","source":"https://based.cooking/orange-jam","page":"orange-jam","tags":["jam","fruit","sweet","spread"]},{"id":"bc-orange-pudding","title":"Orange Pudding","cuisine":"Other","category":"Dessert","ingredients":["One large orange, of a deep colour, and smooth thin rind","One lime","A quarter of a pound of powdered white sugar","A quarter of a pound of fresh butter","Three eggs","A table-spoonful of mixed wine and brandy","A tea-spoonful of rose-water"],"steps":["Grate the yellow rind of the orange and lime, and squeeze the juice into a saucer or soup-plate, taking out all the seeds","Stir the butter and sugar to a cream","Beat the eggs as light as possible, and then stir them by degrees into the pan of butter and sugar. Add, gradually, the liquor and rose-water, and then by degrees, the orange and lime. Stir all well together","Have ready a sheet of puff-paste made of five ounces of sifted flour, and a quarter of a pound of fresh butter. Lay the paste in a buttered soup-plate. Trim and notch the edges, and then put in the mixture. Bake it about half an hour, in a moderate oven. Grate loaf-sugar over it, before you send it to table"],"time":null,"servings":null,"image":"","source":"https://based.cooking/orange-pudding","page":"orange-pudding","tags":["orange","dessert","pudding","fruit"]},{"id":"bc-original-gatorade","title":"Original Gatorade","cuisine":"Other","category":"Drink","ingredients":["4 cups Water","1/4 tsp Table salt","1/4 tsp Salt substitute (NuSalt or NoSalt)","1/4 tsp Cream of Tartar","3 tbsp Sugar","Juice of 1 Lemon"],"steps":["Combine all dry ingredients in a large bowl or mason jar","Add water and lemon juice","Mix until solids are desolved","Bottle in 2 cup portions and serve chilled"],"time":null,"servings":null,"image":"","source":"https://based.cooking/original-gatorade","page":"original-gatorade","tags":["drink"]},{"id":"bc-overnight-oats","title":"Overnight Oats","cuisine":"Other","category":"Breakfast","ingredients":["3 cups milk","3 bananas (the riper, the better)","6 tbsp plain yogurt","9 tbsp peanut butter","3 cups oats","9 eggs (optional)"],"steps":["Pour milk into blender","Slice bananas into a few pieces each and add to blender, blend until combined","Scoop yogurt into blender and blend until combined","Scoop peanut butter into blender and blend until combined","If using eggs, scramble and cook them on the stove. Add them to blender and blend until combined","Divide blender contents between 3 storage containers, such as tupperware","Divide oats into each contatiner","Mix each container throughoughly so that the oats are well distributed and are not clumped together","Let soak in refridgerator for at least 12 hours"],"time":15,"servings":3,"image":"https://based.cooking/pix/overnight-oats.webp","source":"https://based.cooking/overnight-oats","page":"overnight-oats","tags":["breakfast","basic","milk"]},{"id":"bc-pan-pizza","title":"Pan pizza","cuisine":"Other","category":"Recipe","ingredients":["no-knead pizza dough","pizza sauce","cheese","olive oil","pepperoni (optional)","mushrooms (optional)","pineapple (optional)","really whatever you like (optional)"],"steps":["Preheat oven to max temp","Add olive oil to the bottom of an iron skillet. The whole bottom and sides should be coated","Add some oil to hands and shape dough into a ball","Place ball to the center of the pan and press it down gently. It will not cover the whole bottom yet","Cover the skillet and let the dough rest for minimum 30 min","Press the dough to cover the whole bottom of the skillet","Add pizza sauce, cheese, and whatever you like on your pizza","Put in the middle of the oven, and cook for 15-20 minutes"],"time":480,"servings":null,"image":"https://based.cooking/pix/pan-pizza.webp","source":"https://based.cooking/pan-pizza","page":"pan-pizza","tags":["basic","pizza"]},{"id":"bc-pan-seared-chicken","title":"Pan-seared Chicken Fillet","cuisine":"Other","category":"Recipe","ingredients":["Chicken fillet(s); I normally use chicken breasts","Wheat flour","Paprika","Garlic powder","Herbes de Provence"],"steps":["Rinse the chicken fillets","Remove excess moisture from the fillets by patting them with a paper towel","If the fillets are too thick, cut them in half","In a small container, pout enough flour and mix in paprika, garlic powder,","Add a little cooking oil to the pan and heat it up to medium-high heat","Coat the fillets by rolling them in the wheat mix","Once the pan is hot, put the fillets on the pan and sear each side for about","As a final tip, if your fillet is too thick after all, you can just lower the","And that's it. Winner winner chicken dinner!"],"time":null,"servings":null,"image":"https://based.cooking/pix/pan-seared-chicken.webp","source":"https://based.cooking/pan-seared-chicken","page":"pan-seared-chicken","tags":["chicken","fry"]},{"id":"bc-pancake","title":"Pancake","cuisine":"Other","category":"Breakfast","ingredients":["200g wheat flour or 100g glutenfree flour","200 ml milk","2 eggs","2 tsp sugar","1 tsp baking soda","a little bit of salt"],"steps":["Mix all ingredients in a bowl","Let the dough rest for ~15 mins","Heat a pan with a bit butter or oil","For each pancake spread a ladle of dough in the pan and bake them at lower medium temperature until they are brown on both sides"],"time":10,"servings":1,"image":"https://based.cooking/pix/pancake.webp","source":"https://based.cooking/pancake","page":"pancake","tags":["quick","breakfast","sweet","pancake","cheesefare"]},{"id":"bc-parmesan-potatoes","title":"Parmesan potatoes","cuisine":"Other","category":"Side","ingredients":["2-3 medium-sized potatoes","Butter","Parmesan cheese","Rosemary; dried should be fine, but fresh is obviously better"],"steps":["Cut the potatoes into small cubes","Add some butter to a frying pan and heat up","Add potatoes to frying pan, salt them and fry over medium heat for about","About 3-5 minutes before removing the potatoes from the heat, add some","Remove potatoes from pan, serve and add shredded Parmesan and some freshly","Enjoy!"],"time":null,"servings":null,"image":"https://based.cooking/pix/parmesan-potatoes.webp","source":"https://based.cooking/parmesan-potatoes","page":"parmesan-potatoes","tags":["potato","side"]},{"id":"bc-party-mimosa","title":"Party Mimosa","cuisine":"Other","category":"Drink","ingredients":["1 (12 ounce) can apricot-mango nectar","1 (12 ounce) can pineapple juice","1 (6 ounce) can frozen orange juice concentrate, thawed and undiluted","1 (750 milliliter) bottle cold champagne","3/4 cup cold water"],"steps":["Stir together apricot nectar, pineapple juice, water, and orange juice concentrate in a large pitcher until combined. Pour in bottle of sparkling wine just before serving"],"time":null,"servings":null,"image":"","source":"https://based.cooking/party-mimosa","page":"party-mimosa","tags":["drink","sweet","breakfast"]},{"id":"bc-pepper-sauce","title":"Pepper Sauce","cuisine":"Other","category":"Sauce","ingredients":["1 tablespoon freshy ground rose pepper, green pepper and black pepper","1 teaspoon dijon mustard","1dl bouillon","2dl cream","Salt if needed"],"steps":["Ground the peppers and put them on the pan and roast them for about one minute while moving the peppers with your spatula","Mix in the mustard and bouillon and bring to a boil","Add in the cream and let the sauce thicken on medium heat for about 10-20 minutes","Taste the sauce and add salt if needed"],"time":20,"servings":4,"image":"","source":"https://based.cooking/pepper-sauce","page":"pepper-sauce","tags":["sauce","steak"]},{"id":"bc-pickled-onions","title":"Pickled Red Onions","cuisine":"Other","category":"Side","ingredients":["Red Onions","Vinegar","Water"],"steps":["Cut onion in half and slice root to stem and place in a jar","Mix equal parts of water and vinegar in a pot and bring to a boil. Add salt to taste","As soon as it begins to boil, turn off and pour the mix into the jar and allow to cool","Seal and place in fridge for a few hours until vibrant pink"],"time":10,"servings":null,"image":"https://based.cooking/pix/pickled-onions.webp","source":"https://based.cooking/pickled-onions","page":"pickled-onions","tags":["quick","side","basic"]},{"id":"bc-pizza-dough","title":"Pizza Dough","cuisine":"Other","category":"Recipe","ingredients":["400g flour (basic wheat flour)","200ml lukewarm water","1 pkg (7g) dry yeast","1 spoon olive oil","1 teaspoon salt","a teensy bit of sugar (to feed the yeast)"],"steps":["Combine all the ingredients in a bowl and knead into a dough","Let it rest for about 30 minutes somewhere lukewarm","Add some flour to a table and roll the dough out there"],"time":null,"servings":null,"image":"","source":"https://based.cooking/pizza-dough","page":"pizza-dough","tags":["basic","pizza","dough"]},{"id":"bc-pizza-sauce","title":"Pizza sauce","cuisine":"Other","category":"Sauce","ingredients":["400g canned tomatoes, preferebly skinned and whole","150g tomato puré","1 medium sized onion","olive oil","garlic","oregano","chili pepper (optional)"],"steps":["Dice onion and fry in olive oil on medium heat","Add chopped garlic and chili pepper (optional) for some minutes","Mix in tomato puré, salt, pepper, and oregano. Cook until puré gets oily","Add canned tomatoes, and crush with spatula","Let it sit on low heat. The longer the better"],"time":120,"servings":null,"image":"","source":"https://based.cooking/pizza-sauce","page":"pizza-sauce","tags":["basic","pizza","sauce"]},{"id":"bc-plum-pudding","title":"Plum Pudding","cuisine":"Other","category":"Dessert","ingredients":["One pound of raisins, stoned and cut in half","One pound of currants, picked, washed and dried","One pound of beef suet chopped fine","One pound of grated stale bread, or, half a pound of flour and half a pound of bread","Eight eggs","A quarter of a pound of sugar","A glass of brandy","A pint of milk","A glass of wine","Two nutmegs, grated","A table-spoonful of mixed cinnamon and mace","A salt-spoonful of salt"],"steps":["You must prepare all your ingredients the day before (except beating the eggs) that in the morning you may have nothing to do but to mix them, as the pudding will require six hours to boil","Beat the eggs very light, then put to them half the milk and beat both together. Stir in gradually the flour and grated bread. Next add the sugar by degrees. Then the suet and fruit alternately. The fruit must be well sprinkled with flour, lest it sink to the bottom. Stir very hard. Then add the spice and liquor, and lastly the remainder of the milk. Stir the whole mixture very well together. If it is not thick enough, add a little more grated bread or flour. If there is too much bread or flour, the pudding will be hard and heavy","Dip your pudding-cloth, in boiling water, shake it out and sprinkle it slightly with flour. Lay it in a pan and pour the mixture into the cloth. Tie it up carefully, allowing room for the pudding to swell","Boil it six hours, and turn it carefully out of the cloth","Before you send it to table, have ready some blanched sweet almonds cut in slips, or some slips of citron, or both. Stick them all over the outside of the pudding"],"time":null,"servings":null,"image":"","source":"https://based.cooking/plum-pudding","page":"plum-pudding","tags":["raisins","dessert","pudding","fruit"]},{"id":"bc-popcorn","title":"Popcorn","cuisine":"Other","category":"Snack","ingredients":["1/3 cup popcorn kernels","3 tbsp coconut oil","Flavacol or other finely ground salt","High-sided pot which retains heat decently well","Metal strainer wide enough to act as a lid"],"steps":["Place oil and 3 test kernels into the pot over med-high heat. The un-displaced oil won't cover the bottom, so ensure the test kernels are actually touching it","Wait for all 3 of the kernels to pop. The pot and oil are at the right temperature when this happens","Remove pot from heat and add the rest of the kernels. Ensure they all get nice and oily by swirling the pot or mixing them with a wooden spoon","Allow 30 seconds for heat to evenly spread through the kernels. It helps them all pop at the same time","Return to heat with the strainer as a cover. This allows you to release as much steam as possible","When the corn is all popped, pour it into a bowl and toss with flavacol and/or whatever else you like to put on it"],"time":null,"servings":null,"image":"","source":"https://based.cooking/popcorn","page":"popcorn","tags":["corn","snack"]},{"id":"bc-potato-leek-soup","title":"Potato Leek Soup","cuisine":"Other","category":"Soup","ingredients":["3 tablespoons unsalted butter","2 large leeks","1 quart chicken or veggie stock","11 ounces peeled and sliced waxy potatoes","1 bay leaf","¾ cup heavy cream","white pepper","(optional) ½ teaspoon ground nutmeg","(optional) ½ tablespoon dill weed"],"steps":["Chop the white to light-green part of the leek into moderately sized pieces and discard the dark-green ends","Melt the butter in a pot on medium-low heat, add chopped leeks and potatoes. Stir until leeks are sweat","Add stock, bay leaf, pepper and optional ingredients now. Raise heat to medium-high, simmer until potatoes are tender","After removing the pot from the heat, remove the bay leaf and immersion blend pot until you reach a desired consistency","Stir in heavy cream and salt to taste"],"time":80,"servings":2,"image":"https://based.cooking/pix/potato-leek-soup.webp","source":"https://based.cooking/potato-leek-soup","page":"potato-leek-soup","tags":["potato","soup","vegetables","cheesefare"]},{"id":"bc-potato-pure","title":"Potato purée","cuisine":"Other","category":"Side","ingredients":["1 kg potatoes","200 ml milk","3 teaspoons butter","grated cheese (optional)"],"steps":["Peel the potatoes and cut them to small pieces","Put them in a pot and cover with water","Bring to boil and cook until potatoes are soft","Drain and mash with a fork","Warm up milk, but don't let it boil","Still on the fire, add butter and mashed potatoes, and optionally grated cheese, and stir until uniform","Keep stirring on the fire to thicken as you like"],"time":15,"servings":4,"image":"https://based.cooking/pix/potato-puree.webp","source":"https://based.cooking/potato-pure","page":"potato-pure","tags":["easy","potato","side"]},{"id":"bc-potato-soup","title":"Potato Soup","cuisine":"Other","category":"Soup","ingredients":["Potatoes (yellow or brown), I don't count but 10+","Butter, a stick or two","Whole Milk","Garlic","Cheese (optional)","Onion Greens (optional)","Sour Cream (optional)"],"steps":["Bake the potatoes at 450° for about an hour","Take them out and leave them to cool for a good 10 minutes","Begin heating up a big pot to about medium temperature, and put the butter in to melt","Cut the potatoes in half and scoop them directly into the pot","Once you are finished with that, begin mashing them until they are a nice mashed-potato-like consistency","Add milk little by little, stirring as you go, until you reach the desired consistency. I usually use half a gallon or so","Shred cheese into the soup. Then add garlic, salt, pepper, cayenne, onion greens, and anything else you can think of","Let the soup reach a boil, stirring constantly. Remove from heat and serve","I usually eat it with sour cream mixed in to cool it down and get that extra dairy in"],"time":null,"servings":null,"image":"","source":"https://based.cooking/potato-soup","page":"potato-soup","tags":["potato","soup"]},{"id":"bc-sourdough-potato-bread","title":"Potato sourdough bread","cuisine":"Other","category":"Bread","ingredients":["150g boiled potatoes in there skin","350g wheat flour","50g whole rye flour","11g salt","150g water","250g sourdough"],"steps":["Boil the potatoes","Peel of the skin of the potatoes (let them cool down a bit)","Stir all ingredients and knead them well","Let the dough rest for 5 hours in warm (25-30°C) conditions","Preheat the oven to 250°C","Bake for up to 10 minute with steam","Release the steam and turn the heat down to 220°C","Bake for another 35 minutes"],"time":45,"servings":null,"image":"https://based.cooking/pix/sourdough-potato-bread.webp","source":"https://based.cooking/sourdough-potato-bread","page":"sourdough-potato-bread","tags":["sourdough","bread","potato"]},{"id":"bc-pretzels","title":"Pretzels","cuisine":"Other","category":"Bread","ingredients":["1 1/5 (355mL) cups water","1 1/2 teaspoons dry yeast","1-2 teaspoons sugar, honey, barley syrup, or molasses, etc","1-2 teaspoons coarse salt","4.5 (650g) cups flour","1/4 (70g) cup food-grade sodium hydroxide (lye)","5 (1.2L) cups water, for the lye bath","2 tablespoons of crunchy finishing salt"],"steps":["Make the dough by mixing the water, yeast, sugar, and salt with as much flour as you can stir in, then let the dough sit for 15 minutes to autolyse","Knead in the remaining flour, which should be enough to give you a dough that is just barely sticky","Cover the dough and let it rise overnight in the refrigerator for best flavor, or for about 2 hours on the counter","Pull the risen dough out onto a cutting board and cut it into quarters, for the four pretzels we are making. Smash each quarter piece down flat and roll it into a log","Cover the dough logs and let them rest for about 15 minutes to let the gluten relax for easier shaping. Start preheating the oven to 450℉ (230℃) while these rest","Roll each log out into a long thin snake, leaving the center \"belly\" thicker, also don't do this with the counter covered in flour. Pull the ends of a \"snake\" towards you to make an upside-down 'U' shape, fold the \"arms\" over each other twice, then back towards the \"belly\". Seal the tips on the belly by pressing them down firmly onto it. Don't do the next steps too slowly to prevent the pretzels from puffing up much after being shaped","Using a heat-safe and chemically non-reactive vessel (such as a pyrex baking dish) create the lye bath by putting in the 5 cups of water and slowly sprinkle in the sodium hydroxide while gently mixing","Glove your hands with latex gloves or some other kind of chemical-resistant ones and fully submerge each of the four pretzels one at a time into the lye bath for 10 seconds each. Drain each pretzel thouroughly before transfering them to baking sheets","Sprinkle the crunchy finishing salt over the the pretzels and score each pretzel's belly with a knife for aesthetics and to allow it to expand more in the oven","Bake pretzels until they are deep mahogany all over. This should take around 15 minutes. The sodium hydroxide should react with the dough and harmlessly evaporate in the oven","Store or dispose the lye bath. To easily dispose of the lye bath, slowly drizzle the lye down the drain with the faucet running, to dilute it","If at any point you get lye on your skin, wash it off in the sink promptly. It may cause minor skin irritation"],"time":15,"servings":null,"image":"","source":"https://based.cooking/pretzels","page":"pretzels","tags":["bread","fasting"]},{"id":"bc-puff-pastry","title":"Puff Pastry","cuisine":"Other","category":"Recipe","ingredients":["5 cups bread flour","2 1/2 teaspoons salt","2 cups water","2 cups unsalted butter, softened"],"steps":["Before starting on the dough, place the butter between two pieces of plastic wrap. Pound into a flat disc using a rolling pin or other heavy object. Refrigerate until firm, roughly 20 minutes","Mix the flour and salt in a large bowl or in the bowl of a stand mixer with a dough hook. Gradually stir in water until the dough holds together enough to clean the sides of the bowl. The dough should not be sticky, but it should not be dry. Do not put all the water in as you may not need all of it. Let the dough sit for at least 10 minutes","On a lightly floured surface, roll out the dough into a large rectangle about 1/2 inch thick. Place the butter in the center and fold the two ends over it so that it is fully encased in dough. Roll out the dough again, taking care to not let the butter break through the surface. Once the dough is about 1/2 inch thick again fold into thirds. The butter should be warm now, place into fridge for 30 minutes","Repeat rolling and folding two more times, then refrigerate again until firm","Repeat two or more times until the dough was rolled roughly 6 times, then wrap and refrigerate. The dough can now be used in recipes calling for puff pastry. Roll out thin, about 1/4 inch, and bake at 400 degrees F for best results"],"time":25,"servings":24,"image":"","source":"https://based.cooking/puff-pastry","page":"puff-pastry","tags":["dough","cheesefare","pastry"]},{"id":"bc-pulled-rabbit","title":"Pulled Rabbit","cuisine":"Other","category":"Recipe","ingredients":["2 cleaned rabbits","butter","2 hard-boiled egg yolks","minced sweet herbs (basil and/or rosemary)","lemon","nutmeg","cayenne (optional)"],"steps":["Boil 2 cleaned rabbits until very tender","Take them out to cool","When cold, cut them in pieces as for carving, and peel off the skin. Then with a fork pull all the meat from the bones, first loosening it with a knife","Put it into a stew-pan with plenty of cream, or some bits of fresh butter rolled in flour; some minced sweet herbs, some grated fresh lemon rind, and some hard-boiled yolks of eggs crumbled. Season with cayenne and nutmeg","Cover it, and let it simmer till it comes to a boil. Then immediately take it off the stove, and transfer it to a deep dish"],"time":null,"servings":null,"image":"","source":"https://based.cooking/pulled-rabbit","page":"pulled-rabbit","tags":["rabbit","meat"]},{"id":"bc-pumpkin-flatbread","title":"Pumpkin Flatbread","cuisine":"Other","category":"Recipe","ingredients":["Wheat flour, type 405 – 2 cups (about 8.8 oz)","Olive oil – 5 tablespoons","Salt – a pinch","Water – ½ cup (about 3.4 fl oz)","Fresh thyme – ½ oz (about 1 tablespoon chopped)","Soy yogurt – ¾ cup (about 7 oz)","Black pepper, ground – a pinch","Hokkaido pumpkin – ½ piece (about 1 lb)","Red onions – 2 pieces","Pears – 2 pieces","Walnut kernels – 2 tablespoons"],"steps":["Preheat the oven to 465°F (top and bottom heat)","In a bowl, knead together the flour, 3 tablespoons of olive oil, salt, and water into a smooth dough. Wrap the dough ball in plastic wrap and let it rest at room temperature","Wash the thyme, shake it dry, pluck the leaves from the stems, and chop them","In a bowl, mix the soy yogurt with the thyme and season with salt and pepper","Wash the pumpkin, cut it in half, scrape out the seeds with a spoon, and slice it thinly. Halve the onions, peel them, and slice into strips. Wash the pears, quarter them, remove the cores, and cut into thin slices","Roll out the dough on a floured surface into two thin rectangles. Place each one on parchment paper and transfer to a baking sheet","Spread the soy yogurt mixture over the dough and top with pumpkin, pear, and onion slices. Bake in the oven for about 10 minutes, until golden brown","Meanwhile, roughly chop the walnuts. Remove the pumpkin flatbreads from the oven, cut them into portions, sprinkle with walnuts, and serve","Enjoy :)"],"time":60,"servings":4,"image":"https://based.cooking/pix/pumpkin-flatbread-1.avif","source":"https://based.cooking/pumpkin-flatbread","page":"pumpkin-flatbread","tags":["vegan"]},{"id":"bc-pumpkin-loaves","title":"Pumpkin Loaves","cuisine":"Other","category":"Dessert","ingredients":["2 cups flour","1/2 teaspoon salt","1/2 teaspoon baking powder","1 teaspoon baking soda","1 teaspoon ground cloves","1 teaspoon ground cinnamon","1 teaspoon ground nutmeg","1/2 teaspoon grated ginger","2 cups sugar","3/4 cup butter","2 eggs","1 can (1 lb) pumpkin"],"steps":["Grease 2 loaf pans or cover with parchment paper, then preheat oven to 325°F","Sift flour with all other dry ingredients (optional)","Beat sugar and butter","Add eggs to sugar/butter mixture, one at a time","Beat in pureed pumpkin","Whisk in flour and other dry ingrients","Add batter to loaf pans and bake for ~ 1 hour 15 minutes"],"time":75,"servings":2,"image":"","source":"https://based.cooking/pumpkin-loaves","page":"pumpkin-loaves","tags":["pumpkin","dessert","sweet","cheesefare"]},{"id":"bc-quickbreakfastspaghetti","title":"Quick Breakfast Spaghetti","cuisine":"Other","category":"Breakfast","ingredients":["Spaghetti (any kind you prefer)","Ground spices (I like to use cumin, turmeric, paprika, and garlic)","Tomato Paste/Sauce (preferably one with basil and without preservative)","Extra Virgin Olive Oil"],"steps":["Boil some water fully and prepare a pot","While the water is boiling, add all your spices in the pot with the spaghetti on top","Pour the boiled water on the spaghetti to make it soft so you can immerse it fully in the water","Mix thoroughly the water with the spices and salt and pepper if needed","Place the pot on the stove, keep it boiling, and stir every minute or two for 8 minutes","It should take no more than 8 minutes, but you can check if it is fully cooked by tasting one piece at a time","Once it is fully cooked, strain the water from the pot and keep the spaghetti in","Before placing it back on the stove, add and mix a generous amount of olive oil. Now's the time to add bacon or turkey if you are also using that","While stirring the spaghetti, add your tomato sauce or paste and keep mixing for a minute and avoid letting it stick to the boiler","Pour the spaghetti out in your favorite bowl and enjoy!"],"time":null,"servings":null,"image":"","source":"https://based.cooking/quickbreakfastspaghetti","page":"quickbreakfastspaghetti","tags":["breakfast","pasta"]},{"id":"bc-rabbit-onions","title":"Rabbits with Onions","cuisine":"Other","category":"Recipe","ingredients":["2 cleaned rabbits","6 large onions","nutmeg","butter or lard","flour","cayenne (optional)"],"steps":["Peel, boil, and slice six (or more) large onions, and season them with nutmeg, and a very little cayenne. Cover them, and set them aside till wanted","Cut the meat from two rabbits into pieces, and fry them in fresh butter or lard. When browned, and nearly done, cover them with the sliced onions, and brown them, having laid among them some bits of fresh butter rolled in flour","Dish the rabbits, with the pieces entirely hidden under the onions"],"time":null,"servings":null,"image":"","source":"https://based.cooking/rabbit-onions","page":"rabbit-onions","tags":["rabbit","meat"]},{"id":"bc-rice","title":"Rice","cuisine":"Other","category":"Rice","ingredients":["rice","chicken stock (optional)","onion or garlic (optional)","lime and cilantro (optional, for a Mexican taste)"],"steps":["Add some amount of rice to a pot that has a cover","Add twice as much liquid to the same pot. Water is typical, but for extra flavor, use stock or broth","If desired, dice onion or garlic and mix into rice","Cover the pot, put it on the stove and turn the heat on the highest level","As soon as you hear the water beginning to bubble and boil over, turn the heat down to low and allow it to simmer","Wait for twenty minutes or so until the liquid has evaporated and the rice will be ready"],"time":null,"servings":null,"image":"","source":"https://based.cooking/rice","page":"rice","tags":["basic","rice","side","fasting"]},{"id":"bc-rice-pudding","title":"Rice Pudding","cuisine":"Other","category":"Rice","ingredients":["A quarter of a pound of rice","A quarter of a pound of butter","A quarter of a pound of sugar","A pint and a half of milk, or cream and milk","Six eggs","A tea-spoonful of mixed spice, mace, nutmeg and cinnamon","A half wine-glass of rose-water"],"steps":["Wash the rice. Boil it till very soft. Drain it and set it away to get cold. Put the butter and sugar together in a pan, and stir them till very light. Add to them the spice and rose-water. Beat the eggs very light, and stir them, gradually, into the milk. Then stir the eggs and the milk into the butter and sugar, alternately with the rice","Bake it and grate nutmeg over the top","Currants or raisins, floured, and stirred in at the last, will greatly improve it"],"time":null,"servings":null,"image":"","source":"https://based.cooking/rice-pudding","page":"rice-pudding","tags":["rice","dessert","pudding"]},{"id":"bc-roasted-chicken-breast","title":"Roasted chicken breast","cuisine":"Other","category":"Recipe","ingredients":["Boneless skinless chicken breast(s)","1/4 stick of butter per chicken breast","Seasoning (optional)"],"steps":["Fill a large bowl with enough water to submerge the chicken. Add salt to the water until it's fully saturated. Put the chicken under the water and let it sit for 20-40 minutes at room temperature","Preheat the oven to 230°C / 450°F","Remove the chicken from the water. Rinse it. Dry it. Put it in a roasting pan (you can use a casserole dish, oven-safe skillet, or baking pan too)","Brush the chicken with melted butter. For best results, brush all sides of the chicken breast","Season with pepper and any optional seasoning. Season with salt last","Insert the thermometer probe into the thickest part of the smallest breast","Bake until the internal temperature reaches 68°C / 155°F","Remove from the oven and immediately cover with foil leaving the probe inserted. Let the chicken sit for 10 minutes at room temperature. The chicken will continue to cook. It should reach at least 74°C / 165°F but if it doesn't, see this reddit post about food safety when cooking chicken to less than 165°F","Serve"],"time":null,"servings":null,"image":"","source":"https://based.cooking/roasted-chicken-breast","page":"roasted-chicken-breast","tags":["chicken","roast"]},{"id":"bc-sausage-rolls","title":"Sausage Rolls","cuisine":"Other","category":"Recipe","ingredients":["Eggs","Puff pastry","Pork meat / sausage meat"],"steps":["Place baking paper onto a tray","Whisk eggs","Lay out pastry, brush or pour egg whisk so it lightly covers the pastry","Prepare sausage meat onto pastry","Fold pastry around the meat, apply extra egg whisk to the 'seal' where the pastry is folded together","Bake until golden brown"],"time":60,"servings":null,"image":"","source":"https://based.cooking/sausage-rolls","page":"sausage-rolls","tags":["pork","pastry"]},{"id":"bc-scandinavian-coffee-cake","title":"Scandinavian Coffee Cake","cuisine":"Other","category":"Dessert","ingredients":["1/2 cup milk","1/2 cup shortening","1/2 cup sugar","1/2 teaspoon salt","1 package active dry yeast","1/4 cup warm (not hot) water","3 cup sifted enriched Flour","2 eggs, beaten","melted butter, or margarine","2/3 cup firmly packed brown sugar","2 teaspoon cinnamon","chopped walnuts"],"steps":["Scald milk","Add shortening, sugar, and salt","Stir until sugar dissolves; cool to lukewarm","Dissolve yeast in water; combine with milk mixture","Stir in half the flour; add eggs; beat well","Add enough of remaining flour to make a soft dough","Turn out on lightly floured board; knead till smooth and elastic","(See a recipe for white bread) put in a greased bowl; brush with shortening; cover; let rise in a warm place, 80°-85°F (25°-30°C) till double in bulk (about 2 hours)","Turn out on floured board; roll into a rectangle 8 by 12 inches","Brush with butter","Sprinkle with brown sugar and cinnamon","Roll up like jelly roll; shape into a ring on greased baking sheet; pinch ends","From the outside, cut through the ring toward center almost all the way through in 1- inch slices","Fan out slices slightly to side","Brush with shortening; cover; let it rise for about 45 minutes or till double in bulk","Meanwhile set oven for moderate 375°F (190°C)","Bake 25 to 30 minutes","While warm spread with confectioners' sugar icing; sprinkle with chopped walnuts"],"time":180,"servings":1,"image":"","source":"https://based.cooking/scandinavian-coffee-cake","page":"scandinavian-coffee-cake","tags":["sweet","dessert","cake","cheesefare"]},{"id":"bc-shakshouka","title":"Shakshouka","cuisine":"Other","category":"Breakfast","ingredients":["5 small tomatoes","5 eggs","1 peeled white onion","some chives","cumin","powdered sweet pepper"],"steps":["Scald the tomatoes so they are easier to peel","Peel the tomatoes and cut into cubes","Chop the onion and glaze it on the frying pan with oil","Add tomatoes","SEASON","Stir and wait for it to get denser","Knock the eggs in","Season the eggs","Cover the pan with a lid","Cook until eggs are laid","Add chives"],"time":10,"servings":2,"image":"https://based.cooking/pix/shakshouka.webp","source":"https://based.cooking/shakshouka","page":"shakshouka","tags":["breakfast","quick"]},{"id":"bc-shortcrust-pastry","title":"Shortcrust pastry","cuisine":"Other","category":"Recipe","ingredients":["500 g flour","250 g butter","150 g powdered sugar","2 eggs"],"steps":["Cut the butter in slices, put it in a large bowl and leave it at room temperature until it's easy to knead","Add the powdered sugar and knead until uniform","Add the eggs and knead","Add all the flour and knead","Roll out the dough on baking paper","Keep in the fridge for 15-30 minutes before use"],"time":null,"servings":8,"image":"","source":"https://based.cooking/shortcrust-pastry","page":"shortcrust-pastry","tags":["baking","basic","dough","sweet"]},{"id":"bc-simple-chicken-curry","title":"Simple Chicken Curry","cuisine":"Other","category":"Recipe","ingredients":["1 ½ tsp Coriander","1 tsp Cumin","½ tsp Turmeric","½ tsp Ground Fennel Seeds","½ tsp Cinnamon","½ tsp Black Pepper","½ tsp Ginger","¼ tsp Mustard","¼ tsp Ground Cloves","Sriracha Sauce (optional)","¼ cup (½ stick) Butter","1 large Onion","4 cloves Garlic","2-3 cups Chicken Broth","2-3 cups Crushed or Pureed Tomatoes","1 ½ lbs Boneless Skinless Chicken Breasts"],"steps":["Mince the garlic and dice the onion","Saute onion and garlic with the butter in a pot","Once the onion is just beginning to brown, pour in the chicken broth and tomato and raise heat to high","Cut the chicken breasts into bite-sized cubes","Add the chicken and the spices","Once the pot reaches a boil, reduce heat and let simmer for 30 minutes"],"time":null,"servings":3,"image":"","source":"https://based.cooking/simple-chicken-curry","page":"simple-chicken-curry","tags":["chicken","curry","stew"]},{"id":"bc-simple-pasta-cream-sauce","title":"Simple Creamy Pasta Sauce","cuisine":"Other","category":"Sauce","ingredients":["Dairy liquid cream (10%+ fat recommended)","Flour (Wheat flour recommended)"],"steps":["Add 1 teaspoon of flour into a saucepan","Pour ~60ml(2fl oz|1/4 cup) of cream into a saucepan","Stir and turn on maximum heat","Keep stirring until it becomes thick","Mix the sauce with the pasta"],"time":5,"servings":1,"image":"","source":"https://based.cooking/simple-pasta-cream-sauce","page":"simple-pasta-cream-sauce","tags":["basic","quick","sauce","pasta"]},{"id":"bc-tuna-salad","title":"Simple Tuna Salad","cuisine":"Other","category":"Recipe","ingredients":["1 (7 oz) can white tuna, drained","6 tablespoons mayonnaise","1 tablespoons sweet pickle relish","A pinch of garlic powder (optional)","2 tablespoons white vinegar or lemon juice (optional)","1 cup shredded cheese (optional)","1 chopped hard-boiled egg (optional)"],"steps":["In a medium bowl, stir together tuna, mayonnaise, and relish","Add optional ingredients like vinegar, cheese or hard-boiled eggs if wanted","Season with garlic powder, salt, and pepper if wanted"],"time":null,"servings":3,"image":"https://based.cooking/pix/tuna-salad.webp","source":"https://based.cooking/tuna-salad","page":"tuna-salad","tags":["quick","basic","tuna","fish"]},{"id":"bc-slowcooked-green-bean-beef-soup-supreme","title":"Slowcooked Green Bean Beef Soup Supreme","cuisine":"Other","category":"Soup","ingredients":["1x Seasoned Meat package (beef, peppers, some rub)","1-2 cups of water (250-450 ml)","2x Cans french cut green beans (Or Diced green beans)","3x Small Cans chicken noodle soup","1-4x Jalapenos, depending on preferred spice level (optional)"],"steps":["Place the slow cooker on HIGH to let warm up, and pre-thaw the Seasoned Meat Package if applicable","Place the Seasoned Meat in the slow cooker on HIGH for 2-3 hours with 1-2 cups of water to produce vapors, 3-4 hours if you prefer the meat to be more pull-apart","Once the meat is semi-cooked, cut the meat down into thirds or fourth sections. The inside should still be pink and not fully cooked","Dump the cans of soup and green beans into the slow cooker","Dice and cut the jalapenos, then dump into slow cooker","Let cook on HIGH for another 3 or so hours. Taste with a spoon midway to verify flavour or make any adjustments as needed (Add spices, thin with additional water, ETC)","Seperate or \"pull-apart\" the meat within the slow cooker to ensure fully cooked and to release additional flavours","Turn off the slow cooker and turn lid partially to let hot air vent. Let sit for 30 minutes to cool before serving"],"time":400,"servings":6,"image":"https://based.cooking/pix/slowcooked-green-bean-beef-soup-supreme.webp","source":"https://based.cooking/slowcooked-green-bean-beef-soup-supreme","page":"slowcooked-green-bean-beef-soup-supreme","tags":["beef","vegetables","stew","soup","crockpot","slowcooked","spice","adaptable"]},{"id":"bc-smoked-salmon-pasta-primavera","title":"Smoked Salmon Pasta Primavera","cuisine":"Other","category":"Pasta","ingredients":["12 oz Linguine","1/2 lb Asparagus, cut into 2\" pieces","1/4 lb Green Beans, halved","1 cup Sugar Snap Peas, trimmed","1/2 cup Frozen Edamame or Peas","1 Tbsp Butter","1 small Onion, minced","2 cloves Garlic, minced","3 Tbsp All-Purpose Flour","2 1/2 cup Milk","1/3 lb Smoked Salmon, cut into wide strips","1/2 cup Fresh Mint, coarsely chopped","1/2 Lemon"],"steps":["In a large pot of boiling salted water, cook linguine 10 min or until al dente, adding asparagus, beans, and sugar snap peas during the last 3 minutes of cooking and edamame during the last minute. Drain very well","Meanwhile in large saucepan, melt butter over medium heat. Add onion and garlic; cook, stirring 3 minutes. Stir in flour. Very gradually whisk in milk until smooth and stir often until mixture boils and has thickened (5 mins)","Add pasta mixture, stirring until hot. Stir in salmon and mint just until mixed. Squeeze juice from lemon into pasta and stir"],"time":15,"servings":4,"image":"","source":"https://based.cooking/smoked-salmon-pasta-primavera","page":"smoked-salmon-pasta-primavera","tags":["fish","pasta"]},{"id":"bc-sourdough-starter","title":"Sourdough starter","cuisine":"Other","category":"Bread","ingredients":["Wheat or rye flour","Water"],"steps":["Day 1: mix 80g of water to 50g of flour and put a cover on the container loosely. Store somewhere warm","Day 2: the starter should be a bit bubbly. Feed the starter with 80g of water and 50g of flour and store again with loosely covered. If the starter doesn't have bubbles yet, wait another day","Day 3-4: repeat the feeding process","You can now use the starter for baking sourdough bread. Remember to not use all the starter at once and feed the remaining starter to always have it available","Storing the starter: store the starter in a closed container or jar in the fridge. The starter will survive almost indefinitely. After some time a vinegarish liquid forms on top of the starter. Don't be afraid of this, it is there to protect the starter from microbes. It can be poured away when you use the starter next time","When using the starter after long storage you need to activate it again. Feed it 1-2 times and see if bubbles form. You can also test the activity by placing small part into a glass of water. An active starter will float"],"time":null,"servings":null,"image":"","source":"https://based.cooking/sourdough-starter","page":"sourdough-starter","tags":["bread","sourdough","basic"]},{"id":"bc-sourdough-loaf","title":"Sourdough Table Loaf","cuisine":"Other","category":"Bread","ingredients":["100g fed sourdough starter (levain)","330g warm water","137g bread flour","250g all-purpose flour (avoid bleached and enriched)","87g rye or whole wheat flour","7g sea salt"],"steps":["Combine sourdough starter with warm water, break apart and dissolve","Add flour and mix together gently to hydrate. Mixture will be very wet and sticky","Once there is no dry flour, let stand for 30 minutes (autolyze)","Add sea salt","Wet hands and begin to stretch and fold dough to combine salt and to begin gluten formation","Add drops of water until dough becomes cohesive and supple with no toughness or resistance","Dough will prove on the counter top for 4 - 5 hours. About every 30 minutes, perform a stretch and fold. This involves grabbing the dough with a wet hand, folding over the top of itself, and repeating this step by turning the bowl and making your way around the dough. It will take some practice to work with a dough of this level of hydration, but will get easier!","You will know fermentation is complete when small bubbles are seen on the surface around the edge of your dough. You can also perform a window pane test by grasping a pinch of dough and pulling it between your fingers. The dough should stretch enough to become see-through. This means enough gluten has formed that the dough is strong enough to hold large air bubbles as it bakes","Turn onto generously floured surface using a bowl scraper or spatula to protect the dough. Handling the dough gently will prevent deflation","Shape the dough: Take the two sides and fold them into the center of the wet dough. Then, take the top and bottom and fold them also over the center of the wet dough. Optional: grasp the edge of the dough closest to you and roll dough away from you into a tight loaf shape. Generously flour","Place into a dish about the size of the dough, a proving basket is ideal. Use a lot of flour in the bowl and on the loaf. The sides of the container should not be shallow, the goal here is to let the bread rest in the shape you want it to bake in","Refrigerate 12 - 24 hours, the longer the dough rests, the more sour your final product. I don't recommend going over 24 hours but sour dough is fun to experiment with!","Bring dough to room temperature, it should feel like a water balloon, giving resistance to touch with some spring","Put one oven rack in the center and another below it, place a pan of water on the lower rack. Preheat oven to 475 - 500 degrees F, depending on oven capability. The pan of water should create steam to help the bread expand","When oven is hot, turn bread into a baking vessel. I use a 8 inch springform pan, but a dutch oven is ideal. You can use any vessel that is rated for high temperatures. If using a dutch oven, keep it covered for the first 15 minutes, and you don't need to use the pan of water","Flour the top of the loaf and score the bread with a razor blade (this is optional but creates an artisan look)","Bake covered/steamed for 15 minutes, then reduce oven temperature to 425 F. If using steam, remove the water pan now","Bake for another 25 - 30 minutes until crust is a rusty color and sounds hollow when tapped","Let bread cool completely before slicing. (if you can wait!)"],"time":null,"servings":null,"image":"https://based.cooking/pix/sourdough-loaf.webp","source":"https://based.cooking/sourdough-loaf","page":"sourdough-loaf","tags":["bread","sourdough"]},{"id":"bc-spatchcock-chicken","title":"Spatchcock Chicken","cuisine":"Other","category":"Bread","ingredients":["2 (3 1/2) pound whole chickens, wingtips removed","2 teaspoons salt","1 teaspoon dried tarragon","1 teaspoon paprika","1/4 teaspoon black pepper","4 teaspoons olive oil","2 lemons, thinly sliced and seeded"],"steps":["Preheat oven to 450 degrees F (230 degrees C). Line a large rimmed baking sheet with foil","Place chicken, breast side down, on a work surface. Starting at the tail end, cut along both sides of backbone with kitchen shears. Remove backbone. Grabbing hold of both sides of the chicken, open it like a book. Turn breast side up. Push down on each side of breast with your hands until you hear it crack. Flatten chicken and transfer to one short end of the prepared baking sheet. Repeat with the second chicken","Combine salt, tarragon, paprika, and pepper in a small bowl. Stir in oil. Run your fingers under chicken skin and rub tarragon paste under skin. Slide lemon slices under skin, in a single layer","Roast until skin is crisp and an instant-read thermometer inserted into thickest part of breast reads 165 degrees F, about 35 minutes. Let stand 5 minutes before cutting each chicken into 8 pieces"],"time":null,"servings":null,"image":"","source":"https://based.cooking/spatchcock-chicken","page":"spatchcock-chicken","tags":["basic","bread","chicken"]},{"id":"bc-spicy-kung-pao-style-chicken","title":"Spicy Kung Pao-Style Chicken","cuisine":"Other","category":"Rice","ingredients":["4 Chicken Thighs","3/4 cup Basmati Rice","4 Tbsp All-Purpose Flour","2 small Sweet Peppers, chopped","3 ribs Celery","2 cloves Garlic","1 Tbsp Ginger, minced","2 whole Green Onions, thinly sliced","2 Tbsp Chili Garlic Sauce, divided","2 Tbsp Soy Sauce","2 Tbsp Sweet Chili Sauce","1/4 cup Peanuts, chopped","Oil"],"steps":["Heat a medium pot over medium heat. Add 1/2 Tbsp oil, ginger and rice. Cook, stirring often, until fragrant (1 min). Add 1 1/4 cups water and bring to a boil over high heat. Reduce heat and cover until rice is tender and liquid is absorbed (12-14 mins). Remove the pot from heat, leave covered","While rice cooks, cut celery crosswise into 1/4\" slices. Whisk together soy sauce, sweet chili sauce, 1/3 cup water, and half the chili garlic sauce in a medium bowl. Combine flour and 1/4 tsp each of salt and pepper in another medium bowl","Heat a large non-stick pan over medium heat. Add peanuts to the dry pan. Toast, stirring often, until golden brown (4-5 mins). Transfer to a plate and heat the same pan over medium-high. Add 1/2 Tbsp oil, peppers, and celery. Cook, stirring often until fragrant (1 min). Transfer veggies to another plate","Pat chicken dry and cut into 1\" pieces. Add chicken to flour mixture, then toss to coat. Press flour mixture into chicken to coat completely. Heat the same non-stick pan over medium and add oil, then chicken. Cook, turning pieces occasionally, until golden brown and cooked through (6-8 mins)","Add veggies and sauce mixture to the pan with chicken. Cook, stirring occasionally, until sauce thickens slightly (2-3 mins)","Fluff rice with fork. Stir in half the green onions and season with salt. Divide rice between plates. Top with chicken, veggies, and sauce. Sprinkle peanuts and remaining green onions over top"],"time":20,"servings":2,"image":"","source":"https://based.cooking/spicy-kung-pao-style-chicken","page":"spicy-kung-pao-style-chicken","tags":["chicken","rice","asian"]},{"id":"bc-spinach-rice-casserole","title":"Spinach-Rice Casserole","cuisine":"Other","category":"Rice","ingredients":["4 cups Brown Rice, cooked","2 lbs raw Spinach, chopped","1 cup Onion, chopped","2 cloves Garlic, minced","3 Tbsp Butter","4 Eggs, beaten","1 cup Milk","1 1/2 cups Cheddar, grated","1/4 cup Parsley, chopped","2 Tbsp Tamari","1/2 tsp Salt (or more, to taste)","1/4 cup Sunflower Seeds","A few dashes each - Nutmeg; Cayenne; Paprika"],"steps":["Saute onions and garlic with salt in butter. When onions are soft, add spinach. Cook 2 minutes","Combine with all ingredients except sunflower seeds and paprika","Spread into buttered casserole dish and sprinkle sunflower seeds and paprika on top","Bake, covered, 35 minutes at 350F"],"time":40,"servings":6,"image":"","source":"https://based.cooking/spinach-rice-casserole","page":"spinach-rice-casserole","tags":["spinach","rice"]},{"id":"bc-steak-tartare","title":"Steak Tartare","cuisine":"Other","category":"Recipe","ingredients":["Ground Beef (Lean as possible)","Eggs","Onion or Shallots","Capers","Gherkin / Cornichons","Parsley (Optional)","Ketchup (Optional)","Mustard (Optional)","Worcestershire Sauce (Optional)"],"steps":["Dice your onions or shallots","Finely slice your cornichons","Rinse, drain and chop your capers","Chop parsley. (Optional)","Chop ground beef into smaller pieces","Add the above to a mixing bowl and mix with hands","Add ketchup, mustard or Worcestershire sauce as needed and mix further. (Optional)","Separate an egg yolk from the whites","Loosely roll some of the mixture into a ball in your hand and place onto a plate and press softly to form a bowl shape, add egg yolk to indentation","Serve, you may now add salt and pepper as desired"],"time":null,"servings":4,"image":"","source":"https://based.cooking/steak-tartare","page":"steak-tartare","tags":["beef","raw","quick"]},{"id":"bc-stir-fried-chicken-with-an-orange-sauce","title":"Stir Fried Chicken with an Orange Sauce","cuisine":"Other","category":"Recipe","ingredients":["Chicken (a pound or two)","Oranges","An Onion","Two Red Bell Peppers","Soy Sauce","Honey","Butter","Flour"],"steps":["Chop your onion and red bell peppers into small bits and throw them in a large frying pan to cook with a pat of butter, stirring occasionally","Chop your chicken into small bite sized pieces, add them to your pan once your onions begin to become translucent. Stir occasionally","If you have something to zest your oranges with add some zest to the ingredients in your pan (if you don't have a zesting thing don't worry about it)","While your chicken is cooking hand squeeze the juice out of your oranges into a bowl, I will usually use the juice of five oranges but three or four might be enough","Once your chicken is cooked pour your freshly squeezed orange juice into your pan, then pour in some soy sauce (you want your orange juice to soy sauce ratio to be about 3:1, use your best judgment on how much to pour in). Add honey (use as much as you want, I wouldn't use less than two tablespoons though) and stir. Turn the stove to medium-high","Let that sit for a few minutes to let the flavors get to know each other a bit, then stir in a few spoonfuls of flour to thicken the sauce","Once the sauce has reached your preferred level of thickness take it off the heat. Serve over rice"],"time":null,"servings":null,"image":"","source":"https://based.cooking/stir-fried-chicken-with-an-orange-sauce","page":"stir-fried-chicken-with-an-orange-sauce","tags":["asian","chicken"]},{"id":"bc-stracciatella-soup","title":"Stracciatella soup","cuisine":"Other","category":"Soup","ingredients":["2 eggs","500 ml broth","Olive oil (optional)"],"steps":["Beat the eggs in a bowl","Heat broth to boiling","Pour the eggs in the broth without removing from the stovetop","Stir with a whip until eggs coagulate","Serve broth and eggs together","If you want, you may season the dish with some olive oil"],"time":null,"servings":1,"image":"https://based.cooking/pix/stracciatella-soup.webp","source":"https://based.cooking/stracciatella-soup","page":"stracciatella-soup","tags":["eggs","soup"]},{"id":"bc-stuffed-round-squash","title":"Stuffed Round Squash","cuisine":"Other","category":"Rice","ingredients":["2 Onions","1 Carrot","4 Round squash","1 Cup of rice","100gr of Cheese (optional)"],"steps":["Cook the rice. This usually takes 20 minutes. In the meantime, cut the onion into small cubes, grate the carrot, and cut the squash in halves. Scoop the squash halves, and cut the core in small cubes. Save them for later","Strain the rice and let it cool. On an oiled pan, mix the onion, carrot and squash core, and cook them for 10 minutes. You may now add seasoning","Place the squash halves facing down on a metal griddle in the oven. Add the rice to the vegetables, stir, and cook for 10 more minutes","Flip the squash, stuff them with cheese and the vegetables mixture, and put them again in the oven for 10 minutes at max heat","Serve"],"time":null,"servings":4,"image":"https://based.cooking/pix/stuffed-round-squash.webp","source":"https://based.cooking/stuffed-round-squash","page":"stuffed-round-squash","tags":["supper","rice","vegetables","cheesefare","fasting"]},{"id":"bc-stuffed-vegetables","title":"Stuffed vegetables","cuisine":"Other","category":"Recipe","ingredients":["1 medium-sized tomato","1 sweet pepper","1 courgette","1 elongated aubergine","100-150 g grated bread","about 50 g grated Parmigiano cheese","parsley (fresh is best, dry is fine)","extra virgin olive oil","salt (optional)"],"steps":["Cut all the vegetables in half on the long side","Place the vegetables on baking paper in a baking tray","Sprinkle parsley over the vegetables, then, if you want, a little salt","Add copious grated bread, then sprinkle Parmigiano cheese all over it","Add enough olive oil to wet all the bread","Bake for about 45 minutes in the oven pre-heated to 170 °C"],"time":45,"servings":2,"image":"https://based.cooking/pix/stuffed-vegetables.webp","source":"https://based.cooking/stuffed-vegetables","page":"stuffed-vegetables","tags":["baking","cheesefare","vegetables"]},{"id":"bc-sugar-free-brown-sugar-peanut-butter-cookies","title":"Sugar-Free Brown Sugar Peanut Butter Cookies","cuisine":"Other","category":"Dessert","ingredients":["1 cup creamy peanut butter, no sugar added, well stirred","6 tbsp unsalted butter, softened","0.8 cup brown-sugar-style erythritol/stevia blend, lightly packed","1 large egg, room temperature","1 large egg yolk, room temperature","3 tbsp heavy cream or whole milk","2 tsp vanilla extract","1.3 cups all-purpose flour, spooned and leveled","0.8 tsp baking soda","0.8 tsp fine sea salt","0.5 tsp flaky sea salt, for finishing"],"steps":["Powder the sweetener: run it in a blender or food processor until it looks like powdered sugar. This is the step that keeps the cookies from tasting gritty, so don't skip it. Let the dust settle before opening the lid","Cream the butter and powdered sweetener with a hand mixer until pale and fluffy. Take the full time here","Beat in the peanut butter, then the egg, egg yolk, cream, and vanilla. Mix until completely smooth and glossy, scraping the bowl once","Add the flour, baking soda, and fine sea salt. Mix on low just until the last dry streaks disappear, then stop. Overmixing makes them tough","Cover and refrigerate the dough 30 minutes. It will be soft and sticky at first; chilling makes it scoopable and keeps the cookies thick","Heat the oven to 350°F and line two sheets with parchment. Roll the dough into balls of about 1 1/2 tbsp each, space them 2 inches apart, and press a light crosshatch with a fork. Keep them chunky and don't flatten them out","Bake 10-11 minutes. Pull them when the edges are set but the centers still look puffy and underbaked. The sweetener firms up a lot as it cools, so a cookie that looks done in the oven will be dry on the plate","Sprinkle immediately with the flaky sea salt, then leave the cookies on the hot sheet for a full 15 minutes without moving them. They're fragile hot and finish setting as they cool"],"time":11,"servings":24,"image":"","source":"https://based.cooking/sugar-free-brown-sugar-peanut-butter-cookies","page":"sugar-free-brown-sugar-peanut-butter-cookies","tags":["dessert","cookies","sweet","peanut-butter","sugar-free"]},{"id":"bc-sunday-milkshake","title":"Sunday Morning Milkshake","cuisine":"Other","category":"Breakfast","ingredients":["1 banana (or 2 if they are small)","~120 grams of berries. Can be any berries you like","<1 liter of milk","Vanilla","Sugar"],"steps":["Chop the banana so that it fits better in the blender","Add the banana pieces, berries, vanilla and sugar to taste to the blender","Pour enough milk so that the mix fills a liter of the blender volume","Blend it until the mix looks somewhat homogeneous","Pour it and enjoy!"],"time":null,"servings":null,"image":"https://based.cooking/pix/sunday-milkshake.webp","source":"https://based.cooking/sunday-milkshake","page":"sunday-milkshake","tags":["sweet","breakfast","drink","cheesefare"]},{"id":"bc-tahini-short-bread","title":"Tahini short bread","cuisine":"Other","category":"Dessert","ingredients":["125g of butter","from 30g to 70g of sugar","75g of Tahini","1 egg","200g of flour (T45)","3g of baking powder","Any toppings if desired (chocolate chips, ...) although it is very enjoyable on its own"],"steps":["Thoroughly mix the egg, sugar and Tahini","Warm the butter so it is \"pommade\" meaning not liquide but soft enough so you can mix it with the preparation","Have a good mixing of the butter and the preparation so it gets a bit airy","Add the flour slowly so the preparation stays homogenous","Add the baking powder","Let the dough sit and then cook it as described in butter-based biscuits recipe","Enjoy with tea"],"time":15,"servings":4,"image":"https://based.cooking/pix/tahini-short-bread.webp","source":"https://based.cooking/tahini-short-bread","page":"tahini-short-bread","tags":["dessert","side","snack","cheesefare","eggs","dough"]},{"id":"bc-tanzania-tea-with-milk","title":"Tanzania Tea with Milk","cuisine":"Other","category":"Drink","ingredients":["Black Ceylon Tea (Preferably, you want a dark, herbal flavor from your tea. I have some from Dar es Salaam,","Milk/Sweet Cream","Sweetener (Sugar, Syrup, Monk Fruit extract, etc.) (optional, but recommended)"],"steps":["Bring some hot water to boil and seep the tea. Depending on how strong you like it, you can do this for up to 10 min at most","When done seeping, add in the milk (or cream)","Sweeten to taste. Remember you can always add more if there isn't enough"],"time":8,"servings":1,"image":"https://based.cooking/pix/tanzania-tea-with-milk.webp","source":"https://based.cooking/tanzania-tea-with-milk","page":"tanzania-tea-with-milk","tags":["drink","milk","quick"]},{"id":"bc-teriyaki-beef","title":"Teriyaki Beef Wok","cuisine":"Other","category":"Recipe","ingredients":["2 dL water","2 tbsp cornstarch","1 tbsp honey","1/4 tsp ginger","3 tbsp soy sauce","Sesame oil","Beef slices or strips","Carrot, sliced (optional)","Broccoli, florets (optional)","Baby corn (optional)","Water chestnut, sliced (optional)","Bean sprouts (optional)","Chili pepper, diced (optional)","Noodles or rice"],"steps":["Whisk water, cornstarch, honey, ginger and soy sauce. Set aside","Heat some sesame oil to medium heat in a wok and brown the beef","Move the beef aside, add sesame oil and vegetables to the wok at high heat","Mix everything in the wok and heat"],"time":15,"servings":2,"image":"https://based.cooking/pix/teriyaki-beef.webp","source":"https://based.cooking/teriyaki-beef","page":"teriyaki-beef","tags":["beef","asian","noodles"]},{"id":"bc-tofu-and-cashew-chow-mein","title":"Tofu and Cashew Chow Mein","cuisine":"Other","category":"Recipe","ingredients":["10 oz Precooked Thick Wheat Noodles","3 Tbsp Soy Sauce","2 Tbsp Oyster Sauce","2 tsp Sesame Oil","2 Tbsp Peanut Oil or other suitable frying oil","6 oz Firm Tofu, cut into cubes","1 Carrot, julienned","2 cups Small Broccoli Florets","2 cloves Garlic, minced","2 tsp Ginger, finely grated","1/2 cup Roasted Cashews"],"steps":["Loosen the precooked noodles by soaking in a bowl of hot water for 2-3 minutes, then drain and set aside","Mix together the soy sauce, oyster sauce, sesame oil and 2 Tbsp water in a bowl","Heat a wok or large frying pan over a high heat, add the oil and stir-fry the carrot and broccoli for 2 minutes","Add the tofu and stir-fry for 4 minutes","Add the garlic and ginger and stir-fry for a minute","Stir through the noodles and then add the sauce mixture and cashews and mix until thoroughly combined and heated through"],"time":10,"servings":3,"image":"","source":"https://based.cooking/tofu-and-cashew-chow-mein","page":"tofu-and-cashew-chow-mein","tags":["tofu","asian"]},{"id":"bc-tofu-stir-fry","title":"Tofu Stir Fry","cuisine":"Other","category":"Recipe","ingredients":["One block of extra firm tofu","Three eggs","Vegetables per your choice, recommendations include","Sugar snap peas","Chopped cabbage","Sliced carrots","Broccoli","Cauliflower","Soy or teriyaki sauce","2 tbsp minced garlic","Coconut oil"],"steps":["(Optional) Deep freeze tofu at least 24 hours prior and then thaw. The freezing will crystalize the water inside and make the tofu spongey, giving it a more chewy texture, and aids in flavor absorption","Chop tofu into cubes or slabs per preference and carefully drain water","Allow tofu to soak in sauce for a few minutes","Pour cooking oil into a copper wok evenly to coat around the basin. Let it fill up about half an inch at the bottom","Heat oil at medium and place tofu, sauce, and minced garlic into pan. Adding sauce and herbs early helps tofu absorb the flavors","Shift and flip the tofu around, gradually turning up the heat as you go, until surface starts to turn brown","Add in hard vegetables. If using cabbage, save that for last. Cook until veggies soften","If non-vegan, scramble fry eggs in separate smaller pan until no longer runny, then add to stir fry","Once eggs are firm/brown to liking, add cabbage. Cabbage softens fast, so saving it for last lets it retain some crunch","Once cabbage softens, remove wok from heat. Serve on a plate with favorite sides"],"time":null,"servings":null,"image":"","source":"https://based.cooking/tofu-stir-fry","page":"tofu-stir-fry","tags":["tofu","fasting"]},{"id":"bc-tomato-and-grilled-paprika-soup","title":"Tomato and Grilled Bell Pepper soup","cuisine":"Other","category":"Soup","ingredients":["10 tomatoes","2 red bell peppers","2 onions","1 clove of garlic","1L stock or broth","¾t Cayenne pepper","1t paprika powder","3t bruschetta herbs","1t oregano","1t giner syrup","2T olive oil","2T heavy cream"],"steps":["Halve, deseed and grill the bell peppers in an oven or on a grill. Remove skin after grilling","Skin and quarter tomatoes","Sauté onion and crushed garlic in a large soup pan with olive oil","Add broth/stock, tomatoes, bell paper and purée with a stick blender","Add spices, syrup and cream"],"time":30,"servings":12,"image":"","source":"https://based.cooking/tomato-and-grilled-paprika-soup","page":"tomato-and-grilled-paprika-soup","tags":["soup","cheesefare"]},{"id":"bc-tomato-flavored-hamburger-macaroni","title":"Tomato Flavored Hamburger and Macaroni","cuisine":"Other","category":"Pasta","ingredients":["1/4 lb. Pork Sausage","1 lb. Med ground beef","1 3/4 Cups Elbow macaroni","1 Can of tomato sauce","Diced half onion","Diced half bell pepper","Oregano leaves","Paprika","Sage","Thyme","Marjoram","Rosemary leaves","2 Large grated garlic cloves","Onion powder","Frank's RedHot sauce (optional)","Mozzarella Cheese (optional)","Better than Bulion","1 3/4 cups of Macaroni Elbows"],"steps":["Season the meat with the paprika, sage, thyme, marjoram, rosmary leaves, oregano leaves, and black pepper","Saute the onion and the bell pepper until they become soft","Cook stirring for about 7-8 minutes","Drop ground beef and pork into the cooked vegetables on low-medium heat, breaking the lumps into smaller pieces","Cook for about 15 minutes at medium heat","Add the tomato sauce to the pot and stir","Add the Better than Bouillon to the pot and stir","Add a 1/2 cup of water to the large pot and cook and stir until the water has evaporated","Adjust the stove to lowest heat","Cook the macaroni according to this pasta recipe","Important Stir everything together, make sure the hamburger gets evenly distributed in the macaroni. Make sure to stir right to the bottom so the sauce can reach there too"],"time":60,"servings":6,"image":"https://based.cooking/pix/tomato-flavored-hamburger-macaroni.webp","source":"https://based.cooking/tomato-flavored-hamburger-macaroni","page":"tomato-flavored-hamburger-macaroni","tags":["beef","pasta","supper"]},{"id":"bc-tuhu","title":"Tuh'u","cuisine":"Other","category":"Recipe","ingredients":["450 g of lamb leg meat, diced","4 tbsp of sesame oil, olive oil, or rendered fat","350 mL of prepared water","350 mL of sour-tasting beer (e.g. Weißbier)","1 large onion, chopped","2 cups of arugula, chopped","¾ cup of cilantro, chopped","2 tsp of cumin seeds, crushed or powdered","2 large beetroots, chopped","1 leek, minced or diced","3-9 cloves of garlic, minced or diced","1 Persian shallot (Akkadian: samidu ; uncertain translation)","1 Egyptian leek (Akkadian: suhutinnu ; uncertain translation)","Coriander seeds for garnish"],"steps":["Add oil/fat to a large pot (preferably iron) and set over high heat. Sear lamb for several minutes in the oil/fat until lightly browned","Add onions and cook for 5 minutes","Add beetroots and let cook for 5 minutes","Add salt, water, beer, arugula, cilantro, shallot, and cumin. Bring to a boil","Mix garlic with leek and Egyptian leek, and add the mixture to the pot","Lower heat to medium and let simmer for 60 minutes, or until the beetroot and meat are cooked to your liking","Once the tuh'u has finished cooking, serve in a bowl. Sprinkle with coriander seeds. Garnish with chopped cilantro and chopped Egyptian leek"],"time":90,"servings":3,"image":"","source":"https://based.cooking/tuhu","page":"tuhu","tags":["lamb","stew"]},{"id":"bc-tuna-sub","title":"Tuna Sub","cuisine":"Other","category":"Recipe","ingredients":["1 recipe of your favorite tuna salad","Sandwich bun or bread (a good one)","Thinly sliced cheese (your favorite)","Sliced tomatoes","Baby spinach leaves","Pickles","Mayo and mustard","Other sandwich toppings (very little out of bounds here)"],"steps":["Lightly toast one side of the bun","Add cheese to bottom of bun","Spread a layer of tuna salad","Place several spinach leaves on top bun","Add sliced tomatoes","Add pickle slices","Season with salt and pepper to taste","Combine halves and enjoy"],"time":null,"servings":null,"image":"","source":"https://based.cooking/tuna-sub","page":"tuna-sub","tags":["tuna","sandwich","quick","cheesefare"]},{"id":"bc-two-ingredient-pancakes","title":"Two Ingredient Pancakes","cuisine":"Other","category":"Recipe","ingredients":["2 large banana","2 egg or 1/3 cup egg whites from a carton or 2-3 egg whites from whole eggs","A few pinches of oats (optional)","Dash of vanilla, nutmeg, cinnamon, and/or cloves (optional)","Choice of berries or other addition like chocolate chips (optional)"],"steps":["Beat the eggs","Mash bananas into the eggs. Batter can be a bit chunky","Stir in optional additives if desired","Cook on medium in pan"],"time":null,"servings":1,"image":"https://based.cooking/pix/two-ingredient-pancake-02.webp","source":"https://based.cooking/two-ingredient-pancakes","page":"two-ingredient-pancakes","tags":["eggs","egg whites","banana","pancake","fasting"]},{"id":"bc-tzatziki","title":"Tzatziki","cuisine":"Other","category":"Snack","ingredients":["Greek yogurt, 2 cups","Cucumber, 3 inches","Dill","Garlic, 1 clove/teaspoon","Olive oil, 1 teaspoon","Lemon/lime or vinegar","Salt and pepper"],"steps":["Finely grate the cucumber and chop the dill","Strain the cucumber thoroughly with a clean kitchen towel","Mash the garlic and the olive oil in a mortar and pestle","Add all three to the Greek yogurt","Squeeze in some lemon/lime or vinegar","Add a generous pinch of salt and small pinch of pepper","Optionally add some extra olive oil","Stir and enjoy with your favorite snack"],"time":6,"servings":3,"image":"https://based.cooking/pix/tzatziki.webp","source":"https://based.cooking/tzatziki","page":"tzatziki","tags":["basic","snack","spread","traditional"]},{"id":"bc-venezuelan-arepa","title":"Venezuelan Arepa","cuisine":"Other","category":"Breakfast","ingredients":["2 ½ cups of water","2 cups of precooked corn flour","delicatessen to taste"],"steps":["Combine the water, the precooked corn flour, and a little bit of salt in a large mixing bowl","Mix the ingredients by hand until no clumps remain in the resulting dough and it has a smooth but solid consistency","Preheat a pan with oil over low heat","Take a piece of dough and form a ball the size of the palm of your hand","Carefully slap the ball side by side to make a disk neither too thick nor too thin","Repeat the process with the remainder of the dough","Put the arepas in the preheated pan and wait for it approximately 2 minutes and a half to flip it over","When both sides are cooked, take them out of the pan","Cut through the middle of the arepas with a butter knife, and brush them with butter","Fill them with delicatessen to taste (ham, cheese, beans, mortadella, eggs, etc.)"],"time":5,"servings":3,"image":"","source":"https://based.cooking/venezuelan-arepa","page":"venezuelan-arepa","tags":["venezuelan","basic","breakfast","corn","quick"]},{"id":"bc-yogurt","title":"Yogurt","cuisine":"Other","category":"Breakfast","ingredients":["2 thermos, ½l capacity each","thermometer","1l milk","100ml yogurt"],"steps":["bring the milk to 45°C (113°F)","pour the yogurt into the milk","wisk well","bring the milk to 45°C (113°F) again (don't go higher than that, please)","boil some water (about 100ml) and use it to wash the thermos from inside","let the water out and pour the milk into the thermos","leave the thermos in the oven(or in any other place whithout air flow) for 12h","store in the fridge"],"time":null,"servings":null,"image":"","source":"https://based.cooking/yogurt","page":"yogurt","tags":["basic","breakfast","cheesefare"]},{"id":"bc-yogurt-cake","title":"Yogurt cake","cuisine":"Other","category":"Dessert","ingredients":["300 g flour","180 g sugar","3 eggs","120 g butter","200 yogurt (raw or flavoured)","Instant yeast","Powdered sugar (optional)","100 g fruit of your choice (optional)"],"steps":["Beat the yolks with the sugar","Add the butter and stir until uniform","Add the flour. You may sieve it to prevent lumps. Stir until uniform","Add the yogurt and stir until uniform","Beat the albumens in another bowl, then add them to the compound and stir until uniform","The compound should now be thick, but still liquid enough to be poured","Add the yeast and stir","Pour into a mould","You may now sprinkle powdered sugar on top, to create a thin, sweet crust","Cook in pre-heated oven at 180 °C"],"time":45,"servings":15,"image":"https://based.cooking/pix/yogurt-cake.webp","source":"https://based.cooking/yogurt-cake","page":"yogurt-cake","tags":["cheesefare","dessert","sweet"]},{"id":"bc-arroz-chaufa","title":"Arroz Chaufa","cuisine":"Peruvian","category":"Rice","ingredients":["Rice","Salt","Bell pepper","Chicken","Eggs","Soy sauce","Welsh onion"],"steps":["Cut the chicken into pieces and fry it. Don't forget the salt","Cook scrambled eggs. Don't forget the salt","Cook the rice. If it is yesterday's rice better, preferably without salt","Cut the welsh onion and bell pepper into small squares","Mix everything over low heat, adding soy sauce","Optional: add bacon, sesame oil","If everything is salty, you can reduce it with just a teaspoon of sugar, especially if you cook the rice with salt"],"time":10,"servings":4,"image":"https://based.cooking/pix/arroz-chaufa.webp","source":"https://based.cooking/arroz-chaufa","page":"arroz-chaufa","tags":["peruvian","chinese","rice"]},{"id":"bc-ceviche","title":"Ceviche","cuisine":"Peruvian","category":"Recipe","ingredients":["Seafood","Red Onion","Lime Juice"],"steps":["Slice your onion as thinly as you can then let them all sit in a","While your onion is soaking cut your chosen seafood into cubes","Squeeze the juice of several limes onto your seafood, remember when","Add the onion slices then cover and let sit in the fridge. You can"],"time":null,"servings":null,"image":"https://based.cooking/pix/ceviche.webp","source":"https://based.cooking/ceviche","page":"ceviche","tags":["seafood","peruvian"]},{"id":"bc-crab-salad","title":"Crab salad","cuisine":"Russian","category":"Salad","ingredients":["Сrab meat (300 grams)","Egg (3)","Rice (50 grams)","Corn (1 can)","Cucumber (1)","Carrot (1)","Onion (1)","Mayonnaise (100 grams)"],"steps":["Boil rice, eggs and carrot","Chop crab meat and all other ingredients","Combine and mix all ingredients","Add mayonnaise","Chill before serving"],"time":30,"servings":3,"image":"https://based.cooking/pix/crab-salad.webp","source":"https://based.cooking/crab-salad","page":"crab-salad","tags":["salad","russian"]},{"id":"bc-lithuanian-cold-borscht","title":"Lithuanian Cold Borscht","cuisine":"Russian","category":"Soup","ingredients":["2-3 fresh or pickled beets","1-2 potatoes per serving","1-2 normal sized cucumbers per serving","Dill, parsley, chives","Egg (1 per serving)","Kefir (if not available - sour yoghurt or buttermilk) about 150-300 ml per serving","Sour cream (1 tbsp per serving)","Some radish (optional)","1 lemon (optional)"],"steps":["Wash 2-3 beets and cook in 2-3 litres of water (do not drain), peel. Grate on a medium or coarse grater. Squeeze a little lemon juice into the liquid in which the beets have been cooked, mix, then add salt, sugar and pepper to taste. Cool in the fridge","Thinly slice the fresh cucumber and mix with chopped dill and parsley. You can also add chopped radishes if you like","Bake or boil the potatoes without peeling","Boil an egg for each portion of soup","Place a few large spoonfuls of cooled grated beetroot and vegetable mixture in a bowl. Pour in the cold kefir. Add the cooled beetroot decoction (50-150 ml). If the kefir is too thick, add a little more liquid (the ratio of kefir to beetroot liquid varies from region to region and is adjusted to taste)","Serve with potatoes and with a halved egg and spoonful of thick sour cream on top; sprinkle with chives. If you like, you can make it without the egg (as in the photo)"],"time":5,"servings":null,"image":"https://based.cooking/pix/lithuanian-cold-borscht.webp","source":"https://based.cooking/lithuanian-cold-borscht","page":"lithuanian-cold-borscht","tags":["soup","russian","lithuanian","baltic","beetroot"]},{"id":"bc-mazurek","title":"Mazurek","cuisine":"Russian","category":"Dessert","ingredients":["2 1/2 cups flour","1/4 cup powdered sugar","200g (7 oz) butter","1 tablespoon 18% sour cream","2 egg yolks","topping: for example orange jam from 4 oranges","optional additional toppings/decorations","walnuts","pecans","raisins","sliced almonds"],"steps":["Put flour and butter in a bowl","Cut the butter with a sharp knife into tiny pieces, mixing with the flour","Add egg yolks, sugar, sour cream, and a pinch of salt","Knead well and form into a ball. Wrap in plastic wrap and let chill in fridge","Roll out flat and place in large baking sheet (this should be enough for a","Make little holes with fork in the dough","Bake for 15-20 minutes in 200°C (395°F)","Let cool before spreading topping","Decorate with nuts or other toppings"],"time":null,"servings":null,"image":"","source":"https://based.cooking/mazurek","page":"mazurek","tags":["polish","easter","dessert"]},{"id":"bc-merchants-buckwheat","title":"Merchant's Buckwheat","cuisine":"Russian","category":"Recipe","ingredients":["400g pork meat","1/2 metric cup (~125ml) buckwheat","1 1/5 metric cup (~300ml) water","1 medium-sized carrot","1 small onion","6-8 tablespoons tomato paste","Wheat flour","Curcuma","Chili powder (optional)","3-4 garlic cloves","Parsley","3-4 bay leaves"],"steps":["Chop the onion and cut the pork into small pieces","Dust the pork with some flour. I sometimes like to do this once I've added","Heat the frying pan add a bit of oil, add the pork and onion, and fry for","While the pork and onion are being fried, cut the carrot into small pieces","Once the pork and onion are fried, add the water, tomato paste, buckwheat and","Add curcuma, chili powder, salt and black pepper to taste; mix thoroughly","Add in the garlic cloves, bay leaves and chopped parsley","Once the water is boiling, close the pan with a lid and stew for about 25","Serve hot and enjoy!"],"time":null,"servings":null,"image":"https://based.cooking/pix/merchants-buckwheat.webp","source":"https://based.cooking/merchants-buckwheat","page":"merchants-buckwheat","tags":["russian","pork"]},{"id":"bc-mushroom-stragonov","title":"Mushroom Stroganov","cuisine":"Russian","category":"Pasta","ingredients":["8 oz uncooked pasta (spaghetti or any other long noodle will work. Stroganov can also be served over rice.)","12 oz mushrooms (I reccommend shitake, but white, portabello, or maitake will also work.)","2 cloves of garlic, minced","1 small yellow onion, minced","2 Tbsp butter","1 Tbsp general purpose flour","1 Cup vegetable broth","1 Tsp dijon mustard","1 Tsp Smoked paprika","4 Tbsp creme fraiche (can be made by mixing equal parts heavy and sour cream)","2 Tbsp parsely"],"steps":["Bring a large pot of salted water to a boil and cook pasta al dente","In a cup, combine flour, mustard, smoked paprika, salt and pepper. Add broth and whisk until no lumps remain","While pasta is cooking, melt butter in a medium skillet and over medium heat","When the butter is melted, add onions and cook until softened","Add mushrooms and cook until all water evaporates and mushrooms are slightly browned, about 7 minutes","Add garlic and cook for another 30 seconds","Pour the flour and broth mixture into the mushrooms and cook until thickens, about 2 minutes","Stir in Creme Fraiche","Add the strained pasta to the mushroom sauce and stir to coat the pasta completely","Serve immediately"],"time":20,"servings":2,"image":"","source":"https://based.cooking/mushroom-stragonov","page":"mushroom-stragonov","tags":["russian","pasta","mushrooms"]},{"id":"bc-pasta-navy-style","title":"Pasta Navy Style","cuisine":"Russian","category":"Pasta","ingredients":["250g pasta. Usually I prefer to use fusilli or penne, but any short-cut pasta","300-400g ground beef","3-4 tomatoes","1 carrot","1/2 onion","2-3 garlic cloves","Cumin","Paprika"],"steps":["Add olive oil to your frying pan, heat it to medium-high heat","Chop some onions and add them to the preheated pan","After a couple of minutes add the ground beef to the pan, salt it and mix it","When the meat is almost done, mince the garlic and add it together with the","Cook the pasta in a pot until its done al dente while the beef is being","Grate the tomatoes over the pan using a grater with small-sized slots, in","Grate the carrot using a grater with medium-sized slots and add it to the","Salt some more to taste, and add some black pepper to taste, mix","Cook it over medium/medium-low heat for about 10-15 minutes or until the","Once (or if) the pasta and beef is already cooked, add the pasta to the pan","Serve hot and enjoy!"],"time":null,"servings":null,"image":"https://based.cooking/pix/pasta-navy-style.webp","source":"https://based.cooking/pasta-navy-style","page":"pasta-navy-style","tags":["russian","pasta","beef"]},{"id":"bc-pozharskiye-cutlets","title":"Pozharskiye Cutlets","cuisine":"Russian","category":"Recipe","ingredients":["Chicken mince","Butter (originally, 1 part butter per 2 parts chicken; 1/4 works perfectly fine)","Eggs (~1 egg per 500g chicken, plus 3-5 for the breading)","A couple white bread loaves (store-bought breadcrumbs also suffice, but require more eggs)","Spices/salt (optional, recommended)","Non-lard based, non-chunky sauce (optional)","Onions (optional)"],"steps":["Prepare 2 medium-sized and 1 extra large bowl, a few plates and a regular frying pan","Get the chicken out of the cold and into the XL bowl. Butter, too, but onto a plate","While they warm up, crumb up the bread. By hand. The smaller, the better. If you're using store-bought crumbs, just put those into a bowl","Mince the chicken, if necessary. Mince the onions, if you desire them. Divide butter, once softened, into medium bits","Add eggs to the meat and put a few into a medium bowl; mix both bowls' contents thoroughly","Add the spices, salt and/or sauce of your choosing. Some may consider this barbaric, but I found that Heinz's mustard ketchup works exceptionally well with the recipe. They'll come out a tad red, though","Add the softened-up butter to the XL bowl and mix thoroughly","MAKE A TEST CUTLET by rolling up a small ball of the mince, then dipping it into the bread, then into the eggs, then into the bread again, compounding the breading slightly between dips. More dips means less leaked butter/juice, but don't overdo it lest you want more bread than meat in your cutlet","Fry, let cool and then taste the cutlet. (Pozharskiye are very juicy, so liquid in the pan is to be expected.)","If unsatisfied, add more flavoring or throw everything away. If satisfied, repeat step 9. (Most cutlet sizes work well. Haven't tried making giant or tiny ones, though.)"],"time":null,"servings":null,"image":"","source":"https://based.cooking/pozharskiye-cutlets","page":"pozharskiye-cutlets","tags":["russian","chicken"]},{"id":"bc-russian-1000-islands-sauce","title":"Russian 1000 Islands Sauce","cuisine":"Russian","category":"Sauce","ingredients":["Ketchup (Sir Kensington's recommended)","Mayonnaise","Horseradish","Worchestershire sauce","Paprika","Dijon mustard","Onion powder","Pickle relish (optional)"],"steps":["Put ingredients into bowl or cup","Mix together thoroughly"],"time":null,"servings":null,"image":"","source":"https://based.cooking/russian-1000-islands-sauce","page":"russian-1000-islands-sauce","tags":["basic","spread","quick","russian","sauce"]},{"id":"bc-okroshka","title":"Russian Okroshka","cuisine":"Russian","category":"Soup","ingredients":["2-3 medium potatoes","4 eggs","2 long or 4 short cucumbers","3 strands of spring onions","10-12 radishes","bunch of dill","2 Kefir or 1 kvass","500g boiled sausage or boiled chicken meat","1 mineral water (optional)"],"steps":["Prepare a saucepan where you will put the ingredients (5 liters) and a saucepan for boiling eggs and potatoes","Boil potatoes and eggs (hard boiled)","Finely chop cucumbers, radishes, onions, dill and sausage (or meat)","Peel eggs and potatoes and chop finely","Pour kefir (or kvass) and mix all the ingredients","If necessary, add boiled water or mineral water","Let it brew for a few minutes and the dish is ready to eat"],"time":null,"servings":null,"image":"","source":"https://based.cooking/okroshka","page":"okroshka","tags":["basic","spread","quick","russian","soup"]},{"id":"bc-strawberry-compote","title":"Strawberry Compote","cuisine":"Russian","category":"Drink","ingredients":["Strawberries (two standard packs works best)","Sugar"],"steps":["Get 3 bowls and a butter knife (if the butter knife has a point, that will work better)","Dump out both packs of strawberries into a sieve or bowl and wash them thoroughly","Remove the stem and leaves/crown of the strawberry. The crown can be peeled by hand, then use the butter knife to cut out the stem","Large strawberries can be cut in half","Once all of the strawberries are clean, put them in a standard 4 quart (3.8 L) pot. Fill it with water to the brim","Put the pot to boil. The strawberries will gradually lose their color, which is completely normal","Once it boils, let it cook for 5 mins","After five minutes are over, turn off the heat and incrementally add sugar to your preference. I suggest 1-1.5 cups (237 to 355 grams) of sugar for 4 quarts (3.8 L) of compote. Taste between helpings of sugar to make sure its not oversweetened","Let the pot cool, then refrigerate. Serve chilled"],"time":10,"servings":16,"image":"https://based.cooking/pix/glass-of-compote.webp","source":"https://based.cooking/strawberry-compote","page":"strawberry-compote","tags":["Russian","Fruit","Drink"]},{"id":"bc-ukrainian-borscht","title":"Ukrainian Borscht","cuisine":"Russian","category":"Soup","ingredients":["3 red beetroots","4 Tbsp extra virgin olive oil","8 cups chicken broth + 2 cups water","3 yukon potatoes","2 carrots","2 celery ribs","1 onion","4 Tbsp ketchup or 3 Tbsp tomato sauce","1 red bell pepper (optional)","1 can white cannelini beans with their juice (optional)","2 bay leaves (optional)","1 pressed garlic clove (optional)","1 cup sour cream (optional)","fresh dill to taste (optional)"],"steps":["Peel, grate and/or slice all vegetables (keeping sliced potatoes in cold water to prevent browning until ready to use then drain)","Heat a large soup pot (5 1/2 Qt or larger) over medium/high heat and add 2 Tbsp olive oil","Add grated beets and sauté 10 minutes, stirring occasionally until beets are softened","Add 8 cups broth and 2 cups water","Add sliced potatoes and sliced carrots then cook for 10-15 minutes or until easily pierced with a fork","While potatoes are cooking, place a large skillet over medium/high heat and add 2 Tbsp oil","Add chopped onion, celery and bell pepper. Saute stirring occasionally until softened and lightly golden (7-8 minutes)","Add 4 Tbsp Ketchup and stir fry for 30 seconds then transfer to the soup pot to continue cooking with the potatoes","When potatoes and carrots reach desired softness, add optional ingredients from the list","Simmer for an additional 2-3 minutes and add more spices to taste","Serve with a dollop of sour cream on top"],"time":40,"servings":10,"image":"https://based.cooking/pix/borscht.webp","source":"https://based.cooking/ukrainian-borscht","page":"ukrainian-borscht","tags":["ukrainian","soup","beetroot","russian"]},{"id":"bc-ukrainian-vareniki","title":"Ukrainian Vareniki","cuisine":"Russian","category":"Recipe","ingredients":["18 ounces potatoes","3 cups all-purpose flour","¼ cup sour cream","½ teaspoon baking soda","½ cup water","¼ cup butter","2 onions, finely diced","3 ½ cups finely chopped button mushrooms"],"steps":["Place potatoes into a large pot and cover with salted water; bring to a boil. Reduce heat to medium-low and simmer until tender, about 25 minutes. Drain potatoes and mash; season with salt and pepper","Combine flour and 1 teaspoon salt in a large bowl while potatoes are cooking. Stir sour cream and baking soda together in a second bowl. Add water to flour mixture and blend in, followed by sour cream mixture. Knead into a smooth dough, cover with plastic wrap, and refrigerate for 10 to 15 minutes","Melt butter in a skillet over medium heat and cook onions until browned, 5 to 10 minutes. Add mushrooms and cook until browned, about 5 minutes. Add to mashed potatoes","Divide dough into 4 portions and roll each portion into a 1 1/2-inch thick rope. Cut ropes into small 1/2-inch pieces. Press each dough piece into a small flat circle and place 1 teaspoon of potato filling in the center. Fold dough over into a half-moon shape and seal edges","Bring a large pot of salted water to a gentle boil. Add the vareniki in batches and cook until they float to the surface, about 3 minutes. Cook for 2 to 3 minutes more. Remove with a slotted spoon and place in a colander to drain"],"time":25,"servings":45,"image":"","source":"https://based.cooking/ukrainian-vareniki","page":"ukrainian-vareniki","tags":["ukrainian","potato"]},{"id":"bc-almeirim-stone-soup","title":"Almeirim Stone Soup","cuisine":"Spanish","category":"Soup","ingredients":["well-washed stone","kidney beans or fresh","pig's ear (blanched and sliced thin)","chouriço negro or firm type of blood sausage","mixed meat chouriço or mediterranean smoked sausage","pork belly, fatback or bacon","potatoes, cubed","onions, chopped","garlic cloves","bay leaf","cilantro/coriander, chopped"],"steps":["In a saucepan, boil the kidney beans with the pig's ear, sausages, pork belly, onions, garlic and bay leaf in some water and add a well-washed stone. Season with the olive oil and salt and pepper to taste","If necessary, add more water while it’s boiling","Once the meat is cooked, take it out and reserve, then add the diced potatoes and cilantro to the pot","Let the potatoes cook on medium to high heat for about 30-35 minutes","Once the potatoes are well cooked, you can remove the pot from the heat, add the previously chopped meat back in and stir it well","Pour into bowls and serve"],"time":null,"servings":null,"image":"","source":"https://based.cooking/almeirim-stone-soup","page":"almeirim-stone-soup","tags":["portuguese","soup","pork"]},{"id":"bc-apple-chicken","title":"Apple Chicken","cuisine":"Spanish","category":"Recipe","ingredients":["Chicken breast or similar","Onions","Nuez moscada","Apples","Potatoes","Cream or creme fraiche","Salt","Pepper","One glass (33c) of wine or cognac"],"steps":["Heat the oven to 200C and prepare an oven tray","Mix the chicken with nuez moscada, salt and pepper","Remove the center of the apples, fill with nuez moscada and butter","Put the chicken in the oven tray","Put the chicken, onions and apple in the oven tray","Add salt and pepper","Cook in the oven for 40 min","While the chicken is the oven prepare mushed potatoes. First you boil them until they are soft (keep the skin on). Once they are soft, peel them. Then mush them with a fork and add milk or creme fraiche","Add the wine or the cognac. Cook until the chicken is well cooked","Enjoy"],"time":40,"servings":4,"image":"https://based.cooking/pix/apple-chicken.webp","source":"https://based.cooking/apple-chicken","page":"apple-chicken","tags":["spanish","chicken","baking","apple"]},{"id":"bc-portuguese-steak-with-beer-sauce","title":"Bitoque - Portuguese Steak with Beer Sauce","cuisine":"Spanish","category":"Recipe","ingredients":["sirloin steaks","garlic","olive oil q.b. (quanto basta – ‘enough’)","medium fat milk","beer","mustard","flour","eggs"],"steps":["Season the steaks with sliced garlic and salt","In a frying pan, bring the steaks to the boil in abundant olive oil (to make the sauce later) and let it fry. Season with salt only when you are frying them. Remove and set aside in a dish covered with aluminum foil to keep them warm","In a low heat add to the sauce of the steaks, a little more butter or margarine and let it melt. Then add the milk and let it boil a little","Then add the beer, the mustard and the flour dissolved in a little water or milk and stir it well. Add to this sauce the sauce that was formed in the dish of the steaks. Add a little pepper, and stir until it always thickens over a low heat. Rectify the seasonings","When the sauce is ready, place the reserved steaks again in the skillet for a few more minutes","Fry the eggs (use a non-stick frying pan that doesn't require any fat) and season the egg white with salt and the yolk with black pepper","Place the steaks with the sauce and the egg on top in clay bowls and serve with french fries, white rice and salad"],"time":null,"servings":null,"image":"","source":"https://based.cooking/portuguese-steak-with-beer-sauce","page":"portuguese-steak-with-beer-sauce","tags":["portuguese","beef"]},{"id":"bc-bolinhos-de-coco","title":"Bolinhos de Coco","cuisine":"Spanish","category":"Dessert","ingredients":["300 g coconut","150 g sugar","3 egg yolks","1 whole egg","Powdered sugar (optional)"],"steps":["Mix the non-optional ingredients in a medium bowl","Scoop tablespoons of the batter into a cookie sheet or cupcake pan","Cook for around 10 minutes or until slightly brown on top","Top with powdered sugar if desired","Let cool and enjoy!"],"time":10,"servings":null,"image":"","source":"https://based.cooking/bolinhos-de-coco","page":"bolinhos-de-coco","tags":["portuguese","quick","sweet","dessert","cheesefare"]},{"id":"bc-bolo-do-caco","title":"Bolo do Caco (Caco Bread)","cuisine":"Spanish","category":"Bread","ingredients":["1¾ lb sweet potato","8 cups all-purpose flour","⅔ cup water (warm at 75F / 35C)","3 tablespoons active dry - yeast","3 teaspoons salt","750 g sweet potato","1 kg all-purpose flour","150 ml water (warm at 75F / 35C)","3 tablespoons active dry yeast","3 teaspoons salt"],"steps":["Peel the sweet potatoes. Cut into large pieces and place in a saucepan","Cover with water, bring to a boil and cook covered for 20 minutes over 1. medium-high heat","Drain the sweet potatoes and mash them. Add salt","Mix the yeast and water and let stand for 10 minutes","Pour the flour into a large salad bowl","Dig a well in the center and add the mashed sweet potato and yeast","Knead to obtain a homogeneous and elastic dough","Let the dough ferment for 3 days in the refrigerator","After 3 days, divide the dough into 8 to 10 pieces of equal weight on a work surface dusted with flour","Form balls and flatten them to a thickness of about 1 inch (2,5cm)","Let them rest for 30 minutes in a warm place, protected from drafts","Heat a dry pan over medium-high heat and cook the bolos do caco on both sides until a thin and slightly hard crust is formed. Turn them over very regularly","Then take each bolo do caco with tongs and turn them around on the hot pan to bake the sides","Serve warm or lukewarm with salted butter and parsley"],"time":45,"servings":10,"image":"","source":"https://based.cooking/bolo-do-caco","page":"bolo-do-caco","tags":["bread","portuguese"]},{"id":"bc-chorizo-and-chickpea-soup","title":"Chorizo & Chickpea Soup","cuisine":"Spanish","category":"Soup","ingredients":["Chorizo Sausage(s)","2 Garlic cloves","Ginger","Paprika, 2 Tsp","Cumin, Parsley","Juice from whole Lemon","Chickpeas, 400g ( drained )","Butter and sunflower oil, for frying"],"steps":["Fry the sliced Chorizo in butter, along-with diced Ginger and Garlic. Add oil after a couple mins","Pour in Lemon-juice, Chickpeas, and Cumin & Paprika. Then 100ml of water","Allow to boil for 5 or so min. Add Parsley and then salt to taste"],"time":15,"servings":null,"image":"","source":"https://based.cooking/chorizo-and-chickpea-soup","page":"chorizo-and-chickpea-soup","tags":["pork","soup","spanish","quick"]},{"id":"bc-portuguese-creamy-cod","title":"Portuguese Creamy Cod","cuisine":"Spanish","category":"Recipe","ingredients":["2 cod fillets (+- 250 grams)","400ml of milk, either whole or semi-skimmed","half an onion, sliced","1/2 tablespoons of flour","500 grams of potatoes","150ml fresh cream","grated cheese (mozzarella works fine)","ground nutmeg"],"steps":["Pour the milk into a saucepan, bring to boil, then place the cod fillets inside. Boil for 10-15 minutes","Slice the onions and place in a frying pan with some olive oil. Fry until golden","Drain the cod (keep the milk!), place in a chopping board, then shred it. Mix with the onions, fry for a couple of minutes, then add the milk you used to boil it with. Add the flour to thicken. Keep on low heat for 5-10 minutes until you get the desired consistency","Chop the potatoes into cubes roughly the size of a dice. Lightly fry them in some oil or olive oil (not deep frying) for around 5-10 minutes, in low heat","Get an oven tray, oil it with some olive oil, then put in the cod and the potatoes, mixing well. Add the ground nutmeg, salt and pepper","Pour the cream on top. Sprinkle with cheese. Put it in the oven and bake for about 20 minutes, until the top is golden and crispy","Enjoy!"],"time":50,"servings":2,"image":"https://based.cooking/pix/portuguese-creamy-cod.webp","source":"https://based.cooking/portuguese-creamy-cod","page":"portuguese-creamy-cod","tags":["portuguese","fish"]},{"id":"bc-pulpo-gallega","title":"Pulpo a la gallega","cuisine":"Spanish","category":"Recipe","ingredients":["1 octopus (1.7 to 2kg)","Potatoes","2 bay leaves","Sweet and spicy red pepper","Salt","oil"],"steps":["Boil water along with salt and the bay leaves","Once the water is boiling, introduce the octopus 3 times by putting it on and taking it out, then let it cook for 35 to 40 minutes by puncturing it to see whether it is already soft or we need to leave it a little longer","turn off the fire and let it rest for 20 minutes more with the same water. Meanwhile we will have boiled the potatoes with skin for about 25 minutes depending on the size","We will remove the octopus from the water and let it cool, and once it is cold, we will cut it in slices with scissors","To assemble the dish we will laminate the potatoes by placing them at the bottom of the plate, on top and we will put the octopus slices seasoning it with salt, the sweet and spicy red pepper and a good squirt of olive oil"],"time":40,"servings":null,"image":"https://based.cooking/pix/pulpo-gallega.webp","source":"https://based.cooking/pulpo-gallega","page":"pulpo-gallega","tags":["fish","spanish"]},{"id":"bc-lentejas","title":"Sopa de Lentejas","cuisine":"Spanish","category":"Recipe","ingredients":["1 carrot, chopped","1 green bell pepper, chopped","4 garlic cloves, minced","1 large onion, chopped","1 cup dry brown lentils, soaked overnight and drained","2 plum tomatoes, chopped","2 cups water, or as needed","1 bay leaf","1 tbsp extra-virgin olive oil","1/2 tsp of paprika","1/4 spicy chorizo (optional)"],"steps":["Heat olive oil in a large pot over medium heat","Add the onion, carrot, and bell pepper; cook and stir until vegetables begin to soften, about 5 minutes","Stir in the garlic, tomatoes, chorizo and bay leaf; cook about 4 minutes","Add lentils and water (water should be about an inch deeper than the level of the lentils)","Bring to a boil over high heat. Reduce heat to low; simmer, uncovered, until lentils are just cooked, 15 to 20 minutes"],"time":35,"servings":4,"image":"https://based.cooking/pix/lentejas.webp","source":"https://based.cooking/lentejas","page":"lentejas","tags":["spanish"]},{"id":"bc-spanish-tortilla","title":"Spanish Tortilla","cuisine":"Spanish","category":"Recipe","ingredients":["8 free-range eggs","1 kg of potatoes","1 white onion","Extra virgin olive oil"],"steps":["Peel, rinse and dry the potatoes","Cut the potatoes into thin slices. Put in a bowl, add salt to taste and stir","Put a nonstick frying pan on the fire and add enough olive oil to fry all the potato slices","Add the potato slices already salted and let them cook for approximately 20 minutes over low heat","While the potatoes are frying, beat the eggs in a bowl. Peel and cut the onion as finely as possible","Add olive oil in another frying pan and slowly fry the onion until it gets a slightly golden color","Drain the onion and add it to the bowl with the beaten egg","Remove the potatoes from the pan with a slotted spoon, draining the oil away as much as possible, and add them to the bowl with the onion and egg","Let the mixture rest for at least 5 minutes so all the flavors come together. Give it a very gentle stir from time to time","Remove the oil from the pan you used to fry the potatoes. Use the pan to cook the mixture over medium-high fire for about 5 minutes","Flip it over with the help of a big plate and cook the other side for another 5 minutes"],"time":35,"servings":6,"image":"https://based.cooking/pix/spanish-tortilla.webp","source":"https://based.cooking/spanish-tortilla","page":"spanish-tortilla","tags":["spanish","potato","eggs"]},{"id":"bc-tarta-de-santiago","title":"Tarta de Santiago","cuisine":"Spanish","category":"Recipe","ingredients":["3 eggs","¾ cup sugar (150 gr)","1 ½ cup almond meal (150 gr)","½ teaspoon cinnamon powder","¼ teaspoon salt","Zest of 1 lemon","Zest of 1 clementine","Icing sugar, for dusting on top"],"steps":["Add eggs and sugar into a bowl and whisk until the mixture turns pale","Add the rest of the ingredients, except for icing sugar and using a spatula, gently fold everything until well combine","Pour batter into a 7 inch (18 cm) springform pan that has been buttered and floured. Bake in a preheated oven at 360ºF (180ºC) for 40 minutes or until golden brown and fully cooked","Cool completely. Place the Santiago cross cut out on top and dust generous amount of icing sugar all over the cake. Carefully remove the cut out. Slice and serve, enjoy!"],"time":40,"servings":8,"image":"https://based.cooking/pix/tarta-de-santiago.webp","source":"https://based.cooking/tarta-de-santiago","page":"tarta-de-santiago","tags":["spanish","cake","galician"]},{"id":"bc-tarte-merengada","title":"Tarte Merengada de Limão","cuisine":"Spanish","category":"Recipe","ingredients":["200g of buttered cookies (shortcake)","80g of margarine","1 can of condensed milk (370g)","3 / 4 lemons ( 1 dl of juice + the outer scrapings )","5 eggs","150g of sugar"],"steps":["Pre-heat the oven to 220ºC","Separate the yolk from the egg whites and mix the yolks with the condensed milk into whipped cream","Meanwhile mash the cookies into a powder and mix it with the margarine while covering the bottom and sides of a pie dish","Take the outer scrapings of a lemon with a gratter and squeeze the juice of all the lemons","Mix the scrappings and the juice with the yolk and add to the pie dish","Take it to the oven","Meanwhile mix the egg whites until they start to foam, add the sugar then and keep mixing them until the meringe starts to be firm","After 10 to 15 minutes in the oven, cover the surface of the pie with small dumpings of meringe with a spoon","Reduce the heat of the oven to 160ºC and put the pie back into the oven until the meringe on top becomes golden brown"],"time":20,"servings":20,"image":"https://based.cooking/pix/tarte-merengada.webp","source":"https://based.cooking/tarte-merengada","page":"tarte-merengada","tags":["meringue","lemon","pie","portuguese","sweet"]},{"id":"bc-torrijas","title":"Torrijas","cuisine":"Spanish","category":"Dessert","ingredients":["Dried bread (or Torrijas bread). Must be bread from a regular loaf, not from a tin loaf","Milk (to soak the bread, 2 cups per 16 torrijas approx.)","Eggs (to coat the bread, 2 eggs per 16 torrijas approx.)","Cinnamon","Grated lemon rind (optional)","Sugar","Olive oil"],"steps":["Mull the milk with cinnamon and a bit of sugar (not too much, the milk is already sweet). Add the lemon rind if you want","Cool down the milk","While the milk is cooling, beat the eggs and heat up half a pan of olive oil","Cut the dry bread in slices. Soak it in the milk","Coat the bread soaking it in the beaten eggs","Fry the soaked & coated bread with the heated oil","Optionally sprinkle some sugar onto the Torrijas","Enjoy when they are cooled down. Don't eat too much, it won't be easy resisting!"],"time":5,"servings":null,"image":"https://based.cooking/pix/torrijas.webp","source":"https://based.cooking/torrijas","page":"torrijas","tags":["spanish","dessert","quick","easter"]},{"id":"bc-baked-rice","title":"Valencian Baked Rice (Arroz al Horno)","cuisine":"Spanish","category":"Rice","ingredients":["400 g of bomba rice","150 g of cooked chickpeas","500 g of pork ribs, cut into pieces","200 g of pork belly, cut into pieces","2 blood sausages ( morcillas de cebolla )","1 medium potato","1 large tomato","1 whole garlic head","100 g of crushed tomatoes","50 ml of extra virgin olive oil","800 ml of hot broth (preferably from stew)","1 teaspoon of sweet paprika","A few saffron threads","Salt to taste"],"steps":["Preheat the oven to 220°C (428°F), using both upper and lower heat","Peel the potato and cut it into 1 cm thick slices. Set aside","In a clay casserole (oven-safe), heat the olive oil over medium-high heat. Brown the pork ribs and pork belly until golden and crispy. Remove and set aside","In the same oil, lightly fry the potato slices until golden. Remove and set aside","Sear the blood sausages for a few minutes, being careful not to break them. Remove and set aside","Stir the sweet paprika into the remaining oil, mixing quickly to avoid burning. Add the crushed tomatoes and cook until the oil separates from the sauce","Mix in the cooked chickpeas and rice, stirring for a couple of minutes so the rice absorbs the flavors","Return the pork ribs, pork belly, and potato slices to the casserole, evenly distributing them over the rice. Place the whole garlic head in the center and arrange the blood sausages and tomato slices on top","Pour the hot broth into the casserole, ensuring it covers all ingredients. Add the saffron threads and adjust the salt if needed","Bake in the preheated oven for 20-25 minutes, or until the rice has absorbed all the broth and is tender","Once done, remove from the oven and let the baked rice rest, covered with a clean cloth, for 5 minutes before serving"],"time":60,"servings":4,"image":"https://based.cooking/pix/baked-rice.webp","source":"https://based.cooking/baked-rice","page":"baked-rice","tags":["rice","Spanish"]},{"id":"bc-paella","title":"Valencian Paella","cuisine":"Spanish","category":"Rice","ingredients":["500 g of bomba rice","1 free-range chicken, cut into pieces","500 g of rabbit, cut into pieces","150 g of flat green beans ( bajoqueta )","150 g of large white beans ( garrofó )","2 ripe tomatoes, grated","1 tablespoon of sweet paprika","A few saffron threads","5 tablespoons of extra virgin olive oil","Salt to taste","1.5 liters of water","(Optional) 6 artichokes, chopped","(Optional) 500 g of cleaned snails"],"steps":["Heat the olive oil in a paella pan over medium-high heat. Add the chicken and rabbit pieces and fry them until golden brown on all sides","Add the green beans and garrofó to the pan. Sauté the vegetables with the meats for a few minutes so they absorb the flavors","Stir in the grated tomato and cook until it reduces and the oil separates, indicating it is ready","Sprinkle the sweet paprika over the mixture and stir well, being careful not to burn it to avoid bitterness","Pour the hot water into the pan and bring it to a boil. Cook over medium heat for about 20 minutes to let the flavors blend and create a rich broth","Evenly distribute the rice across the paella pan. Add the saffron threads and adjust the salt if needed","Cook over high heat for 10 minutes without stirring the rice. Then, lower to medium-low heat and continue cooking for another 8-10 minutes, until the rice absorbs all the broth and is perfectly cooked","If desired, place a few sprigs of fresh rosemary on top of the rice during the last few minutes of cooking for extra aroma","Once the rice is cooked, remove the pan from the heat and let the paella rest, covered with a clean cloth, for 5 minutes before serving"],"time":60,"servings":4,"image":"https://based.cooking/pix/paella.webp","source":"https://based.cooking/paella","page":"paella","tags":["rice","Spanish"]},{"id":"bc-zarangollo","title":"Zarangollo","cuisine":"Spanish","category":"Side","ingredients":["1 White onion","1 Eggplant","Olive oil","Egg (optional)"],"steps":["Cut onion in julienne (a third or half of an onion ring)","Cut the eggplant in slices or chunks that can fit in a teaspoon","Add oil to a pan (not a shallow one, wide and a bit deep is ideal if you have one) until it barely covers the vegetables","Cook and stir in medium heat until they are tender, caramelized and translucent","Kick up the heat to give them a crispy touch, but not for long","(Optional) Turn off the heat and crack open an egg on top","(Optional) Let the residual heat cook the egg. If it breaks just scramble it, the recipe doesn't call for anything fancy","You can serve the dish with that oil (provided it is not burnt) or keep it for cooking other stuff"],"time":15,"servings":2,"image":"","source":"https://based.cooking/zarangollo","page":"zarangollo","tags":["spanish","mediterranean","side","quick"]},{"id":"bc-chicken-satay","title":"Chicken Satay with Peanut Sauce","cuisine":"Thai","category":"Recipe","ingredients":["2 lbs boneless chicken breast or thigh","1.5 tbsp oyster sauce","1 tbsp ground tumeric","2 tbsp sugar","2 tbsp coconut milk","3 tbsp peanut butter (creamy)","1 tbsp massaman curry paste","water to thin peanut sauce"],"steps":["Cut the chicken into 1/2 inch thick strips","Mix chicken with oyster sauce, tumeric, 1 tbsp sugar and coconut milk. Allow chicken to marinade for at least an hour","Optionally, you can skewer the meat with wooden skewers","Grill chicken until cooked through","Mix peanut butter, 1 tbsp sugar and curry paste together in a small saucepan. Add enough water to thin to a thick sauce","Cook for 1-2 min stirring frequently","Serve chicken with peanut sauce for dipping"],"time":15,"servings":4,"image":"","source":"https://based.cooking/chicken-satay","page":"chicken-satay","tags":["chicken","thai","asian"]},{"id":"bc-fish-curry","title":"Fish Curry","cuisine":"Thai","category":"Recipe","ingredients":["3T neutral oil","1 onion","1 red onion","2 cloves of garlic","4cm ginger","1 red pepper","1t curry powder","250g green beans","4 tomatoes","200ml fish broth","200ml coconut milk","400g fish fillet (white fish)"],"steps":["Boil green beans for 10 minutes","Cut onions, tomato, garlic and fish","Heat oil on a wok and sauté the onion and garlic","Add beans, tomato, broth and spices and boil for 6 minutes","Add coconut milk, fish and pepper (whole) and boil for an additional 6 minutes"],"time":30,"servings":5,"image":"","source":"https://based.cooking/fish-curry","page":"fish-curry","tags":["thai","fish"]},{"id":"bc-instant-tom-yam-kung-noodle-soup","title":"Instant Tom Yam Kung noodle soup","cuisine":"Thai","category":"Soup","ingredients":["2 packages of vegetable- or tom yam-quick noodles","1 can coconut milk","10 small or 5 big mushrooms","2 eggs","A few salad leaves (or practically any veggie you have in the fridge)","1 lime","Coriander"],"steps":["Put small amount of water and coconut milk to boil. Add the noodle spices. (If you don't like it too creamy, add extra water.)","Chop the mushrooms and coriander (and other veggies if you wish). Cut the lime into four pieces","When boiling add mushroom, and crack the eggs directly into the pot (be sure not to stir after this, otherwise they will break). Wait 30 seconds to 1 minute","Add the noodles and salad leaves (or whatever veggie you got)","After 3-5 minutes it's done. Serve in deep bowls. Squeeze the lime juice and chopped coriander on top"],"time":10,"servings":2,"image":"","source":"https://based.cooking/instant-tom-yam-kung-noodle-soup","page":"instant-tom-yam-kung-noodle-soup","tags":["thai","quick","soup","cheesefare"]},{"id":"bc-panang-style-beef-curry","title":"Panang-Style Beef Curry","cuisine":"Thai","category":"Recipe","ingredients":["1/2 lb Ground Beef","1 can (400mL) Coconut Milk","1 Red Chili Pepper","1/2 cup Red Curry Paste","4 tsp Peanut Butter","3/4 cup Jasmine Rice","2 Tbsp Cilantro","1 Sweet Bell Pepper","1/2 Onion (2 oz), chopped","1 Tbsp Garlic Puree","1 oz Peanuts, chopped","1/2 Tbsp Soy Sauce","2 Tbsp Mild Curry Paste"],"steps":["Start rice. While water comes to a boil, core and cut pepper into 1/2 inch pieces. Roughly chop cilantro. Finely chop the chili pepper - remove seeds for less heat","Add rice to boiling water. Reduce heat to low, cover and cook until rice is tender and absorbed, about 12-14 minutes. Remove from heat and keep covered","While rice cooks, heat a large non-stick pan over medium-high heat. Once hot, add a tablespoon of oil, then the beef and garlic puree. Cook, breaking up beef into smaller pieces, until no pink remains (4-5 mins)","Add peppers and onions to the pan with beef. Cook, stirring occasionally until softened (2-3 mins). Add mild curry paste, red curry base, soy sauce, peanut butter, and the minced chili pepper. Cook, stirring often, until fragrant (1 min)","Add coconut milk to the pan. Cook, stirring often, until curry thickens slightly (2-3 mins)","Fluff rice with a fork. Add half the cilantro and season, then stir to combine. Divide rice between plates and top with beef curry. Sprinkle peanuts and remaining cilantro over top"],"time":315,"servings":4,"image":"","source":"https://based.cooking/panang-style-beef-curry","page":"panang-style-beef-curry","tags":["beef","curry","thai"]},{"id":"bc-menemen","title":"Menemen","cuisine":"Turkish","category":"Breakfast","ingredients":["4 green peppers","4 tomatoes","4 eggs","2 onions","butter","1 tsp of thyme (optional)","1 tsp of paprika (optional)"],"steps":["Boil some water and put the tomatoes in it and leave them for a couple of minutes","Chop the onions and peppers into small pieces","Take the tomatoes out of the water and peel them off","Chop the tomatoes into 4 or 6 pieces","Put the butter on the pan and wait till it's melted","Put onions and peppers on the pan","You can add some salt (it will make them a little crispy) and stir till the onions are starting to get brown","Add tomatoes and start mashing them with a spoon","When the tomatoes are all mushed-up, add the eggs and seasonings","Stir some more untill everything is mixed up well","Cover up the pan so eggs don't stay raw on the top","It should be ready in 2 or 3 minutes"],"time":15,"servings":3,"image":"https://based.cooking/pix/menemen.webp","source":"https://based.cooking/menemen","page":"menemen","tags":["turkish","breakfast"]},{"id":"bc-turkish-red-lentil-soup","title":"Turkish Red Lentil Soup","cuisine":"Turkish","category":"Soup","ingredients":["1 cup Red Lentils","5 Tbsp Olive Oil","1 Tbsp Paprika","1/2 Tbsp Red Paper Flakes","1 large Onion, finely diced","1 large Carrot, diced","4 tsp Tomato Paste","2 tsp Cumin","1/2 tsp Dried Mint","1/2 tsp Thyme or Oregano","4 cup Vegetable Broth","4 cup Water"],"steps":["Reserve half the paprika and red pepper flakes, set aside","Pick through lentils for any foreign debris, rinse two or three times, drain and set aside","In a large pot over medium-high heat, saute 2 Tbsp of the olive oil and and onion with a pinch of salt for 3 minutes. Add the carrots and saute for another 3 minutes","Add the tomato paste and stir it around for 1 minute. Add cumin, mint, thyme, and the paprika/pepper flakes not reserved - and saute for 10 seconds to bloom the spices. Immediately add the lentils, water, broth, and salt. Bring the soup to a boil","Once boiling, reduce heat to a medium, cover the pot halfway, and cook for 15-20 minutes or until the lentils have fallen apart and the carrots are fully softened","Meanwhile, heat the remaining olive oil in a small sauce pan over medium heat, and swirl in the reserved paprika and red pepper flakes. The moment you see the paprika start to bubble, remove the pan from the heat","Blend the soup to reach the desired consistency. Taste for seasoning","Divide soup into bowls and drizzle the paprika oil on top of each serving"],"time":30,"servings":6,"image":"","source":"https://based.cooking/turkish-red-lentil-soup","page":"turkish-red-lentil-soup","tags":["lentil","soup","turkish"]},{"id":"bc-turkish-yogurt-soup","title":"Turkish Yogurt Soup","cuisine":"Turkish","category":"Rice","ingredients":["yogurt","1/3 cup rice","2 tablespoon flour","1 egg yolk","butter"],"steps":["wash the rice","put water in the pot and wait for water to boil","add some salt and rice","wait for 15 minutes","mix yogurt, egg and flour and salt in a different bowl","add water from the soup and mix by warming","when the rice is soft, add the yogurt mixture to the soup and mix quickly","cut down the heat, wait for 15 minutes","for the sauce, simply melt the butter in a separate small pan and stir in the dried mint","add sauteed dried mint to the soup and stir well","serve warm"],"time":35,"servings":4,"image":"","source":"https://based.cooking/turkish-yogurt-soup","page":"turkish-yogurt-soup","tags":["turkish","rice","soup"]},{"id":"bc-turkish-style-spiced-chicken","title":"Turkish-Style Spiced Chicken","cuisine":"Turkish","category":"Recipe","ingredients":["2 Chicken Breasts","1 Tbsp Turkish Spice Blend","1 oz Almonds, sliced","3/4 cup Basmati Rice","12 oz Sweet Potato","2 oz Onion, chopped","100 mL Greek Yogurt","2 Tbsp Parsley","1 Lemon","1/2 tsp Garlic Salt","1 1/2 cup Chicken Broth","1 tsp Sugar"],"steps":["Cut sweet potatoes into 1/2 inch pieces. Combine and toss sweet potatoes, half the onions, half the garlic salt, and a tablespoon of oil. Lay to a baking sheet and roast on the middle rack of the oven, stirring halfway through until golden brown (12-22 mins)","While sweet potatoes roast, heat a medium pot over medium-high heat. When hot, add a tablespoon of oil and remaining onions. Cook, stirring often until fragrant (1 min). Add chicken broth and rice, cover, and bring to a boil over high heat. Once boiling, reduce heat to low and leave covered until rice is tender and liquid is absorbed (12-14 mins). Remove pot from heat, still covered","While rice cooks, heat a large non-stick pan over medium heat. When hot, add almonds to the dry pan. Toast, stirring occasionally until golden brown (2-3 mins). When almonds are done, transfer to a plate and set aside","While almonds toast, pat chicken dry with paper towel. Sprinkle with Turkish Spice blend and the remaining garlic salt. Season with pepper. With the pan used in the last step, increase heat to medium-high. Add a tablespoon of oil and the chicken. Pan-fry until golden brown (1-2 min per side). Transfer chicken to another baking sheet. Roast on the top rack of the oven until chicken is cooked through (10-12 mins)","While chicken roasts, zest and juice half the lemon. Cut remaining lemon into wedges. Roughly chop parsley. Add yogurt, half the parsley, sugar, lemon zest and juice to a small bowl. Season with salt and pepper, and whisk to combine","Fluff rice with a fork, then stir in almonds and remaining parsley. Slice chicken. Divide rice between plates, then top with sweet potatoes and chicken. Spoon yogurt sauce over top. Squeeze over a lemon wedge, as desired"],"time":30,"servings":4,"image":"","source":"https://based.cooking/turkish-style-spiced-chicken","page":"turkish-style-spiced-chicken","tags":["chicken","turkish"]},{"id":"bc-turmeric-flatbread","title":"Turmeric Flatbread","cuisine":"Turkish","category":"Bread","ingredients":["1 cup Wheat Flour (white or whole)","1/2 Tbsp Ground Turmeric","1/2 tsp Kosher Salt","1/4 tsp Baking Powder","2 Tbsp Olive Oil"],"steps":["Combine flour, turmeric, salt and baking powder","Stir in 1/3 cup water and the olive oil","Knead until smooth (1-2 min). Cover and set aside 15 minutes","Cut the dough into 4 pieces; flatten each into a 6-inch round","Cook one at a time in an oiled skillet over medium-high heat, flip when browned (2 mins)"],"time":10,"servings":4,"image":"","source":"https://based.cooking/turmeric-flatbread","page":"turmeric-flatbread","tags":["bread","turkish"]},{"id":"bc-pho-soup","title":"Pho Soup","cuisine":"Vietnamese","category":"Recipe","ingredients":["Garlic (4-8 large cloves)","Spring Onions","Cardamom Seeds (10 or so)","Star Anise (4-5)","Ginger","Cinnamon Sticks (3-5 sticks)","Diced Beef (300g)","Beef Bones with marrow (3x)","Beef bouillon cubes (1-3)","Coriander (to taste)","1 Lime (to taste)","Fish/Oyster Sauce","Honey or Brown Sugar","Rice noodles"],"steps":["Heat your oven and place the spices (garlic, cardamom seeds, cinnamon sticks, star anise and ginger) on a tray and bake them until browned or decently toasted","Boil bones until you remove most of the scum, and transfer the spices from the oven into the pot. Life will be easier if you can place the spices in a tea strainer of sorts, otherwise, it's not the worst thing in the world fishing them out later on","Add beef bouillon cubes, diced beef, fish/oyster sauce, and honey/sugar, then simmer for a couple hours with the lid on","Cook the rice noodles (should only take a few minutes, just until the texture is al dente enough)","Once the broth is done cooking, fish out the spices that you added at step 2. It's worth doing this rather than accidentally chewing on a bit of star anise, trust me","Cut up coriander and spring onions as garnish","Add rice noodles to bowl, followed by the broth and its contents, followed by the garnish. This can be made and eaten within 1 hour if you want it quickly, but typically with broths the longer you simmer the tastier it'll be"],"time":120,"servings":4,"image":"https://based.cooking/pix/pho-soup.webp","source":"https://based.cooking/pho-soup","page":"pho-soup","tags":["vietnamese","beef"]}];

if (typeof module !== 'undefined') module.exports = { BASEDCOOKING_RECIPES, BASEDCOOKING_LICENSE };
